typedef struct {
    int value;
    int *key;
} record;

int safe_init_records(int size, long **offsets, int **keys, record ***records) {
    if (!size || !offsets || !keys || !records) return 1; // Check for valid inputs

    srand((unsigned int)time(NULL));

    *offsets = malloc(size * sizeof(long));
    if(!*offsets) return 2; // Check for memory allocation error of offsets

    *keys = malloc(size * sizeof(int));
    if(!*keys) { free(*offsets); return 3; } // Check for memory allocation error of keys

    *records = malloc(size * sizeof(record*));
    if(!*records) { free(*offsets); free(*keys); return 4; } // Check for memory allocation error of records

    for (int i = 0; i < size; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % size;
        if((*keys)[i] == i) ++i; // Ensure keys do not repeat
        (*records)[i] = malloc(sizeof(record));
        if(!(*records)[i]) { free(*offsets); free(*keys); free(*records); return 5; } // Check for memory allocation error of records[i]
        (*(*records)[i]).value = rand() % INT_MAX;
        (*(*records)[i]).key = *keys + i; // Assign key pointer to each record
    }

    return 0; // Successful initialization
}

void print_records(int size, const record **records) {
    if (!size || !records) return; // Check for valid inputs

    printf("Keys:\n");
    for (int i = 0; i < size; ++i) printf("%d ", (*records)[i]->key->value);
    printf("\nValues:\n");
    for (int i = 0; i < size; ++i) printf("%d ", (*records)[i]->value);
    putchar('\n');
}
