// Logging levels
enum { DEBUG, INFO, WARNING, ERROR };

// Global variables for rate limiting and log level configuration
pthread_mutex_t rate_limit_mutex;
unsigned long long current_time;
unsigned int requests_this_minute = 0;
const unsigned int MAX_REQUESTS_PER_MINUTE = 100;
char *log_level_env_var = "LOG_LEVEL";
int log_level = DEBUG; // Default to debug level

// Custom callback for the logging service, modify this according to your service's requirements.
void log_service_callback(const char *message) {
    // ... Your implementation goes here ...
}

void log_message(int level, const char *format, ...) {
    if (level > log_level || requests_this_minute >= MAX_REQUESTS_PER_MINUTE) {
        return;
    }

    pthread_mutex_lock(&rate_limit_mutex);
    current_time = time(NULL);
    requests_this_minute++;
    if (current_time % 60 == 0 && requests_this_minute >= MAX_REQUESTS_PER_MINUTE) {
        // Wait until the next minute to resume logging if rate limit is reached.
        current_time += 60 - (current_time % 60);
    }
    pthread_mutex_unlock(&rate_limit_mutex);

    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        return;
    }

    va_list args;
    va_start(args, format);
    vsnprintf(buffer, buffer_size, format, args);
    va_end(args);

    // Append timestamp and log level to the message.
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
    size_t message_length = strlen(timestamp) + 1 + strlen(buffer);
    if (message_length > buffer_size) {
        // Reallocate memory if the formatted message is too large.
        char *new_buffer = realloc(buffer, message_length);
        if (!new_buffer) {
            free(buffer);
            return;
        }
        buffer = new_buffer;
    }

    snprintf(buffer, message_length, "%s [%s] : %s", timestamp, get_log_level_string(level), buffer);

    // Call the logging service callback with the formatted message.
    log_service_callback(buffer);

    free(buffer);
}

char *get_log_level_string(int level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
    }
    return ""; // Unknown or invalid log level.
}

int main() {
    pthread_mutex_init(&rate_limit_mutex, NULL);

    const char *env_value = getenv(log_level_env_var);
    if (env_value) {
        if (strcmp(env_value, "DEBUG") == 0) {
            log_level = DEBUG;
        } else if (strcmp(env_value, "INFO") == 0) {
            log_level = INFO;
        } else if (strcmp(env_value, "WARNING") == 0) {
            log_level = WARNING;
        } else if (strcmp(env_value, "ERROR") == 0) {
            log_level = ERROR;
        }
    }

    // Example usage of the log_message function.
    log_message(DEBUG, "This is a debug message.");
    log_message(INFO, "This is an info message.");
    log_message(WARNING, "This is a warning message.");
    log_message(ERROR, "This is an error message.");

    pthread_mutex_destroy(&rate_limit_mutex);
    return 0;
}
```

