typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key, *iv;
} aes_context;

aes_context* select_and_configure_cipher(const EVP_CIPHER *cipher, size_t key_size, size_t iv_size, const char *key_id) {
    aes_context *ctx = malloc(sizeof(aes_context));
    ctx->ctx = EVP_CIPHER_CTX_new();

    if (EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, NULL, NULL) <= 0) {
        free(ctx);
        return NULL;
    }

    // Generate key and IV using OpenSSL's RAND_bytes function or external key management system.
    if (key_size > 0) {
        ctx->key = malloc(key_size);
        RAND_bytes(ctx->key, key_size);
    }

    if (iv_size > 0) {
        ctx->iv = malloc(iv_size);
        RAND_bytes(ctx->iv, iv_size);
    }

    if (EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_SET_IVLEN, iv_size) <= 0) {
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, ctx->key, ctx->iv) <= 0) {
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    return ctx;
}
