typedef struct {
    sem_t semaphore;
    void* resource;
} SemaphoreResource;

SemaphoreResource* create_semaphore(int initial_value) {
    SemaphoreResource *sem = mmap(NULL, sizeof(SemaphoreResource), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    sem_init(&sem->semaphore, 0, initial_value);
    return sem;
}

void delete_semaphore(SemaphoreResource* sem) {
    munmap((void*)sem, sizeof(SemaphoreResource));
}

void allocate_resource(SemaphoreResource* sem) {
    if (sem->resource == NULL) {
        // Call external API to allocate a resource and store it in sem->resource
        sem->resource = external_allocate_resource();
    }
    sem_post(&sem->semaphore);
}

void deallocate_resource(SemaphoreResource* sem) {
    if (sem->resource != NULL) {
        // Call external API to deallocate the resource stored in sem->resource
        external_deallocate_resource(sem->resource);
        sem->resource = NULL;
        sem_wait(&sem->semaphore);
    }
}
