namespace highPerformanceSimulationTool {

class RandomNumberGenerator {
public:
    explicit RandomNumberGenerator(unsigned long long seed) : m_mt((seed + std::chrono::system_clock::now().time_since_epoch().count())), m_mutex() {}
    ~RandomNumberGenerator() {}

    static RandomNumberGenerator& getInstance() {
        static RandomNumberGenerator instance;
        return instance;
    }

    int generate() {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_condition.wait(lock, [this](){return m_readyToGenerate; });
