    {
        _config = config;
        _envVarName = _config["EnvironmentVariableName"];
    }

    public XmlElement GetXmlElementByName(string xpathExpression)
    {
        var xmlDocument = new XmlDocument();
        xmlDocument.Load("your_xml_file.xml");
        return xmlDocument.SelectSingleNode(xpathExpression);
    }

    [MethodImpl(MethodImplOptions.Synchronized)] // Synchronizes method invocation to ensure thread-safety
    public void CreateDirectoryAndSetEnv(string directoryName)
    {
        lock (_lockObj)
        {
            if (Environment.GetEnvironmentVariable(_envVarName) != null)
            {
                _envVarPath = Environment.GetEnvironmentVariable(_envVarName);
            }
            else
            {
                var appData = Directory.CreateDirectory(Path.Combine(_config["AppDataRoot"], directoryName));
                _envVarPath = appData.FullName;
                Environment.SetEnvironmentVariable(_envVarName, _envVarPath);
            }
        }
    }
}
```

