                (async () => {
                    try {
                        await f[key]();
                        console.log(`Test ${testName} passed!`);
                    } catch (error) {
                        console.error(`Test ${testName} failed: ${error}`);
                    } finally {
                        // Reset blueslip after the asynchronous operations have completed
                        blueslip.reset();
                    }
                })();
