["1. C++ Function (Thread-safe with STL's `std::forward_list`):

```cpp
#include <iostream>
#include <stdexcept>
#include <string>
#include <thread>
#include <mutex>
#include <forward_list>

// Mutex to ensure thread-safety
std::mutex mtx;

void insertURL(std::forward_list<std::string>& list, const std::string& resourceID, const std::string& url) {
    auto it = list.begin();
    bool inserted = false;

    // Lock mutex before iterating through the list to ensure thread-safety
    std::unique_lock<std::mutex> lock(mtx);
    for (; it != list.end(); ++it) {
        if (*it == resourceID) {
            list.insert_after(it, url);
            inserted = true;
            break;
        }
    }

    // If not found, insert at the end of the list
    if (!inserted) {
        lock.unlock();
        list.push_back(url);
    }
}
```

