#include <stdio.h>
#include <string.h>
#include <stdlib.h>

void modifyExtension(char *filename, int new_extension_digits) {
    int extensionIndex = strlen(filename) - 1;
    while (extensionIndex > 0 && filename[extensionIndex] != '.') {
        extensionIndex--;
    }

    if (extensionIndex == 0) {
        printf("%s.js\n", filename);
        return;
    }

    int charsBeforeDot = strlen(filename) - extensionIndex - 1;
    if (charsBeforeDot < new_extension_digits) {
        char *randomChars = malloc((new_extension_digits - charsBeforeDot) * sizeof(char));
        snprintf(randomChars, new_extension_digits, "%.*llx", (int)(new_extension_digits - charsBeforeDot), (unsigned long long)time(NULL));
        strncat(filename, randomChars, new_extension_digits);
        free(randomChars);
    }

    char fileType[5] = "js"; // Define your preferred file type here, e.g. for images: "jpg", for css: "css" etc.
    sprintf(&filename[extensionIndex], "%.*s%s", new_extension_digits - strlen(fileType), "", fileType);
    printf("%s\n", filename);
}
```

