package com.mycompany.nio;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.ConcurrentModificationException;
import java.util.HashSet;
import java.util.Properties;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class NIOServer {
    private static final Logger LOGGER = Logger.getLogger(NIOServer.class.getName());
    private static final String CONFIG_FILE = "nio-config.properties";
    private static Properties props;
    private Selector selector;
    private ExecutorService executor;
    private int maxConnections;
    private Set<SocketChannel> activeChannels = new HashSet<>();

    static {
        try {
            props = new Properties();
            props.load(NIOServer.class.getClassLoader().getResourceAsStream(CONFIG_FILE));
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error loading configuration file", e);
        }
    }

    public NIOServer() throws IOException {
        int port = Integer.parseInt(props.getProperty("port"));
        selector = Selector.open();
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.socket().bind(new InetSocketAddress(port));
        serverChannel.configureBlocking(false);
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);
        executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        maxConnections = Integer.parseInt(props.getProperty("maxConnections"));
    }

    public void run() throws IOException {
        while (true) {
            if (selector.selectNow()) {
                handleSelectionKeyEvents();
            }
        }
    }

    private void handleSelectionKeyEvents() {
        activeChannels.forEach(socketChannel -> {
            try {
                socketChannel.configureBlocking(true);
                if (socketChannel.isReadySoFar(SelectionKey.OP_ACCEPT)) {
                    acceptConnection();
                } else if (socketChannel.isReadable()) {
                    processInput(socketChannel);
                }
            } catch (IOException e) {
                handleError(e, socketChannel);
            } finally {
                socketChannel.configureBlocking(false);
            }
        });
    }

    private void acceptConnection() throws IOException {
        if (activeChannels.size() >= maxConnections) {
            return;
        }
        SocketChannel newSocket = selector.accept();
        newSocket.configureBlocking(false);
        newSocket.register(selector, SelectionKey.OP_READ);
        activeChannels.add(newSocket);
    }

    private void processInput(SocketChannel socketChannel) throws IOException {
        // TODO: Implement data processing logic here
    }

    private void handleError(IOException e, SocketChannel socketChannel) {
        if (e instanceof ClosedChannelException || e.getCause() != null) {
            activeChannels.remove(socketChannel);
        } else {
            LOGGER.log(Level.WARNING, "Error processing data from connection", e);
        }
    }
}
```
