import java.util.*;
import java.util.concurrent.*;
import com.fasterxml.jackson.databind.*;
import okhttp3.*;

public class ServiceManager {
    private ExecutorService executor;
    private ScheduledExecutorService scheduler;
    private OkHttpClient httpClient;
    private ObjectMapper mapper;

    private Map<Integer, ServiceInstance> instances = new ConcurrentHashMap<>();
    private final int maxInstances;
    private final Duration minDelay, maxDelay;
    private final String messagingUrl;
    private final MonitoringSystem monitoringSystem;

    public ServiceManager(int maxInstances, Duration minDelay, Duration maxDelay, String messagingUrl, MonitoringSystem monitoringSystem) {
        this.maxInstances = maxInstances;
        this.minDelay = minDelay;
        this.maxDelay = maxDelay;
        this.messagingUrl = messagingUrl;
        this.monitoringSystem = monitoringSystem;

        executor = Executors.newFixedThreadPool(maxInstances);
        scheduler = Executors.newScheduledThreadPool(10);
        httpClient = new OkHttpClient();
        mapper = new ObjectMapper();
    }

    public void start() {
        for (int i = 0; i < maxInstances && instances.size() < maxInstances; i++) {
            final int id = i;
            scheduler.scheduleWithFixedDelay(() -> {
                if (!instances.containsKey(id)) {
                    ServiceInstance si = new ServiceInstance(id);
                    instances.put(id, si);
                    startService(si);
                }
            }, randomDelay(), randomDelay(), TimeUnit.MILLISECONDS);
        }
    }

    private Duration randomDelay() {
        return new Random().ints((int) maxDelay.getSeconds()), (int) minDelay.getSeconds())
                .filter(i -> i > 0)
                .findFirst()
                .mapToObj(Duration::ofMillis)
                .orElse(Duration.ZERO);
    }

    private void startService(ServiceInstance si) {
        Runnable task = () -> {
            try {
                si.start();
                successCount(si.getId(), 1);
                monitoringSystem.updateStatus(si, ServiceStatus.STARTED);
            } catch (Exception e) {
                errorCount(si.getId(), 1);
                monitoringSystem.updateError(si, e);
            }
        };
        executor.submit(task);
    }

    private void stopService(int id) {
        ServiceInstance si = instances.get(id);
        if (si != null) {
            si.stop();
            successCount(si.getId(), -1);
            monitoringSystem.updateStatus(si, ServiceStatus.STOPPED);
        }
    }

    private void successCount(int id, int value) {
        AtomicInteger counter = instances.computeIfAbsent(id, k -> new AtomicInteger(0));
        counter.addAndGet(value);
    }

    private void errorCount(int id, int value) {
        AtomicInteger counter = instances.computeIfAbsent(id, k -> new AtomicInteger(0));
        counter.addAndGet(-value);
    }

    // Implement MessagingService class with methods sendStartMessage and sendStopMessage

    public void sendMonitoringData() {
        List<Map<String, Object>> dataList = instances.values().stream()
                .map(si -> ImmutableMap.<String, Object>of("id", si.getId(), "successCount", si.getSuccessCount(), "errorCount", si.getErrorCount()))
                .collect(Collectors.toList());
        String json = mapper.writeValueAsString(dataList);

        RequestBody body = RequestBody.create(MediaType.APPLICATION_JSON, json);
        Request request = new Request.Builder()
                .url(messagingUrl)
                .post(body)
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                monitoringSystem.logError("Failed to send monitoring data: " + response);
            }
        } catch (IOException e) {
            monitoringSystem.logError("Failed to send monitoring data", e);
        }
    }
}

class ServiceInstance {
    private final int id;
    private volatile AtomicInteger successCount = new AtomicInteger(0);
    private volatile AtomicInteger errorCount = new AtomicInteger(0);

    public ServiceInstance(int id) {
        this.id = id;
    }

    public void start() throws Exception {
        // Implement service startup logic here
    }

    public void stop() throws Exception {
        // Implement service shutdown logic here
    }

    public int getId() {
        return id;
    }

    public AtomicInteger getSuccessCount() {
        return successCount;
    }

    public AtomicInteger getErrorCount() {
        return errorCount;
    }
}
