["```javascript
const crypto = require('crypto');
const fs = require('fs');
const stream = require('stream');
const { pipeline } = require('stream/promises');

function oauthRequestHandler(request) {
    const privateKeyPath = request.metadata.private_key_path;
    const certificatePath = request.metadata.certificate_path;

    // Create PEM file from private key and certificate files
    async function combinePemFiles(privateFile, certificateFile, outputFile) {
        let privateKey = '';
        let certificate = '';

        const privateKeyStream = fs.createReadStream(privateFile);
        const certificateStream = fs.createReadStream(certificateFile);

        privateKeyStream.on('data', (chunk) => {
            privateKey += chunk.toString();
        });

        certificateStream.on('data', (chunk) => {
            certificate += chunk.toString();
        });

        privateKeyStream.on('end', () => {
            fs.writeFileSync(outputFile, `--- BEGIN RSA PRIVATE KEY ---\n${privateKey}\n--- END RSA PRIVATE KEY ---`);
        });

        certificateStream.on('end', () => {
            fs.appendFileSync(outputFile, '\n\n---\n--- BEGIN CERTIFICATE ---\n' + certificate + '\n--- END CERTIFICATE ---');
        });
    }

    // Validate integrity of fetched files using SHA256 hash
    function validateIntegrity(filePath) {
        const hashedContent = crypto.createHash('sha256').updateFileSync(filePath);
        return hashedContent === request.metadata.expected_hash;
    }

    let dataArray = [];

    // Function to fetch and process OAuth request data
    async function processRequest() {
        if (!validateIntegrity(privateKeyPath) || !validateIntegrity(certificatePath)) {
            console.error('Invalid or corrupted files found.');
            return;
        }

        await combinePemFiles(privateKeyPath, certificatePath, request.metadata.pem_file_path);

        const pemFileStream = fs.createReadStream(request.metadata.pem_file_path);

        // Create a Writable stream to save data to array
        const dataWriter = new stream.Writable({
            objectMode: true,
            write(chunk, encoding, callback) {
                dataArray.push(chunk);
                callback();
            },
            finalCallback() {
                console.log('Data saved to array.');
            }
        });

        // Read from the PEM file stream and pipe it into the Writable stream
        await pipeline(pemFileStream, dataWriter);
    }

    if (request.pause) {
        request.unpause = () => processRequest();
    } else {
        processRequest().catch((error) => console.error(`Error processing request: ${error}`));
    }
}
```
This JavaScript function handles OAuth requests, fetches the private key and certificate files based on their paths provided in the metadata, validates their integrity using SHA256 hash, combines them into a single PEM file, and saves the data from the PEM file to an array. The function also offers pause and resume functionality by returning a resume function when `request.pause` is true. Additionally, it handles potential errors gracefully and optimizes for performance when dealing with large files or high-frequency requests."]

