        $this->oauthClient = $oauthClient;
        $this->session = $session;
        $this->dnsResolver = $dnsResolver;
    }

    /**
     * Authenticates a user using an OAuth 2.0 client, stores the access token in a session variable, and retrieves user information.
     */
    public function authenticateUser($username, $password) {
        // Perform authentication (using given OAuth client) and get access token
        $accessToken = $this->oauthClient->authenticate($username, $password);

        // Store the access token in a session variable
        $this->session->set('access_token', $accessToken);

        // Retrieve user information using the access token
        return $this->getUserInfo();
    }

    /**
     * Gets user information using the stored access token. Caches the result for performance.
     */
    private function getUserInfo() {
        if (!isset($this->cache[$this->session->get('access_token')])) {
            // API call to retrieve user info using stored access token
            $userInfo = $this->oauthClient->getUserInfo();
            $this->cache[$this->session->get('access_token')] = $userInfo;
        }

        return $this->cache[$this->session->get('access_token')];
    }

    /**
     * Resolves a given hostname to IP address using the standard library functions.
     */
    public function resolveHostname($hostname) {
        try {
            // DNS resolution for given hostname
            $ipAddress = gethostbyname($hostname);
        } catch (Exception $e) {
            return -1; // Error code for DNS resolution failure
        }

        // Convert IP address to u_char array
        $ipArray = unpack('C4', pack('H*', $ipAddress));

        return $ipArray;
    }
}
