            std::cout << "Character ID: " << id_ << ", Attack: " << selectedAttack_ << std::endl;
        }
    }

private:
    int id_;
    long cooldownTimer_;
    int selectedAttack_;
    std::mutex mtx_;
    std::unordered_map<int, LockFreeCounter> hits_{0, 0, 1, 0};
};

class LockFreeCounter {
public:
    void increment() {
        for (;;) {
            auto current = value_.load();
            auto next = current + 1;
            if (value_.compare_exchange_weak(current, next))
                break;
        }
    }

private:
    std::atomic<int> value_;
};

void randomAttack() {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> dis(0, 999);

    Character* charArray[1000]; // Initialize array of characters

    for (int i = 0; i < 1000; ++i) {
        charArray[i] = new Character(i);
    }

    while (true) {
        std::unique_lock<std::mutex> lock(mtx_);
        int randomCharIndex = dis(gen);
        auto now = std::chrono::steady_clock::now();

        if (charArray[randomCharIndex]->cooldownTimer_ <= now) {
            charArray[randomCharIndex]->Attack();
        }

        lock.unlock();
        std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Simulate external content updates delays or inconsistencies
    }
}
```
This solution uses a `Character` class to handle cooldowns for each character and ensures thread safety using a mutex. The `LockFreeCounter` class is used to count the number of times an attack is selected without affecting performance when handling many characters. This solution assumes that you have an existing game engine structure in place, and it can be integrated into it with minimal changes.']

