    {
        minValue = min;
        maxValue = max;
        stepSize = step;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}] with Step Size: {stepSize}";
    }

