    {
        int rangeStart = (int)Math.Ceiling(minValue / stepSize) * stepSize;
        int rangeEnd = (int)Math.Floor((maxValue + 1) / stepSize) * stepSize;
        return UnityEngine.Random.Range(rangeStart, rangeEnd);
    }

    // Method to validate the generated value within the given constraints
