void* parse_line(const void *line) {
    char *token, *temp = strdup((char *) line);
    Section *current_section = NULL;

    if (strchr(temp, '[') && strchr(temp, ']')) {
        current_section = malloc(sizeof(Section));
        current_section->name = strtok(temp, "=");
        current_section->length = strlen(current_section->name);
        current_section->keys = calloc(1, sizeof(char*));
        section_count++;
    }

    token = strtok(temp, "= ");
    if (token) {
