int load_config(const char *path) {
    int config_file, line_count = 0;
    size_t length = 0;
    char buffer[4096];
    ssize_t bytes_read;

    struct stat st;
    if (stat(path, &st) == -1) return -1;

    config_file = open(path, O_RDONLY);
    if (config_file == -1) return -1;

    pthread_t threads[st.st_size];
    while ((bytes_read = read(config_file, buffer, sizeof(buffer))) > 0) {
        line_count += bytes_read / sizeof(char);
        for (int i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                pthread_create(&threads[line_count], NULL, parse_line, buffer + i + 1);
                break;
            }
        }
    }

    close(config_file);

    for (int i = 0; i < line_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    Section **sections = malloc(section_count * sizeof(Section*));
    int index = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < section_count; ++i) {
        sections[index++] = current_section;
    }
    pthread_mutex_unlock(&mutex);

    free(current_section->name);
    free(current_section->keys);
    free(current_section);

    return section_count;
}
