#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct String {
    char *str;
    size_t length;
    size_t capacity;
} String;

String string_new(size_t capacity) {
    String str = {NULL, 0, capacity};
    if (capacity > 0)
        str.str = malloc(capacity * sizeof(char));
    return str;
}

void string_reserve(String *s, size_t n) {
    char *newStr = realloc(s->str, n);
    if (newStr != NULL) {
        s->str = newStr;
        s->capacity = n;
    } else {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
}

void string_push(String *s, char c) {
    if (s->length == s->capacity)
        string_reserve(s, 2 * s->capacity);
    s->str[s->length++] = c;
    s->str[s->length] = '\0';
}

String string_slice(const String src, size_t start, size_t length) {
    String dst = string_new(length + 1);
    memcpy(dst.str, &src.str[start], length);
    dst.length = length;
    return dst;
}

char *string_to_c_string(String s) {
    char *result = malloc((s.length + 1) * sizeof(char));
    memcpy(result, s.str, (s.length + 1) * sizeof(char));
    return result;
}

char *safe_concat(const String str1, const String str2) {
    size_t totalLength = str1.length + str2.length;
    string_reserve(&str1, totalLength);
    memcpy(&str1.str[str1.length], str2.str, str2.length * sizeof(char));
    str1.length += str2.length;
    return string_to_c_string(str1);
}

char *string_with_slash_if_possible(const char *input, size_t limit) {
    String s = string_new(limit + 1);
    for (size_t i = 0; i < strlen(input) && i < limit; ++i)
        string_push(&s, input[i]);
    if (strlen(input) < limit)
        string_push(&s, '/');
    return string_to_c_string(s);
}

