```javascript
function traverseDOMTree(root, selector, callback) {
  const stack = [root];
  const matchedElements = [];

  if (!root || !selector || !callback) return matchedElements;

  while (stack.length > 0) {
    const currentNode = stack.pop();

    if (currentNode.matches && currentNode.matches(selector)) {
      callback(currentNode);
      matchedElements.push(currentNode);
    }

    if (!currentNode.childNodes || !currentNode.childNodes.length) continue;

    for (let i = currentNode.childNodes.length - 1; i >= 0; --i) {
      stack.push(currentNode.childNodes[i]);
    }
  }

  return matchedElements;
}
