        Setting *setting = malloc(sizeof(Setting));
        setting->key = strtok(line, "=");
        setting->value = strtok(NULL, "\n");
        settings_array[lines++] = setting;
    }
    fclose(file);

    *settings = malloc((lines + 1) * sizeof(Setting*));
    memcpy(*settings, settings_array, lines * sizeof(Setting*));
