#include <stdio.h>
#include <stdlib.h>
#include <tiffio.h>
#include <string.h>
#include <openssl/md5.h>
#include <curl/curl.h>
#include <json-c/json.h>

typedef struct {
    unsigned short bits_per_sample;
    unsigned short sample_per_pixel;
    unsigned short extra_samples;
    unsigned long sample_info[8]; // Assuming up to 8 samples per image
    char md5[MD5_DIGEST_LENGTH];
    char *metadata;
} TiffInfo;

TiffInfo parse_tiff(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return (TiffInfo){0};
    }

    uint16_t photometric;
    if (TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &photometric) != 1) {
        fprintf(stderr, "Error getting PhotometricInterpretation tag\n");
        TIFClose(tif);
        return (TiffInfo){0};
    }

    uint16_t bits_per_sample = 0;
    for (int i = 0; i < tiff.imageDescription.numberOfImages; ++i) {
        if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample) != 1 ||
            (bits_per_sample != 1 && bits_per_sample != 2 &&
             bits_per_sample != 4 && bits_per_sample != 8 &&
             bits_per_sample != 16)) {
            fprintf(stderr, "Unsupported number of bits per sample\n");
            TIFClose(tif);
            return (TiffInfo){0};
        }

        uint16_t samples_per_pixel = 0;
        if (TIFFGetField(tif, TIFFTAG_SAMPLESperpixel, &samples_per_pixel) != 1) {
            fprintf(stderr, "Error getting SamplesPerPixel tag\n");
            TIFClose(tif);
            return (TiffInfo){0};
        }

        if (samples_per_pixel > 4) {
            TIFFWarning(tif, "More than 4 samples per pixel is not supported");
            continue;
        }

        TiffInfo info = {};
        info.bits_per_sample = bits_per_sample;
        info.sample_per_pixel = samples_per_pixel;
        info.extra_samples = tiff.imageDescription.numberOfImages - 1;

        for (int j = 0; j < samples_per_pixel; ++j) {
            char sample_name[MAXSAMPLENAME];
            if (TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT, sample_name, sizeof(sample_name)) != 1) {
                fprintf(stderr, "Error getting SampleFormat tag\n");
                TIFClose(tif);
                return (TiffInfo){0};
            }

            info.sample_info[j] = TIFFGetField(tif, TIFFTAG_SAMPLEVALUE, NULL);
        }

        // Compute MD5 hash of the user-provided string using OpenSSL library
        char *user_input = "User Input"; // Replace with actual user input
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)user_input, strlen(user_input), md5_hash);
        memcpy(info.md5, md5_hash, sizeof(md5_hash));

        // Integrate with an external metadata extraction service (using libcurl and json-c)
        CURL *curl;
        CURLcode res;
        char *metadata_json = NULL;
        size_t metadata_len = 0;

        curl = curl_easy_init();
        if(curl) {
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");

            json_object *metadata_obj = json_object(); // Replace with actual metadata object
            char *metadata_str = json_object_to_json_string(metadata_obj);

            curl_easy_setopt(curl, CURLOPT_URL, "http://metadata-service.com");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, metadata_str);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                fprintf(stderr, "Error getting metadata: %s\n", curl_easy_strerror(res));
                curl_free(curl);
                return (TiffInfo){0};
            }

            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
            if (res != HTTP_OK) {
                fprintf(stderr, "Error response from metadata service: %d\n", res);
                curl_free(curl);
                return (TiffInfo){0};
            }

            curl_easy_getinfo(curl, CURLINFO_RESPONSE_LENGTH_EXPECTED, &metadata_len);
            metadata_json = malloc(metadata_len);
            res = curl_easy_read(curl, metadata_json, metadata_len, NULL);
            if (res != CURLE_OK) {
                fprintf(stderr, "Error reading metadata response: %s\n", curl_easy_strerror(res));
                curl_free(curl);
                return (TiffInfo){0};
            }

            curl_free(curl);

            // Parse the JSON metadata string using json-c library
            info.metadata = malloc(sizeof(json_object*) * metadata_obj->member_count + 1);
            for (int i = 0; i < metadata_obj->member_count; ++i) {
                char *key = json_object_get_name(metadata_obj->members[i]);
                info.metadata[i] = json_object_get_obj(metadata_obj, key);
            }
        }

        TIFClose(tif);
        return info;
    }
}
```

