   #define MAX_FILENAME_LENGTH 255

   void modify_filename(char *filename) {
       char new_filename[MAX_FILENAME_LENGTH];
       char keyword[] = "config";
       int digit_count = 0;
       size_t filename_len = strlen(filename);
       size_t new_filename_len = 0;

       // Determine digit count based on filename length, excluding extensions and spaces
       for (int i = 0; i < filename_len; ++i) {
           if (!isspace(filename[i]) && filename[i] != '.') {
               ++digit_count;
           }
       }

       // Check for keywords in filename, regardless of case
       for (int i = 0; keyword[i]; ++i) {
           if ((filename_len - i < strlen(keyword)) ||
               (memcmp(&filename[i], keyword, strlen(keyword)) != 0)) {
               break;
           }

           // If keyword found, set new file type based on keyword
           strncpy(&new_filename[new_filename_len], "type1", sizeof("type1") - 1);
           new_filename_len += strlen(new_filename + new_filename_len);
           break;
       }

       if (strlen(keyword) == 0) {
           // If no keyword found, set new file type based on default
           strncpy(&new_filename[new_filename_len], "type2", sizeof("type2") - 1);
           new_filename_len += strlen(new_filename + new_filename_len);
       }

       // Copy the rest of the original filename to the new file name
       for (int i = 0; i < filename_len && new_filename_len < MAX_FILENAME_LENGTH - 1; ++i) {
           if (!isspace(filename[i]) && (filename[i] != '.' || digit_count > 0)) {
               new_filename[new_filename_len++] = filename[i];
           }
       }

       // Add digits to new file name
       sprintf(&new_filename[new_filename_len], "%0*d", digit_count, 3);

       // Add file type to new file name
       strcat(new_filename, ".txt");
   }
