    if (!EVP_PKEY_set1_RSA(rsa_with_sha1, RSA_size(), NULL)) {
        perror("Failed to create RSA key with SHA1");
        return;
    }
    if (!EVP_PKEY_assign_digest(rsa_with_sha1, EVP_sha1())) {
        perror("Failed to assign digest to RSA key");
        return;
    }

    for (unsigned int i = 0; i < EVP_nids_count(); ++i) {
        const char* name = EVP_get_cipherbyid(EVP_ID(i));
        if (!name) continue; // Skip non-ciphers and non-digests

        int id = EVP_ID(i);
        bool is_cipher = strncmp(name, "evp_", 4) == 0 && name[4] != '\0';

