            if (EVP_add_cipher(name)) {
                ++primitive_counts[id];
                if (primitive_counts[id] > max_primitive_count) {
                    syslog(LOG_ERR, "Exceeded maximum number of AES or Camellia instances: %s", name);
                }
            } else {
                perror("Failed to add cipher");
                return;
            }
        } else if (strncmp(name, "evp_md", 5) == 0 || strncmp(name, "EVP_sha", 5) == 0) {
            if (EVP_add_digest(name)) {
                ++primitive_counts[id];
                if (primitive_counts[id] > max_primitive_count) {
                    syslog(LOG_ERR, "Exceeded maximum number of digest instances: %s", name);
                }
            } else {
                perror("Failed to add digest");
                return;
            }
        } else if (strcmp(name, "EVP_PKEY_RSA") == 0) {
            if (!EVP_add_digest_alias("rsa_sha1", EVP_sha1(), rsa_with_sha1)) {
                perror("Failed to add RSA with SHA1");
