import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CustomShellCommand {
    private static final String COMMAND_FORMAT = "cmd %s";
    private static final int BUFFER_SIZE = 1024;

    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: java CustomShellCommand [command]");
            return;
        }

        String command = String.format(COMMAND_FORMAT, args[0]);
        Path directoryPath = Paths.get(command.split(" ")[0]);

        ExecutorService executor = Executors.newSingleThreadExecutor();
        Runnable deleteDirectoryTask = () -> {
            if (Files.exists(directoryPath)) {
                try {
                    Files.walkFileTree(directoryPath, new RecursiveAction() {
                        @Override
                        protected void postVisit(Path file) throws IOException {
                            Files.delete(file);
                        }
                    });
                    Files.deleteIfExists(directoryPath);
                } catch (IOException e) {
                    System.err.println("Error deleting directory: " + e.getMessage());
                }
            }
        };
        executor.submit(deleteDirectoryTask);

        Process process;
        try {
            process = Runtime.getRuntime().exec(command, null, new File(command.split(" ")[0]));
        } catch (IOException e) {
            System.err.println("Error executing command: " + e.getMessage());
            return;
        }

        BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        Thread inputThread = new Thread(() -> {
            try {
                String line;
                while ((line = inputReader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                System.err.println("Error reading output stream: " + e.getMessage());
            }
        });
        Thread errorThread = new Thread(() -> {
            try {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    System.err.println(line);
                }
            } catch (IOException e) {
                System.err.println("Error reading error stream: " + e.getMessage());
            }
        });

        inputThread.start();
        errorThread.start();

        int exitCode;
        try {
            exitCode = process.waitFor();
        } catch (InterruptedException e) {
            System.err.println("Error waiting for process to finish: " + e.getMessage());
            exitCode = -1;
        }

        executor.shutdownNow();

        System.exit(exitCode);
    }
}
```

This code handles the given programming task by:
