#include <jansson.h>
#include <time.h>
#include <stdint.h>

bool validate_oauth2_token(const char *json_str) {
    json_t *root = json_loads(json_str, 0, NULL);
    bool is_valid = json_is_object(root);

    if (!is_valid) return false;

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");
    json_t *refresh_token = json_object_get(root, "refresh_token");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) return false;

    const char *acc_tok = json_string_value(access_token);
    int expires = json_integer_value(expires_in);
    const char *tok_type = json_string_value(token_type);

    if (strcmp(tok_type, "Bearer") != 0 || expires <= 0) return false;

    time_t now = time(NULL);
    time_t expiry = now + expires;

    struct tm current_time;
    localtime_r(&now, &current_time);
    int access_token_age = difftime(now, strtol(acc_tok, NULL, 10));

    if (access_token_age > expires) return false;

    json_decref(root);
    return true;
}
```

This function uses the JSON for Modern C library (jansson) to parse the input JSON string and validate its structure. It also handles checking the current timestamp, comparing it with the token expiry time, and ensuring that the access token age is less than the expires_in value. The code assumes a unix-style timestamp format for the fields `expires_in` and `access_token`.']

