```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct State {
    int id;
    bool isFinalState;
} State;

void CreateStateList(int* states, int numStates, const FSA* fsa, int lastState, State** result)
{
    // Allocate memory for the new state list.
    *result = malloc((lastState - states[0] + 1) * sizeof(State));

    if (!*result)
    {
        perror("Memory allocation failure.");
        exit(EXIT_FAILURE);
    }

    int currentIndex = 0;
    for (int i = states[0]; i <= lastState; ++i)
    {
        State* state = &((*result)[currentIndex++]);
        state->id = i;
        bool isFinal = false;

        // Traverse the FSA to find the state's properties.
        for (int j = 0; j < fsa->numTransitions; ++j)
        {
            if (fsa->transitions[j].fromState == i)
            {
                int toState = fsa->transitions[j].toState;
                if (toState == fsa->finalStateId)
                    isFinal = true;
            }
        }

        state->isFinalState = isFinal;
    }
}
```

