using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Cryptography.Parameters;
using Org.BouncyCastle.Crypto.Engines;
using Org.BouncyCastle.Security;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class TripleDESDecryption
{
    private const int IV_LENGTH = 8;
    private const string API_URL = "https://your-api-url.com"; // Replace with your API URL

    public async Task<string> DecryptAsync(string encryptedMessage)
    {
        try
        {
            ValidateIV(encryptedMessage);

            byte[] ivBytes = GetIV(encryptedMessage);
            var decryptor = CreateTripleDESCipher(ivBytes);
            byte[] decryptedData = DecryptBase64EncodedMessage(decryptor, encryptedMessage);

            return Encoding.UTF8.GetString(decryptedData);
        }
        catch (Exception ex)
        {
            throw new ApplicationException($"Error decrypting message: {ex.Message}", ex);
        }
    }

    private void ValidateIV(string encryptedMessage)
    {
        if (GetIV(encryptedMessage).Length != IV_LENGTH)
        {
            throw new ArgumentException("Invalid IV length.");
        }
    }

    private byte[] GetIV(string encryptedMessage)
    {
        var base64Bytes = Convert.FromBase64String(encryptedMessage.Split('.')[0]);
        return new ArraySegment<byte>(base64Bytes, 0, IV_LENGTH).ToArray();
    }

    private TripleDES EngineCreate()
    {
        var engine = new TripleDESCryptoServiceProvider();
        engine.KeySize = 192;
        engine.BlockSize = 8;
        return engine;
    }

    private ICipherParameters CreateTripleDESCipher(byte[] iv)
    {
        var key = EngineCreate().Key; // Replace this with your key generation logic
        var parameters = new ParametersWithIV(new TripleDESCryptoServiceProvider(), key, iv);
        return parameters;
    }

    private byte[] DecryptBase64EncodedMessage(ICipherParameters param, string message)
    {
        var dataWithoutPadding = RemovePadding(message);
        var decryptedData = new TripleDESEngine().Decrypt(param, dataWithoutPadding);
        return decryptedData;
    }

    private byte[] RemovePadding(byte[] input)
    {
        int paddingLength = input[input.Length - 1];
        byte[] result = new byte[input.Length - paddingLength];
        Array.Copy(input, 0, result, 0, result.Length);
        return result;
    }
}
```

