```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.Extensions.Configuration;
using BCrypt.Net-Next;

public class HashFunction
{
    private readonly IConfiguration _configuration;
    private string _algorithm;

    public HashFunction(IConfiguration configuration)
    {
        _configuration = configuration;
        LoadAlgorithm();
    }

    private void LoadAlgorithm()
    {
        var config = _configuration.GetSection("HashFunction");
        if (config.GetChildren().Any())
            _algorithm = config.GetChildren().FirstOrDefault()?.Key;
        else
            throw new InvalidOperationException("Missing or incorrect configuration for hash algorithms.");
    }

    public byte[] ComputeHash(string input)
    {
        if (string.IsNullOrWhiteSpace(_algorithm))
            LoadAlgorithm();

        if (!Enum.TryParse<HashingAlgorithms>(_algorithm, out var hashingAlgorithm))
            throw new ArgumentException($"Invalid algorithm '{_algorithm}'.");

        switch (hashingAlgorithm)
        {
            case HashingAlgorithms.MD5:
                return MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(input));
            case HashingAlgorithms.SHA256:
                return SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(input));
            // Add custom algorithm support here if needed
            default:
                throw new NotSupportedException($"Algorithm '{_algorithm}' is not supported.");
        }
    }
}
```

In the code above, we create a `HashFunction` class that accepts an instance of `IConfiguration`. The constructor loads the configured hashing algorithm from the external configuration file. The `ComputeHash()` function takes a string input and returns its hash based on the loaded algorithm. It also ensures that only supported algorithms are used by parsing the algorithm name to an enumeration value.

You can define your custom hashing algorithms in the configuration file under the "HashFunction" section, like this:

```yaml
