using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace EncryptionService
{
    public class Decryptor
    {
        private readonly string _logFilePath;
        private readonly ExternalEncryptionService _api;

        public Decryptor(ExternalEncryptionService api, string logFilePath)
        {
            _api = api;
            _logFilePath = logFilePath;
        }

        public async Task<(byte[], string)> DecryptAsync(byte[] ciphertext, byte[] encryptionKey, byte[] iv)
        {
            if (ciphertext == null || encryptionKey == null || iv == null)
                throw new ArgumentNullException();

            if (ciphertext.Length < EncryptionConstants.MinimumCiphertextLength)
                throw new ArgumentOutOfRangeException("The ciphertext must have a minimum length.");

            using var aes = Aes.Create();
            aes.Key = encryptionKey;
            aes.IV = iv;

            MemoryStream encryptedDataStream = new MemoryStream(ciphertext);
            CryptoStream decryptStream = new CryptoStream(encryptedDataStream, aes.CreateDecryptor(), CryptoStreamMode.Read);

            byte[] decryptedBytes = new byte[decryptStream.ReadByte()]; // Read until EOF
            int bytesToRead = 0;
            while ((bytesToRead = decryptStream.Read(decryptedBytes, bytesToRead, decryptedBytes.Length - bytesToRead)) > 0)
            {
                Array.Resize(ref decryptedBytes, decryptedBytes.Length + bytesToRead);
            }

            byte[] plaintextWithoutPadding;
            try
            {
                plaintextWithoutPadding = RemovePadding(decryptedBytes);
            }
            catch (Exception ex)
            {
                LogError(_logFilePath, ex);
                return (null, $"Decryption failed due to incorrect padding.");
            }

            try
            {
                plaintextWithoutPadding = _api.Decrypt(plaintextWithoutPadding); // Use external service API for decryption if needed
            }
            catch (JsonReaderException ex) when (ex.Message.Contains("Unexpected end of JSON input"))
            {
                LogError(_logFilePath, ex);
                return (null, "Decryption failed due to incorrect data format.");
            }
            catch (Exception ex)
            {
                if (ex.Message.Contains("Rate limiting") || ex.Message.Contains("Service unavailable"))
                {
                    LogError(_logFilePath, ex);
                    return (null, "Decryption temporarily failed due to external service issue.");
                }
                else
                {
                    LogError(_logFilePath, ex);
                    return (null, $"Decryption failed unexpectedly: {ex.Message}");
                }
            }

            return (plaintextWithoutPadding, null);
        }

        private byte[] RemovePadding(byte[] data)
        {
            int paddingLength = data[data.Length - 1];
            if (paddingLength > data.Length || paddingLength < 1)
                throw new CryptographicException("Invalid padding length.");

            return data.Take(data.Length - paddingLength).ToArray();
        }

        private void LogError(string logFilePath, Exception ex)
        {
            var logSettings = ConfigurationManager.GetSection("Logging"); // Configure logging based on environment (e.g., console, file)
            var loggerType = logSettings["LoggerType"]; // E.g., FileLogger, ConsoleLogger
            dynamic logger = Activator.CreateInstance(Type.GetType(loggerType));
            logger.Initialize(_logFilePath);
            logger.LogException(ex);
        }
    }
}
