typedef struct record {
    int value;
    int* key;
};

int init_records(size_t offsets_size, size_t keys_size, size_t records_size, FILE* file) {
    long *offsets = pj_malloc(offsets_size * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets.\n");
        return 1;
    }

    int *keys = pj_malloc(keys_size * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys.\n");
        pj_free(offsets);
        return 1;
    }

    record *records = pj_malloc(records_size * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        pj_free(keys);
        pj_free(offsets);
        return 1;
    }

    srand(time(NULL));

    // Ensure bounds checking
    for (size_t i = 0; i < records_size; ++i) {
        records[i].value = rand() % INT_MAX;
        records[i].key = keys + (rand() % keys_size);

        offsets[*records[i].key] = i;
    }

    // Print the contents of the records array after initialization
    printf("Contents of the records array:\n");
    for (size_t i = 0; i < records_size; ++i) {
        printf("Key: %d, Value: %d\n", *records[i].key, records[i].value);
    }

    // Upload the file specified by the given FILE* 'file' and return the URL of the uploaded file
    // (Implement this with your chosen library)

    pj_free(keys);
    pj_free(offsets);
    return 0;
}
