import { execCommand } from './exec-command'; // Assuming you have a separate module for the shell command execution
import axios from 'axios'; // For API requests

const SHELL_COMMAND_FUNCTION_KEY = 'shellCommandFunction';

function useShellCommand(initialValue) {
  const [command, setCommand] = React.useState(initialValue);
  const [output, setOutput] = React.useState('');
  const [error, setError] = React.useState(null);

  async function handleExecute() {
    try {
      let data;
      // Fetch external data if required
      if (/\bget|fetch\b/i.test(command)) {
        data = await axios.get(`https://api.example.com/${command}`)
          .catch((err) => {
            console.error('API error:', err);
            setError('Error fetching data from the API.');
          });
      }

      if (data) {
        const result = await execCommand(command, data); // Execute shell command with fetched data if applicable

        if (result.error) {
          console.error('Shell command error:', result.error);
          setError(result.error);
        } else {
          setOutput(result);
        }
      }
    } catch (err) {
      console.error('Unhandled error:', err);
      setError('An unhandled error occurred while executing the command.');
    }
  }

  return { command, output, error, handleExecute };
}
```

