// Mutex to safely access and modify environment variables across concurrent operations
static ENV: Mutex<EnvMap> = Mutex::new(EnvMap::new());

// A struct to store environment variables
struct EnvMap {
    paths: Vec<String>,
}

impl EnvMap {
    fn new() -> Self {
        EnvMap { paths: vec![] }
    }

    fn insert(&mut self, key: &str, value: &str) {
        if !self.paths.iter().any(|path| path == value) {
            self.paths.push(value.to_string());
        }
    }
