#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    uint64_t mac_ce;
    pthread_t tid;
} LTE_MAC_Config;

union set {
    int data;
    struct {
        int rank;
        int parent;
    } u;
};

struct rw_lock {
    pthread_rwlock_t lock;
    size_t size;
};

void init_set(union set *s, size_t n) {
    s->data = calloc(n, sizeof(union set));
    for (size_t i = 0; i < n; ++i) {
        s[i].u.rank = 0;
        s[i].u.parent = i;
    }
}

int find(union set *s, size_t i) {
    if (s[i].u.rank == 0) return i;
    return (s[i].u.parent != i) ? (s[i].u.parent = find(s, s[i].u.parent)) : i;
}

void union_sets(union set *s, size_t x, size_t y) {
    x = find(s, x);
    y = find(s, y);
    if (x == y) return;
    if (s[x].u.rank < s[y].u.rank) {
        s[x].u.parent = y;
        s[y].u.rank++;
    } else {
        s[y].u.parent = x;
        s[x].u.rank++;
    }
}

LTE_MAC_Config* create_lte_config(uint64_t mac_ce) {
    LTE_MAC_Config *config = (LTE_MAC_Config*)malloc(sizeof(LTE_MAC_Config));
    config->mac_ce = mac_ce;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    config->tid = pthread_create(&config->tid, &attr, NULL, NULL);
    return config;
}

void delete_lte_config(LTE_MAC_Config **config) {
    if (*config != NULL) {
        free(*config);
        *config = NULL;
    }
}

void filter_configs(LTE_MAC_Config **head, uint64_t mac_ce_type) {
    LTE_MAC_Config *current = *head;
    LTE_MAC_Config *next;
    while (current != NULL) {
        if (current->mac_ce & mac_ce_type) {
            next = current->next;
            delete_lte_config(&current);
            current = next;
        } else {
            next = current->next;
            current = next;
        }
    }
}

int check_disjoint(union set *s, size_t n, int *arr) {
    struct rw_lock lock;
    pthread_rwlock_init(&lock.lock, NULL);
    lock.size = n;

    unsigned long long start = clock_gettime(CLOCK_MONOTONIC, NULL).tv_nsec / 1000000;

    for (size_t i = 0; i < n; ++i) {
        size_t root_x = find(s, arr[2*i]);
        size_t root_y = find(s, arr[2*i+1]);
        union_sets(s, root_x, root_y);
    }

    unsigned long long end = clock_gettime(CLOCK_MONOTONIC, NULL).tv_nsec / 1000000;
    printf("Time taken: %lld milliseconds\n", (end - start));

    return 0;
}
```

