// Function to read a line from the CSV file and store its content into the given arrays
void readCSVLine(char** offset, int* key, double* value, int* int_value, double* float_value, char** string_value, FILE* file) {
    char line[1024], *token;
    if (fgets(line, sizeof(line), file)) {
        token = strtok(line, ","); // offset
        *offset = malloc(strlen(token) + 1);
        strcpy(*offset, token);

        token = strtok(NULL, ","); // key
        *key = atoi(token);

        token = strtok(NULL, ","); // value
        *value = atof(token);

        token = strtok(NULL, ","); // int_value
        *int_value = atoi(token);

        token = strtok(NULL, ","); // float_value
        *float_value = atof(token);

        char* temp = malloc(strlen(token) + 1);
        strcpy(temp, token);

        while ((token = strtok(NULL, ",")) != NULL) { // string_value
            int len = strlen(token) + 1;
            *string_value = realloc(*string_value, len + (*len + 1));
            strcpy(*string_value + strlen(*string_value), token);
            (*len) += strlen(token) + 1;
        }
    }
}

// Function to allocate memory for an array of dataRecord structures and read the CSV file into it
void readCSVFile(int size, dataRecord** records, FILE* file) {
    *records = malloc(size * sizeof(dataRecord));

    for (int i = 0; i < size; ++i) {
        readCSVLine(&(*records)[i].offset, &(*records)[i].key, &(*records)[i].value, &(*records)[i].int_value, &(*records)[i].float_value, &(*records)[i].string_value, file);
    }
}

// Function to free allocated memory when done
void cleanup(dataRecord* records, int size) {
    for (int i = 0; i < size; ++i) {
        free((*records + i)->offset);
        free((*records + i)->string_value);
    }
    free(*records);
}
