std::vector<Record> parse_response(const boost::json::value &response) {
    std::vector<Record> records;
    auto keys = response.as_object().find("keys");
    if (keys == response.as_object().end())
        return records;

    auto offsets = response.as_object().find("offsets");
    if (offsets == response.as_object().end())
