using boost::asio::ip::tcp;

struct record { int value; };
typedef std::vector<record> RecordVector;
typedef std::vector<long> OffsetVector;
typedef std::vector<int> KeyVector;

class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& io_service, const tcp::endpoint& endpoint)
        : socket_(io_service), requestHeader_, responseHeader_, recordArray_(1000), offsetArray_(1000), keyArray_(1000) {
        reset();
        doWork();
    }

    void reset() {
        recordCount_ = 0;
        for (auto& rec : recordArray_)
            rec.value = std::rand() % 100 + 1;
        for (size_t i = 0; i < offsetArray_.size(); ++i)
            offsetArray_[i] = i;
        for (size_t i = 0; i < keyArray_.size(); ++i)
            keyArray_[i] = i;
    }

private:
    void doWork() {
        boost::asio::async_read_until(socket_, responseHeader_, "\r\n", [this](boost::system::error_code ec, std::size_t /*length*/) {
            if (!ec && handleResponse())
                doWork();
        });
    }

    bool handleResponse() {
        logRequest();
        boost::posix_time::ptime start = boost::chrono::system_clock::now();

        // Parse response headers...

        if (parseErrorResponse(responseHeader_)) {
            logErrorMessage();
            return false;
        }

        auto elapsed = boost::chrono::duration_cast<boost::posix_time::milliseconds>(boost::chrono::system_clock::now() - start).count();
        if (elapsed > timeout_) {
            logErrorMessage("Request timed out.");
            return false;
        }

        // Process response data...

        ++recordCount_;
        if (recordCount_ % 100 == 0)
            reset();

        return true;
    }

    void logRequest() {
        log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("SandeshClient"));
        log4cxx::tstring requestLogMessage = (boost::format("Sending request to %1%: %2%") % requestHeader_.target() % requestHeader_.request_line()).str();
        logger->debugString(requestLogMessage);
    }

    void logErrorMessage() {
        log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("SandeshClient"));
        log4cxx::tstring errorLogMessage = "Error occurred.";
        logger->errorString(errorLogMessage);
    }

    void parseErrorResponse(const std::string& response) {
        // Parse the error response...
        return false;
    }

    tcp::socket socket_;
    tcp::request requestHeader_;
    tcp::response responseHeader_;
    RecordVector recordArray_;
    OffsetVector offsetArray_;
    KeyVector keyArray_;
    size_t recordCount_;
    int timeout_{100}; // Milliseconds.
};

int main(int argc, char* argv[]) {
    log4cxx::BasicConfigurator config;
    config.configure("log4cxx.properties");

    boost::asio::io_service io_service;
    tcp::endpoint endpoint(tcp::v4(), 80); // Server port number.

    SandeshClient client(io_service, endpoint);

    try {
        io_service.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
