int *create_state_list(int *states, int num_states, struct FSA *fsa, int last_state) {
    int *new_states = extend_state_list(states, num_states);
    if (!new_states) return NULL;

    for (int i = num_states; i < new_states[num_states]; ++i) {
        update_fsa(fsa);
        int next_state = fsa->states[last_state] * num_states + i;
        new_states[i] = next_state;
    }

    return new_states;
}

