                keys[i] = ext_keys[i];

                current_memory_usage += sizeof(long) + sizeof(int);
            } else {
                valid = false;
                break;
            }
        }

        if (valid) {
            records = malloc(sizeof(record) * ext_keys[total_elements - 1]);
            memory_usage[0] = current_memory_usage + sizeof(long)*total_elements + sizeof(int)*total_elements;

            srand(time(NULL));

            for (size_t i = 0; i < ext_keys[total_elements - 1]; ++i) {
                records[i].value = rand() % 100 + 1;
            }
        } else {
            free(offsets);
            free(keys);
        }
    }

    if (!valid || current_memory_usage > memory_limit) {
        return -1; // Error: Memory allocation exceeded limit
    }

    return 0; // Success
}
