#include <arpa/inet.hostent>
#include <netdb.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 4096

struct dns_context {
    char *hostname;
    u_char ip[sizeof(struct in_addr)];
    int error;
};

void resolve_dns(void *arg) {
    struct dns_context *ctx = arg;
    struct hostent *host;
    memset(ctx->ip, 0, sizeof(ctx->ip));

    if (!(host = gethostbyname(ctx->hostname))) {
        ctx->error = 1;
        return;
    }

    memcpy(ctx->ip, host->h_addr_list[0], sizeof(struct in_addr));
}

int read_and_process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return 1; // Error handling for file open failure

    char *line = NULL;
    size_t len = 0;
    ssize_t nread;

    pthread_t threads[MAX_THREADS];
    struct dns_context contexts[MAX_THREADS];

    while ((nread = getline(&line, &len, file)) != -1) {
        if (nread > BUFFER_SIZE) continue; // Handle lines with varying lengths

        char *token = strtok(line, ",");
        if (!token) continue; // Error handling for invalid input format

        int i = 0;
        while (token) {
            contexts[i].hostname = strdup(token);
            contexts[i].error = 0;
            i++;

            token = strtok(NULL, ",");
        }

        for (int j = 0; j < i && j < MAX_THREADS; j++) {
            if (j >= MAX_THREADS) break; // Limit the number of simultaneous DNS resolution threads

            pthread_create(&threads[j], NULL, resolve_dns, &contexts[j]);
        }

        for (int k = 0; k < i && k < MAX_THREADS; k++) {
            pthread_join(threads[k], NULL);
        }

        double sum = 0.0;
        int count = 0;

        for (int l = 0; l < i && l < MAX_THREADS; l++) {
            if (!contexts[l].error) {
                in_addr_t ip = *(in_addr_t *)contexts[l].ip;
                sum += ip;
                count++;
            }
        }

        if (count < 2) continue; // Ensure at least two fields for average calculation

        double avg = sum / count;

        printf("%s,%f\n", line, avg);

        for (int m = 0; m < i && m < MAX_THREADS; m++) {
            free(contexts[m].hostname);
        }
    }

    fclose(file);
    return 0; // Successful file processing
}

int main(int argc, char **argv) {
    if (argc <= 1) return 1; // Error handling for invalid number of command-line arguments

    FILE *config = fopen(argv[1], "r");
    if (!config) return 1; // Error handling for configuration file open failure

    char line[BUFFER_SIZE];
    size_t len = 0;
    ssize_t nread;

    int max_threads, memory_per_line;

    while ((nread = fgetline(config, line, BUFFER_SIZE)) != -1) {
        char *token = strtok(line, "=");
        if (!token) continue; // Error handling for invalid configuration format

        token = strtok(NULL, "\n");
        if (!token) continue; // Error handling for missing value in configuration format

        if (strcmp(token, "max_threads") == 0) {
            max_threads = atoi(strtok(NULL, ","));
            if (max_threads > MAX_THREADS) max_threads = MAX_THREADS;
        } else if (strcmp(token, "memory_per_line") == 0) {
            memory_per_line = atoi(strtok(NULL, "\n"));
        }
    }

    fclose(config);

    for (int i = 2; i < argc; i++) {
        if (read_and_process_file(argv[i])) return 1; // Error handling for file processing failure
    }

    return 0; // Successful program execution
}
