['```c
#include <stdio.h>
#include <stdlib.h>
#include <zstd.h>
#include <sys/mman.h> // for handling different system architectures

typedef struct {
    ZSTD_CCtx *zstd_ctx;
    size_t compressionLevel;
} ZstdCompressionContext;

ZstdCompressionContext* createZstdCompressionContext(size_t dataSize, const void* dataSource) {
    ZstdCompressionContext *context = mmap(NULL, sizeof(ZstdCompressionContext), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Initialize ZSTD context and set compression level based on input data size and type
    ZSTD_CCtx_params params = ZSTD_CCtx_createParameters();
    params.nextInOff = 0;
    params.nextInSize = dataSize;

    if (dataSize < 1024) { // Small input size, use lower compression level
        params.compressionLevel = 3;
    } else if (dataSize < 65536) { // Medium input size, use medium compression level
        params.compressionLevel = 7;
    } else { // Large input size, use higher compression level
        params.compressionLevel = 19;
    }

    context->zstd_ctx = ZSTD_CCtx_create(&params);

    // Set data source for processing
    ZSTD_CCtx_setInputFrame(context->zstd_ctx, dataSource, dataSize);

    context->compressionLevel = params.compressionLevel;
    return context;
}

void compressDataUsingZstd(const ZstdCompressionContext* context, void** compressedData, size_t* compressedDataSize) {
    // Compress input data using ZSTD_CCtx
    ZSTD_outBuffer outBuf = { 0 };
    ZSTD_inBuffer inBuf = { context->zstd_ctx->nextIn, context->zstd_ctx->nextInSize };

    size_t result = ZSTD_compressStream(context->zstd_ctx, ZSTD_CSTREAM_END == context->compressionLevel ? ZSTD_e_finish : ZSTD_e_continue, compressedData, compressedDataSize, &outBuf, 0);

    if (result < 0) { // Handle errors
        perror("Zstd compression error");
        exit(EXIT_FAILURE);
    }

    context->zstd_ctx->nextIn += outBuf.pos;
    context->zstd_ctx->nextInSize -= outBuf.pos;
}

// Other functions for decompression, cleanup, and logging integration can be implemented similarly
```

