typedef struct {
    int value;
    int *key;
    long offset;
} record;

int init_arrays(int *integers, int size, int *keys, int *offsets) {
    // Ensure size and keys are non-zero before using them.
    if (!size || !keys || !offsets) return -1;

    srand((unsigned)time(NULL));

    for (int i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = integers + i;
    }

    return 0;
}

void allocate_records(record **records, int size, int *keys, long *offsets) {
    if (!size || !keys || !offsets || !records) return;

    *records = malloc(size * sizeof(**records));
    if (*records == NULL) return;

    for (int i = 0; i < size; ++i) {
        (*records)[i].value = *(keys[i]);
        (*records)[i].key = keys + i;
        (*records)[i].offset = offsets[i];
    }
}

void print_records(record *records, int size) {
    if (!size || !records) return;

    for (int i = 0; i < size; ++i) {
        printf("Record %d: Value=%d Key=%p Offset=%ld\n", i, records[i].value, records[i].key, records[i].offset);
    }
}

