typedef struct {
    int value;
    const int *key;
    long offset;
} record;

void create_and_init(size_t num_records, size_t key_count, int *keys, long *offsets, sem_t *semaphore) {
    int *numbers = malloc(num_keys * sizeof(int));
    if (!numbers) {
        perror("Memory allocation failed for numbers.");
        return;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed for records.");
        free(numbers);
        return;
    }

    long *long_offsets = malloc(key_count * sizeof(long));
    if (!long_offsets) {
        perror("Memory allocation failed for long_offsets.");
        free(records);
        free(numbers);
        return;
    }

    int *tmp_keys = malloc(key_count * sizeof(int));
    if (!tmp_keys) {
        perror("Memory allocation failed for tmp_keys.");
        free(long_offsets);
        free(records);
        free(numbers);
        return;
    }

    for (size_t i = 0; i < key_count; ++i) {
        long_offsets[i] = i;
        tmp_keys[i] = keys[i];
    }

    // Initialize semaphore with the given initial value
    if (sem_init(semaphore, 0, num_records)) {
        perror("Failed to initialize semaphore.");
        free(long_offsets);
        free(tmp_keys);
        free(records);
        free(numbers);
        return;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        scanf("%d", &numbers[i]);
    }

    // Initialize the key array with the sorted values and their corresponding indices
    qsort(numbers, num_keys, sizeof(int), (void *) compare);

    for (size_t i = 0; i < key_count; ++i) {
        const int *key_ptr = &tmp_keys[long_offsets[i]];
        records[i].value = numbers[i];
        records[i].key = key_ptr;
        records[i].offset = long_offsets[i];
    }

    // Generate random values within a specified range for each record's int field
    srand(time(NULL));
    for (size_t i = num_keys; i < num_records; ++i) {
        records[i].value = rand() % MAX_RANDOM_VALUE + MIN_RANDOM_VALUE;
    }

    // Print the contents of the records array after initialization
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record[%zu]: value=%d, key=%p, offset=%ld\n", i, records[i].value, records[i].key, records[i].offset);
    }

    free(long_offsets);
    free(tmp_keys);
}

int compare(const void *a, const void *b) {
    return *(int *) a - *(int *) b;
}

// Replace MAX_RANDOM_VALUE and MIN_RANDOM_VALUE with appropriate constants or read them from configuration files/settings.
