#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
    const int *key;
    long offset;
} record;

int init_array(size_t *n, int **arr) {
    *arr = malloc(*n * sizeof(**arr));
    if (!*arr) return 1;
    return 0;
}

int read_input(size_t n, int *arr) {
    for (size_t i = 0; i < n; ++i) {
        scanf("%d", arr + i);
    }
    return 0;
}

void generate_keys(size_t n, const int *arr, size_t *key_n, int **keys) {
    init_array(key_n, keys);
    for (size_t i = 0; i < n; ++i) {
        int key = arr[i];
        for (size_t j = 0; j < *key_n; ++j) {
            if ((*keys)[j] == key) goto found;
        }
        (*key_n)++;
    found:;
        (*keys)[*key_n - 1] = arr + i;
    }
}

void generate_offsets(size_t n, const int *arr, size_t key_n, const int **keys, record **records, size_t *r_n) {
    srand(time(NULL));
    init_array(r_n, records);
    for (size_t i = 0; i < n; ++i) {
        int key_idx = rand() % key_n;
        record *record = *records + (*r_n)++;
        record->value = arr[i];
        record->key = keys[key_idx];
        record->offset = rand() % 1000000;
    }
}

int main(int argc, char **argv) {
    size_t n = atoi(argv[1]);
    int *arr = NULL;
    if (init_array(&n, &arr)) return 1;
    if (read_input(n, arr)) return 1;
    size_t key_n, r_n;
    const int *keys = NULL;
    record *records = NULL;
    generate_keys(n, arr, &key_n, &keys);
    generate_offsets(n, arr, key_n, keys, records, &r_n);
    for (size_t i = 0; i < r_n; ++i) {
        printf("Record %ld: value=%d, key=%p, offset=%ld\n", i, records[i].value, records[i].key, records[i].offset);
    }
    free(arr);
    free(keys);
    free(records);
    return 0;
}
