    float *keys = malloc(keys_count * sizeof(float));
    double *offsets = malloc(keys_count * entries_per_key * sizeof(double));
    data_entry **data_entry_arr = malloc(keys_count * sizeof(data_entry*));

    if (!keys || !offsets || !data_entry_arr) { // Check for allocation failures
