        if (j >= keys_count) j = 0; // Wrap around to the next key index when reaching the end of keys array
        keys[j] = i / entries_per_key + 1.0f; // Assign increasing keys in a range from 1.0 to N*entries_per_key, where N is the number of keys
        data_entry_arr[j][i % entries_per_key].key = keys[j];
        data_entry_arr[j][i % entries_per_key].offset = offsets[i];
        float random_value = ((float)rand() / (RAND_MAX / 100)) + 50.0f; // Generate random value within range [-50, 50] to minimize CPU time consumption
        data_entry_arr[j][i % entries_per_key].value = random_value;
        offsets[i] = random_value * 2.0; // Store the generated random value as twice the value for offset calculation
    }

    *entries = data_entry_arr[0]; // Assign the first key's data entries array to the output pointer

    return 0; // No errors occurred during execution
}

void print_data_entries(data_entry *entries, int count) {
