int initializeDataArray(size_t numKeys, size_t *keys, size_t inputSize, float *input) {
    Data *data = NULL;
    size_t *indices = malloc(sizeof(size_t) * inputSize);
    if (!indices) return 1; // Out of memory

    for (size_t i = 0; i < inputSize; ++i) {
        indices[i] = i;
    }

    data = malloc(sizeof(Data) * numKeys);
    if (!data) {
        free(indices);
        return 2; // Out of memory
    }

    for (size_t i = 0; i < numKeys && inputSize > 0; ++i) {
        size_t index = rand() % inputSize;
        if (index >= numKeys) continue; // Prevent overflow

        data[i].value = input[indices[index]];
        data[i].key = keys + index;
        data[i].index = indices[index];

        indices[index] = indices[--inputSize];
    }

    free(indices);

    if (inputSize != 0) {
        free(data);
        return 3; // Not all input was used
    }

    return 0;
}

void printDataArray(size_t numData, Data *data) {
    for (size_t i = 0; i < numData; ++i) {
        printf("Index: %zu Value: %.2f Key: %p\n", data[i].index, data[i].value, data[i].key);
