        goto cleanup;
    }

    records = calloc(num_files, sizeof(file_record));
    if (!records) {
        perror("Memory allocation failed");
        goto cleanup;
    }

    for (i = 0; i < num_files; ++i) {
        records[i].key = &keys[file_paths[i]];
        records[i].offset = &offsets[file_paths[i]];
        records[i].filesize = file_sizes[i];
    }

    for (i = 0; i < num_files; ++i) {
        void *buffer = mmap(NULL, records[i].filesize, PROT_READ | PROT_WRITE, MAP_PRIVATE, fileno(fopen(file_paths[i], "r")), 0);
        if (buffer == MAP_FAILED) {
            perror("Memory mapping failed");
            goto cleanup;
        }
        records[i].filesize = ftell(fopen(file_paths[i], "r"));
        fseek(fopen(file_paths[i], "r"), 0, SEEK_SET);
        records[i].buffer = buffer;
