        printf("Key: %p\n", records[i].key);
        printf("Offset: %p\n", records[i].offset);
        printf("Buffer: %p\n", records[i].buffer);
    }

cleanup:
    for (j = 0; j < num_files; ++j) {
        if (records[j].buffer != MAP_FAILED)
            munmap(records[j].buffer, records[j].filesize);
    }
    free(offsets);
    free(keys);
    free(records);

    return num_files > 0 ? 0 : -1; // Return 0 on success, non-zero value on failure.
}
