Write a C function that dynamically allocates memory for and initializes arrays to store data points and keys. Each data point will contain a `double` value and a `char*` identifier. The function should allow for dynamically changing ranges for the random values and ensure proper memory management. Additionally, the function must handle large numbers of data points efficiently, considering factors such as memory usage, performance, and scalability.

```c
typedef struct {
    double value;
    char* identifier;
} data_point;

void initialize_data_points(int num_points, int min_value, int max_value, data_point** points, int* keys) {
    // Allocate memory for keys array
    keys = (int*)malloc(num_points * sizeof(int));
    if (keys == NULL) {
        // Handle allocation failure
        return;
    }

    // Initialize keys array with unique values
    for (int i = 0; i < num_points; i++) {
        keys[i] = i;
    }

    // Allocate memory for data points array
    points = (data_point**)malloc(num_points * sizeof(data_point*));
    if (points == NULL) {
        // Handle allocation failure
        free(keys);
        return;
    }

    // Initialize data points array
    for (int i = 0; i < num_points; i++) {
        points[i] = (data_point*)malloc(sizeof(data_point));
        if (points[i] == NULL) {
            // Handle allocation failure
            free(keys);
            free(points);
            return;
        }

        // Set random value within range [min_value, max_value]
        double random_value = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;
        points[i]->value = random_value;

        // Set unique identifier
        char buffer[20];
        snprintf(buffer, sizeof(buffer), "point_%d", i);
        points[i]->identifier = strdup(buffer);

        if (points[i]->identifier == NULL) {
            // Handle allocation failure
            free(keys);
            free(points);
            return;
        }
    }
}
```

### **Extended Use Cases**
- The function should be able to handle large numbers of `num_points`.

### **Design Challenges**
