    if (!fp) {
        perror("Error: Could not open file.");
        return NULL;
    }

    hash_md5_ctx ctx;
    hash_md5_init(&ctx);

    size_t buf_size = 16384;
    char *buf = malloc(buf_size);
    if (!buf) {
        perror("Error: Could not allocate buffer.");
        fclose(fp);
        return NULL;
    }

    size_t bytes_read;
    while ((bytes_read = fread(buf, 1, buf_size, fp)) > 0) {
        hash_md5_update(&ctx, buf, bytes_read);
    }

    free(buf);
    fclose(fp);

    char* digest = malloc(MD5_DIGEST_LENGTH);
    if (!digest) {
        perror("Error: Could not allocate digest buffer.");
        return NULL;
    }

    hash_md5_final(digest, &ctx);
    return digest;
}
