import hashlib
import os

def md5_file(filename):
    f = open(filename, 'rb')
    md5 = hashlib.md5()
    block_size = 65536

    while True:
        data = f.read(block_size)
        if not data:
            break
        md5.update(data)

    f.close()
    return md5.hexdigest()
