int read_and_init(int argc, char **argv, int *input, int *keys, Record **records) {
    int i, j, key_count = 0, record_count = 0;

    // Read input from command line and store in array
    for (i = 1; i < argc; ++i) {
        input[key_count++] = atoi(argv[i]);
    }

    // Allocate memory for keys, records and initialize key pointers
    *keys = malloc((key_count + 1) * sizeof(int));
    if (*keys == NULL) return -1;

    *records = malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        free(*keys);
        return -1;
    }

    // Sort input and initialize keys, records
    qsort(input, key_count, sizeof(int), (void *)compare_function);

    for (i = 0; i < key_count; ++i) {
        (*keys)[i] = i;

        Record *curr_record = &((*records)[record_count++]);
        curr_record->value = input[i];
        curr_record->key = (*keys + i);
        curr_record->offset = i < MAX_KEYS ? 0 : (i - MAX_KEYS) * sizeof(int);
    }

    return 0;
}

// Comparator function for qsort()
static int compare_function(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

// Function to search for a specific integer value within the records array.
int find_value(Record *records, int value, int *key, long *offset) {
    int i;
    for (i = 0; i < MAX_RECORDS; ++i) {
        if (records[i].value == value) {
            *key = records[i].key[0];
            *offset = records[i].offset;
            return 0;
        }
    }

    return -1;
}

void print_records(Record *records, int len) {
    for (int i = 0; i < len; ++i) {
        printf("(%d, %p, %ld)\n", records[i].value, records[i].key, records[i].offset);
    }
}

void sort_records(Record *records, int len) {
    qsort(records, len, sizeof(Record), (void *)compare_record_function);
}

static int compare_record_function(const void *a, const void *b) {
    return (*(Record *)a).value - (*(Record *)b).value;
}
