void insert_at_beginning(Node** head, Node* new_node) {
    if (!new_node || !head || !(*head)) {
        fprintf(stderr, "Invalid input.\n");
        return;
    }
    new_node->next = *head;
    *head = new_node;
}

void insert_at_end(Node** head, Node* new_node) {
    if (!new_node || !head) {
        fprintf(stderr, "Invalid input.\n");
        return;
    }
    Node* current = *head;
    if (!(*head)) {
        *head = new_node;
        return;
    }
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

void free_linked_list(Node** head) {
    if (!head || !(*head)) {
        return;
    }
    Node* temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

