int read_line(FILE *file, char **line, size_t *length) {
    char *buffer = NULL;
    size_t capacity = 0;
    size_t position = 0;

    if (file == NULL || line == NULL || length == NULL) {
        log("Invalid parameters passed to read_line.");
        return -1;
    }

    *length = 0;

    while (!feof(file)) {
        if (capacity <= position) {
            capacity *= 2;
            buffer = realloc(buffer, capacity);
            if (buffer == NULL) {
                log("Failed to allocate memory for line buffer.");
                return -1;
            }
        }

        char c = fgetc(file);
        buffer[position++] = c;
        buffer[position] = '\0';
    }

    *line = malloc((*length + 1) * sizeof(char));
    if (*line == NULL) {
        log("Failed to allocate memory for line.");
        return -1;
    }

    strncpy(*line, buffer, *length);
    free(buffer);
    return 0;
}

