    virtual std::unique_ptr<int[]> getKeys(size_t& length) = 0;
    virtual std::unique_ptr<long[]> getOffsets(size_t& length) = 0;
    virtual std::unique_ptr<record[]> getRecords(size_t& length) = 0;
};

class DataSource : public IDataSource {
