#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    double value;
} record;

struct config {
    int is_dynamic; // 0 for fixed, 1 for dynamic
    int array_sizes[3];
};

struct data_source {
    void* data;
    size_t length;
    void (*get)(void*, long*, int*, double*, size_t);
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record* init_arrays(struct data_source* ds, struct config* cfg) {
    record* records = NULL;
    long* offsets = malloc(cfg->array_sizes[0] * sizeof(long));
    int* keys = malloc(cfg->array_sizes[1] * sizeof(int));
    double* values = malloc(cfg->array_sizes[2] * sizeof(double));

    if (!offsets || !keys || !values) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Implement the data source's get function here. It should handle variable or fixed length data.
    // Make sure to acquire the mutex before accessing shared data and release it afterwards.

    if (ds->get(ds->data, offsets, keys, values, ds->length)) {
        fprintf(stderr, "Error: Failed to retrieve data from the source\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);

    records = malloc(cfg->array_sizes[3] * sizeof(record));

    for (size_t i = 0; i < cfg->array_sizes[3]; ++i) {
        records[i].key = keys[offsets[i]];
        records[i].value = values[offsets[i]];
    }

    pthread_mutex_unlock(&mutex);

    return records;
}

void example_call(struct data_source ds) {
    struct config cfg = {1, {10, 3, 2, 1}, {10, 0, 0}}; // Dynamic arrays with specified sizes

    record* records = init_arrays(&ds, &cfg);

    if (!records) return;

    struct data_source ds_var = {.data = ..., .length = var_len}; // Variable-length data source
    struct config cfg_var = {1, {0, 0, 0, 0}, {0, 0, 0}}; // Array sizes will be determined dynamically based on the variable data source

    record* records_var = init_arrays(&ds_var, &cfg_var);

    if (records_var) {
        // Handle the newly allocated 'records_var' array here.
    }
}
