#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int value;
    char* data;
};

int is_valid(const char* line) {
    // Validate the CSV format, assuming each row has 4 fields separated by commas and spaces
    size_t num_fields = strlen(line) - strlen(strchr(line, ',')) - 1;
    return (num_fields == 4);
}

long* read_offsets(FILE* file, size_t* size) {
    long* offsets = malloc(*size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    size_t i = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file) && i < *size) {
        if (!is_valid(line)) {
            fprintf(stderr, "Error: Incorrect CSV format in row %zu\n", i);
            free(offsets);
            return NULL;
        }

        sscanf(line, "%ld,%*[^,],%*[^,],%*[^\n]", offsets + i);
        ++i;
    }

    if (feof(file)) {
        if (i != *size) {
            fprintf(stderr, "Error: Incomplete data in the CSV file\n");
            free(offsets);
            return NULL;
        }
    } else {
        fprintf(stderr, "Error: Premature end of file\n");
        free(offsets);
        return NULL;
    }

    return offsets;
}

int* read_keys(FILE* file, size_t size) {
    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        return NULL;
    }

    char line[1024];
    size_t i = 0;
    while (fgets(line, sizeof(line), file) && i < size) {
        if (!is_valid(line)) {
            fprintf(stderr, "Error: Incorrect CSV format in row %zu\n", i);
            free(keys);
            return NULL;
        }

        sscanf(line, "%*[^,],%d,%*[^,],%*[^\n]", keys + i);
        ++i;
    }

    if (feof(file)) {
        if (i != size) {
            fprintf(stderr, "Error: Incomplete data in the CSV file\n");
            free(keys);
            return NULL;
        }
    } else {
        fprintf(stderr, "Error: Premature end of file\n");
        free(keys);
        return NULL;
    }

    return keys;
}

size_t allocate_records(Record** records, size_t num_records, size_t max_data_len) {
    size_t total_length = num_records * sizeof(Record) + max_data_len * num_records;
    *records = malloc(total_length);
    if (!*records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return 0;
    }

    memset(*records, 0, total_length);
    return total_length;
}

Record* read_records(FILE* file, size_t offset_size, size_t key_size, size_t data_max_len) {
    long* offsets = read_offsets(file, &offset_size);
    if (!offsets) return NULL;

    int* keys = read_keys(file, offset_size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    size_t records_length = allocate_records((Record**)offsets + *offsets, offset_size - *offsets, data_max_len);
    if (records_length == 0) {
        free(keys);
        free(offsets);
        return NULL;
    }

    Record* records = (Record*)((char*)offsets + records_length);

    size_t i = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file) && i < offset_size - *offsets) {
        if (!is_valid(line)) {
            fprintf(stderr, "Error: Incorrect CSV format in row %zu\n", i + *offsets);
            free_data(records, records_length);
            free(keys);
            free(offsets);
            return NULL;
        }

        sscanf(line, "%ld,%d,%*[^,],%n", offsets + *offsets + i, &data_max_len, line + strlen(line) - data_max_len);
        records[i].value = keys[i];
        records[i].data = ((char*)records + (i + 1) * sizeof(Record)) + records[i].value;
        ++i;
    }

    if (feof(file)) {
        if (i != offset_size - *offsets) {
            fprintf(stderr, "Error: Incomplete data in the CSV file\n");
            free_data(records, records_length);
            free(keys);
            free(offsets);
            return NULL;
        }
    } else {
        fprintf(stderr, "Error: Premature end of file\n");
        free_data(records, records_length);
        free(keys);
        free(offsets);
        return NULL;
    }

    return records;
}

void free_data(Record* data, size_t length) {
    if (data) free(data);
}

int main() {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        fprintf(stderr, "Error: Failed to open the input file\n");
        return 1;
    }

    size_t offset_size, key_size, data_max_len;
    Record* records = read_records(file, &offset_size, &key_size, &data_max_len);
    fclose(file);

    if (!records) return 1;

    // Continue working with the allocated memory here...

    free_data(records, records_length);

    return 0;
}
