size_t calculate_memory_needed(size_t array_size, size_t char_len) {
    size_t memory_needed = sizeof(long) * array_size + sizeof(int) * array_size + sizeof(Record) * array_size;

    // Account for minimum of 10 characters per string and null terminator.
    memory_needed += array_size * (char_len + 1);

    return memory_needed;
