// Mutex for thread safety
pthread_mutex_t mutex;

void* alloc_and_init(size_t array_size, size_t char_len) {
    if (!is_positive(array_size) || !is_positive(char_len)) {
        return NULL;
    }

    // Calculate the total memory required for all allocations.
    size_t memory_needed = calculate_memory_needed(array_size, char_len);

    if (memory_needed > MAX_MEMORY) {
        return NULL;
    }

    long* offsets = malloc(sizeof(long) * array_size);
    int* keys = malloc(sizeof(int) * array_size);
    Record* records = malloc(sizeof(Record) * array_size);

    // Initialize char arrays with null characters.
    char** strs = calloc(array_size, char_len + 1);
    if (!strs) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Lock mutex before performing any thread-sensitive operations.
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < array_size; ++i) {
        int random_value = rand() % 900 + 100; // Generate a random number within [100, 999].
        records[i].value = random_value;

        // Allocate memory for the string and initialize with a null character.
        records[i].str = strs[i];
        records[i].str[0] = '\0';
    }

    pthread_mutex_unlock(&mutex);

    return (void*)records; // Return a void pointer to the array of records.
}

void free_allocated(void* data) {
    Record* records = (Record*)data;
    if (!records) {
        return;
