        char *token = strtok(line, ":");
        int key = atoi(token);
        token = strtok(NULL, ":");
        int value = atoi(token);
        token = strtok(NULL, ":");
        if (!token) {
            fprintf(stderr, "Invalid record format: %s\n", line);
