    }

    *records = records_arr;
    *offsets = offset;

    return 0;

cleanup_records_arr:
    for (size_t i = 0; i < records_counter; ++i) {
        free(records_arr[i]->value);
        free(records_arr[i]);
    }
    free(records_arr);

cleanup_keys:
    free(keys_arr);

cleanup_offset:
