#define MAX_CACHE_SIZE 10000
typedef struct {
    int key;
    int value;
    void *key_ptr;
} record;

typedef struct cache_node {
    record data;
    struct cache_node *next;
} cache_node;

cache_node *cache_head = NULL;
cache_node *cache_tail = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void md5_cache_init(int offsets_size, int keys_size, int records_size) {
    void *offsets = malloc(sizeof(long) * offsets_size);
    if (!offsets) {
        perror("Error allocating offsets memory");
        exit(1);
    }

    void *keys = malloc(sizeof(int) * keys_size);
    if (!keys) {
        perror("Error allocating keys memory");
        free(offsets);
        exit(1);
    }

    void *records = malloc(sizeof(record) * records_size);
    if (!records) {
        perror("Error allocating records memory");
        free(keys);
        free(offsets);
        exit(1);
    }

    for (int i = 0; i < records_size; ++i) {
        record *record_ptr = (record *)records + i;
        record_ptr->key = 0;
        record_ptr->value = generate_random(0, INT32_MAX);
        record_ptr->key_ptr = &((int *)keys)[i];
    }

    for (int i = 0; i < offsets_size; ++i) {
        ((long *)offsets)[i] = 0;
    }
}

record *md5_cache_get(int key) {
    pthread_mutex_lock(&cache_lock);
    cache_node *current = cache_head;
    while (current != NULL) {
        if (*((int *)current->data.key_ptr) == key) {
            void *record_ptr = current;
            pthread_mutex_unlock(&cache_lock);
            return (record *)record_ptr;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache_lock);

    if (cache_head == NULL || cache_tail == NULL) {
        cache_node *new_node = malloc(sizeof(cache_node));
        if (!new_node) {
            perror("Error allocating new cache node");
            return NULL;
        }
        new_node->data.key = key;
        new_node->next = NULL;

        pthread_mutex_lock(&cache_lock);
        if (cache_head == NULL) {
            cache_head = new_node;
            cache_tail = new_node;
        } else {
            cache_tail->next = new_node;
            cache_tail = new_node;
        }
        pthread_mutex_unlock(&cache_lock);
    }

    record *record_ptr = (record *)cache_head;
    if (*((int *)record_ptr->data.key_ptr) != key) {
        while (record_ptr->next != NULL && *((int *)record_ptr->next->data.key_ptr) != key) {
            record_ptr = record_ptr->next;
        }
    }
    if (record_ptr->next == NULL) {
        cache_node *new_node = malloc(sizeof(cache_node));
        if (!new_node) {
            perror("Error allocating new cache node");
            return NULL;
        }
        new_node->data.key = key;
        new_node->next = NULL;

        pthread_mutex_lock(&cache_lock);
        record_ptr->next = new_node;
        pthread_mutex_unlock(&cache_lock);
    }

    record *result = (record *)record_ptr->next;
    if (*((int *)result->data.key_ptr) == key) {
        return result;
    } else {
        perror("Internal cache error");
        return NULL;
    }
}

void md5_cache_free() {
    pthread_mutex_lock(&cache_lock);
    cache_node *current = cache_head;
    while (current != NULL) {
        cache_node *next = current->next;
        free(current);
        current = next;
    }
    cache_head = NULL;
    cache_tail = NULL;
    pthread_mutex_unlock(&cache_lock);
}
```

