int read_and_process_data(int capacity, FILE **input_stream) {
    data_t *data = malloc(capacity * sizeof(data_t));
    if (!data) return -1; // Memory allocation error

    float key;
    for (int i = 0; i < capacity; ++i) {
        if (fscanf(*input_stream, "%f", &key) != 1) {
            free(data);
            return -2; // Input error
        }

        data[i].value = key;
        data[i].index = i;

        if (get_metadata(&key, &data[i]) < 0) {
            for (int j = 0; j < i; ++j) free(data[j].key_ptr);
            free(data);
            return -3; // External data source error
        }

        data[i].key_ptr = malloc(sizeof(void*));
        if (!data[i].key_ptr) {
            for (int j = 0; j <= i; ++j) {
                free(data[j].key_ptr);
                free(data);
            }
            return -4; // Memory allocation error
        }
    }

    return 0;
}
