#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    int *key_ptr;
    long offset;
} Record;

int read_input(int argc, char **argv) {
    int *numbers = malloc((argc - 1) * sizeof(int));
    if (!numbers) return 1;

    for (int i = 1; i < argc; ++i)
        numbers[i - 1] = atoi(argv[i]);

    return 0;
}

void init_keys(int num_keys, int *numbers) {
    int *keys = malloc((num_keys + 1) * sizeof(int));

    for (int i = 0; i <= num_keys; ++i) keys[i] = -1;

    for (int i = 0; i < num_keys; ++i) {
        int j = numbers[i];
        if (keys[j] != -1) continue;
        keys[j] = i;
    }
}

Record *init_records(int num_keys, int *numbers) {
    Record *records = malloc((num_keys + 1) * sizeof(Record));
    if (!records) return NULL;

    init_keys(num_keys, numbers);

    for (int i = 0; i <= num_keys; ++i) {
        records[i].key_ptr = &keys[i];
        records[i].offset = i;
        records[i].value = numbers[*records[i].key_ptr];
        *records[i].key_ptr = -1;
    }

    qsort(records, num_keys + 1, sizeof(Record), compare);

    return records;
}

int find_value(Record *records, int value) {
    int start = 0, end = (int)(sizeof(Record) / sizeof(int)) - 1;

    while (start <= end) {
        int mid = (start + end) >> 1;
        if (value == records[mid].value) return mid;
        if (value < records[mid].value) end = mid - 1;
        else start = mid + 1;
    }

    return -1;
}

void print_records(Record *records, int num_keys) {
    for (int i = 0; i <= num_keys; ++i) {
        if (i > 0) printf("\n");
        printf("(%d, %p, %ld)", records[i].value, records[i].key_ptr, records[i].offset);
    }
}

int compare(const void *a, const void *b) {
    return (*(Record *)a).value - (*(Record *)b).value;
}

int main(int argc, char **argv) {
    if (read_input(argc, argv)) return 1;

    Record *records = init_records((int)(argc - 1), argv + 1);

    if (!records) return 2;

    print_records(records, (int)(sizeof(Record) / sizeof(int)) - 1);

    int value = rand() % ((int)(sizeof(Record) / sizeof(int)));
    printf("\nSearching for %d...\n", value);
    int result = find_value(records, value);

    if (result == -1) printf("Not found.\n");
    else printf("Found at index %d.\n", result);

    free(records);
    return 0;
}
