        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < capacity && total + sizeof(*records) * capacity + sizeof(*offsets) * capacity + sizeof(*keys) * capacity <= limit; ++i) {
        total += sizeof(**records);

        (*records)[i] = malloc(sizeof(struct Record));
        if ((*records)[i] == NULL) {
