            free(temp_keys);
            free(temp_records);
            exit(EXIT_FAILURE);
        }

        *offsets = temp_offsets;
        *keys = temp_keys;
        *records = temp_records;
    }
}

void cleanup(size_t* offsets, size_t* keys, struct Record** records) {
    free(*offsets);
    free(*keys);
    for (size_t i = 0; i < *records != NULL && *records[i] != NULL; ++i) {
        free((*records)[i]);
    }
    free(*records);
}
