    if (size <= 0 || min_temp > max_temp) {
        fprintf(stderr, "Invalid input: Size and temperature range are invalid.\n");
        return;
    }

    *sensor_records = malloc(size * sizeof(sensor_data));
    if (!*sensor_records) {
        perror("Error allocating memory for sensor records.");
        return;
    }

    char **locations = malloc(size * sizeof(char *));
    if (!locations) {
        perror("Error allocating memory for locations.");
        free(*sensor_records);
        return;
    }

    double *temperatures = malloc(size * sizeof(double));
    if (!temperatures) {
        perror("Error allocating memory for temperatures.");
        free(locations);
        free(*sensor_records);
        return;
    }

    srand((unsigned int)time(NULL)); // Seed random number generator with current time

    for (int i = 0; i < size; ++i) {
        // Assuming that the location string is not longer than MAX_STR_LEN
        locations[i] = malloc(MAX_STR_LEN * sizeof(char));
        if (!locations[i]) {
            perror("Error allocating memory for location.");
            free(temperatures);
            free(locations);
            free(*sensor_records);
            return;
        }

        // Set the location string using input or a default value if necessary
        // ...

        temperatures[i] = (double)(rand() % (max_temp - min_temp + 1)) + min_temp;
        // Bounds checking for random number generation
        if (temperatures[i] < min_temp || temperatures[i] > max_temp) {
            fprintf(stderr, "Error: Temperature out of bounds.\n");
            free(locations[i]);
            free(temperatures);
            free(locations);
            free(*sensor_records);
            return;
        }

        (*sensor_records)[i].location = locations[i];
        (*sensor_records)[i].temperature = temperatures[i];
    }
}
