```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int val;
    int *key;
    long offset;
} record;

int init_records(int *input, int size, int *keys, int keySize, int numRecords, int *errorCode) {
    clock_t start = clock();
    record *records = malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        *errorCode = 1;
        return -1;
    }

    long *offsets = malloc((size + numRecords) * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed.\n");
        *errorCode = 2;
        free(records);
        return -1;
    }

    long maxOffset = 0;

    for (int i = 0; i < size; ++i) {
        offsets[input[i]] += 1;
        if (offsets[input[i]] > maxOffset) {
            maxOffset = offsets[input[i]];
        }
    }

    if (maxOffset >= numRecords) {
        fprintf(stderr, "Overflow in generating random values.\n");
        *errorCode = 3;
        free(offsets);
        free(records);
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        offsets[input[i]] += numRecords;
    }

    int j = 0;
    for (int i = 0; i < size; ++i) {
        while (offsets[input[i]] > 0) {
            records[j].val = input[i];
            records[j].key = keys + (offsets[input[i]] - 1);
            records[j].offset = offsets[input[i]];
            offsets[records[j].val] -= 1;
            ++j;
            --offsets[input[i]];
        }
    }

    qsort(records, numRecords, sizeof(record), (int (*)(const void *, const void *))compare_records);

    printf("Contents of the records array:\n");
    for (int i = 0; i < numRecords; ++i) {
        printf("Record %d: %d, Key %d, Offset %ld\n", i, records[i].val, *(records[i].key), records[i].offset);
    }

    free(offsets);
    return 0;
}

int compare_records(const void *a, const void *b) {
    return (*(record *)a).val - (*(record *)b).val;
}
