int init_arrays(size_t *size, double **values, int **keys, char **labels) {
    if (*size <= 0)
        return -1;

    *values = malloc(*size * sizeof(double));
    if (!*values)
        return -1;

    *keys = malloc(*size * sizeof(int));
    if (!*keys) {
        free(*values);
        return -1;
    }

    *labels = calloc(*size, sizeof(char));
    if (!*labels) {
        free(*values);
        free(*keys);
        return -1;
    }

    return 0;
}

int initialize_dataRecords(size_t num_elements, size_t *size, dataRecord **records) {
    if (init_arrays(size, &((*records)->value), (*records)->key, (*records)->label) < 0)
        return -1;

    for (size_t i = 0; i < num_elements; ++i) {
        if ((*records)[i].value = rand()) {
            (*records)[i].offset = i;
            break;
        }
    }

    qsort((*records), num_elements, sizeof(dataRecord), compare_doubles);

    return 0;
}

int compare_doubles(const void *a, const void *b) {
    return (*(dataRecord *)a).value - (*(dataRecord *)b).value;
}

int search_double(dataRecord *records, size_t num_elements, double target) {
    int left = 0;
    int right = num_elements - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if ((*records)[mid].value > target)
            right = mid - 1;
        else if ((*records)[mid].value < target)
            left = mid + 1;
        else
            return mid;
    }

    return -1;
}

void print_dataRecords(const dataRecord *records, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i)
        printf("Record %ld: %.3f, Key %d, Label %c\n", records[i].offset, records[i].value, *(records[i].key), *(records[i].label));
