int search_dataRecord(DATA_RECORD *records, size_t num, double value) {
    int left = 0;
    int right = num - 1;
    int mid;
    while (left <= right) {
        mid = (left + right) / 2;
        if (records[mid].value == value) {
            return mid;
        } else if (records[mid].value > value) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
