[" Here's a C function that meets your requirements, using `pthread_mutex_t` for thread safety:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

pthread_mutex_t mutex;
long *offsets = NULL;
int *keys = NULL;
record *records = NULL;
size_t size = 0;

void init_and_allocate(size_t new_size) {
    if (new_size == size) return; // No need to reallocate if size hasn't changed

    pthread_mutex_lock(&mutex);

    free(offsets);
    free(keys);
    free(records);

    offsets = malloc(sizeof(long) * new_size);
    keys = malloc(sizeof(int) * new_size);
    records = malloc(sizeof(record) * new_size);

    if (offsets == NULL || keys == NULL || records == NULL) {
        // Handle failure
        pthread_mutex_unlock(&mutex);
        return;
    }

    size = new_size;
    pthread_mutex_unlock(&mutex);
}

void set_random_values(size_t start, size_t end) {
    pthread_mutex_lock(&mutex);

    for (size_t i = start; i < end; ++i) {
        records[i].value = rand() % 100 + 1;
    }

    pthread_mutex_unlock(&mutex);
}

void update(int key, long offset, int new_value) {
    pthread_mutex_lock(&mutex);

    // Find the record with the given key
    size_t index = 0;
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] == key) {
            index = i;
            break;
        }
    }

    // Update the record's value and offset value
    records[index].value = new_value;
    offsets[index] = offset;

    pthread_mutex_unlock(&mutex);
}

void thread_safe_example() {
    pthread_mutex_init(&mutex, NULL);

    // Initialize and allocate memory for the first time
