#include <unistd.h>
#include <sys/stat.h>
#include <dirent.h>
#include <pthread.h>

enum { SUCCESS = 0, FAILURE = -1 };

struct file_data {
    char *filename;
    char *buffer;
    size_t buffer_size;
    size_t line_count;
};

void* process_file(void *arg) {
    struct file_data *data = arg;
    FILE *fp = fopen(data->filename, "r");
    if (!fp) return (void*)FAILURE;

    data->buffer = malloc(data->buffer_size);
    if (!data->buffer) {
        fclose(fp);
        return (void*)FAILURE;
    }

    size_t read = 0;
    while ((read = fgets(data->buffer, data->buffer_size, fp)) != NULL) {
        ++data->line_count;
        // Perform other operations on the data...
    }

    free(data->buffer);
    fclose(fp);

    return (void*)SUCCESS;
}

int process_directory(const char *directory, size_t num_threads) {
    DIR *dir = opendir(directory);
    if (!dir) return FAILURE;

    pthread_t threads[num_threads];
    struct file_data files[num_threads];

    struct dirent *entry;
    size_t index = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char *filename = malloc(strlen(entry->d_name) + 1);
        if (!filename) {
            closedir(dir);
            return FAILURE;
        }
        strcpy(filename, entry->d_name);

        files[index].filename = filename;
        files[index].buffer = NULL;
        files[index].buffer_size = 4096; // Adjust buffer size as needed.
        files[index].line_count = 0;

        pthread_create(&threads[index], NULL, process_file, &files[index]);
        ++index;
    }

    int results[num_threads];
    for (size_t i = 0; i < index; ++i) {
        void *ret;
        pthread_join(threads[i], &ret);
        results[i] = (int)ret;
    }

    closedir(dir);

    // Check for errors and print results...
}
```
