    if (unionfind->data[rootX].rank < unionfind->data[rootY].rank) {
        unionfind->data[rootX].parent = rootY;
        unionfind->data[rootY].rank++;
    } else if (unionfind->data[rootX].rank > unionfind->data[rootY].rank) {
