void create_connection_pool(int num_records, const char *db_url, bool disable_ssl_verification) {
    // Initialize random seed for good distribution in random number generation
    srand(time(NULL));

    // Allocate memory for configuration settings and connection records
    struct Config *config = malloc(num_records * sizeof(struct Config));
    if (!config) {
        fprintf(stderr, "Error: Failed to allocate memory for config array\n");
        exit(EXIT_FAILURE);
    }

    struct ConnectionRecord **records = malloc(num_records * sizeof(struct ConnectionRecord*));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records array\n");
        free(config);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets and timeouts arrays
    long *offsets = malloc((num_records + 1) * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets array\n");
        free(config);
        free(records);
        exit(EXIT_FAILURE);
    }

    int *timeouts = malloc(num_records * sizeof(int));
    if (!timeouts) {
        fprintf(stderr, "Error: Failed to allocate memory for timeouts array\n");
        free(config);
        free(records);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize configuration settings and offset values
    for (int i = 0; i < num_records; ++i) {
        config[i].db_url = strdup(db_url);
        config[i].disable_ssl_verification = disable_ssl_verification;

        offsets[i] = i;
    }
    offsets[num_records] = -1; // Mark end of array

    // Initialize timeouts and connection records
    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(struct ConnectionRecord));
        if (!records[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free(config);
            free(records);
            free(offsets);
            free(timeouts);
            exit(EXIT_FAILURE);
        }

        // Ensure random timeout value does not exceed the maximum allowed value
        int max_timeout = 60; // Set maximum timeout to 60 seconds for this example
        int timeout = rand() % (max_timeout + 1);
        records[i]->timeout = &timeouts[i];
        timeouts[i] = timeout;

        // Generate unique IDs for each connection record without potential overflow conditions
        records[i]->id = offsets[i];
        while (records[offsets[i + 1]] && records[offsets[i + 1]]->id >= records[i]->id) {
            records[i]->id += num_records;
        }

        // Initialize config pointer for each record
        records[i]->config = &config[i];
    }

    // Initialize connection pool object
    struct ConnectionPool *pool = malloc(sizeof(struct ConnectionPool));
    if (!pool) {
        fprintf(stderr, "Error: Failed to allocate memory for connection pool object\n");
        free(config);
        free(records);
        free(offsets);
        free(timeouts);
        exit(EXIT_FAILURE);
    }

    pool->num_connections = num_records;
    pool->records = records;
    pool->offsets = offsets;
    pool->timeouts = timeouts;

    return;
}
