#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct Record {
    int value;
} Record;

int check_memory(size_t size, size_t total_limit) {
    // Check if the requested memory is within the total limit and available system memory
    mallinfo mem_info = mallinfo();
    if (mem_info.uordblks + size > total_limit || mem_info.fordblks < 2 * size) {
        return -1; // Insufficient memory
    }
    return 0; // Sufficient memory
}

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment - 1);
    if (ptr != NULL) {
        ptr = (char *)((size_t)ptr + alignment - 1 & ~(alignment - 1));
    }
    return ptr;
}

void aligned_free(void *ptr) {
    free((char *)(((size_t)ptr + sizeof(char) - 1) & ~(sizeof(char) - 1)));
}

int create_arrays(size_t offset_len, size_t key_range_len, size_t record_len, size_t total_limit, long *offsets, int *keys, Record **records) {
    if (check_memory((offset_len + key_range_len + record_len * sizeof(Record)) * sizeof(void*), total_limit) != 0) {
        return -1; // Insufficient memory
    }

    offsets = aligned_malloc(offset_len * sizeof(long), 4);
    if (offsets == NULL) {
        return -1; // Memory allocation failure
    }

    for (size_t i = 0; i < offset_len; ++i) {
        offsets[i] = 4 * (i + 1); // Ensure alignment with multiples of 4
    }

    keys = aligned_malloc(key_range_len * sizeof(int), 8);
    if (keys == NULL) {
        aligned_free(offsets);
        return -1; // Memory allocation failure
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < key_range_len; ++i) {
        keys[i] = rand() % key_range_len + 1; // Ensure uniqueness within the specified range
