Record init_record(const std::array<int, 2>& range) {
    Record r;
    r.value = std::get<0>(range) + std::random_device{}() % (std::get<1>(range) - std::get<0>(range));
    return r;
}

// Function to initialize data structures for a given round of initialization
void init_data(const size_t rounds, const size_t offsetsSize, const size_t keysSize, const size_t recordsSize, std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<> dis(0, recordsSize - 1);

    std::mutex mtx;
    auto shuffle_indexes = [&](std::vector<size_t>& v) {
        std::sort(v.begin(), v.end());
        std::random_shuffle(v.begin(), v.end(), rng);
    };

    // Allocate and initialize offsets, keys, and records for the current round
    offsets.resize(offsetsSize);
    keys.resize(keysSize);
    records.resize(recordsSize);

    std::vector<size_t> idx;
    idx.reserve(recordsSize);
    shuffle_indexes(idx);

    auto validate = [&]() {
        // Validate integrity of the data structures after initialization
        for (size_t i = 0; i < recordsSize; ++i) {
            if (records[idx[i]].value < 0 || records[idx[i]].value >= recordsSize) {
                std::cout << "Validation error: invalid record value." << std::endl;
                return false;
            }
        }
        return true;
    };

    log_details("Init Data", rounds, offsetsSize, keysSize, recordsSize);

    for (size_t r = 0; r < rounds; ++r) {
        auto minMax = rand_range(0, recordsSize);
        std::fill(offsets.begin(), offsets.end(), r * recordsSize + r);
        std::fill(keys.begin(), keys.end(), r);
        std::copy_n(idx.begin(), recordsSize / rounds, keys.begin() + r * recordsSize);

        // Perform concurrent initialization using threads
        std::vector<std::future<void>> futures;
        for (size_t i = 0; i < rounds; ++i) {
            size_t start = i * recordsSize / rounds;
            size_t end = (i + 1) * recordsSize / rounds;
            if (end > recordsSize) end = recordsSize;

            futures.push_back(std::async(std::launch::async, [=]() mutable {
                std::lock_guard<std::mutex> lock(mtx);
                for (size_t j = start; j < end; ++j) {
                    records[idx[j]] = init_record(minMax);
                }
            }));
        }

        if (!validate()) break;

        // Wait for all threads to finish their work
        for (auto& f : futures) f.wait();

        log_details("Validation", rounds, offsetsSize, keysSize, recordsSize);
    }
}
