int allocate_and_initialize(int num_records, size_t *offsets, int *keys, record **records, metadata **metadata, bool *error) {
    if (num_records > INT_MAX || num_records <= 0) {
        *error = true;
        return -1;
    }

    // Allocate memory for offsets, keys, records, and metadata arrays
    long *offsets_arr = malloc(num_records * sizeof(long));
    int *keys_arr = malloc(num_records * sizeof(int));
    record *records_arr = calloc(num_records, sizeof(record));
    metadata *metadata_arr = calloc(num_records, sizeof(metadata));

    if (!offsets_arr || !keys_arr || !records_arr || !metadata_arr) {
        *error = true;
        free(offsets_arr);
        free(keys_arr);
        free(records_arr);
        free(metadata_arr);
        return -1;
    }

    // Initialize offsets and keys arrays with zeros, as they are not needed for this example
    memset(offsets_arr, 0, num_records * sizeof(long));
    memset(keys_arr, 0, num_records * sizeof(int));

    // Set values in records array to random numbers within [0, 100]
