        metadata_arr[i].offset = offsets_arr[i];
        metadata_arr[i].key = keys_arr[i];
    }

    // Sort records based on their 'key' values in ascending order
    qsort(records_arr, num_records, sizeof(record), compare_records);

    // Store pointers to allocated arrays for return
    *offsets = offsets_arr;
    *keys = keys_arr;
    *records = records_arr;
    *metadata = metadata_arr;

    *error = false;
    return 0;
}

int compare_records(const void *a, const void *b) {
    // Implement your sorting algorithm here. For simplicity, this example uses a basic qsort implementation for comparison purposes.
    record *r1 = (record *)a;
    record *r2 = (record *)b;
    return r1->value - r2->value;
}

void free_memory(size_t *offsets, int *keys, record *records, metadata *metadata) {
    // Free dynamically allocated memory for each array in reverse order to ensure proper cleanup of nested allocations
    free(metadata);
    free(records);
    free(keys);
    free(offsets);
}
