```cpp
#include <vector>
#include <chrono>
#include <iostream>
#include <string>
#include <functional>
#include <memory>
#include <unordered_map>
#include <utility>
#include <atomic>

using Clock = std::chrono::steady_clock;
typedef std::vector<std::unique_ptr<LogEntry>> LogEntries;
typedef std::vector<MetadataField*> MetadataFields;

struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
    MetadataFields metadata;
};

struct MetadataField {
    enum { INT, DOUBLE, STRING } type;
    union {
        int i;
        double d;
        std::string s;
    } value;
};

class LogProcessor {
private:
    size_t logCapacity = 0;
    size_t metadataFieldCount = 0;
    LogEntries logs;
    MetadataFields metadataFields;
    std::function<void(LogEntry&)> onLogAdded;
    std::unordered_map<std::string, std::function<void(MetadataField&)>> onMetadataChanged;
    std::atomic_int numThreads{ 1 };
    mutable std::mutex mtx;

public:
    LogProcessor() : logs(logCapacity), metadataFields(metadataFieldCount) {}

    void setOnLogAdded(const std::function<void(LogEntry&)>& f) { onLogAdded = f; }

    void setOnMetadataChanged(const std::string& key, const std::function<void(MetadataField&)>& f) {
        onMetadataChanged[key] = f;
    }

    void addCustomFunction(const std::function<void(LogEntry&)>& f) {
        std::unique_lock<std::mutex> lk(mtx);
        if (onLogAdded == nullptr) {
            onLogAdded = f;
        } else {
            auto combinedFn = [this, f](LogEntry& e) {
                onLogAdded(e);
                f(e);
            };
            setOnLogAdded(combinedFn);
        }
    }

    void addCustomMetadataFunction(const std::string& key, const std::function<void(MetadataField&)>& f) {
        if (onMetadataChanged.count(key)) {
            auto combinedFn = [this, f](MetadataField& e) {
                onMetadataChanged[key](e);
                f(e);
            };
            setOnMetadataChanged(key, combinedFn);
        } else {
            setOnMetadataChanged(key, f);
        }
    }

    void resizeLogs() {
        if (logCapacity == logs.size()) {
            logCapacity *= 2;
            LogEntries newLogs(logCapacity);
            for (auto& e : logs) {
                newLogs.push_back(std::move(e));
            }
            logs = std::move(newLogs);
        }
    }

    void resizeMetadataFields() {
        if (metadataFieldCount == metadataFields.size()) {
            metadataFieldCount *= 2;
            MetadataFields newFields(metadataFieldCount);
            for (auto f : metadataFields) {
                newFields.push_back(f);
            }
            metadataFields = std::move(newFields);
        }
    }

    LogEntry& addLogEntry() {
        resizeLogs();
        auto& entry = logs.back().reset(new LogEntry());
        entry->timestamp = Clock::now();
        return *entry;
    }

    MetadataField& addMetadataField() {
        resizeMetadataFields();
        auto& field = metadataFields.back().reset(new MetadataField());
        return *field;
    }

    void log(const LogEntry& entry) {
        std::unique_lock<std::mutex> lk(mtx);
        logs.push_back(std::make_unique<LogEntry>(entry));
        if (onLogAdded) {
            onLogAdded(*logs.back().get());
        }
    }

    void changeMetadataField(const std::string& key, const MetadataField& field) {
        auto it = onMetadataChanged.find(key);
        if (it != onMetadataChanged.end()) {
            std::unique_lock<std::mutex> lk(mtx);
            for (auto& mf : metadataFields) {
                if (&(*mf) == &field) {
                    it->second(mf->operator*());
                    break;
                }
            }
        }
    }
};
```

This implementation uses smart pointers to manage the log entries and metadata fields dynamically. It includes functions for adding custom data modification functions and integrating with an external logging system. The code also handles resizing gracefully, but it is not thread-safe by design. To make it safe for concurrent environments, use a mutex or another synchronization mechanism when accessing the internal structures."]

