    size_t record_size = sizeof(record);
    size_t memory_used = 0;
    size_t chunk_size = max_memory / (num_records + 2);

    if (chunk_size < record_size * 3) { // Minimum chunks for offsets, keys, and records
        chunk_size = record_size * 3;
    }

    long *offsets_chunk = malloc(num_records * sizeof(long));
    int *keys_chunk = malloc(num_records * sizeof(int));
    record *records_chunk = malloc(num_records * (sizeof(record) + chunk_size));

    if (!offsets_chunk || !keys_chunk || !records_chunk) {
        free(offsets_chunk);
        free(keys_chunk);
        free(records_chunk);
        return -1;
    }

    memory_used += num_records * sizeof(long) + num_records * sizeof(int) + num_records * (sizeof(record) + chunk_size);

    // Handle edge cases for small or large numbers of records
    if (num_records <= 10) {
        for (size_t i = 0; i < num_records; ++i) {
            offsets[i] = i * chunk_size + sizeof(long) * 3; // Store offsets in memory
            keys[i] = i; // Simulate initial record values
            records_chunk[i].value = 1; // Set initial value for each record
        }
    } else {
        size_t start_index = num_records / 2;
        size_t half_records = num_records / 2;

        for (size_t i = 0; i < half_records; ++i) {
            offsets[i] = i * chunk_size + sizeof(long) * 3; // Store offsets in memory
            keys[i] = i; // Simulate initial record values
            records_chunk[i].value = (i % 2 == 0) ? 1 : -1; // Set initial value for even and odd records
        }

        for (size_t i = half_records; i < num_records; ++i) {
            offsets[i] = start_index * chunk_size + sizeof(long) * 3 + (i - half_records) * record_size; // Store offsets in memory
            keys[i] = i + half_records; // Simulate initial record values
            records_chunk[i].value = ((start_index + i) % 2 == 0) ? 1 : -1; // Set initial value for each record
        }
    }

    *offsets = malloc(num_records * sizeof(long));
    memcpy(*offsets, offsets_chunk, num_records * sizeof(long));
    free(offsets_chunk);

    *keys = malloc(num_records * sizeof(int));
    memcpy(*keys, keys_chunk, num_records * sizeof(int));
    free(keys_chunk);

    *records = records_chunk;
    memory_used += num_records * chunk_size; // Account for record and chunk data

    if (memory_used > max_memory) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    return 0;
}
