    {
        Thread.Sleep(TimeSpan.FromMinutes(5)); // Adjust as needed for real-time updates
        FetchConfigurationAsync().Wait();
    }
}

private static int RetryCount = 3;
private static async Task<Task> RetryWithExponentialBackoff(int retryCount, Func<Task> action)
{
    for (int i = 0; i < retryCount; i++)
    {
        try
        {
            return action();
        }
        catch (Exception ex)
        {
            LogErrorAndMonitor(ex);
            await Task.Delay((long)Math.Pow(2, i + 1) * 1000); // Increase delay exponentially for each retry
        }
    }
    throw new Exception("Maximum retries exceeded.");
}

private static void LogErrorAndMonitor(Exception ex)
{
    logger.Error(ex, "Failed to fetch configuration or update cache");
    // Integrate with external monitoring system here
}

