}

void search(Record *records, size_t num_records, int value) {
    size_t low = 0, high = num_records - 1;
    while(low <= high) {
        size_t mid = (low + high) / 2;
        if(records[mid].value > value)
            high = mid - 1;
        else if(records[mid].value < value)
            low = mid + 1;
        else
            printf("Found %d at position %zu\n", value, mid);
    }
}

