#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

// Maximum number of records for each allocation, can be adjusted dynamically based on user input or configuration file
#define MAX_RECORDS 1024

// Structure representing a record with an integer value
typedef struct Record {
    int value;
} Record;

// Function to read initial values from configuration file
int* loadConfig(const char* filename, size_t* size) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening configuration file");
        exit(EXIT_FAILURE);
    }

    struct stat st;
    fstat(fd, &st);
    void* data = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) {
        perror("Error mapping configuration file");
        exit(EXIT_FAILURE);
    }

    int* config = data;
    *size = st.st_size / sizeof(int);
    return config;
}

// Function to manage dynamically allocated resources for the database indexing system
void initDatabase(Record** records, int* keys, long* offsets, size_t* sizes, const char* filename) {
    int* config = loadConfig(filename, sizes);

    // Allocate and initialize arrays based on configuration file values
    keys = realloc(keys, *sizes * sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys");
        exit(EXIT_FAILURE);
    }
    offsets = realloc(offsets, *sizes * sizeof(long));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        exit(EXIT_FAILURE);
    }

    records = malloc(MAX_RECORDS * sizeof(Record*));
    if (!records) {
        perror("Error allocating memory for record pointers");
        exit(EXIT_FAILURE);
    }

    // Initialize keys and offsets with values from configuration file
    for (size_t i = 0; i < *sizes; ++i) {
        keys[i] = config[i];
        offsets[i] = i == 0 ? 0 : offsets[i - 1] + sizeof(keys[i - 1]);
    }

    // Initialize records with random values within a given range
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            perror("Error allocating memory for record");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % *sizes;
    }
}

// Thread-safe access to the database, using pthread_mutex_t for mutual exclusion
pthread_mutex_t db_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to perform operations on the database indexing system, used by multiple threads
void operateOnDatabase(Record* record) {
    // Lock the mutex to ensure thread safety when accessing or modifying the data structures
    pthread_mutex_lock(&db_mutex);

    int index = record->value;
    Record* target = records[index];
    if (target && !target->value) {
        // Mark the record as occupied to avoid conflicts in subsequent operations
        target->value = 1;
        printf("Record %d is now occupied.\n", index);
    } else {
        printf("Record %d is already occupied or not available.\n", index);
    }

    // Unlock the mutex to allow other threads to access or modify the data structures
    pthread_mutex_unlock(&db_mutex);
}

// Example usage in main function
int main() {
    Record* records = NULL;
    int keys[10];
    long offsets[10];
    size_t sizes[] = { 5 }; // Initialize with a small array for testing purposes

    initDatabase(&records, keys, offsets, sizes, "config.txt");

    pthread_t threads[MAX_RECORDS];
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        Record* record = records[i];
        if (record && !record->value) {
            pthread_create(&threads[i], NULL, operateOnDatabase, record);
        }
    }

    // Wait for all threads to finish their work
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free dynamically allocated resources when done
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);
    free(offsets);
    free(keys);

    return 0;
}
