int init_records(size_t size, long *offsets, int *keys, record **records) {
    if (!size || !offsets || !keys || !records)
        return -1; // Invalid input parameters

    *records = malloc(size * sizeof(**records));
    if (!*records)
        return -2; // Failed to allocate memory for records

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < size; ++i) {
        (*records + i)->value = rand() % 100;
        if (i < size - 1)
            (*records + i)->offset = (*records + i + 1)->offset + 1; // Increment offsets sequentially
        else
            (*records + i)->offset = 0; // Last record has an offset of 0

        if (!(*(keys + (*records + i)->offset) = malloc(sizeof(int)))) {
            free(*records); // Deallocate records in case of error
            return -3; // Failed to allocate memory for keys
        }
    }

    *offsets = 0;

    return 0; // Successfully initialized records
}

void print_records(size_t size, record *records) {
