   void init_records(int size, int min_value, int max_value, int *keys, int *error) {
       long *offsets = malloc((size + 1) * sizeof(long));
       if (!offsets) {
           *error = -1; // Allocation failed
           return;
       }

       *keys = malloc(size * sizeof(int));
       if (!*keys) {
           free(offsets);
           *error = -2; // Key allocation failed
           return;
       }

       struct record *records = malloc(size * sizeof(struct record));
       if (!records) {
           free(*keys);
           free(offsets);
           *error = -3; // Record allocation failed
           return;
       }

       srand((unsigned int)time(NULL));

       offsets[0] = 0;
       for (int i = 0; i < size; ++i) {
           int key = arc4random_uniform(i);
           if (key >= 0 && key < size) {
               records[i].value = arc4random_range(min_value, max_value);
               records[i].key = &keys[key];

               while (*records[i].key != -1 && offsets[*records[i].key] < i) {
                   ++(*records[i].key);
               }
               *records[i].key = -1;
               offsets[*records[i].key] = i + 1;
           } else {
               *error = -4; // Random value generation overflow
               break;
           }
       }

       for (int i = 0; i < size; ++i) {
           printf("Record %d: Value = %d, Key = %d\n", i, records[i].value, *records[i].key);
       }

       free(offsets);
   }

   void arc4random_range(int *min, int *max) {
       int range = *max - *min;
       if (range <= 0) {
           return;
       }

       *min = arc4random_uniform(range + 1);
       *max = *min + range;
   }

   void arc4random_uniform(int *result, int n) {
       if (n <= 0) {
           return;
       }

       unsigned short w[4] = {12345, 36243, 12376, 54678};
       unsigned short v[256];

       int i, j, k, t, x, r;

       for (i = 0; i < 256; i++) {
           v[i] = i;
       }

       for (x = 17; x > 0; x--) {
           for (r = 30; r > 0; r -= 2) {
               for (i = 0; i < 256; i++) {
                   j = (w[i] & 0x0f) ^ v[i];
                   v[i] = v[(j + w[i] >> 4) & 255];
               }
           }

           for (i = 0; i < 256; i++) {
               j = (w[i] & 0x0f8) >> 3;
               t = v[j] ^ v[v[(w[i] & 0xfff) >> 11]];
               v[j] = v[v[j] ^ t];
               v[t] = v[i];
           }

           for (i = 0; i < 256; i++) {
               w[(w[i] + 1) & 0x1ff] = v[i];
           }
       }

       *result = v[arc4random_uniform(256)];
   }
