    int *keys = malloc(recordSize * sizeof(int));
    if (!(offsets || keys)) {
        free(input);
        return 1; // Allocation error
    }

    for (int i = 0; i < inputSize; ++i) {
        scanf("%d", &input[i]);
    }

    qsort(input, inputSize, sizeof(int), (int (*)(const void*, const void*))compare);

    for (int i = 0; i < recordSize; ++i) {
        keys[i] = binarySearch(input, 0, inputSize - 1, input[i]);
        if (keys[i] == -1) { // Key not found error
            free(offsets);
            free(keys);
            free(input);
            return 1;
        }
        offsets[i] = i;
    }

    struct Record *records = malloc(recordSize * sizeof(struct Record));
