    }

    free(input);
    free(keys);
    free(offsets);

    return 0; // Success
}

int binarySearch(const int arr[], int low, int high, int key) {
    if (low <= high) {
        int mid = (high + low) / 2;

        if (arr[mid] == key)
            return mid;

        if (arr[mid] < key)
            return binarySearch(arr, mid + 1, high, key);

        return binarySearch(arr, low, mid - 1, key);
    }

    return -1; // Key not found error
}

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
