#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char *str_ptr;
} data_entry;

int init_data_entries_from_file(const char *filename, size_t *num_entries, data_entry **entries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        return 1; // Error: cannot open file
    }

    size_t size = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        size++;
    }
    fclose(file);

    if (!size) {
        return 1; // Error: no data in the file
    }

    *entries = malloc(size * sizeof(data_entry));
    if (!*entries) {
        return 1; // Error: memory allocation failed for entries
    }

    char **strings = malloc(size * sizeof(char *));
    if (!strings) {
        free(*entries);
        return 1; // Error: memory allocation failed for strings
    }

    double *values = malloc(size * sizeof(double));
    if (!values) {
        free(*entries);
        free(strings);
        return 1; // Error: memory allocation failed for values
    }

    *num_entries = size;

    file = fopen(filename, "r");
    if (!file) {
        free(values);
        free(strings);
        free(*entries);
        return 1; // Error: cannot re-open the file
    }

    size_t i = 0;
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " \n");
        double value;
        if (sscanf(token, "%lf", &value) != 1 || !token) {
            break; // Error: invalid input format in the line
        }
        values[i] = value;

        token = strtok(NULL, " \n");
        if (!token) {
            break; // Error: no string data found for this line
        }

        size_t len = strlen(token) + 1;
        strings[i] = malloc(len);
        if (!strings[i]) {
            free(values);
            free(strings);
            free(*entries);
            fclose(file);
            return 1; // Error: memory allocation failed for string in line i
        }
        strcpy(strings[i], token);

        (*entries)[i].value = values[i];
        (*entries)[i].str_ptr = strings[i];
        i++;
    }

    fclose(file);

    if (i < size) { // Error: not all lines in the file were processed correctly
        free(values);
        free(strings);
        for (size_t j = 0; j < i; j++) {
            free((*entries)[j].str_ptr);
        }
        free(*entries);
        return 1;
