int init_records(size_t size, size_t *offsets, size_t *keys, record **records) {
    if (!size || !offsets || !keys || !records) return 1; // Null pointer check

    *records = malloc(size * sizeof(record));
    if (*records == NULL) return 2; // Allocation error

    long *offset_arr = malloc(size * sizeof(long));
    int *key_arr = malloc(size * sizeof(int));
    if (!offset_arr || !key_arr) {
        free(*records); // Release memory in case of allocation failure
        return 2;
    }

    *offsets = offset_arr;
    *keys = key_arr;

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i; // Initialize offset array
        (*key_arr)[i] = i; // Initialize key array
        (*records)[i].val = rand() % MAX_RANDOM; // Generate random value within range
        (*records)[i].key = &(*key_arr)[i]; // Assign corresponding key pointer
    }

    return 0;
}

void print_records(size_t size, const record *const records) {
    if (!size || !records) return; // Null pointer check

    for (size_t i = 0; i < size; ++i) {
        printf("Record %ld: Key %d, Value %d\n", (*records)[i].key, (*records)[i].val);
    }
