int init_records(size_t offsets_size, size_t keys_size, size_t records_size, unsigned long min_offset, unsigned long max_offset) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (!(offsets = malloc(offsets_size * sizeof(long))) ||
         !(keys = malloc(keys_size * sizeof(int))) ||
         !(records = malloc(records_size * sizeof(record)))) {
        // Deallocate and return an error code
        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        return 1;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < offsets_size; ++i) {
        // Ensure uniqueness of offset values within the allocated range
        while (1) {
            offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
            int unique = 1;
            for (size_t j = 0; j < i; ++j) {
                if (offsets[j] == offsets[i]) {
                    unique = 0;
                    break;
                }
            }
            if (unique) break;
        }

        keys[i] = i;
        records[i].key = &keys[i];
        records[i].value = rand() % INT_MAX + 1;
    }

    // Sort the records based on their offset values in ascending order
    qsort(offsets, offsets_size, sizeof(long), (int (*)(const void*, const void*))compare_long);

    printf("Offsets: ");
    for (size_t i = 0; i < offsets_size; ++i) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");

    return 0;
}

int compare_long(const void *a, const void *b) {
    return (*(const long *)a - *(const long *)b);
}
