#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct sensorData {
    double value;
    int timestamp, id;
    const char *key, *label;
} SensorData;

int read_input(double *arr, int *size) {
    double num;
    for (int i = 0; i < *size; ++i) {
        scanf("%lf", &num);
        arr[i] = num;
    }
    return 0;
}

int init_arrays(double *values, int *keys, char *labels, int size, SensorData **data) {
    *data = malloc(size * sizeof(SensorData));
    if (!*data) return -1;

    (*data) = calloc(size, sizeof((*data)[0]));
    if (!(*data)) {
        free(*data);
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        (*data)[i].value = values[i];
        (*data)[i].key = keys + i;
        (*data)[i].label = labels + i;
    }
    return 0;
}

int generate_rand(int min, int max) {
    static unsigned seed = time(NULL);
    int randNum;
    if (seed == time(NULL)) seed = 1; // reset seed at the start of the program
    srand(seed++);
    randNum = rand() % (max - min + 1) + min;
    return randNum;
}

int initialize_sensor_data(double *values, int size, SensorData **data) {
    if (init_arrays(values, NULL, NULL, size, data) < 0) return -1;

    for (int i = 0; i < size; ++i) {
        (*data)[i].timestamp = generate_rand(0, INT32_MAX);
        (*data)[i].id = generate_rand(0, INT32_MAX);
    }

    qsort((*data), size, sizeof((*data)[0]), (int (*)(const void*, const void *))cmp);
    return 0;
}

int cmp(const void *a, const void *b) {
    SensorData *x = a, *y = b;
    if (x->value > y->value) return 1;
    else if (x->value < y->value) return -1;
    else return 0;
}

int search_value(SensorData *data, int size, double value) {
    int left = 0, right = size - 1, mid;
    while (left <= right) {
        mid = (left + right) / 2;
        if (data[mid].value == value) return mid;
        if (data[mid].value < value) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

void print_sensor_data(SensorData *data, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Sensor Data [%d]: Value: %.2lf, Timestamp: %d, Sensor ID: %d\n",
               i, data[i].value, data[i].timestamp, data[i].id);
    }
}

