    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            line_count++;
        }
    }
    rewind(file);
    *lines = line_count + 1; // Account for the final newline not being counted.
    fclose(file);

    return 0;
}

size_t half(size_t n) {
    if (n == 0) {
        return 0;
    }
    return n / 2;
}

int main() {
    const char *filename = "config.txt";
    size_t lines, keys, offsets, records;
    int err = read_lines(filename, &lines);
    if (err) {
        return err;
    }

    offsets = (size_t)lines;
    keys = half(offsets);
    records = min(offsets, keys);

    long *offset_arr = malloc(offsets * sizeof(long));
    int *key_arr = malloc(keys * sizeof(int));
    Record *record_arr = malloc(records * sizeof(Record));

    if (!offset_arr || !key_arr || !record_arr) {
        perror("Error allocating memory");
        if (!offset_arr) {
            free(key_arr);
            free(record_arr);
        }
        if (!key_arr) {
            free(record_arr);
        }
        return -1;
    }

    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        free(offset_arr);
        free(key_arr);
        free(record_arr);
        return -1;
    }

    size_t line_index = 0;
    int key_index = 0;
    long current_line_number = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            if (line_index > 0) {
                offset_arr[current_line_number] = current_line_number;
                key_arr[key_index++] = line_index;
            }
            current_line_number++;
            line_index = 0;
        } else {
            line_index++;
        }
    }
    rewind(file); // Rewind the file for randomizing record values

    if (ferror(file)) {
        perror("Error reading file");
        free(offset_arr);
        free(key_arr);
        free(record_arr);
        return -1;
    }
    fclose(file);

    for (size_t i = 0; i < records; ++i) {
        record_arr[i].value = rand() % 2001 - 1000;
    }

    // You can perform further operations with offset_arr, key_arr, and record_arr here.

    free(offset_arr);
    free(key_arr);
    free(record_arr);

    return 0;
}
```

This code reads the number of lines in a file named "config.txt" and dynamically allocates memory for offsets, keys, and record arrays based on that information. It handles potential edge cases where the file might be empty or contain only a few lines by accounting for the final newline not being counted and checking for errors during file reading operations. The function also initializes each record's int field with a random value within the range of -1000 to 1000 and frees the allocated memory after the operations are completed.

Note that this implementation assumes the configuration file contains only integers, separated by newlines. If you need to handle additional formatting or characters in the configuration file, you'll need to adjust the code accordingly.']

