#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

int init_data(size_t *key_arr, size_t *offset_arr, size_t *record_arr, size_t *num_records, const char *config_file) {
    int fd = open(config_file, O_RDONLY);
    if (fd < 0) return -1;

    struct stat st;
    fstat(fd, &st);
    long size = st.st_size;
    char *buf = malloc(size);
    if (!buf) {
        close(fd);
        return -2;
    }

    ssize_t read = read(fd, buf, size);
    if (read != size) {
        free(buf);
        close(fd);
        return -3;
    }

    char delim[] = "\n";
    char *token = strtok(buf, delim);
    int i = 0;
    while (token) {
        if (i >= *num_records) {
            *num_records += 1000; // Scale up the array size for future records
            record_arr = realloc(record_arr, (*num_records) * sizeof(record));
            key_arr = realloc(key_arr, (*num_records) * sizeof(size_t));
            offset_arr = realloc(offset_arr, (*num_records) * sizeof(long));
        }

        sscanf(token, "%ld %d", &record_arr[i].offset, &record_arr[i].key);
        key_arr[i] = record_arr[i].key;
        offset_arr[i] = record_arr[i].offset;
        i++;

        if (!(i % 100)) {
            time_t rawtime;
            struct tm *timeinfo;
            char time_string[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("Initialized record %d at offset %ld with key %d at: %s\n", i, record_arr[i].offset, record_arr[i].key, time_string);
        }

        token = strtok(NULL, delim);
    }
    free(buf);
    close(fd);
    return 0;
}

void cleanup(size_t *key_arr, size_t *offset_arr, size_t *record_arr, size_t num_records) {
    if (key_arr) free(key_arr);
    if (offset_arr) free(offset_arr);
    if (record_arr) free(record_arr);
}
