#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    float humidity;
} Record;

void validate_file(FILE *fp) {
    if (!fp || feof(fp) || ferror(fp)) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }
}

int count_lines(FILE *fp) {
    int count = 0;
    char c;
    while ((c = fgetc(fp)) != EOF) {
        if (c == '\n') count++;
    }
    rewind(fp);
    return count + 1; // Considering the first line as well
}

void read_data(FILE *fp, double *temperatures, int *days, Record **records) {
    int temperature_size = (int)(count_lines(fp) / 2);
    int day_index_size = temperature_index_size / 2;
    int record_size = (temperature_size < day_index_size) ? temperature_size : day_index_size;

    *temperatures = malloc(temperature_size * sizeof(double));
    *days = calloc(day_index_size, sizeof(int));
    *records = malloc(record_size * sizeof(Record));

    if (!*temperatures || !*days || !(*records)) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    int i = 0;
    while (fscanf(fp, "%lf %d", &((*temperatures)[i]), &((*days)[i])) != EOF) {
        (*records)[i].humidity = (float)(rand() % 101);
        i++;
    }
}

int main() {
    srand(time(NULL));
    FILE *fp = fopen("weather.log", "r");
    validate_file(fp);

    double *temperatures = NULL;
    int *days = NULL;
    Record **records = NULL;

    read_data(fp, &temperatures, &days, &records);

    // Perform further operations with the allocated memory here

    free(temperatures);
    free(days);
    for (int i = 0; i < record_size; ++i) {
        free(records[i]);
    }
    free(records);
    fclose(fp);

    return 0;
}
