int dns_resolve(char* hostname, size_t records_count, size_t offset_size, size_t key_size, size_t record_size, u_char** ip_address) {
    struct hostent *host;
    struct in_addr **addr_list;
    int i;
    size_t total_size = records_count * record_size + offset_size * (records_count + 1);
    Record* records = malloc(total_size);
    u_char* keys = calloc(offset_size, key_size);
    u_long* offsets = calloc(records_count + 1, sizeof(u_long));

    if (!records || !keys || !offsets) {
        free(records);
        free(keys);
        free(offsets);
        return -1; // Memory allocation failed
    }

    host = gethostbyname(hostname);
    if (!host) {
        free(records);
        free(keys);
        free(offsets);
        return -2; // Host not found
    }

    addr_list = (struct in_addr**)host->h_addr_list;

    for (i = 0; addr_list[i]; i++) {
        memcpy(&records[offsets[records_count]].value, &((*addr_list[i]).s_addr), sizeof(u_long));
        records[offsets[records_count]++].key = (int)(keys + offset_size * i);
    }

    // Randomly fill the remaining records with values in a given range
    for (; i < records_count; i++) {
        records[offsets[i]].value = rand() % 100 + 50;
        records[offsets[i]].key = (int)(keys + offset_size * i);
    }

    // Print the contents of the records array for debugging purposes
    for (i = 0; i < records_count; i++) {
        printf("Record %d: key=%p, value=%d\n", i, records[offsets[i]].key, records[offsets[i]].value);
    }

    *ip_address = malloc(sizeof(u_char) * 4);
    memcpy(*ip_address, &records[0].value, sizeof(u_char) * 4);

    free(records);
    free(keys);
    free(offsets);

    return 0; // Success
}
