#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    double value;
    int *key_ptr;
    double *value_ptr;
};

int init_data(size_t *offsets, size_t num_offsets, size_t *keys, size_t num_keys,
              size_t *values, size_t num_values, size_t record_count, FILE *config) {
    int i;
    pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Handle dynamic allocation sizes provided as parameters
    long *long_offsets = malloc(record_count * sizeof(long));
    int *keys_array = malloc(num_keys * sizeof(int));
    double *values_array = malloc(num_values * sizeof(double));
    struct Record *records = malloc(record_count * sizeof(struct Record));

    if (!long_offsets || !keys_array || !values_array || !records) {
        perror("Memory allocation failed");
        return 1;
    }

    // Read and initialize data from external source
    for (i = 0; i < record_count; ++i) {
        // Optimized random number generation within the loop
        records[i].key = fgetc(config);
        records[i].value = rand() / RAND_MAX * 100.0;

        records[i].key_ptr = &keys_array[i];
        records[i].value_ptr = &values_array[i];
    }

    // If the data source provides variable-length data, reallocate accordingly
    if (feof(config)) {
        while (!feof(config) && fgetc(config) != '\n') {}  // Skip newline character if present
        rewind(config);

        // Reallocate as needed and continue reading data
        long_offsets = realloc(long_offsets, (ftell(config) + 1) * sizeof(long));
        keys_array = realloc(keys_array, ftell(config) * sizeof(int));
        values_array = realloc(values_array, ftell(config) * sizeof(double));
        records = realloc(records, ftell(config) * sizeof(struct Record));

        if (!long_offsets || !keys_array || !values_array || !records) {
            perror("Memory allocation failed");
            return 1;
        }
    }

    // Implement thread-safe access to the data structure using a mutex
    pthread_mutex_lock(&data_mutex);

    *offsets = ftell(config);
    *keys = num_keys;
    *values = num_values;

    pthread_mutex_unlock(&data_mutex);

    return 0;
}
