#include <time.h>

typedef struct Record {
    int value;
    int *key;
} Record;

int initialize_data(int array_size, int record_count, Record **records, int *keys, int *offsets) {
    if (array_size <= 0 || record_count <= 0)
        return 1; // Error: invalid parameters

    srand((unsigned)time(NULL));

    *records = malloc(record_count * sizeof(Record));
    if (!*records)
        return 2; // Error: memory allocation for records failed

    *keys = malloc(record_count * sizeof(int));
    if (!(*keys)) {
        free(*records);
        return 3; // Error: memory allocation for keys failed
    }

    *offsets = malloc((array_size + 1) * sizeof(int));
    if (!(*offsets)) {
        free(*records);
        free(*keys);
        return 4; // Error: memory allocation for offsets failed
    }

    int key_index = 0, offset_index = 0;
    for (int i = 0; i < record_count; ++i) {
        int value = rand() % array_size;

        // Ensure uniqueness of offset values
        while (offset_index < offset_index + array_size && offsets[offset_index] == value)
            value = (value + 1) % array_size;

        offsets[offset_index++] = value;
        records[i].value = rand() % INT_MAX;
        records[i].key = &keys[key_index++];
    }

    qsort(offsets, array_size + 1, sizeof(int), (void *)compare_offsets);

    return 0; // Success: initialization completed
}

int compare_offsets(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}
