    FILE_OPEN_FAIL = -3
};

int init_database(int *offsets, int num_keys, int max_memory, FILE *fp) {
    int total_size = 0;
    int size_per_record = sizeof(long) + sizeof(int) + sizeof(Record);
    int current_offset = 0;

    if (num_keys <= 0 || max_memory <= 0) {
        return INVALID_PARAMS;
    }

