        int key;
        int val;

        if (fp != NULL) {
            if (fscanf(fp, "%d%*d", &key) != 1) {
                return FILE_OPEN_FAIL;
            }
        } else {
            key = num_keys--;
        }

        if (total_size + size_per_record > max_memory) {
            return MEMORY_EXCEEDED;
        }

        Record *record = (Record *)((char*)offsets + current_offset);
        record->key = key;
        srand(key);
        record->value = rand() % 100; // Modify this to a suitable range for your use case.

        offsets[key] = current_offset;
        total_size += size_per_record;
        current_offset += size_per_record;
    }

