std::forward_list<std::string> insertString(std::forward_list<std::string>& list, const std::string& first, const std::string& second) {
    auto it = std::find(list.begin(), list.end(), first);
    if (it == list.end()) {
        list.push_back(first);
        it = list.end();
        --it;
    }
    it++;
    list.insert(it, second);

