long *initialize_offsets(long num_offsets, long* initial_values) {
    long *offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) return NULL;

    if (initial_values) {
        for (long i = 0; i < num_offsets; ++i) {
            offsets[i] = initial_values[i];
        }
    } else {
        for (long i = 0; i < num_offsets; ++i) {
            offsets[i] = rand() % RAND_MAX; // using RAND_MAX as an upper limit is more portable than using INT_MAX
        }
    }

    return offsets;
}

void free_offsets(long* offsets, long num_offsets) {
    if (offsets) free(offsets);
}

int* initialize_keys(long num_keys) {
    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) return NULL;

    for (long i = 0; i < num_keys; ++i) {
        keys[i] = i; // using sequential integer values by default
    }

    // sort and ensure uniqueness of keys
    qsort(keys, num_keys, sizeof(int), (int (*)(const void*, const void*))compare_ints);

    return keys;
}

void free_keys(int* keys, long num_keys) {
    if (keys) free(keys);
}

struct Record* initialize_records(long num_records, int min_val, int max_val, long seed) {
    int *keys = initialize_keys(num_records);
    if (!keys) return NULL;

    struct Record* records = malloc(num_records * sizeof(struct Record));
    if (!records) {
        free_keys(keys, num_records);
        return NULL;
    }

    long *offsets = initialize_offsets(num_records, NULL); // use current time as seed for random number generation if no seed is provided
    if (!offsets) {
        free_records(records, num_records);
        free_keys(keys, num_records);
        return NULL;
    }

    srand(seed != 0 ? seed : time(NULL));

    for (long i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        char str[21]; // buffer size is between [10, 20] characters for the random string
        snprintf(str, sizeof(str), "%.*s", rand() % 10 + 10, generate_random_string());
        records[i].str = malloc(strlen(str) + 1); // +1 for null terminator
        if (!records[i].str) {
            free_offsets(offsets, num_records);
            free_records(records, num_records);
            free_keys(keys, num_records);
            return NULL;
        }
        strcpy(records[i].str, str); // copy the generated string into the dynamically allocated buffer
    }

    free_offsets(offsets, num_records); // no longer needed after records have been initialized with offsets

    // validate records to ensure that all strings are correctly allocated and not null before returning from the function
    for (long i = 0; i < num_records; ++i) {
        if (!records[i].str || strlen(records[i].str) <= 0) {
            free_records(records, num_records);
            free_keys(keys, num_records);
            return NULL;
        }
    }

    free_keys(keys, num_records);
    return records;
}

void free_records(struct Record* records, long num_records) {
    if (records) {
        for (long i = 0; i < num_records; ++i) {
            free(records[i].str);
        }
        free(records);
    }
}
