    for (size_t i = allocatedSize; i < allocatedSize + 1024 && i < limit / sizeof(int); ++i) {
        keys[i] = rand() % 100 + 1; // Array of int keys
    }

    for (size_t i = allocatedSize; i < allocatedSize + 1024 && i < limit / sizeof(record); ++i) {
        records[i].value = rand() % 100 + 1; // Array of record structures
    }

    allocatedSize += 1024;
    return 0; // Successful memory allocation
}

void free_memory() {
    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s limit\n", argv[0]);
        return 1;
    }

    limit = strtoul(argv[1], NULL, 10);

    for (int i = 0; i < 5; ++i) {
        if (init() == -1) {
            free_memory();
            continue;
        }
        // Use the allocated memory here...
        reset();
    }

    free_memory();
    return 0;
}
