    long current_offset = 0;
    int i = 0;
    while (1) {
        Record record;
        if (fread(&record, sizeof(Record), 1, file) != 1)
            break;
        if (current_offset + sizeof(Record) > current_offset + *total_size) {
            *total_size += sizeof(Record) * (*num_records > i ? *num_records : i + 1);
            record.value = 0;
            record.key = 0;
            record.offset = current_offset;
            if (!realloc((void *)record, *total_size))
                error_and_exit("Failed to reallocate memory.");
            *num_records += 1;
        } else {
            record.value = 0;
            record.key = 0;
            record.offset = current_offset;
        }
        record.value = read_integer(file);
        record.key = read_integer(file);
        if (feof(file)) {
            (*num_records)--;
            break;
        }
        current_offset += sizeof(Record);
    }
    return realloc((void *)record, *total_size);
}

