#include <stdbool.h>
#include <time.h>

typedef struct {
    int key;
    int value;
} Record;

// Function to dynamically allocate memory and initialize arrays
int initializeArrays(size_t *offsets, int *keys, Record **records, size_t max_offsets) {
    // Validate input parameters
    if (max_offsets <= 0 || !max_offsets % sizeof(long)) {
        perror("Invalid maximum offset value");
        return 1;
    }

    // Allocate memory for offsets
    *offsets = (size_t)malloc(max_offsets * sizeof(size_t));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        return 1;
    }

    // Validate and limit the values in the offset array
    size_t num_records = 0;
    for (size_t i = 0; i < max_offsets; ++i) {
        if (*(offsets + i) >= max_offsets || *(offsets + i) < 0) {
            fprintf(stderr, "Invalid offset value at index %zu\n", i);
            free(*offsets);
            return 1;
        }
        if (i + 1 < *(offsets + i)) {
            fprintf(stderr, "Offset values must be non-decreasing\n");
            free(*offsets);
            return 1;
        }
        if (*(offsets + num_records) == i + 1) {
            ++num_records;
        }
    }

    // Allocate memory for keys and records
    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        return 1;
    }

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        free(*keys);
        free(*offsets);
        return 1;
    }

    // Initialize keys and records with random values
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        (*keys + i) = rand() % 101;
        (*records + i)->key = *(offsets + i);
        (*records + i)->value = rand() % 101;
    }

    return 0; // Successful initialization
}
