#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <dirent.h>
#include <pthread.h>

typedef struct file_entry {
    char *path;
    off_t size;
    void *content;
} file_entry;

file_entry* read_files(int *input_count, const char **input_list) {
    int count = *input_count;
    file_entry *entries = malloc(sizeof(file_entry) * count);

    for (int i = 0; i < count; ++i) {
        entries[i].path = strdup(input_list[i]);
        struct stat st;
        if (stat(input_list[i], &st) != 0) {
            fprintf(stderr, "Error reading %s\n", input_list[i]);
            continue;
        }
        entries[i].size = st.st_size;
        entries[i].content = malloc(entries[i].size);

        FILE *fp = fopen(input_list[i], "rb");
        if (!fp) {
            fprintf(stderr, "Error opening %s\n", input_list[i]);
            continue;
        }

        size_t bytes_read;
        while ((bytes_read = fread(entries[i].content, 1, entries[i].size, fp)) != static_cast<size_t>(entries[i].size)) {
            fprintf(stderr, "Error reading %s\n", input_list[i]);
            break;
        }

        fclose(fp);
    }

    *input_count = count;
    return entries;
}

void print_file_entries(const file_entry *entries, int count) {
    for (int i = 0; i < count; ++i) {
        printf("File %d:\n", i);
        printf("Path: %s\n", entries[i].path);
        printf("Size: %ld bytes\n", entries[i].size);
    }
}

// Thread-safe access and modification of the files array
pthread_mutex_t files_mutex = PTHREAD_MUTEX_INITIALIZER;
