namespace mylib {

class RandomGenerator {
public:
    RandomGenerator(unsigned int seed) : mt_(seed), a_(null_value_) { }

    double operator()() {
        // Mersenne Twister algorithm implementation with good distribution properties and minimal CPU usage
        uint32_t kk;
        do {
            next_ = mt_(mt_);
            kk = next_ >> 18u;
            next_ = (next_ << (36)) ^ (kk * uint64_t(a_[kk]) +uint64_t(a_[kk ^ (kk >> 13)]));
        } while ((next_ & uint64_t(1) << 18) == 0);
        double r = next_ >> 1; // 53 bit mantissa
        return r * (1.0 / std::pow(2, 53));
    }

    ~RandomGenerator() { delete[] a_; }

private:
    static constexpr uint64_t null_value_ = 0xc6a4d9fd; // Initial seeds for the Mersenne Twister algorithm
    std::mt19937 mt_;
    std::array<uint32_t, 624> a_;
    uint32_t next_;
};

