#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int initialize(int* keys, int n_keys, int* values, int* offsets, int capacity, int* records) {
    if (!capacity || !values || !offsets || !records) return -1;

    *records = malloc(sizeof(struct record) * capacity);
    if (*records == NULL) return -2;

    qsort(values, n_keys, sizeof(int), (int(*)(const void*, const void*)) &compare);

    for (int i = 0; i < n_keys; ++i) {
        int j = 0;
        while (j < capacity && values[j] != values[i]) ++j;
        if (j == capacity) return -3; // overflow
        records[j].value = values[i];
        records[j].key = keys + i;
        records[j].offset = offsets[i];
    }

    for (int j = n_keys; j < capacity; ++j) {
        int rand_index = rand() % n_keys;
        records[j] = (struct record){values[rand_index], keys + rand_index, offsets[rand_index]};
    }

    return 0;
}

// Helper function for qsort comparison
int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

