    int* key_ptr;
    double offset;
} data_entry;

int init_data(int num_entries, int* keys, double* values, data_entry** data) {
    *data = malloc(num_entries * sizeof(data_entry));
    if (!(*data)) return 1;

    for (int i = 0; i < num_entries; ++i) {
        (*data)[i].value = values[i];
        (*data)[i].key_ptr = keys + i;
        // Generate offset with good distribution properties
        (*data)[i].offset = rand() / (double)RAND_MAX * 100.0;
    }

    return 0;
}

int main(int argc, char** argv) {
    int num_entries = argc > 1 ? atoi(argv[1]) : 10;
    int* keys = malloc((num_entries + 1) * sizeof(int));
    double* values = malloc(num_entries * sizeof(double));

    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        values[i] = (double)(rand() % 100);
        keys[i] = i;
    }
    keys[num_entries] = -1;

    data_entry* data;
    if (init_data(num_entries, keys, values, &data)) {
        perror("Error initializing data");
        return 1;
    }

    // Print contents of data array
    for (int i = 0; i < num_entries; ++i) {
        printf("Value: %.2f\tKey: %d\tOffset: %.2f\n", data[i].value, *data[i].key_ptr, data[i].offset);
    }

    free(keys);
    free(values);
    free(data);

    return 0;
}
