#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    const int *key;
    long offset;
} Record;

int init_arrays(int key_count, size_t record_size, int **keys, Record **records) {
    if (!(*keys = malloc(key_count * sizeof(int))) || !(*records = malloc(record_size * sizeof(Record)))) {
        free(*keys);
        return 1;
    }

    for (int i = 0; i < key_count; ++i)
        (*keys)[i] = i;

    return 0;
}

long random_in_range(const long min, const long max) {
    if (max - min <= RAND_MAX)
        return rand() % (max - min + 1) + min;

    long result = min + (rand() / (RAND_MAX / (max - min) + 1));
    return result > max ? random_in_range(min, max) : result;
}

int init_records(size_t record_count, int key_count, Record **records) {
    if (!(*records = realloc(*records, record_count * sizeof(Record))))
        return 1;

    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = random_in_range(0, INT_MAX);
        if (!(*records)[i].key || !(*records)[i].offset) {
            free(*records);
            return 1;
        }
    }

    for (size_t i = 0; i < record_count; ++i) {
        int key = random_in_range(0, key_count - 1);
        (*records)[i].key = &((*keys)[key]);
        (*records)[i].offset = random_in_range(INT32_MIN, INT32_MAX);
    }

    return 0;
}

void print_records(const size_t record_count, const Record *records) {
    for (size_t i = 0; i < record_count; ++i)
        printf("Value: %d Key: %p Offset: %ld\n", records[i].value, records[i].key, records[i].offset);
}

int main() {
    int key_count;
    size_t record_size;
    scanf("%d%ld", &key_count, &record_size);

    int *keys;
    Record *records;
    if (init_arrays(key_count, record_size, &keys, &records)) {
        printf("Error allocating memory\n");
        return 1;
    }

    if (init_records(record_size, key_count, &records)) {
        printf("Error initializing records\n");
        free(keys);
        free(records);
        return 1;
    }

    print_records(record_size, records);

    free(keys);
    free(records);
    return 0;
}
