#include <time.h>

typedef struct {
    int value;
    int *key;
    long offset;
} record;

void init_records(int size, union_find_t *uf) {
    long *offsets = calloc(size + 1, sizeof(long)); // One extra for the root node in UF data structure
    if (!offsets) {
        fprintf(stderr, "Error: Allocation of offsets array failed.\n");
        exit(EXIT_FAILURE);
    }

    int *keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Allocation of keys array failed.\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record *records = calloc(size, sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Allocation of records array failed.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        scanf("%d", &keys[i]);
        uf_make_set(uf, keys[i]);
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % 100 + 1; // Random integer between 1 and 100
        records[i].key = &keys[i];

        while (uf_find(uf, records[i].key) == uf_find(uf, &offsets[records[i].offset])) {
            records[i].offset++;
        }
        offsets[records[i].offset] = i; // Set the new node's parent in UF data structure
        records[i].offset = records[i].offset == 0 ? -1 : offsets[records[i].offset]; // Record the offset of its representative in UF data structure
    }

    for (int i = 0; i < size; ++i) {
        printf("Record %d: value=%d, key=%d, offset=%ld\n", i, records[i].value, *records[i].key, records[i].offset);
    }
}

typedef struct uf_set {
    int count;
    int *parent;
} uf_set_t;

union union_find {
    uf_set_t set;
};

void uf_init(union_find_t *uf, int n) {
    uf->set.count = n;
    uf->set.parent = calloc(n + 1, sizeof(int));
    if (!uf->set.parent) {
        fprintf(stderr, "Error: Allocation of parent array failed.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < n; ++i) {
        uf->set.parent[i] = i;
    }
}

int uf_find(const union_find_t *uf, int *x) {
    if (*x != uf->set.parent[*x]) {
        *x = uf->set.parent[*x];
    }
    return uf->set.parent[*x];
}

void uf_make_set(union_find_t *uf, int x) {
    if (uf->set.count == 0) {
        fprintf(stderr, "Error: UF data structure not initialized.\n");
        exit(EXIT_FAILURE);
    }
    uf->set.parent[x] = x;
    uf->set.count--;
}
```

