    }

    return 0;
}

int compare_doubles(const void *a, const void *b) {
    if (*(const dataRecord*)a->value < *(const dataRecord*)b->value)
        return -1;
    else if (*(const dataRecord*)a->value > *(const dataRecord*)b->value)
        return 1;
    return 0;
}
