```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    int *key;
    long offset;
};

int initialize(int num_integers, int *input, int *keys, int *offsets, int *records, size_t records_size) {
    if (num_integers > INT_MAX || num_integers + sizeof(struct Record)*records_size >= INT_MAX) {
        return 1; // Error: overflow
    }

    int *arr = malloc((num_integers+1)*sizeof(int));
    if (!arr) {
        return 2; // Allocation error
    }

    for (int i = 0; i <= num_integers; ++i) {
        arr[i] = -1; // Mark end of input integers
    }

    int index = 0;
    for (int i = 0; i < num_integers; ++i) {
        int j = arr[input[i]];
        arr[input[i]] = i;
        struct Record *record = (struct Record*)malloc(sizeof(struct Record));
        if (!record) {
            free(arr);
            return 2; // Allocation error
        }
        record->value = input[i];
        record->key = keys + j;
        record->offset = index++;

        if (records_size > 0 && index >= records_size) {
            free(record);
            break; // No more room for records, stop allocation
        }

        if (!records || index >= records_size) {
            records = realloc(records, index*sizeof(struct Record));
            if (!records) {
                free(arr);
                free(record);
                return 2; // Allocation error
            }
        }
        records[index-1] = *record;
    }

    free(arr);
    print_records(records, index);
    return 0;
}

void print_records(struct Record* records, size_t num) {
    for (size_t i = 0; i < num; ++i) {
        printf("%d: (%p) %ld\n", records[i].value, records[i].key, records[i].offset);
    }
}
