typedef struct {
    char *key;
    int value;
} record;

int init_records(int size, const char **keys, FILE *config_file) {
    long *offsets = NULL;
    record *records = NULL;

    if (!(offsets = malloc(size * sizeof(long)))) {
        perror("Failed to allocate memory for offsets");
        return 1;
    }

    if (!(records = malloc(size * sizeof(record)))) {
        perror("Failed to allocate memory for records");
        free(offsets);
        return 1;
    }

    srand((unsigned)time(NULL));

    int i, j;
    for (i = 0; i < size; ++i) {
        offsets[i] = ftell(config_file);
        records[i].key = keys[i];
        records[i].value = rand() % RANDOM_MAX + MIN_VALUE;
    }

    pid_t pid;
    for (j = 0; j < size - 1; ++j) {
        char command[256];
        snprintf(command, sizeof(command), "sed -i %d's/%%%s%%/%d/g' %s", records[j].value, records[j].key, records[j].value, config_file);
        if ((pid = fork()) < 0) {
            perror("Failed to fork");
            free(records);
            free(offsets);
            return 1;
        } else if (pid == 0) {
            execlp("sed", "sed", "-i", command, NULL);
            perror("Failed to execute sed command");
            _exit(EXIT_FAILURE);
        }
    }

    char buffer[4096];
    rewind(config_file);
    fseek(config_file, offsets[size - 1], SEEK_SET);

    for (i = 0; i < size; ++i) {
        if (fgets(buffer, sizeof(buffer), config_file)) {
            printf("%s", buffer);
        }
        fseek(config_file, offsets[i], SEEK_SET);
    }

    free(records);
    free(offsets);

    return 0;
}
