#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include "logging_system.h" // Assuming you have a logging system defined here

typedef struct {
    int value;
} Record;

// Maximum number of records that can be stored in one block
#define BLOCK_SIZE 1024

// A structure to keep track of memory blocks and used records
struct MemoryBlock {
    Record* records;
    size_t num_records;
    struct MemoryBlock* next;
};

// Thread-safe memory pool for managing record structures
struct MemPool {
    struct MemoryBlock* head;
    sem_t lock;
    size_t max_size;
};

void init_mempool(struct MemPool* mempool, size_t max_size) {
    mempool->head = NULL;
    mempool->max_size = max_size;
    sem_init(&mempool->lock, 0, 1);
}

// Allocate a memory block from the pool
struct MemoryBlock* alloc_block(struct MemPool* mempool) {
    struct MemoryBlock* new_block = malloc(sizeof(struct MemoryBlock));
    if (!new_block) {
        log_error("Failed to allocate memory for new MemoryBlock");
        return NULL;
    }

    sem_wait(&mempool->lock);

    new_block->records = malloc(BLOCK_SIZE * sizeof(Record));
    if (!new_block->records) {
        free(new_block);
        log_error("Failed to allocate memory for records in new MemoryBlock");
        sem_post(&mempool->lock);
        return NULL;
    }

    new_block->num_records = 0;
    new_block->next = mempool->head;
    mempool->head = new_block;
    sem_post(&mempool->lock);

    return new_block;
}

// Free a memory block and reuse it if possible
void free_block(struct MemoryBlock* block) {
    if (!block || !block->records) return;

    sem_wait(&block->next->sem_free); // Wait for the next block to be freed
    struct MemoryBlock* temp = block->next;
    block->next = block->next->next;
    free(temp->records);
    free(temp);
    temp = block;
    sem_post(&block->sem_free);

    sem_wait(&mempool->lock);
    temp->records = malloc(BLOCK_SIZE * sizeof(Record));
    if (!temp->records) {
        log_error("Failed to reallocate memory for records in block");
        sem_post(&mempool->lock);
        return;
    }
    temp->num_records = 0;
    temp->next = mempool->head;
    mempool->head = temp;
    sem_post(&mempool->lock);
}

// Allocate an array of records with the given number of elements
Record* allocate_records(struct MemPool* mempool, size_t num_records) {
    struct MemoryBlock* block = alloc_block(mempool);
    if (!block) return NULL;

    if (num_records > BLOCK_SIZE) {
        log_error("Requested number of records exceeds the maximum per memory block");
        free_block(block);
        return NULL;
    }

    sem_wait(&mempool->lock);
    block->num_records = num_records;
    sem_post(&mempool->lock);
    return block->records;
}

// Deallocate an array of records and free the memory
void deallocate_records(Record* records, size_t num_records) {
    if (!records || !num_records) return;

    sem_wait(&records[0].sem_record); // Lock all records in the array

    sem_wait(&mempool->lock);
    struct MemoryBlock* block = (struct MemoryBlock*)((size_t)records - offsetof(struct MemoryBlock, records));
    block->num_records = num_records;
    sem_post(&mempool->lock);

    free_block(block);

    sem_post(&records[0].sem_record); // Unlock all records in the array
}

// Initialize a record structure with a value within the specified range
void init_record(Record* record, int min, int max) {
    if (record->value < min || max < record->value) {
        log_error("Record value is out of the specified range");
        return;
    }
    record->value = rand() % (max - min + 1) + min;
}

// Function to handle external data sources and initialize records with initial values
void init_records(Record* records, size_t num_records, int min, int max) {
    sem_wait(&records[0].sem_record); // Lock all records in the array

    for (size_t i = 0; i < num_records; ++i) {
        init_record(records + i, min, max);
    }

    sem_post(&records[0].sem_record); // Unlock all records in the array
}
```

This code provides a basic memory pool implementation that manages an array of `Record` structures. The thread safety is handled using a mutex lock (semaphore). External data sources can be integrated by initializing the records within the `init_records()` function. To optimize for memory fragmentation and handle potential buffer overflow conditions, a mechanism for reusing previously freed blocks has been implemented. However, to ensure data integrity during updates from external data sources, additional error checking or synchronization mechanisms may need to be added depending on your specific use case.']

