```c
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct sensor_data {
    time_t timestamp;
    int temperature;
    int humidity;
    struct sensor_data *next;
    struct sensor_data *prev;
} sensor_data_t;

// Global variables
static const int MAX_POINTS = 1000;
static int memory_size_threshold = 500;
static int current_memory_usage = 0;
static sensor_data_t *head = NULL;
static sensor_data_t *tail = NULL;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static bool logging_enabled = true;

void log_memory(const char *message) {
    if (logging_enabled) {
        printf("%s\n", message);
    }
}

void allocate_sensor_data(int num_points) {
    sensor_data_t *new_data, *iter;

    pthread_mutex_lock(&lock);
    if (current_memory_usage + num_points > memory_size_threshold) {
        log_memory("Memory overflow. Dropping data.");
        free_sensor_data(num_points);
        num_points = current_memory_usage;
    }
    pthread_mutex_unlock(&lock);

    new_data = malloc(num_points * sizeof(sensor_data_t));
    if (new_data == NULL) {
        log_memory("Memory allocation failed.");
        return;
    }

    for (int i = 0; i < num_points; i++) {
        new_data[i].timestamp = get_timestamp();
        new_data[i].temperature = fetch_valid_temperature();
        new_data[i].humidity = fetch_valid_humidity();
    }

    if (num_points > 0) {
        pthread_mutex_lock(&lock);
        iter = tail;

        // Add data to the end of the list
        if (iter != NULL) {
            iter->next = new_data;
            new_data[num_points - 1].next = head;
            new_data[num_points - 1].prev = tail;
            head = new_data;
            tail = &new_data[num_points - 1];
        } else {
            head = new_data;
            tail = &new_data[num_points - 1];
        }
        current_memory_usage += num_points;
        pthread_mutex_unlock(&lock);
    }
}

void free_sensor_data(int num_points) {
    sensor_data_t *iter, *temp;

    pthread_mutex_lock(&lock);
    current_memory_usage -= num_points;
    pthread_mutex_unlock(&lock);

    iter = head;
    while (num_points > 0) {
        temp = iter->next;
        free(iter);
        iter = temp;
        if (iter == NULL) {
            break;
        }
        num_Points--;
    }

    // Update the head and tail pointers
    if (current_memory_usage > 0) {
        head = iter;
        tail = &head[current_memory_usage - 1];
    } else {
        head = NULL;
        tail = NULL;
    }
}
```

