} node;

typedef struct {
    node *node_ptr;
} record;

int init_records(int nodes_count, int strings_max_len, int records_count) {
    if (nodes_count <= 0 || strings_max_len <= 0 || records_count <= 0)
        return -1; // Invalid input parameters

    srand((unsigned int)time(NULL));

    node *nodes = malloc(nodes_count * sizeof(node));
    if (!nodes)
        return -2; // Failed to allocate memory for nodes

    record *records = malloc(records_count * sizeof(record));
    if (!records) {
        free(nodes);
        return -2; // Failed to allocate memory for records
    }

    for (int i = 0; i < nodes_count; ++i) {
        nodes[i].value = i;
        nodes[i].string = malloc(rand() % strings_max_len + 1); // Generate random string length within the given range
        if (!nodes[i].string) {
            for (int j = 0; j < i; ++j)
                free(nodes[j].string);
            free(nodes);
            free(records);
            return -2; // Failed to allocate memory for a node string
        }
        for (int j = 0; j < rand() % 26 + 33; ++j) // Generate random alphanumeric string using ASCII characters within the range [33, 126]
            nodes[i].string[rand() % (strings_max_len - j)] = rand() % 95 + 33;
        nodes[i].string[strings_max_len] = '\0';
    }

    for (int i = 0; i < records_count; ++i) {
        int index = rand() % nodes_count;
        records[i].node_ptr = &nodes[index];
    }

    return 0; // Successfully initialized the records array
}

void print_records(int records_count, node **nodes) {
    for (int i = 0; i < records_count; ++i) {
        printf("Record %d:\n", i);
        printf("\tValue: %d\n", (*nodes[i])->value);
        printf("\tString: %s\n", (*nodes[i])->string);
        nodes[i] = &(*nodes[i]->string + 1); // Move to the next node for the next iteration
    }
}
