int read_integers(int size, int *array) {
    if (scanf("%d", array) != 1 || size <= 0) {
        fprintf(stderr, "Invalid input or size\n");
        return -1;
    }
    for (int i = 1; i < size; ++i) {
        if (scanf("%d", &array[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            return -1;
        }
    }
    return 0;
}

int *create_keys(int size) {
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        keys[i] = i;
    }
    return keys;
}

long *create_offsets(int size) {
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        offsets[i] = -1;
    }
    return offsets;
}

struct Record* create_records(int *values, int *keys, long *offsets, int size) {
    struct Record *records = malloc(sizeof(struct Record) * size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        records[i].value = values[i];
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
    }
    return records;
}

void print_records(struct Record *records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Record %d: value=%d, key=%d, offset=%ld\n", i, records[i].value, *records[i].key, records[i].offset);
    }
}

void sort_records(struct Record *records, int size) {
    qsort(records, size, sizeof(struct Record), (int (*)(const void *, const void *))compare);
}

int compare(const void *a, const void *b) {
    return (*(const struct Record *)a).value - (*(const struct Record *)b).value;
}

int search_record(struct Record *records, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (records[i].value == value) {
            return *(records[i].key);
        }
    }
    return -1;
}

