    if (!keys) {
        free(input_list);
        return -1;
    }
    long *offsets = create_offsets(size);
    if (!offsets) {
        free(input_list);
        free(keys);
        return -1;
    }
    struct Record* records = create_records(input_list, keys, offsets, size);
    if (!records) {
        free(input_list);
        free(keys);
        free(offsets);
        return -1;
    }

    print_records(records, size);
    sort_records(records, size);
    printf("\nSorted Records:\n");
    print_records(records, size);

    int value = rand() % (size * 2 + 1); // Optimized random number generation
    if ((search_record(records, size, value) != -1)) {
        printf("Value %d found at key: %d\n", value, search_record(records, size, value));
    } else {
        printf("Value %d not found\n", value);
    }

    free(input_list);
    free(keys);
    free(offsets);
    free(records);
    return 0;
}
