typedef struct {
    int id;
    int *next;
} State;

State* create_state(int id) {
    State* state = malloc(sizeof(State));
    if (!state) return NULL;
    state->id = id;
    state->next = NULL;
    return state;
}

State** extend_state_list(State **list, int *states, int num_states, int last_state) {
    int new_num_states = num_states + 1;
    State **new_list = malloc((new_num_states) * sizeof(State*));
    if (!new_list) return NULL;

    memcpy(new_list, list, last_state * sizeof(State*));
    new_list[last_state] = create_state(new_num_states - 1);
    if (!new_list[last_state]) {
        free(new_list);
        return NULL;
    }

    for (int i = last_state + 1; i < new_num_states; ++i) {
        new_list[i] = create_state(i);
        if (!new_list[i]) {
            free(new_list[last_state]->next);
            free(new_list);
            return NULL;
        }
        new_list[i - 1]->next = &new_list[i]->id;
    }
    free(list);
    return new_list;
}

