int initializeFileRecords(const int num_records, const int *keys, const char **labels, FILE *fp, fileRecord **records) {
    int i;
    long *offsets = NULL;
    double *values = malloc(num_records * sizeof(double));

    if (values == NULL) return -1;

    if (fread(values, sizeof(double), num_records, fp) != num_records) {
        free(values);
        return -1;
    }

    offsets = malloc((num_records + 1) * sizeof(long));
    if (offsets == NULL) {
        free(values);
        return -1;
    }

    for (i = 0; i < num_records; ++i)
        offsets[i] = i;

    offsets[num_records] = -1;

    *records = malloc(num_records * sizeof(fileRecord));
    if (*records == NULL) {
