#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} record;

enum error_codes {
    NO_ERROR = 0,
    MEMORY_ALLOCATION_FAILURE = -1,
    RANGE_EXCEEDED = -2,
};

int initialize_arrays(size_t num_records, size_t keys_len, size_t offsets_len, int min, int max, int *keys, long *offsets, record **records, int *error) {
    if(!(keys = malloc(keys_len * sizeof(int))) || !(offsets = malloc(offsets_len * sizeof(long))) || !(records = malloc(num_records * sizeof(record)))) {
        free(keys);
        free(offsets);
        free(records);
        *error = MEMORY_ALLOCATION_FAILURE;
        return *error;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        int randomValue = min + rand() % (max - min + 1);
        if (randomValue < min || randomValue > max) {
            free(keys);
            free(offsets);
            free(records);
            *error = RANGE_EXCEEDED;
            return *error;
        }
        records[i].key = i;
        records[i].value = randomValue;
        if (i > 0) {
            long difference = records[i].key - records[i-1].key;
            records[i].offset = records[i-1].offset + difference;
        } else {
            records[i].offset = 0;
        }
        keys[records[i].key] = records[i].value;
    }

    *error = NO_ERROR;
    return *error;
}
