#define BUF_SIZE 1049000 // Buffer size for binary file serialization (adjust to your needs)
#define DATA_RECORD_SIZE sizeof(struct dataRecord)
#define OFFSET_ARRAY_SIZE 3
#define MAX_LONG 2147483647
#define MIN_LONG -2147483647
#define MAX_DOUBLE 1e15 // Adjust this value to your desired floating-point range
#define MIN_DOUBLE 0.0
#define MAX_INT 2147483647
#define MIN_INT 0

typedef struct {
    double data;
    int key1, key2;
} dataRecord;

int createDataArrays(long** offsets, double** fps, int** keys, size_t* recordsCount, dataRecord** records, FILE** file) {
    void *bufPtr = mmap(NULL, BUF_SIZE, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (bufPtr == MAP_FAILED) {
        perror("mmap() failed");
        return 1;
    }

    *offsets = malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    if (!*offsets) {
        perror("malloc() failed for offsets");
        munmap(bufPtr, BUF_SIZE);
        return 1;
    }

    *fps = malloc(recordsCount * sizeof(double));
    if (!*fps) {
        perror("malloc() failed for floating-point numbers");
        free(*offsets);
        munmap(bufPtr, BUF_SIZE);
        return 1;
    }

    *keys = malloc(recordsCount * sizeof(int));
    if (!*keys) {
        perror("malloc() failed for keys");
        free(*offsets);
        free(*fps);
        munmap(bufPtr, BUF_SIZE);
        return 1;
    }

    *records = (dataRecord*) bufPtr;

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < recordsCount; ++i) {
        (*offsets)[i] = rand() + OFFSET_ARRAY_SIZE; // Ensure offset values are greater than the array size to avoid overlapping
        (*records)[i].key1 = rand() % MAX_INT + MIN_INT;
        (*records)[i].key2 = rand() % MAX_INT + MIN_INT;
        (*records)[i].data = (double)rand() / RAND_MAX * (MAX_DOUBLE - MIN_DOUBLE) + MIN_DOUBLE;
        ++(*keys[i]); // Increment key count for each record
    }

    *file = fmemopen(bufPtr, BUF_SIZE, "wb");
    if (*file == NULL) {
        perror("fmemopen() failed");
        free(*offsets);
        free(*fps);
        free(*keys);
        munmap(bufPtr, BUF_SIZE);
        return 1;
    }

    // Serialize data records into binary file format
    for (size_t i = 0; i < recordsCount; ++i) {
        fwrite(&(*records)[i].key1, sizeof(int), 1, *file);
        fwrite(&(*records)[i].key2, sizeof(int), 1, *file);
        fwrite(&(*records)[i].data, sizeof(double), 1, *file);
    }

    return 0; // Successful execution
}
