typedef struct {
    int value;
    const int *key;
    const int *offset;
} record;

int initialize_records(int num_integers, int max_val, int *integers, size_t *key_size, size_t *offset_size, record ***records) {
    int i, j;
    int *keys = malloc(*key_size * sizeof(int));
    if (!keys) return 1;
    int *offsets = malloc(*offset_size * sizeof(int));
    if (!offsets) {
        free(keys);
        return 2;
    }

    for (i = 0; i < *key_size; ++i) keys[i] = -1;
    for (i = 0; i < *offset_size; ++i) offsets[i] = -1;

    *records = malloc(num_integers * sizeof(record*));
    if (!*records) {
        free(keys);
        free(offsets);
        return 3;
    }

    for (i = 0; i < num_integers; ++i) {
        int index = integers[i];
        while (keys[index] >= 0) index = integers[(++i) % num_integers];

        keys[index] = i;
        offsets[i] = index;
        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            for (j = 0; j < i; ++j) free((*records)[j]);
            free(keys);
            free(offsets);
            return 4;
        }

        (*(*records)[i]).value = rand() % max_val + 1;
        (*(*records)[i]).key = &keys[index];
        (*(*records)[i]).offset = &offsets[i];
    }

    *key_size = *offset_size = num_integers;
    srand(time(NULL));
    return 0;
}

