typedef struct {
    int value;
} record;

void validate_params(size_t *keys, size_t keys_len, size_t offsets, size_t records) {
    if (keys == NULL || offsets == 0 || records == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < keys_len; ++i) {
        if (keys[i] >= records || keys[i] > offsets || (i != 0 && keys[i - 1] >= keys[i])) {
            fprintf(stderr, "Invalid key values.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void* rand_buffer(void *arg) {
    record *records = (record*) arg;
    for (size_t i = 0; i < records_len; ++i)
        records[i].value = rand() % RANGE + MIN_VALUE;
    return NULL;
}

void set_random_values(record *records, size_t records_len, int order, unsigned int min_value, unsigned int range) {
    if (order == ASCENDING) {
        qsort(records, records_len, sizeof(record), compare_func);
    } else {
        qsort(records, records_len, sizeof(record), reverse_compare_func);
    }

    pthread_t threads[num_threads];
    record *rand_buf = malloc(sizeof(record) * records_len);

    num_threads = min((int) (2 * cpu_count() + 1), records_len);

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, rand_buffer, &records[i]);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    memcpy(records, rand_buf, sizeof(record) * records_len);

    free(rand_buf);
}

int compare_func(const void *a, const void *b) {
    return (*(int*) a - *(int*) b);
}

int reverse_compare_func(const void *a, const void *b) {
    return (*(int*) b - *(int*) a);
}

void init_arrays(size_t *keys, size_t keys_len, size_t offsets, size_t records, int order, unsigned int min_value, unsigned int range) {
    validate_params(keys, keys_len, offsets, records);

    int *keys_arr = malloc(sizeof(int) * keys_len);
    long *offsets_arr = malloc(sizeof(long) * offsets);
    record *records_arr = malloc(sizeof(record) * records);

    for (size_t i = 0; i < keys_len; ++i) {
        keys_arr[i] = keys[i];
    }

    for (size_t i = 0; i < offsets; ++i) {
        offsets_arr[i] = offsets;
    }

    set_random_values(records_arr, records, order, min_value, range);

    // Copy final results to user's arrays.
    for (size_t i = 0; i < keys_len; ++i) {
        keys[i] = keys_arr[i];
    }

    for (size_t i = 0; i < offsets; ++i) {
        offsets[i] = offsets_arr[i];
    }

    for (size_t i = 0; i < records; ++i) {
        records[i] = records_arr[i].value;
    }

    free(keys_arr);
    free(offsets_arr);
    free(records_arr);
}
