#include <cstdlib>
#include <ctime>
#include <vector>
#include <list>
#include <memory>
#include <new>

struct Node {
    int value;
    std::unique_ptr<Node> parent;
};

class Octree {
public:
    Octree(int maxDepth, int minSize, int maxSize, int valueRange, bool ascending) : maxDepth_(maxDepth), minSize_(minSize), maxSize_(maxSize), valueRange_(valueRange), ascending_(ascending), currentDepth_(0), dataBuffers_{std::vector<double>(), std::vector<char>(), std::vector<Node*>()} {}

    ~Octree() {
        clear();
    }

    void initialize(size_t numSensors) {
        if (numSensors < 1 || maxDepth_ <= 0 || minSize_ > maxSize_) {
            throw std::invalid_argument("Invalid input parameters");
        }

        root_ = std::make_unique<Node>();
        initializeNode(root_.get(), currentDepth_, dataBuffers_);

        // Adjust capacity based on number of sensors and maintain octree balance
        adjustCapacity(numSensors);
    }

    void setSensorData(size_t sensorIndex, int key, double value) {
        if (sensorIndex >= numSensors_) {
            throw std::out_of_range("Sensor index out of range");
        }

        Node* currentNode = root_.get();
        for (int i = currentDepth_; i > 0; --i) {
            currentNode = currentNode->parent.get();
            if ((currentNode->value >> (7 * (i - 1))) & 1 == 0) {
                currentNode = currentNode->parent.get()->parent.get();
            }
        }

        dataBuffers_[0][sensorIndex] = value;
        dataBuffers_[1][sensorIndex] = static_cast<char>(key);

        Node* nodeToUpdate = findNode(currentNode, sensorIndex);
        nodeToUpdate->value = getRandomValue(valueRange_);
    }

private:
    void initializeNode(Node* node, int depth, std::vector<std::vector<>>& dataBuffers) {
        if (depth > maxDepth_) {
            return;
        }

        node->value = 0;

        auto children = std::make_unique<std::list<Node*>>();
        node->parent = std::move(std::unique_ptr<Node>(new Node()));
        node->parent->get()->children = std::move(children);

        for (int i = 0; i < 8; ++i) {
            if ((node->value >> (7 * depth)) & 1 == 1) {
                initializeNode(node->children->front(), depth + 1, dataBuffers);
                node->children->pop_front();
            }
            if (depth < maxDepth_) {
                int bitIndex = depth * 8 + i;
                auto& buffer = dataBuffers[bitIndex % 3];
                if (buffer.size() > 0) {
                    Node* newNode = new Node();
                    newNode->parent = std::move(std::unique_ptr<Node>(node));
                    initializeNode(newNode, depth + 1, dataBuffers);
                    node->children->emplace_back(newNode);
                }
            }
        }
    }

    void adjustCapacity(size_t numSensors) {
        int newCapacity = static_cast<int>(std::pow(8, maxDepth_ - 1)) * numSensors_;
        if (newCapacity > dataBuffers_[0].capacity()) {
            for (auto& buffer : dataBuffers_) {
                buffer.resize(newCapacity);
            }
        }
    }

    Node* findNode(Node* node, size_t sensorIndex) const {
        if (!node) return nullptr;

        auto key = dataBuffers_[1][sensorIndex];
        if (key == dataBuffers_[1][node->value]) {
            return node;
        }

        for (const auto& child : node->children) {
            Node* foundNode = findNode(child.get(), sensorIndex);
            if (foundNode) return foundNode;
        }

        return nullptr;
    }

    int getRandomValue(int range) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(0, range - 1);

        if (ascending_) {
            return distr(gen);
        } else {
            return distr(gen) + range;
        }
    }

    void clear() {
        root_.reset();
        for (auto& buffer : dataBuffers_) {
            buffer.clear();
        }
    }

    int maxDepth_;
    int minSize_;
    int maxSize_;
    int valueRange_;
    bool ascending_;
    size_t currentDepth_;
    std::unique_ptr<Node> root_;
    std::vector<std::vector<>> dataBuffers_; // First element is for doubles, second for chars, third for Node pointers
    size_t numSensors_ = 0; // Updated dynamically based on the number of sensors passed during Octree initialization
};
```

