#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Define maximum limits for memory allocation and hash table size
#define MAX_MEMORY_USAGE (100 * 1024 * 1024) // 100MB
#define HASH_TABLE_SIZE (1024)

// Global variables to store the keys, offsets, and records arrays
long* offsets;
int* keys;
Record* records;

// Mutex for thread-safe access to the hash table
pthread_mutex_t hash_table_lock;

// Function to generate random number within a given range
int rand_in_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Thread-safe function to add a new key and record
void add_key_and_record(int key, int order) {
    pthread_mutex_lock(&hash_table_lock);

    int i = keys[offsets[key]];
    keys[offsets[key]] = key;
    offsets[key] = offsets[i];
    keys[offsets[i]] = i;

    records = realloc(records, (sizeof(Record) * (offsets[keys[0]] + 1)));
    records[key].value = order ? rand_in_range(0, RAND_MAX / 2) : rand_in_range(RAND_MAX / 2, RAND_MAX);

    pthread_mutex_unlock(&hash_table_lock);
}

// Function to initialize the hash table with given parameters
void init_hash_table(int* keys, int num_keys, unsigned long max_memory_usage) {
    // Initialize mutex and dynamically allocate memory for offsets and records arrays
    pthread_mutex_init(&hash_table_lock, NULL);
    offsets = mmap(NULL, sizeof(long) * (num_keys + 1), PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offsets == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets array\n");
        exit(EXIT_FAILURE);
    }

    records = malloc(sizeof(Record) * (num_keys + 1));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize offsets array and call add_key_and_record function for each key in the input array
    for (int i = 0; i < num_keys; ++i) {
        add_key_and_record(keys[i], 1);
    }

    // Check if total memory usage exceeds the maximum limit and free memory if necessary
    unsigned long current_memory_usage = (unsigned long)(offsets + (num_keys + 1)) - (void*)offsets;
    if (current_memory_usage > max_memory_usage) {
        free(records);
        munmap(offsets, sizeof(long) * (num_keys + 1));
        pthread_mutex_destroy(&hash_table_lock);

        fprintf(stderr, "Error: Total memory usage exceeded the maximum limit\n");
        exit(EXIT_FAILURE);
    }
}

// Function to destroy the hash table and free dynamically allocated memory
void destroy_hash_table() {
    if (offsets) {
        munmap(offsets, sizeof(long) * (keys[0] + 1));
    }

    if (records) {
        free(records);
    }

    pthread_mutex_destroy(&hash_table_lock);
}
```

This code provides a basic implementation of a thread-safe hash table in C. The `init_hash_table()` function initializes the offsets, keys, and records arrays based on the provided parameters. It also checks if the total memory usage exceeds the specified maximum limit before allocating memory for the records array. The `add_key_and_record()` function is used to add new key-value pairs to the hash table in a thread-safe manner using a mutex lock.

The code uses `mmap()` and `malloc()` for dynamic memory allocation, ensuring proper cleanup with `munmap()` and `free()`. Additionally, it employs a logging mechanism (not implemented here) to track issues during runtime.

