#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int value;
} Record;

typedef struct MemManager {
    Record* data;
    size_t capacity;
    size_t size;
    size_t memory_limit;
} MemManager;

MemManager* create_mem_manager(size_t memory_limit) {
    MemManager* mm = malloc(sizeof(MemManager));
    if (!mm) {
        perror("Error: Failed to allocate memory for MemManager");
        return NULL;
    }
    mm->memory_limit = memory_limit < INT_MAX ? memory_limit : INT_MAX;
    mm->capacity = 0;
    mm->size = 0;
    mm->data = NULL;
    return mm;
}

void destroy_mem_manager(MemManager* mm) {
    if (mm && mm->data) {
        free(mm->data);
        free(mm);
    }
}

Record* reallocate(MemManager* mm, size_t new_capacity) {
    Record* old_data = mm->data;
    if (!new_capacity || new_capacity <= mm->capacity) {
        return mm->data;
    }
    mm->data = realloc(old_data, new_capacity * sizeof(Record));
    if (!mm->data) {
        perror("Error: Failed to reallocate memory");
        free(old_data);
        mm->data = NULL;
    }
    return mm->data;
}

size_t find_index_to_free(MemManager* mm, size_t start) {
    for (size_t i = start + 1; i < mm->capacity; ++i) {
        if (mm->data[i].value != INT_MAX) {
            return i;
        }
    }
    return mm->capacity - 1;
}

int add_record(MemManager* mm, int value) {
    if (mm->size == mm->capacity) {
        size_t new_capacity = (mm->capacity * 2 > mm->memory_limit) ? find_index_to_free(mm, 0) + 1 : mm->capacity * 2;
        mm->data = reallocate(mm, new_capacity);
        if (!mm->data) {
            perror("Error: Failed to reallocate memory");
            return -1;
        }
        mm->capacity = (new_capacity == mm->capacity * 2) ? (mm->capacity * 2) : new_capacity;
    }
    mm->data[mm->size].value = value;
    ++mm->size;
    return 0;
}

int get_record(MemManager* mm, size_t index, int* value) {
    if (index >= mm->size) {
        *value = INT_MIN;
        return -1;
    }
    *value = mm->data[index].value;
    return 0;
}
