#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int level;
    const char *message;
} log_record;

struct logging_system {
    pthread_mutex_t mutex;
    long *offsets;
    int *timestamps;
    log_record *records;
    size_t capacity;
    size_t length;
    size_t max_size;
};

void _log_init(struct logging_system *system, size_t max_size) {
    system->max_size = max_size;
    system->capacity = 0;
    system->length = 0;
}

bool _log_resize(struct logging_system *system, size_t new_capacity) {
    if (new_capacity > system->max_size || !new_capacity)
        return false;

    long *temp_offsets = realloc(system->offsets, new_capacity * sizeof(long));
    if (!temp_offsets)
        return false;

    int *temp_timestamps = realloc(system->timestamps, new_capacity * sizeof(int));
    if (!temp_timestamps) {
        free(temp_offsets);
        return false;
    }

    log_record *temp_records = realloc(system->records, new_capacity * sizeof(log_record));
    if (!temp_records) {
        free(temp_offsets);
        free(temp_timestamps);
        return false;
    }

    system->offsets = temp_offsets;
    system->timestamps = temp_timestamps;
    system->records = temp_records;
    system->capacity = new_capacity;
    return true;
}

void _log_insert(struct logging_system *system, int level, const char *message) {
    pthread_mutex_lock(&system->mutex);

    if (system->length >= system->capacity) {
        if (!_log_resize(system, system->capacity * 2)) {
            pthread_mutex_unlock(&system->mutex);
            return;
        }
    }

    system->records[system->length].level = level;
    system->records[system->length].message = message;
    system->offsets[system->length] = system->timestamps[system->length] = system->length;
    system->length++;

    pthread_mutex_unlock(&system->mutex);
}

struct logging_system *log_init(const char *name, size_t max_size) {
    struct logging_system *system = malloc(sizeof(struct logging_system));
    if (!system) {
        fprintf(stderr, "Failed to allocate memory for the logging system: %s\n", name);
        return NULL;
    }

    _log_init(system, max_size);
    pthread_mutex_init(&system->mutex, NULL);

    if (log_initialize(name)) {
        fprintf(stderr, "Log initialization failed: %s\n", name);
        free(system);
        return NULL;
    }

    return system;
}

