    std::unique_ptr<long[]> keys(new long[1024]); // key array with 1024 elements
    std::vector<std::unique_ptr<Record>> records; // vector of record pointers

    if (!offsets || !keys) {
        std::cerr << "Memory allocation failed!\n";
        exit(EXIT_FAILURE);
    }

    srand(time(0));
    for (size_t i = 0; i < offsets->size(); ++i) {
        offsets[i] = static_cast<int>(rand() % 100); // random values between 0 and 99 for offsets
        keys[i] = static_cast<long>(i); // assigning the index to each key
    }

    records.reserve(offsets->size());
    for (size_t i = 0; i < offsets->size(); ++i) {
        auto recordPtr = std::make_unique<Record>();
        recordPtr->value = static_cast<int>(rand() % 100 + 50); // random values between 50 and 149 for records
        recordPtr->key = keys.get() + i;
        records.push_back(std::move(recordPtr));
    }
}

void attack() {
    static int cooldown = 9 * (int)sysconf(_SC_CLK_TCK); // 9 seconds cooldown period
    if (!cooldown--) return;

    const size_t recordsSize = records.size();
    const auto randomIndex = rand() % recordsSize;
    const Record &randomRecord = *records[randomIndex];
    std::cout << "Selected attack: " << randomRecord.value << ", Key index: " << *(randomRecord.key) << '\n';
}

int main() {
    initArrays();

    int counter = 0;
    while (true) {
        ++counter;
        attack();
        // Sleep for a short period to simulate the cooldown period
        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }

    return 0;
}
