#include <time.h>

typedef struct {
    double value;
    int *key;
    char *label;
    long offset;
} dataRecord;

int initializeDataRecords(int num_doubles, int *num_keys, int *num_labels, dataRecord **records) {
    clock_t start = clock();

    size_t dataSize = sizeof(dataRecord) * num_doubles;
    size_t keySize = *num_keys * sizeof(int);
    size_t labelSize = *num_labels * sizeof(char);

    dataRecord *dataRecords = malloc(dataSize);
    if (!dataRecords) return -1;

    int *keys = malloc(keySize);
    if (!keys) {
        free(dataRecords);
        return -2;
    }

    char *labels = malloc(labelSize);
    if (!labels) {
        free(dataRecords);
        free(keys);
        return -3;
    }

    for (int i = 0; i < num_doubles; ++i) {
        dataRecords[i].value = rand() / (RAND_MAX / num_doubles + 1.0); // Optimized random number generation
        dataRecords[i].key = &keys[i];
        dataRecords[i].label = &labels[i];
        dataRecords[i].offset = i;
    }

    *records = dataRecords;
    *num_keys = *num_keys < num_doubles ? num_doubles : *num_keys;
    *num_labels = *num_labels < num_doubles ? num_doubles : *num_labels;

    clock_t end = clock();
    printf("Time taken: %.6fs\n", (end - start) / (double)CLOCKS_PER_SEC);
    for (int i = 0; i < num_doubles; ++i) {
        printf("dataRecords[%d]: %f, Key: %d, Label: %c, Offset: %ld\n", i, dataRecords[i].value, *dataRecords[i].key, *dataRecords[i].label, dataRecords[i].offset);
    }

    qsort(dataRecords, num_doubles, sizeof(dataRecord), (int (*)(const void*, const void*))compareDouble);
    int findIndex = binarySearch(dataRecords, 3.14, 0, num_doubles - 1);
    if (findIndex != -1) printf("Found 3.14 at index: %d\n", findIndex);

    free(keys);
    free(labels);
    return 0;
}

int compareDouble(const void *a, const void *b) {
    return (*((dataRecord *)a)->value - *((dataRecord *)b)->value);
}

int binarySearch(dataRecord *arr, double target, int low, int high) {
    if (high < low) return -1;
    int mid = (low + high) / 2;
    if (*(arr + mid)->value == target) return mid;
    else if (*(arr + mid)->value < target) return binarySearch(arr, target, mid + 1, high);
    else return binarySearch(arr, target, low, mid - 1);
}
