    if(!records || !num_elements || !keys || !offsets) return;

    *records = malloc(sizeof(struct Record) * num_elements);
    if(!*records) {
        fprintf(stderr, "Error: Could not allocate memory for records.\n");
        return;
    }

    for(int i = 0; i < num_elements; ++i) {
        (*records)[i].value = keys[i];
        (*records)[i].key = &keys[i];
        (*records)[i].offset = offsets[i];
    }
}

