int init_data(int *arr, size_t arr_size, size_t *key_arr_size, size_t *label_arr_size, size_t *record_arr_size) {
    int *input_arr = (int*) realloc(arr, sizeof(int)*arr_size);
    if (!input_arr) return 1;

    int *key_arr = malloc(*key_arr_size*sizeof(int));
    if (!key_arr) {
        free(input_arr);
        return 2;
    }

    char *label_arr = malloc(*label_arr_size*sizeof(char));
    if (!label_arr) {
        free(input_arr);
        free(key_arr);
        return 3;
    }

    record *record_arr = malloc(*record_arr_size*sizeof(record));
    if (!record_arr) {
        free(input_arr);
        free(key_arr);
        free(label_arr);
        return 4;
    }

    if (arr_size + key_arr_size + label_arr_size + record_arr_size > INT_MAX) {
        free(input_arr);
        free(key_arr);
        free(label_arr);
        free(record_arr);
        return 5; // overflow
    }

    size_t i;
    for (i = 0; i < arr_size; ++i) {
        input_arr[i] = rand()%100 + 1; // random values within the range [1,100]
    }

    for (i = 0; i < arr_size; ++i) {
        record_arr[i].value = (long)input_arr[i];
        record_arr[i].key = key_arr + i;
        record_arr[i].label = label_arr + i;
    }

    qsort(record_arr, arr_size, sizeof(record), (int (*)(const void*, const void*))compare_long);

    printf("Sorted records:\n");
    for (i = 0; i < arr_size; ++i) {
        printf("Record [%ld]: %d, Key: %d, Label: %c\n", record_arr[i].value, input_arr[*record_arr[i].key], *record_arr[i].label);
    }

    free(input_arr);
    return 0; // success
}

int compare_long(const void *a, const void *b) {
    record *r1 = (record*) a;
    record *r2 = (record*) b;

    if (*r1->value < *r2->value) return -1;
    if (*r1->value > *r2->value) return 1;
    return 0;
}
