#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    const int *key;
    long offset;
};

int read_integers(const int n, int *numbers) {
    if (n <= 0 || numbers == NULL) return -1;

    for (int i = 0; i < n; ++i) {
        scanf("%d", numbers + i);
    }
    return 0;
}

void initialize_arrays(const int n, int *keys, int *values, long **offsets) {
    for (int i = 0; i < n; ++i) {
        keys[i] = i;
        values[i] = rand();
        offsets[i] = malloc(sizeof(long));
        if (!offsets[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for offset array.\n");
            exit(1);
        }
    }
}

void initialize_records(const int n, const int *keys, int *values, long **offsets, struct record **records) {
    if (n <= 0 || keys == NULL || values == NULL || offsets == NULL || records == NULL) return;

    *records = malloc(n * sizeof(struct record));
    if (!(*records)) {
        fprintf(stderr, "Error: Failed to allocate memory for record array.\n");
        exit(1);
    }

    for (int i = 0; i < n; ++i) {
        (*records + i)->value = values[i];
        (*records + i)->key = keys + i;
        (*records + i)->offset = *offsets[i];
    }
}

void print_records(const int n, const struct record *records) {
    for (int i = 0; i < n; ++i) {
        printf("%d %p %ld\n", records[i]->value, records[i]->key, records[i]->offset);
    }
}

void sort_records(const int n, struct record *records) {
    qsort(records, n, sizeof(struct record), compare_records);
}

int search_record(const int n, const struct record *records, int value) {
    for (int i = 0; i < n; ++i) {
        if (records[i].value == value) return i;
    }
    return -1;
}

int main(int argc, char **argv) {
    srand(time(NULL));

    int size = atoi(argv[1]);
    int *keys, *values, *offsets;
    struct record *records;

    if (size <= 0 || read_integers(size, values) != 0) return -1;

    initialize_arrays(size, keys, values, &offsets);
    initialize_records(size, keys, values, offsets, &records);

    print_records(size, records);
    sort_records(size, records);
    printf("Sorted:\n");
    print_records(size, records);

    int search_value = atoi(argv[2]);
    int index = search_record(size, records, search_value);
    if (index != -1) printf("\n%d found at index: %d\n", search_value, index);
    else printf("Not found.\n");

    for (int i = 0; i < size; ++i) {
        free(offsets[i]);
    }
    free(offsets);
    free(records);
    return 0;
}

int compare_records(const void *a, const void *b) {
    struct record *recordA = (struct record *)a;
    struct record *recordB = (struct record *)b;

    if (recordA->value < recordB->value) return -1;
    else if (recordA->value > recordB->value) return 1;

    return 0;
}
