    // Calculate the number of records needed
    for (i = 0; i < num_ints; ++i) {
        if (offsets[i] > records_used)
            records_used = offsets[i] + 1;
    }

    // Allocate memory for records array and its pointers
    if (!(records && (records = malloc(records_used * sizeof(Record))))) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(keys);
        free(offsets);
        return -1;
