        uint64_t xorshift128plus() {
            static uint64_t x = 0x9e3779b97f4a7c15;
            static uint64_t y = 0x9e3779b97f4a7c15;
            static const uint64_t MASK = UINT64_C(0x7fffffffffffffff);
            uint64_t z, v;

            z = x ^ (x << 33);
            v = y ^ (y >> 3);
            y = z;
            z = (z ^ (z >> 21)) & MASK;
            x = (x ^ (x >> 14)) & MASK;
            return ((x << 48) | (v << 32) | (z << 16) | (x)) >> 12; // Optimized division by 4096
        }

        values[i] = min + xorshift128plus() / (RAND_MAX / (max - min));
        entries[i].value = values[i];
    }

