#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int value;
} record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
const int MAX_KEYS = 50000;
const int MAX_OFFSETS = 100000;
const int RECORD_SIZE = sizeof(record);
const int MAX_MEMORY = (1 * (1024 * 1024)); // 1 MB

void error_log(const char* message) {
    FILE* file;
    file = fopen("error_log.txt", "a");
    fprintf(file, "%s\n", message);
    fclose(file);
}

bool isValidInput(int offsetCount, int keyCount, bool enableLogging) {
    if (offsetCount <= 0 || keyCount <= 0) {
        error_log("Invalid input parameters.");
        return false;
    }
    if (offsetCount > MAX_OFFSETS || keyCount > MAX_KEYS) {
        error_log("Invalid dataset sizes.");
        return false;
    }
    if ((MAX_MEMORY - (MAX_OFFSETS * sizeof(long) + MAX_KEYS * sizeof(int))) / keyCount < RECORD_SIZE) {
        error_log("Memory limit exceeded.");
        return false;
    }
    return true;
}

void* allocateMemory(size_t size, const char* source, bool enableLogging) {
    void* ptr = malloc(size);
    if (!ptr) {
        if (enableLogging) {
            error_log(source):malloc failed.");
        }
        return NULL;
    }
    return ptr;
}

void deallocateMemory(void* ptr, const char* source, bool enableLogging) {
    if (!ptr || !free(ptr)) {
        if (enableLogging) {
            error_log(source):free failed.");
        }
    }
}

int* allocateAndInitializeOffsets(int offsetCount, bool enableLogging) {
    if (!isValidInput(offsetCount, 0, enableLogging)) return NULL;
    int* offsets = allocateMemory(offsetCount * sizeof(long), "offsets allocation", enableLogging);
    for (int i = 0; i < offsetCount; ++i) {
        offsets[i] = i; // You can set the value as per your requirement.
    }
    return offsets;
}

int* allocateAndInitializeKeys(int keyCount, bool enableLogging) {
    if (!isValidInput(0, keyCount, enableLogging)) return NULL;
    int* keys = allocateMemory(keyCount * sizeof(int), "keys allocation", enableLogging);
    for (int i = 0; i < keyCount; ++i) {
        keys[i] = rand() % 100; // You can set the value as per your requirement.
    }
    return keys;
}

record* allocateAndInitializeRecords(int keyCount, bool enableLogging) {
    if (!isValidInput(0, keyCount, enableLogging)) return NULL;
    pthread_mutex_lock(&mutex);
    record* records = allocateMemory(keyCount * RECORD_SIZE, "records allocation", enableLogging);
    for (int i = 0; i < keyCount; ++i) {
        records[i].value = rand() % 100; // You can set the value as per your requirement.
    }
    pthread_mutex_unlock(&mutex);
    return records;
}

void dynamicallyAllocateAndInitialize(int offsetCount, int keyCount, bool enableLogging) {
    if (!isValidInput(offsetCount, keyCount, enableLogging)) return;

    int* offsets = allocateAndInitializeOffsets(offsetCount, enableLogging);
    int* keys = allocateAndInitializeKeys(keyCount, enableLogging);
    record* records = allocateAndInitializeRecords(keyCount, enableLogging);

    // Use the allocated memory as per your requirements.

    deallocateMemory(offsets, "offsets deallocation", enableLogging);
    deallocateMemory(keys, "keys deallocation", enableLogging);
    deallocateMemory(records, "records deallocation", enableLogging);
}
```

