#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[50];
    int age;
    int *measurements;
    size_t measurements_count;
} Data;

int process_file(const char *file_path, Data **data, size_t *data_count) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    size_t capacity = 0;
    while (1) {
        char line[256];
        size_t len = fgets(line, sizeof(line), file);
        if (!len) break; // EOF reached

        Data data_item;
        sscanf(line, "%[^,],%d", data_item.name, &data_item.age);
        capacity++;

        data_item.measurements = malloc((capacity + 1) * sizeof(*data_item.measurements));
        if (!data_item.measurements) {
            perror("Error allocating memory");
            free(data_item.name);
            fclose(file);
            return 1;
        }

        char *token = strtok(line, ","); // Skip the comma after age
        size_t i = 0;
        while (token) {
            data_item.measurements[i] = atoi(token);
            token = strtok(NULL, ",");
            i++;
        }
        data_item.measurements_count = capacity - i;

        if (!*data) { // First item
            *data = malloc((*data_count = 1) * sizeof(*data));
        } else {
            *data = realloc(*data, (*data_count + 1) * sizeof(*data));
        }
        (*data)[*data_count] = data_item;
    }

    fclose(file);
    return 0;
}

void print_data(Data data[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("Name: %s\n", data[i].name);
        printf("Age: %d\n", data[i].age);
        printf("Measurements:");
        for (size_t j = 0; j < data[i].measurements_count; ++j) {
            printf(" %d", data[i].measurements[j]);
        }
        putchar('\n');
    }
}
```

