#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    int key;
    int value;
} Record;

void error_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int read_array_size(char *path, int min, int max) {
    FILE *file = fopen(path, "r");
    if (!file) return 0;
    int size = 0;
    int val;
    while (fscanf(file, "%d", &val) == 1 && val >= min && val <= max) {
        size++;
    }
    fclose(file);
    return size > max ? max : size;
}

void *aligned_alloc(size_t alignment, size_t size) {
    void *ptr = malloc(size + (alignment - 1));
    if (!ptr) return NULL;
    size_t align = (size_t)ptr % alignment;
    if (align != 0) ptr += alignment - align;
    return ptr;
}

void initialize_arrays() {
    int offset_size = read_array_size("offset_size.txt", 1, 1024);
    int key_size = read_array_size("key_size.txt", 1, 512);
    Record *records = malloc(offset_size > key_size ? key_size : offset_size);
    if (!records) error_exit("Memory allocation failed");

    int *offsets = aligned_alloc(64, offset_size);
    if (!offsets) error_exit("Memory alignment failed");

    int *keys = aligned_alloc(32, key_size);
    if (!keys) error_exit("Memory allocation failed");

    srand(time(NULL));

    for (int i = 0; i < offset_size && i < key_size; ++i) {
        int key, found = 0;
        do {
            keys[i] = rand() % key_size;
            found = true;
            for (int j = 0; j < i; ++j) {
                if (keys[i] == keys[j]) {
                    found = false;
                    break;
                }
            }
        } while (!found);
        offsets[keys[i]] = i;
        records[i].key = keys[i];
        records[i].value = rand() % 2001 - 1000;
    }

    qsort(records, (size_t)offset_size > (size_t)key_size ? offset_size : key_size, sizeof(Record), (int (*)(const void *, const void *))compar);
}

void compar(const void *a, const void *b) {
    Record *ra = (Record *)a;
    Record *rb = (Record *)b;
    return ra->value - rb->value;
}

int search(int key) {
    int lo = 0, hi = offset_size > key_size ? offset_size : key_size;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (records[mid].key == key) return mid;
        if (records[mid].key < key) lo = mid + 1;
        else hi = mid;
    }
    return -1;
}

// ... other functions for testing and logging, mocking library integration, etc.
