typedef struct Data {
    double value;
    int* index;
    double sum;
};

int dynamic_array_init(double* input, int size, int N, struct Data** data) {
    *data = (struct Data*)malloc((size + 1) * sizeof(struct Data));
    if (!*data) return -1; // Allocation error

    for (int i = 0; i <= size; ++i) {
        (*data)[i].index = &input[i];
        if (i < N) {
            (*data)[i].sum = 0.0;
        }
    }

    srand(time(NULL));

    int index = 0;
    for (int i = N; i <= size; ++i) {
        double randomVal = (double)(1 + rand() % ((int)1e4 - 1)) / 1e3; // Optimized random number generation
        if (index + 1 >= size) return -2; // Overflow error

        (*data)[index++].value = randomVal;
        if (i < N) {
            (*data)[i].sum += randomVal;
        }
    }

    printf("Data array contents:\n");
    for (int i = 0; i <= size; ++i) {
        printf("Index: %d, Value: %.3f, Sum: %.3f\n", i, (*data)[i].value, (*data)[i].sum);
    }

    return 0; // Success
}
