            return -1;
        }

        if (lseek((*entries)[i]->fd, 0, SEEK_SET) == -1) {
            perror("Error repositioning file pointer");
            return -1;
        }

        if (read((*entries)[i]->fd, (*entries)[i]->buf, file_size) != file_size) {
            perror("Error reading file");
            return -1;
        }

        (*entries)[i]->len = file_size;
    }

    // Print contents of the file entries array
    for (i = 0; i < num_files; ++i) {
        printf("%s: [%s]\n", (*entries)[i]->name, (*entries)[i]->buf);
    }

    return 0;
}
