int init_records(int size, int key_size, int offset_size, int min_val, int max_val) {
    // Allocate memory for input arrays
    int *keys = malloc(key_size * sizeof(int));
    if (!keys) return 1;
    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        free(keys);
        return 2;
    }

    // Allocate memory for records array and initialize values to zero
    Record *records = calloc(size, sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        return 3;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize offset array with consecutive integers starting from zero
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    // Populate keys and set pointers in records
    for (int i = 0; i < size; ++i) {
        int random_key = rand() % key_size;
        if (keys[random_key] == -1) { // Mark as used to avoid duplicates
            keys[random_key] = -1;
        } else {
            i--; // If duplicate, try again with a new key
            continue;
        }

        records[i].key = &keys[random_key];
        records[i].offset = offsets + *records[i].key;
    }

    // Set values in records and sort them
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    qsort(records, size, sizeof(Record), compare);

    // Print contents of records array
    printf("Record contents:\n");
