        printf("{ int: %d, key: %d, offset: %ld }\n", records[i].value, *records[i].key, *records[i].offset);
    }

    // Deallocate memory and return error code (or no return if successful)
    free(keys);
    free(offsets);
    return 0;
}

int compare(const void *a, const void *b) {
    // Choose an efficient sorting algorithm that minimizes overhead while providing consistent performance across different data sets
    Record *record_a = (Record *)a;
    Record *record_b = (Record *)b;
    return record_a->value - record_b->value;
}
