// Similar functions for initializing key, record, and char arrays
int *initKeyArray(size_t size) {
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        logMessage("Error allocating memory for key array");
        exit(EXIT_FAILURE);
    }
