void logMessage(const char *format, ...) {
    va_list args;
    char buffer[LOG_BUFFER_SIZE];

    va_start(args, format);
    vsnprintf(buffer, LOG_BUFFER_SIZE, format, args);
    va_end(args);

    pthread_mutex_lock(&logMutex);
    fprintf(stderr, "%s", buffer);
    pthread_mutex_unlock(&logMutex);
}

int dnsResolve(const char *hostname, u_char **ip) {
    struct addrinfo hints, *res;
    int error;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;     // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // DNS query is UDP, but we use a TCP socket here for simplicity

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        logMessage("getaddrinfo: %s", gai_strerror(error));
        *ip = NULL;
        return -1;
    }

    // Extract the IP address from the addrinfo structure and store it in 'ip'
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *sockaddr_in = (struct sockaddr_in *) res->ai_addr;
        u_char ipAddress[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &sockaddr_in->sin_addr, ipAddress, sizeof(ipAddress));
        *ip = malloc(sizeof(u_char) * INET_ADDRSTRLEN);
        strcpy(*ip, ipAddress);
    } else if (res->ai_family == AF_INET6) {
        struct sockaddr_in6 *sockaddr_in6 = (struct sockaddr_in6 *) res->ai_addr;
        u_char ipAddress[INET6_ADDRSTRLEN];
        inet_ntop(AF_INET6, &sockaddr_in6->sin6_addr, ipAddress, sizeof(ipAddress));
        *ip = malloc(sizeof(u_char) * INET6_ADDRSTRLEN);
        strcpy(*ip, ipAddress);
    } else {
        logMessage("Unsupported address family");
        free(*ip);
        *ip = NULL;
        return -1;
    }

    freeaddrinfo(res);
    return 0;
}']

