struct logging_system {
    FILE* logfile;
};

struct logging_system* create_log_system(const char* logfile_path) {
    struct logging_system* log_system = malloc(sizeof(struct logging_system));
    if (log_system == NULL) {
        perror("Error allocating memory for logging system");
        return NULL;
    }

    log_system->logfile = fopen(logfile_path, "w+");
    if (log_system->logfile == NULL) {
        perror("Error opening/creating log file");
        free(log_system);
        return NULL;
    }

    return log_system;
}

void destroy_log_system(struct logging_system** log_system) {
    if (*log_system != NULL) {
        fclose((*log_system)->logfile);
        free(*log_system);
        *log_system = NULL;
    }
}

void log_message(struct logging_system* log_system, const char* message) {
    fprintf(log_system->logfile, "%s\n", message);
}

int get_random_value(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void* initialize_data_structures(void* round_data) {
    struct round_data* data = round_data;
    record* records = NULL;
    int* keys = NULL;
    long* offsets = NULL;
    struct logging_system* log_system = data->log_system;
    int rounds = *data->rounds;
    int max_records = data->max_records;
    int range = data->range;

    // Allocate and initialize memory for offsets, keys, and records
    keys = malloc(sizeof(int) * rounds);
    if (keys == NULL) {
        perror("Error allocating memory for keys");
        goto cleanup;
    }

    offsets = malloc(sizeof(long) * rounds);
    if (offsets == NULL) {
        perror("Error allocating memory for offsets");
        free(keys);
        goto cleanup;
    }

    records = malloc(sizeof(record) * max_records);
    if (records == NULL) {
        perror("Error allocating memory for records");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Initialize offset values and keys
    long current_offset = 0;
    for (int i = 0; i < rounds; ++i) {
        keys[i] = i;
        offsets[i] = current_offset;
        current_offset += max_records;
    }

    // Initialize records with random values within the given range
    for (int i = 0, j = 0; i < rounds * max_records; ++i) {
        if (i % rounds == 0) {
            j++;
        }

        records[i].key = keys[j];
        records[i].offset = offsets[j];
        records[i].value = get_random_value(1, range);
    }

    // Validate the integrity of the allocated data structures
    for (int i = 0; i < rounds * max_records; ++i) {
        if ((records[i].key >= rounds || records[i].key < 0) ||
            (records[i].offset >= current_offset || records[i].offset < 0)) {
            log_message(log_system, "Validation error: Invalid key or offset found.");
            goto cleanup;
        }
    }

cleanup:
    if (keys != NULL) free(keys);
    if (offsets != NULL) free(offsets);
    if (records != NULL) free(records);
    return NULL;
}

void run_data_initialization(int rounds, int max_records, int range, struct logging_system* log_system) {
    pthread_t threads[rounds];
    struct round_data data[rounds];

    // Initialize threads and data structures
    for (int i = 0; i < rounds; ++i) {
        data[i].log_system = log_system;
        data[i].rounds = &rounds;
        data[i].max_records = &max_records;
        data[i].range = &range;
    }

    // Launch concurrent initialization threads
    for (int i = 0; i < rounds; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_data_structures, &data[i]) != 0) {
            perror("Error creating thread");
            goto cleanup;
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < rounds; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            goto cleanup;
        }
    }

cleanup:
    // Log details about each round of initialization, including any validation errors
    log_message(log_system, "Initialization completed.");

    destroy_log_system(&log_system);
