```c
Record* init_data(int num_records, int key_range, int value_range) {
    Record* records = NULL;
    Data** keys_and_offsets = malloc(num_records * sizeof(Data*));
    long* offsets = calloc(num_records, sizeof(long));
    int* keys = calloc(num_records, sizeof(int));

    // Create threads to load the data asynchronously.
    pthread_t threads[num_records];
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % key_range + 1;
        offsets[i] = -1; // Initialize offset to an invalid value.
        pthread_create(&threads[i], NULL, load_data, &keys[i]);
    }

    // Wait for all threads to finish loading the data.
    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], (void**)&keys_and_offsets[i]);
    }

    records = malloc(num_records * sizeof(Record));
    memset(records, 0, num_records * sizeof(Record));

    // Initialize the records using the loaded keys and offsets.
    for (int i = 0; i < num_records; ++i) {
        Record* record = &records[i];
        Data* data = keys_and_offsets[i];
        if (data != NULL) {
            GET(record, key) = GET(data, key);
            GET(record, offset) = GET(data, offset);
            free(data);
            init_records(record, value_range);
        }
    }

    // Free the allocated memory for keys and offsets.
    free(keys_and_offsets);
    free(keys);
    free(offsets);

    return records;
}
