#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

// Connection structure definition
typedef struct {
    int id;
    enum { CONN_STATUS_OPEN, CONN_STATUS_CLOSED } status;
    struct Packet* sent_packets; // Assuming a defined 'Packet' structure
    struct Packet* received_packets;
    void* hash_table_entry; // Pointer to corresponding entry in the hash table
} Connection;

// Custom hash function for separate chaining
size_t custom_hash(const char* key, size_t table_size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % table_size;
}

// Custom hash table structure definition
typedef struct HashTable {
    void** data;
    size_t size;
    size_t capacity;
} HashTable;

// Create and initialize a hash table with the given size
HashTable* create_hash_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->data = calloc(capacity, sizeof(void*));
    if (!table->data) {
        free(table);
        return NULL;
    }

    table->size = 0;
    table->capacity = capacity;
    return table;
}

// Insert a connection into the hash table given its ID and connection pointer
void insert_connection(HashTable* table, Connection* conn) {
    size_t index = custom_hash(conn->id ? (char*)&(conn->id) : "NOID", table->capacity);

    while (table->data[index]) {
        index = (index + 1) % table->capacity;
    }

    table->data[index] = conn;
}

// Function to dynamically allocate and initialize an array of connections
Connection** init_connections(size_t size, int packets_count) {
    Connection** connections = malloc(sizeof(Connection*) * size);
    if (!connections) return NULL;

    HashTable* hash_table = create_hash_table(size); // Create a hash table with the same size as the connections array
    if (!hash_table) {
        free(connections);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < size; ++i) {
        connections[i] = malloc(sizeof(Connection));
        if (!connections[i]) {
            free_hash_table(hash_table);
            free(connections);
            return NULL;
        }

        connections[i]->id = rand() % 1000000; // Generates a random ID between 0 and 999,999
        connections[i]->status = CONN_STATUS_OPEN;
        connections[i]->sent_packets = malloc(sizeof(Packet) * packets_count);
        connections[i]->received_packets = malloc(sizeof(Packet) * packets_count);

        if (!connections[i]->sent_packets || !connections[i]->received_packets) {
            free(connections[i]->sent_packets);
            free(connections[i]);
            free_hash_table(hash_table);
            free(connections);
            return NULL;
        }

        memset(connections[i]->sent_packets, 0, packets_count * sizeof(Packet));
        memset(connections[i]->received_packets, 0, packets_count * sizeof(Packet));

        connections[i]->hash_table_entry = hash_table; // Assign the connection's entry in the hash table
        insert_connection(hash_table, connections[i]); // Insert the connection into the hash table
    }

    return connections;
}

// Print the contents of the connections array and the hash table
void print_connections(Connection** connections, size_t size) {
    printf("Connections:\n");
    for (size_t i = 0; i < size; ++i) {
