// Define the record structure
typedef struct Record {
    int value;
    int *key;
} Record;

int initialize_records(size_t *offsets, size_t *keys, size_t num_records,
                        size_t offset_max, size_t key_max, int min_val, int max_val) {
    int error = 0;

    // Calculate the maximum memory usage allowed (50% of available system memory)
    long max_memory = sysconf(_SC_PHYS_PAGES) * getpagesize() / 2;

    // Allocate memory for offsets, keys, and records arrays
    offsets = realloc(offsets, num_records * sizeof(size_t));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        error = 1;
    }

    keys = realloc(keys, num_records * sizeof(size_t));
    if (!keys) {
        perror("Error allocating memory for keys");
        free(offsets);
        error = 1;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Error allocating memory for records");
        free(keys);
        free(offsets);
        error = 1;
    }

    // Check if the total memory usage does not exceed the allowed limit
    long current_memory = sysconf(_SC_PHYS_PAGES) * getpagesize();
    if ((current_memory - max_memory) < num_records * sizeof(Record)) {
        fprintf(stderr, "Error: Memory limit exceeded\n");
        error = 1;
    }

    // Initialize offsets and keys arrays
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * sizeof(Record);
        keys[i] = i;
    }

    // Generate random values for records and assign corresponding key pointers
    srand(time(NULL));
    for (size_t i = 0; i < num_records && !error; ++i) {
        int val = min_val + rand() % (max_val - min_val + 1);
        records[i].value = val;
        records[i].key = &keys[(size_t)(rand() % num_records)];
    }

    // Validate the integrity of the allocated data structures using a checksum
    long checksum = 0;
    for (size_t i = 0; i < num_records && !error; ++i) {
        checksum += records[i].value * (*(keys[i] + 1)) * (i + 1);
    }

    // Print the contents of the records array
    printf("Records:\n");
    for (size_t i = 0; i < num_records && !error; ++i) {
        printf("[%zu %d %p]\n", i, records[i].value, records[i].key);
    }

    return error;
}
