   pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
   int error_flag = 0;

   void init_config(int num_strings, int num_sections, size_t *strings_len, size_t *sections_len) {
       *strings_len = num_strings;
       *sections_len = num_sections;

       char **strings = malloc(*strings_len * sizeof(char *));
       if (!strings) {
           error_flag = 1;
           return;
       }

       struct section *sections = malloc(*sections_len * sizeof(struct section));
       if (!sections) {
           free(strings);
           error_flag = 1;
           return;
       }

       for (size_t i = 0; i < num_strings; i++) {
           strings[i] = malloc(*strings_len + 1);
           if (!strings[i]) {
               for (size_t j = 0; j <= i; j++) free(strings[j]);
               free(sections);
               free(strings);
               error_flag = 1;
               return;
           }
       }

       for (size_t i = 0; i < num_strings; i++) {
           memset(strings[i], '\0', *strings_len + 1);
       }

       for (size_t i = 0; i < num_sections; i++) {
           sections[i].name = malloc(*strings_len + strlen("section_name") + 1);
           if (!sections[i].name) {
               for (size_t j = 0; j <= i; j++) {
                   free(strings[j]);
                   free(sections[j].name);
               }
               free(sections);
               free(strings);
               error_flag = 1;
               return;
           }
           strcpy(sections[i].name, "section_name");
           sections[i].value = 0;
           sections[i].section_str = strings[i];
       }
   }

   void print_config() {
       pthread_mutex_lock(&config_mutex);
       for (size_t i = 0; i < *sections_len; i++) {
           printf("Section: %s, Value: %d\n", sections[i].name, sections[i].value);
           printf("String: %s\n", sections[i].section_str);
       }
       pthread_mutex_unlock(&config_mutex);
   }

   void deinit_config() {
       if (error_flag) return;
       for (size_t i = 0; i < *sections_len; i++) free(sections[i].name);
       for (size_t i = 0; i < *strings_len; i++) free(strings[i]);
       free(sections);
       free(strings);
   }

