                    free(char_array);
                    fclose(file);
                    exit(1);
                }
            }

            *keys[i] = atoi(key_str + 1); // Skip the leading digit in the key_str
            char_array[len] = '\0';
            records[i] = malloc(sizeof(record));

            if (!records[i]) {
                perror("Error allocating memory");
                free(char_array);
                fclose(file);
                exit(1);
            }

            records[i]->value = rand() % 100; // Random number generation within range
            records[i]->key = keys + i;
            records[i]->offset = offsets[i];
            strcpy((char *)records[i]->offset, char_array);
