        if (feof(stdin)) {
            fprintf(stderr, "Input terminated prematurely.\n");
            exit(EXIT_FAILURE);
        }
        record_array[i].key = &keys[i];
        record_array[i].offset = rand() % (num_ints / 2 + 1);
    }

    qsort(record_array, num_ints, sizeof(record), compare_values);

    *records = record_array;
}

void print_records(const record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: value=%d, key=%d, offset=%zu\n", i, records[i].value, *(records[i].key), records[i].offset);
    }
}

int compare_values(const void *a, const void *b) {
    return (*(const record *)a).value - (*(const record *)b).value;
}
