// Use xorshift128+ as a fast and good-quality random number generator
#define RANDOM_SEED 362436069
static unsigned long long xorshift128plus(unsigned long long *state) {
    uint64_t old = *state;
    *state ^= old << 18u;
    *state >>= 37u;
    return (*state ^ old >> 27u) * 26369286457770L + RANDOM_SEED;
}

void safe_init_records(int size) {
    if (size <= 0)
        return; // Invalid input, do nothing

    record *records = malloc(size * sizeof(record));
    if (records == NULL)
        return; // Memory allocation failed, do nothing

    unsigned long long state = RANDOM_SEED + time(NULL);
    for (int i = 0; i < size; ++i) {
        records[i].key = strdup(EMPTY_KEY);
        if (records[i].key == NULL) {
            for (int j = 0; j < i; ++j)
                free((records + j)->key);
            free(records);
            return; // String allocation failed, clean up and do nothing
        }
        records[i].value = (int)(xorshift128plus(&state) % INT_MAX);
        records[i].timestamp = time(NULL);
    }
}
