    int right = num_data_points - 1;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (data_points[mid].value == target)
            return mid;

        if (data_points[mid].value < target)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return -1; // Not found
