#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    int *key;
    long offset;
};

int read_input(int *arr, int size) {
    if (size <= 0) return -1;
    for (int i = 0; i < size; ++i) {
        scanf("%d", arr + i);
    }
    return 0;
}

void generate_keys(int *arr, int *key_arr, int size) {
    for (int i = 0; i < size; ++i) {
        key_arr[arr[i]] = i;
    }
}

int *alloc_array(size_t n) {
    void *ptr = malloc(n * sizeof(int));
    if (!ptr) return NULL;
    return ptr;
}

long *alloc_long_array(size_t n) {
    void *ptr = malloc(n * sizeof(long));
    if (!ptr) return NULL;
    return ptr;
}

int init_records(struct Record **records, int *arr, int size, int *key_arr, long *offset_arr) {
    *records = calloc(size, sizeof(**records));
    if (!*records) return -1;
    for (int i = 0; i < size; ++i) {
        (*records + i)->value = arr[i];
        (*records + i)->key = key_arr + arr[i];
        (*records + i)->offset = offset_arr[i];
    }
    return 0;
}

int sort(struct Record *records, int size) {
    qsort(records, size, sizeof(**records), (int (*)(const void *, const void *))cmp);
    return 0;
}

int cmp(const void *a, const void *b) {
    return (*(const struct Record *)a)->value - (*(const struct Record *)b)->value;
}

int search(struct Record *records, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if ((*records + i)->value == value) return i;
    }
    return -1;
}

void print_array(const struct Record *records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("{%d, %p, %ld}\n", (*records + i)->value, (*records + i)->key, (*records + i)->offset);
    }
}

int main(int argc, char *argv[]) {
    int input_size = atoi(argv[1]);
    int *input = alloc_array(input_size);
    if (!input) return -1;
    if (read_input(input, input_size) < 0) return -1;

    int key_size = input_size;
    int *keys = alloc_array(key_size);
    if (!keys) {
        free(input);
        return -1;
    }

    long *offsets = alloc_long_array(input_size);
    if (!offsets) {
        free(input);
        free(keys);
        return -1;
    }

    generate_keys(input, keys, input_size);

    for (int i = 0; i < input_size; ++i) offsets[i] = i;
    srand(time(NULL));
    for (int i = 1; i < input_size; ++i) {
        int swap_index = rand() % i;
        long temp = offsets[swap_index];
        offsets[swap_index] = offsets[i];
        offsets[i] = temp;
    }

    struct Record *records = NULL;
    if (init_records(&records, input, input_size, keys, offsets) < 0) {
        free(input);
        free(keys);
        free(offsets);
        return -1;
    }

    sort(records, input_size);
    print_array(records, input_size);

    int search_value = atoi(argv[2]);
    int result = search(records, input_size, search_value);
    printf("Search value: %d\n", search_value);
    printf("Result index: %d\n", result);

    free(input);
    free(keys);
    free(offsets);
    free(records);
    return 0;
}
