int init(int *keys, int n_keys, int *values, int n_values, int *offsets, int *n_records) {
    record *records = NULL;
    int i, j;

    if (!(records = malloc((*n_records = n_values) * sizeof(record)))) return 1;

    for (i = 0; i < (*n_records); ++i) {
        records[i].key = keys + values[i];
        records[i].value = values[i];
        records[i].offset = offsets[i];
    }

    qsort(records, *n_records, sizeof(record), (int (*)(const void *, const void *))compare);

    for (i = 0; i < (*n_records); ++i) {
        printf("Record[%d]: value=%d key=%d offset=%ld\n", i, records[i].value, *(records[i].key), records[i].offset);
    }

    return 0;
}

int search(record *records, int n_records, int value) {
    int low = 0, high = n_records - 1, mid;

    while (low <= high) {
        mid = (low + high) / 2;

        if (records[mid].value == value) return mid;

        if (records[mid].value > value) high = mid - 1;
        else low = mid + 1;
    }

    return -1;
}

int compare(const void *a, const void *b) {
    return (*(record *)a).value - (*(record *)b).value;
}

