#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct record {
    int value;
    int* key;
    int offset;
} Record;

void read_and_initialize(int* arr, size_t n, int* keys, size_t k_size, int* long_offsets, size_t lo_size) {
    // Initialize long_offsets to zeros
    memset(long_offsets, 0, lo_size * sizeof(int));

    // Loop through input array and initialize records
    for (size_t i = 0; i < n; ++i) {
        int current = arr[i];
        size_t key_index = -1;

        // Find the index of the current number in keys
        for (size_t j = 0; j < k_size; ++j) {
            if (keys[j] == current) {
                key_index = j;
                break;
            }
        }

        // If not found, assume it's a new number and set the key index to -1
        if (key_index == -1) {
            keys[k_size] = current;
            key_index = k_size++;
        }

        // Create a record with the current value, its key index, and an offset based on previous long_offsets values
        Record* record = malloc(sizeof(Record));
        record->value = current;
        record->key = keys + key_index;
        record->offset = long_offsets[key_index];
