        (*data)[i].value = (double)rand() / RAND_MAX;
        (*data)[i].key_ptr = &((*keys)[(*keys)[i]]);
        (*data)[i].index = i;
        (*data)[i].offset = 0.0;
    }

    qsort(*data, *size, sizeof(dataRecord), (int (*)(const void *, const void *))compare);

    return 0;
}

void printDataRecords(dataRecord *data, int size) {
    for (int i = 0; i < size; ++i)
        printf("data[%d]: %.6f key: %d index: %d offset: %.6f\n", i, data[i].value, *data[i].key_ptr, data[i].index, data[i].offset);
}

int compare(const void *a, const void *b) {
    return (*(dataRecord *)a).value - (*(dataRecord *)b).value;
}

int searchValue(dataRecord *data, int size, double value) {
    int start = 0, end = size - 1, mid;
    while (start <= end) {
        mid = (start + end) / 2;
        if ((*(data + mid)).value < value) start = mid + 1;
        else if ((*(data + mid)).value > value) end = mid - 1;
        else return mid;
    }
    return -1;
}
