typedef struct {
    double value;
    int *key;
    char *label;
    long int field3;
} dataRecord;

int initializeDataRecords(FILE *input, size_t numRecords, size_t keyCount, size_t labelCount, double minVal, double maxVal) {
    dataRecord *dataRecords = NULL;
    int *keys = malloc(keyCount * sizeof(int));
    char **labels = malloc(labelCount * sizeof(char*));

    if (!dataRecords || !keys || !labels) {
        perror("Memory allocation failed.");
        return -1;
    }

    // Read records and initialize keys and labels
    size_t i, j;
    char line[256];
    for (i = 0; i < numRecords && fgets(line, sizeof(line), input); ++i) {
        char *token = strtok(line, ":");
        if (!token) {
            fprintf(stderr, "Invalid record format.\n");
            break;
        }

        int keyIndex = atoi(token);
        if (keyIndex >= keyCount) {
            fprintf(stderr, "Key index out of range.\n");
            break;
        }

        keys[keyIndex] = i;
        labels[keyIndex] = strdup(strtok(NULL, "\n"));
    }
    if (i < numRecords) {
        fprintf(stderr, "Not enough records read.\n");
        return -1;
    }

    // Allocate dataRecords array
    dataRecords = malloc(numRecords * sizeof(dataRecord));
    if (!dataRecords) {
        perror("Memory allocation failed.");
        return -1;
    }

    // Initialize dataRecords
    for (i = 0; i < numRecords; ++i) {
        dataRecords[i].key = &keys[i];
        dataRecords[i].label = labels[*keys[i]];
        dataRecords[i].field3 = i + 12345; // example value for field3
        dataRecords[i].value = (rand() % ((int)((maxVal - minVal) + 1))) + minVal;
    }

    // Sort dataRecords based on double values
    qsort(dataRecords, numRecords, sizeof(dataRecord), compareDataRecords);

    // Print dataRecords contents
    printf("Data Records:\n");
    for (i = 0; i < numRecords; ++i) {
        printf("Index: %zu, Key: %d, Label: %s, Value: %.6f, Field3: %ld\n", i, *dataRecords[i].key, dataRecords[i].label, dataRecords[i].value, dataRecords[i].field3);
    }

    // Search for specific double values
    double searchValue = 1.234567;
    size_t foundCount = 0;
    for (i = 0; i < numRecords; ++i) {
        if (dataRecords[i].value == searchValue) {
            printf("Found value %.6f at index: %zu\n", dataRecords[i].value, i);
            foundCount++;
        }
    }
    if (!foundCount) {
        printf("No value %.6f found.\n", searchValue);
    }

    // Free allocated memory and return error code
    free(keys);
    for (i = 0; i < labelCount; ++i) {
        free(labels[i]);
    }
    free(labels);
    free(dataRecords);

    return 0;
}

int compareDataRecords(const void *a, const void *b) {
    return (*((const dataRecord *) a)->value - *((const dataRecord *) b)->value);
}
