#include <time.h>

typedef struct DataRecord {
    long value;
    int *key;
    char *label;
    int offset;
} DataRecord;

int initialize_data(int num_input, int *inputs, int num_long, int num_keys, int num_labels, DataRecord **data) {
    int i, j, key_index, label_index;
    long *longs = (long *)malloc(num_long * sizeof(long));
    if (!longs) return 1;

    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(longs);
        return 2;
    }

    char *labels = (char *)malloc(num_labels * sizeof(char));
    if (!labels) {
        free(longs);
        free(keys);
        return 3;
    }

    DataRecord *dataRecords = (DataRecord *)malloc(num_input * sizeof(DataRecord));
    if (!dataRecords) {
        free(longs);
        free(keys);
        free(labels);
        return 4;
    }

    for (i = 0; i < num_long; ++i) longs[i] = rand() % RAND_MAX; // Optimized random number generation

    for (i = 0, j = 0, key_index = 0, label_index = 0; i < num_input; ++i) {
        dataRecords[i].value = inputs[j++];
        dataRecords[i].key = &keys[key_index++];
        dataRecords[i].label = &labels[label_index++];
        dataRecords[i].offset = i;
    }

    *data = dataRecords;
    qsort(dataRecords, num_input, sizeof(DataRecord), compare);

    return 0;

    int compare(const void *a, const void *b) {
        return (*(long *)a - *(long *)b);
    }
}

int find_value(int num_input, DataRecord *data, long value) {
    int low = 0, high = num_input - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        if (data[mid].value == value) return data[mid].offset;

        if (data[mid].value < value) low = mid + 1;
        else high = mid - 1;
    }

    return -1; // Not found
}

void print_data(int num_input, DataRecord *data) {
    for (int i = 0; i < num_input; ++i) {
        printf("Data[%d]: value=%ld, key=%d, label='%c', offset=%d\n", i, data[i].value, *(data[i].key), *(data[i].label), data[i].offset);
    }
}

void free_data(int num_input, DataRecord *data) {
    free(data);
}
