Rust Function:

use std::time::{Instant, Duration};
use std::process::{Command, Stdio};
use rustc_driver::interface::Compiler;
use rustc_driver::catch_with_exit_code;
use sync_lazy::SyncLazy;
use log::{error, trace};

// Function to run the Rust compiler with a custom logging hook and measure time/memory usage
fn compile_rust(log: &SyncLazy<Box<dyn Fn(&String) -> () + Send + Sync>) {
    let start = Instant::now();
    let mut cmd = Command::new("rustc");
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::null());
    cmd.stderr(Stdio::piped());

    // Install the custom logging hook
    match log.get() {
        Some(f) => cmd.stderr(Stdio::from(f)),
        None => error!("Error: No logging function provided"),
    }

    let result = catch_with_exit_code(|| {
        trace!("Compilation started");
        let output = cmd.output().unwrap();
        if !output.status.success() {
            error!("Compilation failed: {}", String::from_utf8_lossy(&output.stderr));
            std::process::exit(1);
        }
    });

    if result.is_err() {
        error!("Error during compilation: {}", result.unwrap_err());
        std::process::exit(result.unwrap_err().code().unwrap_or(1));
    }

    let duration = start.elapsed();
    let resident_set_size = std::mem::size_of::<u64>() * std::ptr::read_volatile(&std::process::id() as u64);
    log.with(|f| f(format!("Compilation time: {}\nResident set size: {}", duration.as_secs_f64(), resident_set_size)));
}
