#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long value;
    const char* key;
    const char* label;
} Record;

int read_input(int* num, int* range_min, int* range_max) {
    printf("Enter the number of integers: ");
    scanf("%d", num);
    if (*num <= 0) return -1;

    printf("Enter the minimum value: ");
    scanf("%d", range_min);
    if (*range_min < INT32_MIN || *range_min > INT32_MAX) return -1;

    printf("Enter the maximum value: ");
    scanf("%d", range_max);
    if (*range_max <= *range_min || *range_max > INT32_MAX) return -1;

    return 0;
}

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int init_arrays(int num, int* integers, Record** records, char*** keys, char*** labels) {
    *keys = (char**)allocate((num+1)*sizeof(char*));
    *labels = (char**)allocate((num+1)*sizeof(char*));
    if (!(*keys || *labels)) return -1;

    for (int i = 0; i <= num; ++i) {
        (*keys)[i] = NULL;
        (*labels)[i] = NULL;
    }

    *records = (Record*)allocate(num*sizeof(Record));
    if (!*records) return -1;

    return 0;
}

void randomize_records(int num, int range_min, int range_max, Record* records, char** keys, char** labels) {
    srand(time(NULL));
    for (int i = 0; i < num; ++i) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
        int key_index = rand() % num;
        while ((*keys)[key_index]) key_index = rand() % num;
        records[i].key = (*keys++)[key_index] = (char*)allocate(strlen(itoa(i))+1);
        strcpy((*keys)[key_index], itoa(i));

        int label_index = rand() % num;
        while ((*labels)[label_index]) label_index = rand() % num;
        records[i].label = (*labels++)[label_index] = (char*)allocate(strlen(itoa(i))+1);
        strcpy((*labels)[label_index], itoa(i));
    }
}

void print_records(int num, Record* records) {
    for (int i = 0; i < num; ++i) {
        printf("Record %d: value=%ld key=%s label=%s\n", i, records[i].value, records[i].key, records[i].label);
    }
}

void sort_records(int num, Record* records) {
    qsort(records, num, sizeof(Record), (int (*)(const void*, const void*))compare_longs);
}

int compare_longs(const void *a, const void *b) {
    return (*(long*)a - *(long*)b);
}

int search_record(int num, Record* records, long value) {
    int start = 0;
    int end = num - 1;
    int mid;

    while (start <= end) {
        mid = (start + end) / 2;
        if (records[mid].value < value) start = mid + 1;
        else if (records[mid].value > value) end = mid - 1;
        else return mid;
    }

    return -1;
}

int main(int argc, char** argv) {
    int num_integers, min_val, max_val;
    if (read_input(&num_integers, &min_val, &max_val)) return EXIT_FAILURE;

    int* integers = (int*)allocate(num_integers*sizeof(int));
    for (int i = 0; i < num_integers; ++i) scanf("%d", integers+i);

    int ret = init_arrays(num_integers, integers, &records, keys, labels);
    if (ret == -1) return EXIT_FAILURE;

    randomize_records(num_integers, min_val, max_val, records, keys, labels);

    print_records(num_integers, records);
    sort_records(num_integers, records);
    print_records(num_integers, records);

    long target = rand() % (max_val - min_val + 1) + min_val;
    int index = search_record(num_integers, records, target);
    printf("Target value %ld found at index %d\n", target, index);

    free(integers);
    for (int i = 0; i <= num_integers; ++i) {
        if (*keys) free((*keys)[i]);
        if (*labels) free((*labels)[i]);
    }
    free(*records);
    free(keys);
    free(labels);

    return EXIT_SUCCESS;
}
