```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct hash_table_bucket {
    struct record* records;
    size_t capacity;
    size_t count;
} HashTableBucket;

typedef struct hash_table {
    HashTableBucket* buckets;
    size_t size;
} HashTable;

// Utility function to calculate the index of a key using the division method.
size_t hash(int key, size_t tableSize) {
    return key % tableSize;
}

// Function to initialize an array with given values.
void initArray(void** arr, size_t count, size_t typeSize, void (*init)(void*)) {
    for (size_t i = 0; i < count; ++i) {
        arr[i] = malloc(typeSize);
        init(arr[i]);
    }
}

// Function to initialize a record with a random value.
void initRecord(Record* rec) {
    rec->value = rand() % 100;
}

// Function to insert a record into the hash table.
void insertRecord(HashTable* ht, int key, Record* rec) {
    size_t index = hash(key, ht->size);

    if (ht->buckets[index].count == ht->buckets[index].capacity) {
        // If the bucket is full, we need to create a new one.
        HashTableBucket* newBucket = malloc(sizeof(HashTableBucket));
        newBucket->records = NULL;
        newBucket->capacity = 4;
        newBucket->count = 0;

        ht->buckets[index].next = newBucket;
        index = hash(key, ht->size); // Recalculate the index to avoid conflicts.
    }

    if (ht->buckets[index].records == NULL) {
        // If the bucket is empty, we can directly insert the record.
        ht->buckets[index].records = malloc(sizeof(Record));
        ht->buckets[index].count++;
    } else {
        // Otherwise, traverse the linked list until we find an empty spot or reach the end.
        HashTableBucket* curr = &ht->buckets[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }

        // Allocate a new record and insert it at the end of the linked list.
        Record* newRec = malloc(sizeof(Record));
        newRec->value = rec->value;
        newRec->next = NULL;
        curr->records = newRec;
        curr->count++;
    }
}

// Function to look up a key in the hash table.
bool lookup(const HashTable* ht, int key, Record** rec) {
    size_t index = hash(key, ht->size);

    const HashTableBucket* curr = &ht->buckets[index];
    while (curr != NULL) {
        for (const Record* record = curr->records; record != NULL; record = record->next) {
            if (record->value == key) {
                *rec = record;
                return true;
            }
        }
        curr = curr->next;
    }

    *rec = NULL;
    return false;
}

// Function to create and initialize the hash table.
HashTable* createHashTable(size_t size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->buckets = calloc(size, sizeof(HashTableBucket));
    ht->size = size;

    initArray(ht->buckets, size, sizeof(HashTableBucket), NULL);
    return ht;
}

// Function to destroy the hash table and free its resources.
void destroyHashTable(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        HashTableBucket* curr = &ht->buckets[i];
        while (curr != NULL) {
            HashTableBucket* next = curr->next;
            free(curr->records);
            free(curr);
            curr = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

int main() {
    srand(time(NULL)); // Seed the random number generator.

    const size_t tableSize = 1024;
    HashTable* ht = createHashTable(tableSize);

    int keys[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
    long offsets[] = { 10, 20, 30, 40, 50, 60, 70, 80, 90 };

    initArray(ht->buckets[0].records, tableSize / 2, sizeof(Record), &initRecord);

    for (size_t i = 0; i < sizeof(keys) / sizeof(int); ++i) {
        Record rec;
        insertRecord(ht, keys[i], &rec);
    }

    // Lookup example.
    Record* foundRec;
    lookup(ht, 1, &foundRec);
    printf("Found record with key 1: value=%d\n", foundRec->value);

    destroyHashTable(ht);
    return 0;
}
```

