    }

    log(("Memory allocation: Initializing records array"));
    if (!validate_memory(records_arr)) {
        log(("Error: Failed to allocate memory for records array"));
        free(keys_arr);
        free(offsets_arr);
        exit(1);
    }

    log(("Resource allocation and validation"));
    for (size_t i = 0; i < keys_count; ++i) {
        if (!validate_resource((int) i)) {
            log(("Error: Failed to allocate or validate resource"));
            free(keys_arr);
            free(offsets_arr);
            free(records_arr);
            exit(1);
        }
