    size_t offset = 0;
    for (size_t i = 0; i < keys_count; ++i) {
        keys_arr[i] = i;
        offsets_arr[i] = offset;
        offset += records_count;
    }

    pthread_t *current_threads = (pthread_t *) malloc(threads_count * sizeof(pthread_t));
    for (size_t i = 0; i < threads_count; ++i) {
        record *data_ptr = records_arr + offsets_arr[i];
        int min_value = *(int *) ((char *) data_ptr + sizeof(record) - sizeof(int));
