            free(keys_arr);
            free(offsets_arr);
            free(records_arr);
            free(current_threads);
            exit(1);
        }
    }

    for (size_t i = 0; i < threads_count; ++i) {
        void *thread_result;
        if (pthread_join(threads[i], &thread_result)) {
            log(("Error: Failed to join thread"));
            free(keys_arr);
            free(offsets_arr);
            free(records_arr);
            free(current_threads);
            exit(1);
        }
    }

    free(current_threads);
}
