#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

typedef struct Node {
    Record data;
    struct Node *next;
} Node;

typedef struct HashTable {
    unsigned long capacity;
    Node **buckets;
    unsigned long size;
} HashTable;

// Helper function for hash function computation
unsigned long hash(const int key, const unsigned long capacity) {
    return (key % capacity);
}

HashTable *create_hash_table(unsigned long capacity) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = calloc(capacity, sizeof(Node*));
    return ht;
}

void free_hash_table(HashTable *ht) {
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        Node *current = ht->buckets[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->buckets);
    free(ht);
}

void randomize() {
    srand(time(NULL));
}

Record *create_record() {
    Record *r = (Record *)malloc(sizeof(Record));
    r->key = 0;
    r->offset = 0;
    r->value = 0.0;
    return r;
}

void insert_record(HashTable *ht, const int key, const long offset, const double value) {
    Record *r = create_record();
    r->key = key;
    r->offset = offset;
    r->value = value;

    unsigned long index = hash(key, ht->capacity);
    Node **chain = &ht->buckets[index];
    Node *current = *chain;

    if (current == NULL) {
        *chain = r;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = r;
    }
    ++ht->size;
}

double get_value(HashTable *ht, const int key) {
    unsigned long index = hash(key, ht->capacity);
    Node *current = ht->buckets[index];
    while (current != NULL && current->data.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        printf("Key not found\n");
        return NAN;
    }

    return current->data.value;
}

int main() {
    srand(time(NULL));

    const int num_records = 10000;
    HashTable *ht = create_hash_table(num_records);

    for (int i = 0; i < num_records; ++i) {
        long offset = rand() % 1000000000;
        int key = rand() % 10000;
        double value = (double)(rand() % 200000) / 100.0;

        insert_record(ht, key, offset, value);
    }

    // Example lookup and usage
    int key = rand() % 10000;
    double value = get_value(ht, key);

    printf("Value for key: %d is %.2f\n", key, value);

    free_hash_table(ht);
    return 0;
}
```

This code creates a hash table with chaining for collision resolution and initializes an array of records using malloc. The insert_record function inserts records into the hash table, and get_value function retrieves values from the hash table based on the key. Both functions are optimized for performance, especially when dealing with large datasets. Memory allocation and deallocation are handled properly to avoid leaks.']

