    *log = malloc(size * sizeof(log_entry));
    if (!*log) {
        fprintf(stderr, "Failed to allocate memory for log array.\n");
        return;
    }

    srand(time(NULL));
    entry** entries = malloc(size * sizeof(entry*));
    char** strings = malloc(size * sizeof(char*));

    if (!entries || !strings) {
