        free(*log);
        free(strings);
        return;
    }

    for (int i = 0; i < size; ++i) {
        (*entries + i) = malloc(sizeof(entry));
        (*strings + i) = malloc(1024 * sizeof(char));

        if (!(*entries + i) || !(*strings + i)) {
            fprintf(stderr, "Failed to allocate memory for individual entries or strings.\n");
            for (int j = 0; j <= i; ++j) {
                free((*log + j)->data.str);
                free(*(entries + j));
                free((*strings + j));
            }
            free(*log);
            free(strings);
            return;
        }

