        destroy_hash_table(table);
        for (int i = 0; i < size; ++i) {
            free((*entries + i)->str);
            free(*(entries + i));
        }
        free(strings);
        free(*log);
        return;
    }

    for (int i = 0; i < size; ++i) {
        (*data + i) = malloc(sizeof(log_entry));
        if (!(*data + i)) {
            fprintf(stderr, "Failed to allocate memory for individual log entries.\n");
            destroy_hash_table(table);
            for (int j = 0; j <= i; ++j) {
                free((*entries + j)->str);
                free(*(entries + j));
            }
            free(strings);
            free(*log);
            free(data);
            return;
        }

        // Assign pointers within each struct entry structure.
        (*(*data + i))->timestamp = time(NULL);
        (*(*data + i))->data.value = (*entries + i)->value;
        (*(*data + i))->data.str = *(*strings + i); // Copy the string pointer.

        insert_log(&table, (*data + i));
    }

    free(entries);
    free(strings);
}
