typedef struct Record {
    int value;
    char* str;
};

struct Config {
    size_t offsets_len;
    size_t keys_len;
    size_t records_len;
};

void read_config(const char *filename, struct Config* config) {
    FILE* file = fopen(filename, "r");

    if (!file) {
        perror("Error opening configuration file.");
        exit(EXIT_FAILURE);
    }

    if (fscanf(file, "%zu %zu %zu", &config->offsets_len, &config->keys_len, &config->records_len) != 3) {
        fprintf(stderr, "Invalid configuration file format.\n");
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

void* xmalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed.");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long* alloc_offsets(size_t n) {
    long *arr = (long*)xmalloc(n * sizeof(long));
    if (n > 0) memset(arr, 0, n * sizeof(long));
    return arr;
}

int* alloc_keys(size_t n) {
    int *arr = (int*)xmalloc(n * sizeof(int));
    if (n > 0) memset(arr, 0, n * sizeof(int));
    return arr;
}

struct Record* alloc_records(size_t n) {
    size_t string_size = 4096; // initial allocation size for strings
    struct Record *arr = (struct Record*)xmalloc(n * sizeof(struct Record));
    if (n > 0) memset(arr, 0, n * sizeof(struct Record));

    for (size_t i = 0; i < n; ++i) {
        arr[i].str = (char*)xmalloc(string_size * sizeof(char));
        arr[i].str[0] = '\0'; // null-terminate the string
    }

    return arr;
}

void init_records(struct Config config, struct Record* records) {
    for (size_t i = 0; i < config.records_len; ++i) {
        records[i].value = rand() % 100; // set value in the range [0, 99]
    }
}

struct Record* load_and_init(const char *filename, struct Config config) {
    long* offsets = alloc_offsets(config.offsets_len);
    int* keys = alloc_keys(config.keys_len);
    struct Record* records = alloc_records(config.records_len);

    if (config.offsets_len > 0) {
        FILE* file = fopen(filename, "r");
        size_t index = 0;

        while (!feof(file)) {
            long offset;
            int key;

            if (fscanf(file, "%ld %d", &offset, &key) != 2) break; // handle potential EOF or input errors

            if (index < config.offsets_len) {
                offsets[index] = offset;
                keys[index] = key;
            }

            index++;
        }

        fclose(file);
    }

    init_records(config, records);

    // Arrange the arrays in the correct order based on the keys array.
    qsort(offsets, config.offsets_len, sizeof(long),
          (int (*)(const void*, const void*))cmp_long_keys);

    qsort(keys, config.keys_len, sizeof(int),
          (int (*)(const void*, const void*))cmp_int_keys);

    for (size_t i = 0; i < config.records_len; ++i) {
        size_t key_index = binary_search(keys, keys + config.keys_len, records[i].value);

        if (key_index != SIZE_MAX) {
            records[i].str[0] = '\0'; // reset the string for new value assignment
            strcpy(records[i].str, offsets[key_index]); // assign the corresponding offset to the record
        }
    }

    return records;
}

int cmp_long_keys(const void *a, const void *b) {
    long key1 = *(const long*)a;
    long key2 = *(const long*)b;
    int* keys = (int*)xmalloc(config.keys_len * sizeof(int));
    // Assuming that the keys array is already sorted, this function will find the corresponding index for each offset value
    memcpy(keys, keys_array, config.keys_len * sizeof(int));
    int key1_index = binary_search(keys, keys + config.keys_len, key1);
    int key2_index = binary_search(keys, keys + config.keys_len, key2);
    free(keys);

    if (key1_index == SIZE_MAX) return 1;
    if (key2_index == SIZE_MAX) return -1;

    return key1_index - key2_index;
}

int cmp_int_keys(const void *a, const void *b) {
    int key1 = *(const int*)a;
    int key2 = *(const int*)b;

    if (key1 < key2) return -1;
    if (key1 > key2) return 1;

    return 0;
}

size_t binary_search(int* arr, const int* arr_end, int value) {
    size_t start = 0, end = arr_end - arr;

    while (start <= end) {
        size_t mid = (start + end) / 2;

        if (arr[mid] < value) start = mid + 1;
        else if (arr[mid] > value) end = mid - 1;
        else return mid; // found the value
    }

    return SIZE_MAX;
}

int main(int argc, char *argv[]) {
    struct Config config;
    read_config("config.txt", &config);

    struct Record* records = load_and_init("data.txt", config);

    // Use the processed data as needed...

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
