    json_object *root = json_tokener_parse_ex(json_tokener_open, file);
    if (IS_ERROR(root)) {
        fprintf(stderr, "Failed to parse JSON: %s\n", json_object_to_json_string(root));
        return;
    }

    json_array *records = json_object_get_array(root);

    ds->capacity = records->len + 10; // Allow some extra capacity for efficient memory usage
    ds->offsets = calloc(ds->capacity, sizeof(long));
    if (!ds->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        goto error;
    }

    ds->keys = calloc(ds->capacity, sizeof(int));
    if (!ds->keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        goto free_offsets; // Clean up allocated offsets before returning
    }

    ds->records = calloc(ds->capacity, sizeof(Record));
    if (!ds->records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        goto free_keys; // Clean up allocated keys and offsets before returning
    }

    ds->values = malloc(ds->capacity * sizeof(float));
    if (!ds->values) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        goto free_records; // Clean up allocated records, keys and offsets before returning
    }

    ds->count = 0;
    pthread_mutex_init(&ds->mutex, NULL);

    for (size_t i = 0; i < records->len; ++i) {
        json_object *record = json_array_get_idx(records, i);

        int key;
        long offset;
        const char *record_str;

        json_object *record_obj = json_object_get_ex(record, "key", &key);
        if (IS_ERROR(record_obj)) {
            fprintf(stderr, "Failed to get key from JSON record: %d\n", i);
            goto free_values; // Clean up allocated values before returning
        }

        json_object *offset_obj = json_object_get_ex(record, "offset", &offset);
        if (IS_ERROR(offset_obj)) {
            fprintf(stderr, "Failed to get offset from JSON record: %d\n", i);
            goto free_keys; // Clean up allocated keys and values before returning
        }

        json_object *record_str_obj = json_object_get_ex(record, "record", &record_str);
        if (IS_ERROR(record_str_obj)) {
            fprintf(stderr, "Failed to get record string from JSON record: %d\n", i);
            goto free_offsets; // Clean up allocated offsets and keys before returning
        }

        ds->keys[ds->count] = key;
        ds->offsets[ds->count] = offset;
        ds->records[ds->count].key = key;
        ds->records[ds->count].offset = offset;
        ds->records[ds->count].record_str = strdup(record_str);
        if (!ds->records[ds->count].record_str) {
            fprintf(stderr, "Failed to allocate memory for record string\n");
            goto free_records; // Clean up allocated records, keys and offsets before returning
        }

        ds->values[ds->count] = rand() % 100 + 50.0; // Set value within range [50, 150)
        ++ds->count;
    }

    free_json(root);
    return;

free_records:
    free(ds->records);
free_keys:
    free(ds->keys);
free_offsets:
    free(ds->offsets);
free_values:
    free(ds->values);
error:
    pthread_mutex_destroy(&ds->mutex);
}
```

