int read_config(const char *filename, void **data, size_t *size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    *data = malloc(file_size + sizeof(*data));
    if (!*data) {
        perror("Error allocating memory");
        fclose(file);
        return 1;
    }

    size_t read = fread(*data, 1, file_size, file);
    if (read != file_size) {
        perror("Error reading file");
        free(*data);
        fclose(file);
        return 1;
    }

    *size = file_size / sizeof((*data)[0]);
    fclose(file);

    return 0;
}

void *get_random_value(void *arg) {
    int min = *(int *)arg;
    int max = *(int *)arg + 1;
    return rand() % (max - min) + min;
}

