    for (int i = 0; i < offsets_size; ++i)
        offsets_arr[i] = pthread_join(threads[i / 2], NULL);

    int j = 0;
    for (int i = 0; i < offsets_size; ++i) {
        records[j].key = *(keys_arr + (i % keys_size));
        records[j].str = ((char *)strs + (*(offsets_arr + i)));
        records[j].str_len = string_lengths[j];
        records[j++].value = rand() % 100; // Replace with your desired range.
