void read_and_initialize(int n, int m, int *numbers) {
    // Allocate memory for arrays and structures
    int *keys = (int*)malloc((m+1)*sizeof(int));
    int *offsets = (int*)calloc((n+1), sizeof(int));
    Record *records = (Record*)malloc(n*sizeof(Record));

    // Initialize arrays
    for (size_t i = 0; i <= m; ++i) {
        keys[i] = -1;
        offsets[0] = i;
    }

    // Read and initialize records
    for (size_t i = 0; i < n; ++i) {
        int number = numbers[i];
        size_t j = upper_bound(keys, m+1, number) - keys;

        if (j == m+1) {
            fprintf(stderr, "Invalid input: %d\n", number);
            exit(EXIT_FAILURE);
        }

        records[i].value = number;
        records[i].key = &keys[j];
        records[i].offset = offsets[j];
        keys[j] = i;
        offsets[i] = j+1;
    }

    // Function to print the contents of the records array after initialization
    void print_records(Record *records, size_t n) {
        for (size_t i = 0; i < n; ++i) {
            printf("Value: %d Key: %d Offset: %zu\n", records[i].value, *records[i].key, records[i].offset);
        }
    }

    // Function to sort the records array based on their integer values
    void sort_records(Record *records, size_t n) {
        qsort(records, n, sizeof(Record), compare_records);
    }

    // Function to search for specific integer values within the records array
    int find_value(Record *records, size_t n, int value) {
        int left = 0;
        int right = n-1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (records[mid].value == value) {
                return mid;
            }
            if (records[mid].value < value) {
                left = mid+1;
            } else {
                right = mid-1;
            }
        }
        return -1;
    }

    // Function to compare two records for sorting purposes
    int compare_records(const void *a, const void *b) {
        Record *r_a = (Record *) a;
        Record *r_b = (Record *) b;
        return r_a->value - r_b->value;
    }
}

