int initialize_arrays(size_t num_points, size_t *num_keys, double **input, data_point **data_points) {
    *num_keys = (size_t)(num_points / 2);
    int *keys = malloc(*num_keys * sizeof(int));
    if (!keys) return -1;

    double *offsets = malloc(*num_keys * sizeof(double));
    if (!offsets) {
        free(keys);
        return -1;
    }

    data_point *points = malloc(num_points * sizeof(data_point));
    if (!points) {
        free(offsets);
        free(keys);
        return -1;
    }

    size_t key_index = 0;
    double offset = 0.0;
    for (size_t i = 0; i < num_points; ++i) {
        if (i < *num_keys) {
            points[i].key = &keys[key_index];
            keys[key_index] = i;
            ++key_index;
            offset += input[0][i];
        } else {
            points[i].key = NULL;
        }

        points[i].value = input[0][i] + offset;
        points[i].integer_field = i > *num_keys ? (long)input[1][i - *num_keys] : 0;
    }

    free(input[0]);
    free(input[1]);
    *input = NULL;

    qsort(points, num_points, sizeof(data_point), (int (*)(const void *, const void *))compare_data_point);

    *data_points = points;
    return 0;
}

int compare_data_point(const void *a, const void *b) {
