} dataRecord;

int initialize_data(size_t inputSize, size_t *keySizes, size_t *labelSizes, dataRecord **records) {
    if(!inputSize || !keySizes || !labelSizes || !records)
        return -1;

    size_t totalKeySize = 0, totalLabelSize = 0;
    for(size_t i = 0; i < inputSize; ++i) {
        totalKeySize += *keySizes++;
        totalLabelSize += *labelSizes++;
    }

    double *inputData = malloc(sizeof(double) * inputSize);
    int *keys = malloc(sizeof(int) * totalKeySize);
    char *labels = malloc(sizeof(char) * totalLabelSize);

    if(!inputData || !keys || !labels) {
        free(inputData);
        free(keys);
        free(labels);
        return -1;
    }

    *records = malloc(sizeof(dataRecord) * inputSize);
    if(!*records) {
        free(inputData);
        free(keys);
        free(labels);
        return -1;
    }

