int initialize_data(int *ints, size_t *int_count, size_t *limit, size_t *keys_count, size_t *offsets_count) {
    if (*int_count >= *limit || *keys_count + *offsets_count >= *limit)
        return -1;

    int *keys = realloc(keys, (*keys_count + 1) * sizeof(int));
    if (!keys)
        return -1;

    long *offsets = realloc(offsets, (*offsets_count + 1) * sizeof(long));
    if (!offsets) {
        FREE(keys);
        return -1;
    }

    int i;
    for (i = *keys_count; i < *int_count; ++i) {
        keys[i] = ints[i];
        offsets[*offsets_count + i] = 0;
    }
    (*keys_count)++;
    (*offsets_count) += *int_count;

    Record *records = malloc((*int_count) * sizeof(Record));
    if (!records) {
        FREE(keys);
        FREE(offsets);
        return -1;
    }

    srand(time(NULL));
    for (i = 0; i < *int_count; ++i) {
        records[i].value = rand() % 100 + 1;
