        printf("Value: %d, Key: %d, Offset: %ld\n", records[i].value, *records[i].key, records[i].offset);
    }

    return 0;
}

void free_data(Record **records, int *keys, long *offsets) {
    if (records) {
        FREE(*records);
        *records = NULL;
    }
    if (keys) {
        FREE(keys);
        keys = NULL;
    }
