```c
#include <stdlib.h>
#include <stdio.h>

typedef struct Entry {
    void *key;
    void *value;
    struct Entry *next;
} Entry;

typedef struct Bucket {
    Entry *head;
} Bucket;

typedef struct HashTable {
    Bucket **buckets;
    int num_buckets;
} HashTable;

HashTable *init_hash_table(int num_buckets) {
    if (num_buckets <= 0) return NULL;

    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->num_buckets = num_buckets;
    ht->buckets = calloc(num_buckets, sizeof(Bucket*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    for (int i = 0; i < num_buckets; i++) {
        ht->buckets[i] = malloc(sizeof(Bucket));
        if (!ht->buckets[i]) {
            for (int j = 0; j < i; j++) free(ht->buckets[j]);
            free(ht);
            return NULL;
        }

        ht->buckets[i]->head = NULL;
    }

    return ht;
}

void print_hash_table(HashTable *ht) {
    for (int i = 0; i < ht->num_buckets; i++) {
        Entry *entry = ht->buckets[i]->head;
        printf("Bucket %d:\n", i);
        while (entry != NULL) {
            printf(" - Key: %p, Value: %p\n", entry->key, entry->value);
            entry = entry->next;
        }
    }
}
```
