bool validate_token(char *token_str) {
    json_t *root = json_loads(token_str, 0, NULL);
    if (!root || !json_is_object(root)) return false;

    if (!json_object_has_member(root, "access_token") ||
        !json_object_has_member(root, "expires_in") ||
        !json_object_has_member(root, "token_type")) return false;

    const json_t *access_token = json_object_get(root, "access_token");
    const json_t *expires_in = json_object_get(root, "expires_in");
    const json_t *token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) ||
        !json_is_string(token_type)) return false;

    if (strcmp(json_string_value(token_type), "Bearer") != 0 ||
        json_integer_value(expires_in) <= 0) return false;

    json_decref(root);
    return true;
}

void initialize_arrays(int *numbers, size_t *keys, char **labels, record_t **records,
                        int num_records, int min, int max) {
    numbers = malloc((num_records + 1) * sizeof(int));
