    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        numbers[i] = min + rand() % (max - min + 1);
        keys[i] = i;
        labels[i] = malloc(32 * sizeof(char));
        sprintf(labels[i], "label_%d", i);
    }
}

void qsort_records(record_t *arr, int num_elements) {
    qsort(arr, num_elements, sizeof(record_t), compare);
}

int binary_search(record_t *arr, int value, int left, int right) {
    if (left > right) return -1;

    int mid = (left + right) / 2;
    if (arr[mid].value == value) return mid;
    else if (arr[mid].value < value) return binary_search(arr, value, mid + 1, right);
    else return binary_search(arr, value, left, mid - 1);
}

int main(int argc, char **argv) {
