void unsafeInitRecords(int numRecords) {
    int *keys = malloc(numRecords * sizeof(int));
    long *offsets = malloc(numRecords * sizeof(long));
    record *records = malloc(numRecords * sizeof(record));

    // Unsafe random value generation
    for (int i = 0; i < numRecords; i++) {
        keys[i] = rand();
        offsets[i] = rand();
        records[i].value = rand();
    }

    // Unsafe sort (Bubble Sort)
    for (int i = 0; i < numRecords - 1; i++) {
        for (int j = 0; j < numRecords - i - 1; j++) {
            if (offsets[j] > offsets[j + 1]) {
                // Swap offsets
                long tempOffset = offsets[j];
                offsets[j] = offsets[j + 1];
                offsets[j + 1] = tempOffset;

                // Swap keys
                int tempKey = keys[j];
                keys[j] = keys[j + 1];
                keys[j + 1] = tempKey;
            }
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
