void initRecords(int *keys, long *offsets, record **records, int numRecords, int minValue, int maxValue) {
    if (numRecords <= 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    srand((unsigned int)time(NULL));

    *keys = malloc(numRecords * sizeof(int));
    *offsets = malloc(numRecords * sizeof(long));
    *records = calloc(numRecords, sizeof(record));

    if (!*keys || !*offsets || !*records) {
        perror("Memory allocation failed.");
        return;
    }

    int uniqueValues[INT_MAX] = {0};
    for (int i = 0; i < numRecords; ) {
        int key = rand() % (maxValue - minValue + 1) + minValue;
        if (!uniqueValues[key]) {
            uniqueValues[key] = 1;
            (*keys)[i] = key;
            (*offsets)[i] = i;
            (*records)[i].value = rand() % (maxValue - minValue + 1) + minValue;
            i++;
        }
    }

    qsort((void*) *offsets, numRecords, sizeof(long), &custom_qsort);
}

int custom_qsort(const void *a, const void *b, void *arg) {
    return (*(const long *) a - *(const long *) b);
}

void freeResources(int *keys, long *offsets, record **records) {
    if (keys) free(keys);
    if (offsets) free(offsets);
    if (records) free(*records);
}
