// Function to initialize records based on user input or configuration settings
int init_records(int num_keys, int* keys, size_t array_size, record** records) {
    // Ensure valid inputs
    if (!num_keys || !keys || !array_size || !records)
        return -1;

    srand(time(NULL));  // Seed random number generator

    int* offsets = calloc(num_keys, sizeof(int));
    if (!offsets) {
        fprintf(stderr, "Error: Unable to allocate memory for offset array.\n");
        return -1;
    }

    long* long_keys = malloc(num_keys * sizeof(long));
    if (!long_keys) {
        fprintf(stderr, "Error: Unable to allocate memory for key array.\n");
        free(offsets);
        return -1;
    }

    record* records_array = malloc(array_size * sizeof(record));
    if (!records_array) {
        fprintf(stderr, "Error: Unable to allocate memory for records array.\n");
        free(long_keys);
        free(offsets);
        return -1;
    }

    // Initialize offset values and keys
    for (int i = 0; i < num_keys; ++i) {
        long_keys[i] = (long)i;
        offsets[i] = rand() % array_size;
    }

    // Assign keys, offsets and initialize values in records array
    for (int i = 0; i < array_size && i < num_keys; ++i) {
        records_array[i].value = keys[offsets[i]];
        records_array[i].key = &long_keys[offsets[i]];
        records_array[i].offset = offsets[i];
    }

    *records = records_array;
    return 0;
}
