#include <string.h>

typedef struct File {
    char *path;
    size_t size;
    char *content;
} File;

int init_files(int max_count, FILE **input, File **files) {
    int count = 0;
    File *file_arr = NULL;

    // Allocate initial capacity for the array of files
    file_arr = malloc(max_count * sizeof(File));
    if (!file_arr) {
        perror("Error allocating memory for file array");
        return 1;
    }

    while ((*input++) && count < max_count) {
        // Dynamically allocate space for the path string and read it from input
        char *path = malloc(BUFSIZ + 1);
        if (!path) {
            perror("Error allocating memory for file path");
            return 2;
        }

        if (fgets(path, BUFSIZ + 1, stdin) == NULL || path[strcspn(path, "\n")] == '\0') {
            printf("Invalid file path\n");
            free(path);
            continue;
        }
        path[strcspn(path, "\n")] = '\0';

        // Trim whitespace from the beginning and end of the string
        char *start = path;
        while (isspace(*start)) start++;
        char *end = path + strlen(path);
        while (end > start && isspace(*(end - 1))) *(end--) = '\0';

        file_arr[count].path = strdup(start);
        if (!file_arr[count].path) {
            perror("Error allocating memory for file path");
            return 3;
        }

        // Calculate the size of the file and allocate memory for its content
        FILE *fp = fopen(file_arr[count].path, "rb");
        if (!fp) {
            perror("Error opening file");
            free(file_arr[count].path);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        size_t file_size = ftell(fp);
        if (file_size >= BUFSIZ) {
            fprintf(stderr, "File too large to be processed\n");
            fclose(fp);
            free(file_arr[count].path);
            continue;
        }
        rewind(fp);

        file_arr[count].content = malloc(file_size + 1);
        if (!file_arr[count].content) {
            perror("Error allocating memory for file content");
            fclose(fp);
            free(file_arr[count].path);
            continue;
        }

        if (fread(file_arr[count].content, 1, file_size, fp) != file_size) {
            perror("Error reading file");
            fclose(fp);
            free(file_arr[count].path);
            free(file_arr[count].content);
            continue;
        }

        fclose(fp);
        ++count;
    }

    *files = file_arr;
    return count == 0 ? -1 : 0;
}
