#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int *key;
    long offset;
} record;

int read_input(int *size) {
    printf("Enter the size of the list: ");
    scanf("%d", size);
    return 0;
}

int **allocate_keys(int size) {
    int i;
    int **keys = (int**)malloc(sizeof(int*) * size);
    for (i = 0; i < size; ++i) {
        keys[i] = malloc(sizeof(int));
    }
    return keys;
}

record* allocate_records(int size) {
    record *records = (record*)malloc(sizeof(record) * size);
    if (!records) {
        perror("Error allocating memory for records");
        exit(1);
    }
    return records;
}

void initialize(int *keys, int *values, int size) {
    int i;
    for (i = 0; i < size; ++i) {
        keys[i] = i;
        values[i] = rand();
    }
}

int sort(record* records, int size) {
    // Insertion Sort Algorithm
    record tmp;
    int i, j, key;
    for (i = 1; i < size; ++i) {
        tmp = records[i];
        key = tmp.value;
        for (j = i - 1; j >= 0 && records[j].value > key; --j) {
            records[j + 1] = records[j];
        }
        records[j + 1] = tmp;
    }
    return 0;
}

int search(record* records, int size, int value) {
    int i;
    for (i = 0; i < size; ++i) {
        if (records[i].value == value) {
            printf("Value found at index: %d\n", i);
            return 0;
        }
    }
    printf("Value not found.\n");
    return 1;
}

void print_records(record* records, int size) {
    int i;
    for (i = 0; i < size; ++i) {
        printf("Record %d: value=%d, key=%d, offset=%ld\n", i, records[i].value, *(records[i].key), records[i].offset);
    }
}

int main(int argc, char **argv) {
    int size;
    if (argc < 2) {
        printf("Usage: %s <list_size>\n", argv[0]);
        return 1;
    }
    read_input(&size);

    int *keys = NULL, *values = NULL;
    keys = allocate_keys(size);
    values = (int*)calloc(size, sizeof(int));
    if (!keys || !values) {
        perror("Error allocating memory");
        exit(1);
    }

    initialize(keys, values, size);

    record *records = allocate_records(size);
    int i;
    for (i = 0; i < size; ++i) {
        records[i].value = values[i];
        records[i].key = keys + i;
        records[i].offset = rand() % 10000;
    }

    sort(records, size);

    print_records(records, size);

    search(records, size, 42);

    free(keys);
    free(values);
    free(records);

    return 0;
}
