void init_data_record(dataRecord* rec, void *key, void *label) {
    rec->value = 0.0;
    rec->key = key;
    rec->label = label;
    rec->integer_field = 0;
}

int load_data(size_t *inputSize, size_t keySize, size_t labelSize, dataRecord **records) {
    double num;
    size_t i;

    if (!*inputSize || !keySize || !labelSize) return -1;

