[' Here is a C implementation that addresses the given programming task. I've used `getopt` for handling command line arguments, `malloc`, `calloc` and `realloc` for dynamic memory allocation, `qsort` for sorting, and `bsearch` for searching.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <getopt.h>

typedef struct Record {
    int key;
    char id[16];
    int value;
} Record;

int compare_records(const void *a, const void *b) {
    return ((Record *)a)->value - ((Record *)b)->value;
}

void generate_id(char *id, size_t idx) {
    snprintf(id, sizeof(id), "record_%zu", idx);
}

int read_integers(FILE *file, int **array, size_t *size) {
    if (fscanf(file, "%d\n", *(*array)) != 1) return -1;
    (*size)++;
    if ((*array = realloc(*array, sizeof(int) * (*size))) == NULL) return -1;
    return 0;
}

Record *create_record(int key, int value) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    generate_id(record->id, sizeof(Record) / sizeof(char));
    record->value = value;
    return record;
}

void insert_record(Record **records, size_t *size, int key, int value) {
    Record *record = create_record(key, value);
    if (!record) return;

    for (size_t i = 0; i < *size; ++i) {
        if ((*records)[i]->key == key) continue;
        memcpy(&(*records)[*size], record, sizeof(Record));
        (*size)++;
        break;
    }
}

void sort_records(Record **records, size_t size) {
    qsort((*records), size, sizeof(Record), compare_records);
}

int search_record(const Record *records, size_t size, int value) {
    return bsearch((void *)&value, records, size, sizeof(Record), compare_records);
}

int main(int argc, char **argv) {
    const int max_offset = 1024;
    const int max_key = 512;
    int offset_size = 0, key_size = 0, record_size = 0;
    int *offsets = NULL, *keys = NULL, *records = NULL;

    struct option long_opts[] = {{"config", required_argument, NULL, 'c'}, {0} };
    int opt;
    while ((opt = getopt_long(argc, argv, "c:", long_opts, NULL)) != -1) {
        switch (opt) {
            case 'c':
                sscanf(optarg, "%d %d", &offset_size, &key_size);
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                return -1;
        }
    }
    offsets = calloc(offset_size, sizeof(int));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offset array\n");
        free(offsets);
        return -1;
    }

    keys = calloc(key_size, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for key array\n");
        free(offsets);
        free(keys);
        return -1;
    }

    if (offset_size > max_offset || key_size > max_key) {
        fprintf(stderr, "Array sizes exceed maximum allowed values\n");
        free(offsets);
        free(keys);
        return -1;
    }

    record_size = (offset_size < key_size ? offset_size : key_size);
    records = malloc(record_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error allocating memory for record array\n");
        free(offsets);
        free(keys);
        return -1;
    }

    FILE *file = fopen("input.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening input file\n");
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    srand(time(NULL));
    int n = 0;
    while (read_integers(file, &offsets, &offset_size) == 0 && offset_size <= max_offset) {
        read_integers(file, &keys, &key_size) == 0 && key_size <= max_key ? n++ : break;
    }

    for (int i = 0; i < n; ++i) insert_record(records, &record_size, offsets[i], rand() % 2001 - 1000);

    sort_records(records, record_size);

    Record *result = bsearch((Record *)&value, records, record_size, sizeof(Record), compare_records);
    if (result) printf("Value found: %d\n", result->value);
    else printf("Value not found\n");

    free(offsets);
    free(keys);
    free(records);
    fclose(file);

    return 0;
}
```

