typedef struct {
    double value;
    int *key;
    char *label;
    long offset;
} dataRecord;

int initializeDataRecords(int num_doubles, int key_size, int label_size) {
    double *doubles = malloc(num_doubles * sizeof(double));
    if (!doubles) return 1;

    int *keys = malloc(key_size * sizeof(int));
    if (!keys) {
        free(doubles);
        return 2;
    }

    char *labels = malloc(label_size * sizeof(char));
    if (!labels) {
        free(doubles);
        free(keys);
        return 3;
    }

    dataRecord *dataRecords = malloc(num_doubles * sizeof(dataRecord));
    if (!dataRecords) {
        free(doubles);
        free(keys);
        free(labels);
        return 4;
    }

    for (int i = 0; i < num_doubles; ++i) {
        dataRecords[i].value = rand() / (double)(RAND_MAX / num_doubles);
        dataRecords[i].key = &keys[i];
        dataRecords[i].label = labels + i * label_size;
        dataRecords[i].offset = i;
    }

    printf("Data Records:\n");
    for (int i = 0; i < num_doubles; ++i) {
        printf("Index: %2d, Value: %.6f, Key: %d, Label: %c\n", i, dataRecords[i].value, *dataRecords[i].key, dataRecords[i].label[0]);
    }

    qsort(dataRecords, num_doubles, sizeof(dataRecord), (int (*)(const void *, const void *))compareDoubles);

    int searchValue = 3.14;
    int found = 0;
    for (int i = 0; i < num_doubles && !found; ++i) {
        if (dataRecords[i].value == searchValue) {
            found = 1;
            printf("Found %.6f at index %d\n", searchValue, i);
        }
    }

    free(keys);
    free(labels);
    free(dataRecords);
    free(doubles);

    return 0;
}

int compareDoubles(const void *a, const void *b) {
    return (*(const dataRecord *)a).value - (*(const dataRecord *)b).value;
}
