def data_point():
    return ("key", float(), int())

def read_input(n):
    nums = []
    for _ in range(n):
        nums.append(float(input()))
    return np.array(nums)

def generate_keys(n, max_len):
    return np.random.randint(0, max_len, size=n).tolist()

def allocate_data_points(nums, keys, size):
    data_points = ([data_point()] * size)
    for i, num in enumerate(nums):
        data_points[i] = (keys[i], num, int(timer() * 1e6))
    return np.array(data_points)

def deallocate(data_points):
    if data_points is not None:
        data_points.flags.writeable = False
        del data_points[0]

@patch('builtins.input', side_effect=read_input)
