#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>
#include <float.h>

#define MAX_SENSORS 1000
#define MAX_TEMPERATURE DBL_MAX
#define THRESHOLD 1000000

typedef struct {
    float temperature;
    char sensor_id;
} sensor_data;

int read_sensors(sensor_data** sensors, char** ids, int* size) {
    FILE *config = fopen("config.txt", "r");
    if (!config) return 1; // error opening config file

    int total_size, current_size = 0;
    fscanf(config, "%d", &total_size);

    *sensors = malloc(total_size * sizeof(sensor_data));
    if (!*sensors) {
        free(*sensors);
        return 2; // error allocating memory for sensor_data array
    }

    *ids = malloc(total_size * sizeof(char));
    if (!*ids) {
        free(*sensors);
        free(*ids);
        return 3; // error allocating memory for ID array
    }

    for (int i = 0; i < total_size; ++i) {
        fscanf(config, "%c", &((*ids)[current_size]));
        (*sensors + current_size)->sensor_id = (*ids)[current_size];

        // Generate random temperature within the specified range
        (*sensors + current_size)->temperature = (double)(rand() % ((int)(MAX_TEMPERATURE * 100))) / 100;

        if (sizeof(*sensors) * ++current_size > THRESHOLD) {
            sensor_data* new_sensors = realloc(*sensors, current_size * sizeof(sensor_data));
            if (!new_sensors) {
                free(*sensors);
                free(*ids);
                return 4; // error resizing memory for sensor_data array
            }
            *sensors = new_sensors;
        }
    }

    fclose(config);
    *size = current_size;
    return 0; // success
}
