#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    int *key;
    char *label;
    long offset;
} dataRecord;

int initializeDataRecords(size_t max_records, size_t key_array_size, size_t label_array_size, size_t *double_array_size, size_t *key_array, size_t *label_array, int *data_records) {
    double min_val, max_val;
    if (max_records == 0 || key_array_size < max_records || label_array_size < max_records) {
        return -1;
    }
    *double_array_size = max_records;
    double *double_arr = malloc(sizeof(double) * max_records);
    if (!double_arr) {
        return -2;
    }
    for (int i = 0; i < max_records; ++i) {
        double_arr[i] = (double)(rand() % RAND_MAX / 10.0); // Optimized random number generation
    }
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    for (int i = 0; i < max_records; ++i) {
        dataRecord *data_record = malloc(sizeof(dataRecord));
        if (!data_record) {
            free(double_arr);
            return -3;
        }
        data_record->value = double_arr[i];
        data_record->key = &key_array[i];
        data_record->label = &label_array[i];
        data_record->offset = (long)now.tv_sec * 1000 + (long)(now.tv_nsec / 1000000);
        data_records[i] = (int)data_record;
    }
    qsort(data_records, max_records, sizeof(int), compareFunc); // Sorting functionality
    return 0;
}

// Comparison function for qsort()
static int compareFunc(const void *a, const void *b) {
    dataRecord *recA = (dataRecord*)*a, *recB = (dataRecord*)*b;
    if (recA->value < recB->value) {
        return -1;
    }
    if (recA->value > recB->value) {
        return 1;
    }
    return 0;
}

// Search functionality
int findRecord(double value, int *data_records, size_t length) {
    int *left = data_records, *right = data_records + length - 1, *mid;
    while (left <= right) {
        mid = left + (right - left) / 2;
        if (*(dataRecord*)*mid < value) {
            left = mid + 1;
        } else if (*(dataRecord*)*mid > value) {
            right = mid - 1;
        } else {
            return *mid;
        }
    }
    return -1;
}

