#define RECORD_COUNT 10000
#define SEED 123456789

typedef struct Record {
    int value;
    int *key;
    long offset;
};

int read_input(int *arr, int size) {
    if (scanf("%d%*c", arr) != 1 || size <= 0)
        return -1;
    return 0;
}

void init_arrays(int keys[], long offsets[], int records[]) {
    for (int i = 0; i < MAX_KEYS; ++i)
        keys[i] = -1;
    for (int i = 0; i < RECORD_COUNT; ++i)
        records[i] = -1;
}

void init_records(struct Record *records, int key[], long offset[], int records[]) {
    for (int i = 0; i < RECORD_COUNT; ++i) {
        records[i].value = rand();
        records[i].key = &key[records[i].value];
        records[i].offset = offset[records[i].value];
    }
}

void print_records(struct Record *records, int size) {
    for (int i = 0; i < size && i < RECORD_COUNT; ++i) {
        printf("Record %d: value=%d key=%d offset=%ld\n", i, records[i].value, *(records[i].key), records[i].offset);
    }
}

void sort_records(struct Record *records, int size) {
    qsort(records, size, sizeof(struct Record), (int (*)(const void *, const void *))compareRecords);
}

int compareRecords(const void *a, const void *b) {
    return ((struct Record *)a)->value - ((struct Record *)b)->value;
}

int search_records(struct Record *records, int size, int value) {
    for (int i = 0; i < size && i < RECORD_COUNT; ++i) {
        if (records[i].value == value)
            return *(records[i].key);
    }
    return -1;
}

int main(int argc, char **argv) {
    srand(SEED);
    int input_size = atoi(argv[1]);
    int keys[MAX_KEYS], offsets[MAX_KEYS], records[RECORD_COUNT];
    init_arrays(keys, offsets, records);

    for (int i = 0; i < input_size && read_input(records + i, 1) == 0; ++i);
    if (input_size != i) {
        printf("Error: Invalid number of inputs\n");
        return -1;
    }

    init_arrays(offsets, offsets, records);

    long *current_offset = offsets;
    for (int i = 0; i < input_size && read_input(records + i, 1) == 0; ++i) {
        *current_offset++ = (long)*current_offset + records[i];
    }
    if (input_size != i) {
        printf("Error: Invalid number of inputs\n");
        return -1;
    }

    struct Record *records_arr = malloc(RECORD_COUNT * sizeof(struct Record));
    init_records(records_arr, keys, offsets, records);

    print_records(records_arr, RECORD_COUNT);
    sort_records(records_arr, RECORD_COUNT);
    printf("\nSorted Records:\n");
    print_records(records_arr, RECORD_COUNT);

    int target = atoi(argv[2]);
    if (search_records(records_arr, RECORD_COUNT, target) != -1)
        printf("Target value %d found with key %d\n", target, search_records(records_arr, RECORD_COUNT, target));
    else
        printf("Target value %d not found\n", target);

    free(records_arr);
    return 0;
}
