int init_arrays(const int keys_count, const int integers_count, int *keys, int *integers) {
    if(!(keys && integers)) return 1; // Check for null pointers

    // Allocate memory for long and int arrays
    long *offsets = (long *) malloc(sizeof(long) * keys_count);
    if (!offsets) return 2; // Check for allocation failure

    int *keys_array = (int *) malloc(sizeof(int) * keys_count);
    if (!keys_array) { free(offsets); return 3; } // Check for allocation failure

    // Copy input integers into the new array and initialize offsets
    for (int i = 0; i < keys_count && i < integers_count; ++i) {
        if (i < integers_count) keys_array[i] = integers[i];
        offsets[i] = i;
    }

    // Shuffle the array to improve randomness and return pointers to arrays
    srand(time(NULL));
    for (int i = keys_count - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        if (j != i) {
            int temp = keys_array[i];
            keys_array[i] = keys_array[j];
            keys_array[j] = temp;

            long temp_long = offsets[i];
            offsets[i] = offsets[j];
            offsets[j] = temp_long;
        }
    }

    return 0; // Success
}

int create_record_arrays(const int records_count, const int keys_count, Record **records) {
    if(!records || !(keys_array && integers_array)) return 1; // Check for null pointers

    *records = (Record *) malloc(sizeof(Record) * records_count);
    if (!*records) return 2; // Check for allocation failure

    for (int i = 0; i < records_count; ++i) {
        (*records)[i].value = keys_array[rand() % keys_count];
        (*records)[i].key = &keys_array[(*records)[i].value];
        (*records)[i].offset = offsets[(*records)[i].value];
    }

    return 0; // Success
}

int free_record_arrays(Record *records, const int records_count) {
    if (!records || records_count <= 0) return 1; // Check for null pointers or invalid size

    free(records);
    return 0; // Success
}

void print_record_array(const int records_count, const Record *records) {
    if (!records || records_count <= 0) return; // Check for null pointers or invalid size

    printf("Printing record array:\n");
    for (int i = 0; i < records_count; ++i) {
        printf("Record %d: value %d, key %d, offset %ld\n", i, records[i].value, *(records[i].key), records[i].offset);
