int read_and_init(int key_count, int record_count, int *keys, struct Record **records) {
    if (key_count <= 0 || record_count <= 0) return 1;

    int *key_array = malloc(sizeof(int) * key_count);
    if (!key_array) return 2;
    memcpy(key_array, keys, sizeof(int) * key_count);

    long offset_max = (long)(1 << (sizeof(long) * 8 - 1));
    long *offsets = malloc(sizeof(long) * record_count);
    if (!offsets) {
        free(key_array);
        return 3;
    }

    struct Record *records_array = malloc(sizeof(struct Record) * record_count);
    if (!records_array) {
        free(key_array);
        free(offsets);
        return 4;
    }

    for (int i = 0; i < record_count; ++i) {
        records_array[i].value = rand();
        records_array[i].key = &key_array[(rand() % key_count)];
        records_array[i].offset = offsets[i] = (rand() % offset_max);
    }

    *records = records_array;
    return 0;
}

void print_records(struct Record *records, int record_count) {
    for (int i = 0; i < record_count; ++i) {
        printf("Record %d: value=%d, key=%p, offset=%ld\n", i, records[i].value, records[i].key, records[i].offset);
    }
}

