    int key_count = atoi(argv[1]);
    int record_count = atoi(argv[2]);
    int *keys = malloc(sizeof(int) * key_count);

    for (int i = 0; i < key_count; ++i) keys[i] = atoi(argv[3 + i]);

    struct Record *records;
    int err = read_and_init(key_count, record_count, keys, &records);

    if (err > 0) {
        fprintf(stderr, "Error: %d\n", err);
        return err;
    }

    print_records(records, record_count);
    free(keys);
    free(records);
    return 0;
}
