typedef struct Node {
    char *str;
    int value;
    struct ChildNode **children;
    size_t num_children;
} Node;

typedef struct ChildNode {
    char *str;
    int value;
    struct ChildNode *next;
} ChildNode;

void init_nodes(size_t size, const char *filename, size_t max_child_count, size_t min_value, size_t max_value) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    cJSON *root = cJSON_Parse_File(filename);
    if (!root || !cJSON_IsObject(root)) {
        printf("Invalid JSON format\n");
        goto cleanup;
    }

    Node *nodes = malloc(size * sizeof(Node));
    if (!nodes) {
        perror("Error allocating memory for nodes array");
        goto cleanup;
    }

    cJSON_Array *children_array = cJSON_GetObjectItem(root, "children");
    if (children_array && children_array->count > max_child_count) {
        printf("Error: Too many child nodes\n");
        goto cleanup;
    }

    for (size_t i = 0; i < size; ++i) {
        Node *node = &nodes[i];
        node->str = strdup(cJSON_GetObjectItem(root, csecp_format("node_%d", i))->valuestring);
        if (!node->str) {
            perror("Error allocating memory for string");
            goto cleanup;
        }

        node->value = (rand() % (max_value - min_value + 1)) + min_value;

        ChildNode **child_head = &node->children;
        cJSON *children_list = cJSON_GetObjectItem(root, csecp_format("children_%d", i));
        if (children_list) {
            cJSON_Array *array = children_list->child;
            node->num_children = array ? array->count : 0;
            for (size_t j = 0; j < node->num_children; ++j) {
                ChildNode *child = malloc(sizeof(ChildNode));
                if (!child) {
                    perror("Error allocating memory for child");
                    goto cleanup;
                }
                child->str = strdup(cJSON_GetArrayItem(array, j)->valuestring);
                if (!child->str) {
                    perror("Error allocating memory for child string");
                    free(child);
                    goto cleanup;
                }
                child->value = (rand() % (max_value - min_value + 1)) + min_value;
                child->next = *child_head;
                *child_head = child;
                child_head = &child->next;
            }
        }
    }

cleanup:
    cJSON_Delete(root);
    fclose(file);
}
