// Function to initialize and allocate memory for offsets, keys, and records
// Returns an appropriate error code on failure
enum ResultCode init_arrays(size_t num_offsets, size_t num_keys, size_t num_records, int min_value, int max_value, long* offsets, int* keys, Record** records) {
    *offsets = (long*) my_malloc((num_offsets + 1) * sizeof(long));
