long read_csv(FILE *file, long *offsets, size_t *capacity, size_t *length) {
    char delimiter = ',';
    char c;
    long index = 0;
    while ((c = fgetc(file)) != EOF) {
        if (index++ == 0 || c == delimiter)
            ++(*capacity);
        if (index >= *length) {
            *length += 1024;
            offsets = realloc(offsets, sizeof(long)*(*length));
        }
        if (c == delimiter)
            offsets[index-1] = ftell(file);
    }
    return index - 1;
}

bool is_valid_record(const char *line, double *key, char **data) {
    // Parse key and data from the line.
    // Implement the validation logic based on your desired criteria.
    // For simplicity, I assume the format: "key,data" where both are separated by a comma.

    size_t capacity = 1024;
    char *key_str = malloc(capacity*sizeof(char));
    char *data_str = malloc(capacity*sizeof(char));

    bool in_key = true;
    int key_index = 0, data_index = 0;
    for (size_t i = 0; line[i]; ++i) {
        if (in_key && isdigit(line[i]))
            continue;

        if (!in_key && isdigit(line[i])) {
            in_key = true;
            key_index = 0;
        }

        if (in_key)
            key_str[key_index++] = line[i];

        if (!in_key && line[i] == ',') {
            in_key = false;
            data_str[data_index++] = line[i];
        }

        if (key_index >= capacity) {
            capacity *= 2;
            key_str = realloc(key_str, capacity*sizeof(char));
        }

        if (data_index >= capacity) {
            capacity *= 2;
            data_str = realloc(data_str, capacity*sizeof(char));
        }
    }

    *key = atof(key_str);
    *data = malloc((data_index + 1)*sizeof(char));
    strncpy(*data, data_str, data_index);
    (*data)[data_index] = '\0';

    // Perform validation here, for example:
    // if (key < 0 || key > DBL_MAX) return false;
    // if (strlen(*data) > MAX_STRING_LENGTH) return false;
    // ...

    free(key_str);
    free(data_str);

    return true;
}

void process_file(const char *filename, size_t *n_offsets, size_t *capacity_offsets,
                   size_t *length_offsets, size_t *n_records, size_t *capacity_records,
                   size_t *length_records) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s.\n", filename);
        exit(EXIT_FAILURE);
    }

    long offsets[0];
    size_t capacity_offsets_init = 1;
    size_t length_offsets_init = 0;
    long n_offsets_init = 0;

    data_record *records = NULL;
    size_t capacity_records_init = 0;
    size_t length_records_init = 0;
    size_t n_records_init = 0;

    fseek(file, 0, SEEK_END);
    long num_lines = ftell(file) / sizeof(char);
    rewind(file);

    if (num_lines < 2) {
        fprintf(stderr, "Not enough data in file.\n");
        exit(EXIT_FAILURE);
    }

    n_offsets[0] = read_csv(file, &offsets[n_offsets_init], &capacity_offsets_init, &length_offsets_init);

    char line[num_lines];
    size_t current_line = 0;
    while (fgets(line + current_line, sizeof(line) - current_line, file)) {
        if (!is_valid_record(line + current_line, &records[n_records_init].key, &records[n_records_init].data)) {
            fprintf(stderr, "Invalid record format.\n");
            exit(EXIT_FAILURE);
        }
        ++current_line;
        if (current_line >= num_lines) break;

        if (++n_records_init == capacity_records_init) {
            capacity_records_init *= 2;
            records = realloc(records, sizeof(data_record)*capacity_records_init);
        }
    }

    *n_offsets = n_offsets_init + n_offsets[n_offsets_init];
    *n_records = n_records_init;

    size_t capacity = (*n_offsets < *n_records) ? *n_records : *n_offsets;
    size_t *new_capacity_offsets = malloc(sizeof(size_t)*capacity);
    size_t *new_length_offsets = malloc(sizeof(size_t)*capacity);
    data_record *new_records = malloc(sizeof(data_record)*capacity);

    memcpy(new_capacity_offsets, capacity_offsets, sizeof(size_t)*n_offsets_init);
    memcpy(new_length_offsets, length_offsets, sizeof(size_t)*n_offsets_init);
    memcpy(new_records, records, sizeof(data_record)*n_records_init);

    free(capacity_offsets);
    free(length_offsets);
    free(records);

    capacity_offsets = new_capacity_offsets;
    length_offsets = new_length_offsets;
    records = new_records;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    size_t n_offsets = 0;
    size_t capacity_offsets = 1;
    size_t length_offsets = 0;
    size_t n_records = 0;
    size_t capacity_records = 0;
    size_t length_records = 0;

    process_file(argv[1], &n_offsets, &capacity_offsets, &length_offsets, &n_records, &capacity_records, &length_records);

    printf("Number of offsets: %zu\n", n_offsets);
    printf("Capacity for offsets: %zu\n", capacity_offsets);
    printf("Length for offsets: %zu\n", length_offsets);
    printf("Number of records: %zu\n", n_records);
    printf("Capacity for records: %zu\n", capacity_records);
    printf("Length for records: %zu\n", length_records);

    return EXIT_SUCCESS;
}
