int init_arrays(size_t *offsets, size_t *keys, size_t *num_records, size_t record_size, int min, int max, int seed) {
    if (num_records == NULL || record_size <= 0 || min > max)
        return -1; // Invalid arguments

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    pthread_mutex_lock(&mutex);
    time_t now = time(NULL);
    srand((unsigned int)now + seed);

    size_t offsets_size = *num_records;
    size_t keys_size = *num_records;
    size_t records_size = *num_records * record_size;

    // Allocate and initialize offset array with random values
    offsets = realloc(offsets, offsets_size * sizeof(size_t));
    if (!offsets) {
        pthread_mutex_unlock(&mutex);
        return -2; // Failed to allocate memory for offsets
    }
    for (size_t i = 0; i < offsets_size; ++i)
        offsets[i] = rand() % (max + 1 - min) + min;

    // Allocate and initialize key array with unique integer values
    keys = realloc(keys, keys_size * sizeof(size_t));
    if (!keys) {
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return -2; // Failed to allocate memory for keys
    }
    size_t used_keys[max + 1];
    memset(used_keys, 0, sizeof(used_keys));
    for (size_t i = 0; i < keys_size; ++i) {
        int key;
        do {
            key = rand() % (max + 1 - min) + min;
        } while (used_keys[key]);
        used_keys[key] = 1;
        keys[i] = key;
    }

    // Allocate and initialize record array with random values and strings
    Record *records = malloc(records_size);
    if (!records) {
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return -2; // Failed to allocate memory for records
    }
    char **strings = calloc(records_size, sizeof(char *));
    if (!strings) {
        free(records);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return -2; // Failed to allocate memory for strings
    }

    for (size_t i = 0; i < records_size; ++i) {
        records[i].value = rand() % (max + 1 - min) + min;
        char str[256];
        snprintf(str, sizeof(str), "%.*s", rand() % 20 + 10, alphabet_string());
        strings[i] = strdup(str);
        if (!strings[i]) {
            for (size_t j = 0; j < i; ++j)
                free(strings[j]); // Free already allocated strings up to this point
            free(records);
            free(offsets);
            free(keys);
            pthread_mutex_unlock(&mutex);
            return -2; // Failed to allocate memory for a string
        }
        records[i].str = strings[i];
    }

    pthread_mutex_unlock(&mutex);

    // Validate the integrity of the allocated memory
    for (size_t i = 0; i < offsets_size; ++i) {
        if (!offsets[i]) {
            free(offsets);
            free(keys);
            free(records);
            free(strings);
            return -2; // Found a null pointer in the offset array
        }
    }

    for (size_t i = 0; i < records_size; ++i) {
        if (!records[i].str || !strings[i]) {
            for (size_t j = 0; j < i; ++j)
                free(strings[j]); // Free already allocated strings up to this point
            free(offsets);
            free(keys);
            free(records);
            free(strings);
            return -2; // Found a null pointer in the record or string arrays
        }
    }

    *offsets = offsets;
    *keys = keys;
    *num_records = records;

    return 0; // Success
}

// Helper function to generate an alphanumeric string of a given length
char* alphabet_string() {
    static const char alnum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    static thread_local Random rnd; // Use a per-thread random number generator

    char *str = malloc(256);
    for (size_t i = 0; i < 256; ++i) str[i] = '\0';

    size_t len = rand() % 20 + 10; // Generate a random length between 10 and 20 characters

    for (size_t i = 0; i < len; ++i) {
        int pos = rand() % strlen(alnum);
        str[i] = alnum[pos];
    }

    return str;
}
```
This function initializes three arrays: one for offsets, one for keys, and one for records. It uses a per-thread random number generator to ensure thread safety and provides a helper function `alphabet_string()` that generates an alphanumeric string of a given length. The function also validates the integrity of the allocated memory before returning the arrays.']

