#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int value;
};

struct HashTable {
    unsigned long capacity;
    unsigned long size;
    unsigned long *keys;
    struct Record **records;
    pthread_mutex_t mutex;
};

void init_hash_table(struct HashTable *ht, unsigned long capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->keys = calloc(capacity, sizeof(unsigned long));
    ht->records = calloc(capacity, sizeof(struct Record*));
    if (!ht->keys || !ht->records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&ht->mutex, NULL);
}

unsigned long hash(unsigned long key, unsigned long capacity) {
    return key % capacity;
}

void rehash(struct HashTable *ht) {
    struct HashTable new_ht;
    init_hash_table(&new_ht, 2 * ht->capacity);

    pthread_mutex_lock(&ht->mutex);
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        if (ht->keys[i] != 0) {
            unsigned long new_index = hash(ht->keys[i], new_ht.capacity);
            while (new_ht.keys[new_index] != 0) {
                ++new_index %= new_ht.capacity;
            }
            new_ht.keys[new_index] = ht->keys[i];
            new_ht.records[new_index] = malloc(sizeof(struct Record));
            if (!new_ht.records[new_index]) {
                perror("Memory allocation failed");
                exit(EXIT_FAILURE);
            }
            *new_ht.records[new_index] = *ht->records[i];
        }
    }
    pthread_mutex_unlock(&ht->mutex);

    free(ht->keys);
    free(ht->records);
    ht->keys = new_ht.keys;
    ht->records = new_ht.records;
}

bool put(struct HashTable *ht, unsigned long key, struct Record record) {
    unsigned long index = hash(key, ht->capacity);

    pthread_mutex_lock(&ht->mutex);
    while (ht->keys[index] != 0 && ht->keys[index] == key) {
        ++index %= ht->capacity;
    }
    if (index == ht->keys[index]) {
        ht->records[index] = malloc(sizeof(struct Record));
        if (!ht->records[index]) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&ht->mutex);
            return false;
        }
        *ht->records[index] = record;
        ht->keys[index] = key;
        ++(ht->size);
        if ((double)ht->size / ht->capacity > 0.75) {
            rehash(ht);
        }
        pthread_mutex_unlock(&ht->mutex);
        return true;
    }
    pthread_mutex_unlock(&ht->mutex);
    return false;
}

struct Record *get(struct HashTable *ht, unsigned long key) {
    unsigned long index = hash(key, ht->capacity);

    struct Record *record = NULL;
    pthread_mutex_lock(&ht->mutex);
    while (ht->keys[index] != 0 && ht->keys[index] != key) {
        ++index %= ht->capacity;
    }
    if (ht->keys[index] == key) {
        record = ht->records[index];
    }
    pthread_mutex_unlock(&ht->mutex);
    return record;
}

void free_hash_table(struct HashTable *ht) {
    pthread_mutex_destroy(&ht->mutex);
    free(ht->keys);
    free(ht->records);
}

void generate_and_insert(unsigned long offsets[], int keys[], struct Record **records, unsigned long size, unsigned long range) {
    srand(time(NULL));
    for (unsigned long i = 0; i < size; ++i) {
        records[offsets[i]]->value = rand() % range + 1;
        put(ht, keys[i], *records[offsets[i]]);
    }
}
```

