typedef struct {
    int value;
    int *key;
    struct record *next;
} record;

typedef struct {
    unsigned long *offsets;
    int *keys;
    record **records;
    int size;
    pthread_mutex_t mutex;
} database;

database *init_db(int offset_size, int key_size, int record_size) {
    database *db = malloc(sizeof(database));
    if (!db) {
        perror("Failed to allocate memory for database");
        exit(1);
    }

    db->offsets = calloc(offset_size, sizeof(unsigned long));
    if (!db->offsets) {
        perror("Failed to allocate memory for offset array");
        free(db);
        exit(1);
    }

    db->keys = malloc(key_size * sizeof(int));
    if (!db->keys) {
        perror("Failed to allocate memory for key array");
        free(db->offsets);
        free(db);
        exit(1);
    }

    db->records = malloc(record_size * sizeof(record*));
    if (!db->records) {
        perror("Failed to allocate memory for record pointers array");
        free(db->offsets);
        free(db->keys);
        free(db);
        exit(1);
    }

    db->size = 0;
    pthread_mutex_init(&db->mutex, NULL);

    return db;
}

record *create_record() {
    record *new_record = malloc(sizeof(record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        exit(1);
    }

    new_record->next = NULL;
    return new_record;
}

void insert_record(database *db, int key, int value) {
    pthread_mutex_lock(&db->mutex);

    record **current = &db->records[0];
    for (int i = 0; i < db->size; ++i, current = &((*current)->next)) {
        if ((*current)->key == key) {
            (*current)->value = value;
            pthread_mutex_unlock(&db->mutex);
            return;
        }
    }

    record *new_record = create_record();
    new_record->key = &db->keys[key];
    new_record->value = value;

    pthread_mutex_lock(&current->mutex); // Assuming each record has its own mutex.
    new_record->next = *current;
    *current = new_record;
    pthread_mutex_unlock(&current->mutex);

    if (++db->size > db->offsets[db->size - 1]) {
        db->offsets[db->size - 1]++;
    }

    pthread_mutex_unlock(&db->mutex);
}

int *read_integers(int *num_inputs) {
    int *inputs = malloc(*num_inputs * sizeof(int));
    if (!inputs) {
        perror("Failed to allocate memory for input array");
        exit(1);
    }

    for (int i = 0; i < *num_inputs; ++i) {
        scanf("%d", &inputs[i]);
    }

    return inputs;
}

void generate_records(database *db, int num_inputs) {
    int *inputs = read_integers(&num_inputs);

    for (int i = 0; i < num_inputs; ++i) {
        if (!insert_record(db, inputs[i], rand() % 100)) { // Generating random numbers within range [0, 99].
            perror("Failed to insert record");
            free(inputs);
            exit(1);
        }
    }

    free(inputs);
}

void print_records(database *db) {
    for (int i = 0; i < db->size; ++i) {
        printf("Record %d: key=%d, value=%d\n", i, *(db->keys + (*(db->offsets + i))), *(db->records[*(db->offsets + i)]->value));
    }
}
