        fprintf(stderr, "Error: Memory allocation failed\n");
        free(offsets);
        free(keys);
        return -1;
    }

    size_t data_index = 0;
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
        records[i].key = &keys[*input++];

        if (data_index < buffered_data_size) {
            size_t data_chunk_len = strlen(buffered_data[data_index]);
            if (data_chunk_len > buffer_size) {
                fprintf(stderr, "Error: Buffer overflow during data copying\n");
                free(offsets);
                free(keys);
                free(records);
                return -1;
            }
            records[i].buffer = malloc(data_chunk_len);

            if (!records[i].buffer) {
                fprintf(stderr, "Error: Memory allocation failed\n");
                free(offsets);
                free(keys);
                for (size_t j = 0; j < i; ++j)
                    free(records[j].buffer);
                free(records);
                return -1;
            }

            memcpy(records[i].buffer, buffered_data[data_index++], data_chunk_len);
        } else {
            records[i].buffer = NULL;
        }

        offsets[i] = rand() % input_size;
    }

    for (size_t i = 0; i < input_size; ++i) {
        size_t j = *input++;
        if (j >= num_records) break;
        records[j].key = &offsets[i];
    }

    return 0;
}

