typedef struct {
    int value;
    int *key_ptr;
    long offset;
} record;

int read_and_init(int *input, int num_inputs, int *keys, int *offsets, int *num_records) {
    record *records = NULL;
    int i;

    if((records = malloc(sizeof(record)*num_records)) == NULL) {
        printf("Error: Memory allocation for records failed.\n");
        return 1;
    }

    srand(time(NULL));
    for(i = 0; i < *num_records; ++i) {
        records[i].value = input[rand() % num_inputs];
        if((records[i].key_ptr = bsearch(&(records[i].value), keys, *num_inputs, sizeof(int), &compare)) == NULL) {
            printf("Error: Key not found during insertion.\n");
            free(records);
            return 1;
        }
        records[i].offset = (long)(rand() % INT_MAX);
    }

    qsort(records, *num_records, sizeof(record), compare_value);

    // Print the contents of the records array for debugging purposes
    printf("Containing records:\n");
    for(i = 0; i < *num_records; ++i) {
        printf("[%d] %d -> %ld\n", *(keys + records[i].key_ptr), records[i].value, records[i].offset);
    }

    *num_records = num_inputs;
    return 0;
}

int compare(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int compare_value(const void *a, const void *b) {
    record *ra = (record *)a, *rb = (record *)b;
    return ra->value - rb->value;
}

// Function to search for a specific integer value within the records array.
int search_value(record *records, int num_records, int target) {
    int left = 0, right = num_records - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (records[mid].value > target)
            right = mid - 1;
        else if (records[mid].value < target)
            left = mid + 1;
        else
            return mid; // Found the value
    }
    return -1; // Value not found
}
