int init_files(int max_entries, int keys_per_entry, int *keys, long *offsets, char **file_paths, file_entry **file_entries) {
    if (max_entries <= 0 || keys_per_entry <= 0) {
        return -1; // Error: Invalid input parameters
    }

    *file_entries = malloc(sizeof(file_entry) * max_entries);
    if (*file_entries == NULL) {
        return -2; // Allocation error for file_entries array
    }

    for (int i = 0; i < max_entries; ++i) {
        char *path = strdup(file_paths[i]);
        if (path == NULL) {
            free(*file_entries); // Clean up in case of allocation error
            return -2; // Allocation error for file path string
        }

        (*file_entries)[i].path = path;
        (*file_entries)[i].key = &keys[i * keys_per_entry];
        if ((*file_entries)[i].key == NULL) {
            free(*file_entries); // Clean up in case of allocation error
            for (int j = 0; j < i; ++j) {
                free((*file_entries)[j].path);
            }
            return -2; // Allocation error for keys array pointer
        }

        (*file_entries)[i].offset = offsets[i];
    }

    srand(time(NULL)); // Seed random number generator

    return 0; // Successful initialization
}

