#include <string.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int value;
} Record;

void read_ints_from_file(const char *filename, int *array, size_t *size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        *size = 0;
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t n = ftell(file) / sizeof(int);
    rewind(file);

    if (n > *size) {
        *size = n;
        int *tmp = realloc(*array, n * sizeof(int));
        if (!tmp) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            fclose(file);
            *size = 0;
            return;
        }
        *array = tmp;
    }

    size_t read = fread(*array, sizeof(int), n, file);
    if (read != n) {
        fprintf(stderr, "Error: Unable to read %d integers from the file\n", n);
        free(*array);
        *size = 0;
        return;
    }

    fclose(file);
}

Record* initialize_records(int *keys, long *offsets, int size) {
    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].value = 0;
    }

    return records;
}

void set_random_values(Record *records, int size, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

void print_records(const Record *records, int size) {
    printf("Records:\n");
    for (size_t i = 0; i < size; ++i) {
        printf("{ key: %d, offset: %ld, value: %d }\n", records[i].key, records[i].offset, records[i].value);
    }
}

void sort_records(Record *records, int size) {
    qsort(records, size, sizeof(Record), compare_records);
}

int search_for_value(const Record *records, int value, int size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].value == value) {
            return records[i].key;
        }
    }
    return -1;
}

int compare_records(const void *a, const void *b) {
    Record *aa = (Record*) a;
    Record *bb = (Record*) b;
    return aa->value - bb->value;
}

// ... Other function definitions as needed for the given requirements
