}

int compare_datapoints(const void *a, const void *b) {
    return ((data_point*)a)->value - ((data_point*)b)->value;
}

void find_value(int num, data_point* data, float value) {
    int left = 0, right = num - 1, mid;

    while(left <= right) {
        mid = (left + right) / 2;

        if((data[mid]->value == value)) {
            printf("Value found at index %d\n", mid);
            return;
        }

        else if(data[mid]->value < value)
            left = mid + 1;

        else
            right = mid - 1;
    }

    printf("Value not found in the array.\n");
}

// Function to generate random number within a given range (0-1) using xorshift128+ algorithm.
unsigned long xorshift128plus(unsigned long *xsubi) {
    unsigned long xorShifted;

    xorShifted = (*xsubi) + 0x9e3779b97f4a7c15;
    xorShifted = (xorShifted ^ (xorShifted >> 30)) * 0xbf692b18;
    xorShifted = (xorShifted ^ (xorShifted >> 23)) * 0xc4aabb1c;
    xorShifted = (xorShifted ^ (xorShifted >> 18));
    (*xsubi) = xorShifted;

    return xorShifted;
}

// Main function to initialize and manipulate the data points array.
