    int num, i;
    float* numbers;
    read_input(&num, &numbers);

    if(!numbers) {
        printf("Error: Unable to allocate memory for input list.\n");
        return 1;
    }

    int keys_size = num;
    const float* keys;
    double* offsets;
    init_offsets_keys(num, numbers, &keys_size, &keys, &offsets);

    data_point* data;
    init_data_points(num, numbers, keys_size, keys, offsets, &data);

    print_data(num, data);
    sort_data(num, data);
    print_data(num, data);

    float valueToFind = 0.5;
    find_value(num, data, valueToFind);

    free(keys);
    free(offsets);
    free(numbers);
    free(data);

    return 0;
}
