#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

void init_arrays(size_t *keys, size_t *offsets, record **records, size_t capacity) {
    size_t i;
    long seed = time(NULL);
    void *mem = mmap(NULL, capacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    *records = mem;

    *keys = malloc(capacity * sizeof(size_t));
    if (!*keys) {
        perror("malloc for keys failed");
        munmap(mem, capacity * sizeof(record));
        exit(EXIT_FAILURE);
    }

    *offsets = malloc(sizeof(long) * (capacity + 1));
    if (!*offsets) {
        perror("malloc for offsets failed");
        free(*keys);
        munmap(mem, capacity * sizeof(record));
        exit(EXIT_FAILURE);
    }

    (*offsets)[0] = 0;
    for (i = 1; i <= capacity; ++i) {
        (*offsets)[i] = (*offsets)[i - 1] + 1;
    }

    for (i = 0; i < capacity; ++i) {
        (*keys)[(*offsets)[i]] = i;
        (*records + i)->value = rand_r(&seed) % 1e7; // Within range [0, 10000000]
    }
}

void free_arrays(size_t *keys, size_t *offsets, record **records) {
    if (keys) free(keys);
    if (offsets) free(offsets);
    if (records) munmap(*records, sizeof(**records) * *keys);
}
```

This code provides a function `init_arrays()` that takes in pointers to the arrays and dynamically allocates memory for them. It uses an anonymous mapping (`mmap`) to allocate large blocks of contiguous memory, which can improve cache locality when accessing records later. The random number generator is implemented using `rand_r()`, seeded with the current time using `time(NULL)`.

The function handles memory allocation failures by calling `perror` and exiting the program if it encounters an error. It also ensures that all allocated resources are freed appropriately using `free()` for the key and offset arrays, and `munmap()` for the record array. The trade-offs discussed in the requirements section have been addressed as follows:

* Decide on whether to use statically allocated buffers or dynamically allocated strings for identifiers: dynamic allocation is used here.
* Determine an appropriate buffer size for identifiers to avoid frequent reallocations while ensuring sufficient capacity: a single, large block of memory (up to 10 million records) is allocated using `mmap()`.
* Evaluate trade-offs between using `malloc` for all allocations versus preallocating large blocks of memory: a single, large block of memory is preallocated using `mmap()`.
* Optimize the random number generation process to ensure uniform distribution without significantly impacting performance: the range is kept within [0, 1e7], which should provide good coverage and avoid overflow issues.
* Consider how different buffer sizes might affect cache locality and overall system performance: using a single large block of memory improves cache locality by keeping data contiguous in physical memory.']

