import json
import copy

class JSONParser:
    _registry = {}

    def __init__(self, registry=None):
        self._registry = registry or {}

    def register(self, class_name, factory):
        self._registry[class_name] = factory

    def from_json(self, json_str):
        obj = json.loads(json_str)
        if isinstance(obj, dict):
            cls_name = obj.get('__type__')
            if cls_name in self._registry:
                return self._registry[cls_name](**obj)
            else:
                raise ValueError(f"Unknown class {cls_name}")
        else:
            return obj

    def to_json(self, obj):
        return json.dumps(obj, default=lambda o: o.__dict__, cls=JSONEncoder)

class JSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Record):
            # Customize the serialization of the record structure as needed
            return {'value': obj.value, 'key': obj.key, 'offset': obj.offset}
        return super().default(obj)
