    if (!keys || !offsets) return -1;

    int i;
    for (i = 0; i < n; ++i) {
        keys[i] = i;
        offsets[i] = rand(); // Optimized random number generation
    }
    return 0;
}

int init_records(size_t num, size_t len, record **records) {
    if (!num || !len || !records) return -1;

    *records = calloc(num, sizeof(**records));
    if (*records == NULL) return -2;

    size_t n = len + 1;
    int i, j;
    if (init_arrays(n, (*records)->key = malloc(sizeof(int) * num)) < 0) {
        free(*records);
        return -3;
    }
    if (init_arrays(len, (*records)->offset = calloc(sizeof(long), num)) < 0) {
        free((*records)->key);
        free(*records);
        return -4;
    }

    for (i = 0; i < num; ++i)
        for (j = 0; j < len && (*records)[i].val != INT_MAX; ++j) {
            if ((*records)[j].val == i + 1) {
                (*records)[i].val = i + 1;
                break;
            }
        }
    return 0;
}

void print_records(size_t num, record *records) {
    for (size_t i = 0; i < num; ++i)
        printf("(%d %p %ld)\n", records[i].val, records[i].key, records[i].offset);
}

void sort_records(size_t num, record *records) {
    qsort(records, num, sizeof(*records), (int (*)(const void *, const void *))compare);
}

int compare(const void *a, const void *b) {
    return ((record *)a)->val - ((record *)b)->val;
}

int search_value(size_t num, record *records, int value) {
    size_t left = 0, right = num - 1;
    while (left <= right) {
        size_t mid = (left + right) / 2;
        if ((records[mid]).val == value) return 1;
        else if ((records[mid]).val < value) left = mid + 1;
        else right = mid - 1;
    }
    return 0;
}
