int initialize_records(long max_offset_count, int min_value, int max_value) {
    // Check if the input parameters are valid
    if (max_offset_count <= 0 || max_value < min_value) {
        perror("Invalid input parameters");
        return -1;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Allocate memory for offsets and keys arrays
    offsets = (long*) malloc(max_offset_count * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        goto cleanup;
    }

    keys = (int*) malloc((max_offset_count + 1) * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        goto cleanup;
    }

    // Initialize offsets and keys arrays
    long current_offset = 0;
    int key_index = 0;
    for (long i = 0; i < max_offset_count; ++i) {
        offsets[i] = current_offset++;
        keys[key_index++] = i;
    }
    keys[key_index] = -1; // Set the last key index as sentinel value

    // Allocate memory for records array
    records = (record*) malloc(key_index * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Initialize records values and offset pointers using random integers
    srand(time(NULL));
    for (int i = 0; i < key_index; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = offsets + keys[i];
    }

    // Successful allocation, return 0
    return 0;

cleanup:
    if (records) free(records);
    if (keys) free(keys);
    if (offsets) free(offsets);
    return -1;
}
