   unsigned int hash(const void *data, size_t len) {
       unsigned int hash = 0;
       const unsigned char *str = (const unsigned char *) data;
       for (size_t i = 0; i < len; ++i) {
           hash = (hash << 5) + hash + str[i] + (hash >> 2);
       }
       return hash % size;
   }

   void init_records(int size, int *keys, long *offsets, Record **records, int min, int max) {
       if (!size || !keys || !offsets || !records) {
           // Handle invalid input
           return;
       }

       srand((unsigned int) time(NULL));
       *records = malloc(size * sizeof(Record));
       if (*records == NULL) {
           // Handle allocation failure
           return;
       }

       long *record_offsets = calloc(size, sizeof(long));
       if (record_offsets == NULL) {
           // Handle allocation failure
           free(*records);
           *records = NULL;
           return;
       }

       int hash_table[size]; // Initialize hash table to 0

       for (int i = 0; i < size; ++i) {
           int key_index = hash((const void *) &keys[i], sizeof(keys[i]));
           while (hash_table[key_index] != 0) {
               key_index = (key_index + 1) % size;
           }
           keys[i] = key_index;
           hash_table[key_index] = 1;
       }

       for (int i = 0; i < size; ++i) {
           int key_index = keys[i];
           long offset_index = record_offsets[i] = offsets[key_index];

           (*records)[i].value = rand() % (max - min + 1) + min;
           (*records)[i].key = &keys[i];
           (*records)[i].offset = &record_offsets[i];
       }

       free(record_offsets);
