typedef struct {
    int key_index;
    long timestamp;
} Record;

int initialize_arrays(long *offsets, int *keys, double *values, Record **records, char *filename, long capacity) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    size_t lines = 0;
    char line[256];

    while (fgets(line, sizeof(line), file)) {
        lines++;
    }
    rewind(file);

    if (lines > capacity) {
        fprintf(stderr, "File contains more data than allocated space\n");
        return 2;
    }

    offsets = malloc((long)(lines + 1) * sizeof(long));
    keys = malloc((int)(lines + 1) * sizeof(int));
    values = malloc((double)(lines + 1) * sizeof(double));

    if (!offsets || !keys || !values) {
        perror("Memory allocation failed");
        return 3;
    }

    Record *records_arr = malloc((size_t)(lines + 1) * sizeof(Record));

    if (!records_arr) {
        free(offsets);
        free(keys);
        free(values);
        perror("Memory allocation failed");
        return 3;
    }

    Record *records = records_arr;

    size_t index = 0;
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " ");
        offsets[index] = atol(token);
        token = strtok(NULL, " ");
        keys[index] = atoi(token);
        token = strtok(NULL, " ");
        values[index] = atof(token);

        records[index].key_index = keys[index];
        records[index].timestamp = (long)time(NULL);

        index++;
    }

    fclose(file);

    // Print contents of records array
    for (size_t i = 0; i < index; ++i) {
        printf("Record %zu: key %d, value %.2f, timestamp %ld\n", i, records[i].key_index, values[i], records[i].timestamp);
    }

    return 0;
}
