void init_records(int num_records, int value_range, int key_size, int offset_size, int **keys, long **offsets, record ***records) {
    *records = malloc(num_records * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % value_range;
        (*keys) = realloc(*keys, (i + 1) * sizeof(int));
        if (!*keys) {
            fprintf(stderr, "Failed to allocate memory for keys\n");
            free(*records);
            return;
        }
        (*offsets) = realloc(*offsets, (i + 1) * sizeof(long));
        if (!*offsets) {
            fprintf(stderr, "Failed to allocate memory for offsets\n");
            free(*keys);
            free(*records);
            return;
        }
        (*keys)[i] = i;
        (*offsets)[i] = i;
        (*records)[i].key = *keys + i;
        (*records)[i].offset = *offsets + i;
    }
}

void print_records(int num_records, record **records) {
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: key=%d, offset=%ld, value=%d\n", i, (*records)[i].key[0], (*records)[i].offset[0], (*records)[i].value);
