}

// Syncronize access to records array with this mutex.
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void update_record(int index, int new_value, record **records) {
    pthread_mutex_lock(&records_mutex);
    (*records)[index].value = new_value;
    pthread_mutex_unlock(&records_mutex);
}
