void init_arrays(size_t *offsets, size_t offsetSize, int keys[], size_t keySize, Record records[], size_t recordCount) {
    if (!offsetSize || !keySize || !recordCount) {
        fprintf(stderr, "Error: Invalid input parameters.\n");
        exit(EXIT_FAILURE);
    }

    offsets = malloc(offsetSize * sizeof(size_t));
    keys = malloc(keySize * sizeof(int));
    records = malloc(recordCount * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Out of memory.\n");
        exit(EXIT_FAILURE);
    }

    size_t offsetIndex = 0;
    int keyIndex = 0;
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = rand() % RAND_MAX; // Handle potential integer overflow by using a suitable maximum value
        offsets[offsetIndex++] = offsetIndex;
        keys[keyIndex++] = keyIndex;
    }
}

int main(int argc, char *argv[]) {
    size_t offsetSize = 0;
    int keySize = 0;
    size_t recordCount = 0;

    static const struct option long_options[] = {
        {"offset-size", required_argument, NULL, 'o'},
        {"key-size", required_argument, NULL, 'k'},
        {"record-count", required_argument, NULL, 'r'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "o:k:r:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'o':
                offsetSize = atoi(optarg);
                break;
            case 'k':
                keySize = atoi(optarg);
                break;
            case 'r':
                recordCount = atoi(optarg);
