    if (!offsetSize || !keySize || !recordCount) {
        fprintf(stderr, "Error: Missing or invalid configuration parameters.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    init_arrays((size_t*)0, offsetSize, (int*)0, keySize, (Record*)0, recordCount);

    return EXIT_SUCCESS;
}
