            free(*records);
            *records = NULL;
            return -2;
        }
    }

    *metadata = calloc(product_count, 256);
    if (*metadata == NULL) {
        perror("Error: Memory allocation failed.");
        for (int i = 0; i < product_count; ++i) {
            free((*records)[i]);
        }
        free(*records);
        *records = NULL;
        return -2;
