#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int key;
    int value;
} record;

static int* offsets = NULL;
static int* keys = NULL;
static record* records = NULL;
static size_t capacity = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_threads = 0;

void init_data_structures(size_t round, size_t offset_range, size_t key_range, size_t record_value_range) {
    if (capacity == 0) {
        capacity = round * 2;
        offsets = mmap(NULL, capacity * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        keys = offsets + round;
        records = keys + round;
    }

    if (round * 3 > capacity) {
        capacity *= 2;
        offsets = realloc(offsets, capacity * sizeof(int));
        keys = offsets + round;
        records = keys + round;
    }

    srand(time(NULL));

    for (size_t i = 0; i < round; ++i) {
        pthread_mutex_lock(&mutex);
            offsets[i] = rand() % offset_range;
            keys[i] = rand() % key_range;
            records[i].value = rand() % record_value_range;
        pthread_mutex_unlock(&mutex);
    }
}

int validate_data_structures(size_t round) {
    int errors = 0;

    for (size_t i = 0; i < round; ++i) {
        if ((offsets[i] > offset_range || offsets[i] < 0) ||
            (keys[i] > key_range || keys[i] < 0) ||
            (records[i].value > record_value_range || records[i].value < 0)) {
            errors++;
        }
    }

    return errors;
}

void log_round(size_t round, int validation_errors) {
    // Integration with external logging system goes here.
}

#ifdef _WIN32
#define thread_local __thread
#else
#define thread_local __Thread_local
#endif

void* worker_function(void* data) {
    size_t round = *(size_t*)data;

    init_data_structures(round, offset_range, key_range, record_value_range);

    int errors = validate_data_structures(round);

    log_round(round, errors);

    // Continue with other tasks...

    return NULL;
}

void run_multiple_rounds(size_t num_rounds, size_t offset_range, size_t key_range, size_t record_value_range) {
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    size_t* rounds_per_thread = malloc(num_threads * sizeof(size_t));

    num_threads = std::min(num_cpu_count(), num_rounds);

    for (size_t i = 0; i < num_threads; ++i) {
        rounds_per_thread[i] = num_rounds / num_threads + (i < (num_rounds % num_threads)? 1:0);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        size_t thread_rounds_start = i * rounds_per_thread[i];
        size_t thread_rounds_end = (i == num_threads - 1)? num_rounds: (thread_rounds_start + rounds_per_thread[i]);

        void* thread_data = malloc(sizeof(size_t));
        *(size_t*)thread_data = thread_rounds_start;

        pthread_create(&threads[i], NULL, worker_function, thread_data);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(rounds_per_thread);
}
