#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pq.h>

struct Config {
    const char *db_url;
    bool disable_ssl_verification;
};

struct Record {
    int key;
};

struct ConnectionPool {
    int num_records;
    struct Record *records;
    long *offsets;
    int *keys;
};

void create_connection_pool(int num_records, const char *db_url, bool disable_ssl_verification) {
    if (num_records > 10000) {
        fprintf(stderr, "Maximum number of records is 10,000.\n");
        exit(EXIT_FAILURE);
    }

    struct Config config = {strdup(db_url), disable_ssl_verification};
    struct ConnectionPool *pool = malloc(sizeof(struct ConnectionPool));
    if (!pool) {
        fprintf(stderr, "Error allocating memory for connection pool.\n");
        exit(EXIT_FAILURE);
    }

    pool->num_records = num_records;
    pool->records = calloc(num_records, sizeof(struct Record));
    if (!pool->records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        exit(EXIT_FAILURE);
    }

    pool->offsets = malloc((num_records + 1) * sizeof(long));
    if (!pool->offsets) {
        fprintf(stderr, "Error allocating memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    pool->keys = malloc(sizeof(int) * (num_records + 1));
    if (!pool->keys) {
        fprintf(stderr, "Error allocating memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    // Initialize offsets and keys
    for (int i = 0; i <= num_records; ++i) {
        pool->offsets[i] = i;
        pool->keys[i] = -1;
    }

    // Shuffle keys array for good distribution
    for (int i = num_records; i > 0; --i) {
        int j = rand() % i + 1;
        int tmp = pool->keys[j];
        pool->keys[j] = pool->keys[i];
        pool->keys[i] = tmp;
    }

    // Assign keys to records and update offsets
    for (int i = 0; i < num_records; ++i) {
        int key = pool->keys[i];
        if (key == -1) {
            fprintf(stderr, "Error: Unable to assign key to record.\n");
            exit(EXIT_FAILURE);
        }
        pool->records[i].key = key;

        for (int j = i + 1; pool->keys[j] != -1 && j < num_records; ++j) {
            pool->offsets[pool->keys[j]] = pool->offsets[i + 1];
        }
    }

    // Connect to the database using the provided configuration
    PGconn *db_connection = PQconnectdb(config.db_url);
    if (PQstatus(db_connection) != CONNECTION_OK) {
        fprintf(stderr, "Error connecting to database: %s\n", PQerrorMessage(db_connection));
        exit(EXIT_FAILURE);
    }
    pool->config = config;
    pool->db_connection = db_connection;
}
```']

