#include <stdbool.h>

typedef struct Record {
    int value;
    double float_value;
    time_t last_update;
    char* string_value;
    int* key;
} Record;

int read_csv(const char* filename, char delimiter, size_t* offsets, int* keys, double* values, int* int_values, Record** records, size_t* capacity, size_t* size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    char line[4096];
    bool header = true;
    size_t offset_idx = 0;
    size_t key_idx = 0;

    while (fgets(line, sizeof(line), file)) {
        if (header) {
            char* token = strtok(line, delimiter);
            if (!token || strcmp(token, "offset") != 0 || strcmp(strtok(NULL, delimiter), "key") != 0 || strcmp(strtok(NULL, delimiter), "value") != 0 ||
                strcmp(strtok(NULL, delimiter), "int_value") != 0 || strcmp(strtok(NULL, delimiter), "float_value") != 0 || strcmp(strtok(NULL, delimiter), "string_value") != 0) {
                fprintf(stderr, "Error: Invalid CSV format\n");
                fclose(file);
                return 1;
            }
            header = false;
            continue;
        }

        char* token = strtok(line, delimiter);
        if (!token) {
            fprintf(stderr, "Error: Missing value in CSV record\n");
            fclose(file);
            return 1;
        }

        switch (offset_idx) {
            case 0: offsets[offset_idx++] = atol(token); break;
            case 1: keys[key_idx++] = atoi(token); break;
            case 2: int_values[key_idx - 1] = atoi(token); break;
            case 3: values[key_idx - 1] = atof(token); break;
            case 4: {
                size_t new_capacity = *capacity + 10;
                Record* tmp = realloc(*records, new_capacity * sizeof(Record));
                if (!tmp) {
                    fprintf(stderr, "Error: Out of memory\n");
                    fclose(file);
                    return 1;
                }
                *records = tmp;
                Record* record = &(*records)[*size];
                record->value = int_values[key_idx - 1];
                record->float_value = values[key_idx - 1];
                record->last_update = time(NULL);
                record->string_value = strdup(token);
                record->key = &keys[key_idx - 1];
                *size += 1;
            }
        }
    }

    fclose(file);
    return 0;
}
```

