int initializeDataRecords(int np, int nk, int nl, int *input, dataRecord** records) {
    int i, j, k;
    double random_val;
    clock_t start, end;

    // Allocate and initialize arrays for doubles, ints, and chars.
    double* d_array = (double*)malloc(np * sizeof(double));
    if (!d_array) return -1;

    int* k_array = (int*)malloc(nk * sizeof(int));
    if (!k_array) { free(d_array); return -1; }

    char* l_array = (char*)malloc((nl + 1) * sizeof(char)); // +1 for null terminator
    if (!l_array) { free(d_array); free(k_array); return -1; }

    dataRecord** r_array = (dataRecord**)calloc(np, sizeof(dataRecord*));
    if (!r_array) { free(d_array); free(k_array); free(l_array); return -1; }

    // Initialize double array with input values and shuffle them for better distribution.
    start = clock();
    for (i = 0; i < np; ++i) d_array[i] = input[i];
    for (i = np - 1; i > 0; --i) {
        k = rand() % (i + 1);
        if (k != i) {
            swap(d_array[i], d_array[k]);
            swap(&r_array[i], &r_array[k]);
        }
    }
    end = clock();

    // Allocate and initialize records array.
    for (i = 0; i < np; ++i) {
        r_array[i] = malloc(sizeof(dataRecord));
