    if (d_a->id > d_b->id) return 1;
    if (d_a->value < d_b->value) return -1;
    if (d_a->value > d_b->value) return 1;
    return 0;
}

void free_memory(size_t* darr, char** Carr, data_entry** dearr, size_t num_entries) {
