#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

#define MAX_STR_LEN 100
#define ERR_NO_MEMORY -1
#define ERR_OVERFLOW -2

struct item {
    int i;
    char *str;
    double d;
};

int init_items(struct item **items, size_t size, FILE *f) {
    if (!items || !size || !f)
        return ERR_NO_MEMORY;

    *items = malloc(size * sizeof(**items));
    if (!*items)
        return ERR_NO_MEMORY;

    for (size_t i = 0; i < size; ++i) {
        struct item *item = &(*items)[i];
        item->i = rand() % 100;
        item->d = rand() / (double) RAND_MAX;

        char str[MAX_STR_LEN];
        if (fscanf(f, "%s", str) != 1 || strlen(str) >= MAX_STR_LEN) {
            free(*items);
            return ERR_OVERFLOW;
        }

        item->str = malloc(strlen(str) + 1);
        if (!item->str) {
            free(*items);
            return ERR_NO_MEMORY;
        }
        strcpy(item->str, str);
    }

    return 0;
}

void free_items(struct item *items, size_t size) {
    if (items && size) {
        for (size_t i = 0; i < size; ++i) {
            struct item *item = &items[i];
            free(item->str);
        }
        free(items);
    }
}
