#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    int data_index;
    double value;
} record;

int randomInRange(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void generateData(int num_records, int key_size, int* keys, long* offsets, record** records, int* data, int data_count) {
    srand(time(NULL));

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        printf("Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        int value = randomInRange(-1e6, 1e6);
        (*records)[i].key = randomInRange(0, key_size - 1);
        if ((*keys)[(*records)[i].key] == 0) {
            i--; // reuse previous index if key is not in use
            continue;
        }

        (*records)[i].offset = i * sizeof(record);
        (*records)[i].value = value;
    }

    int* data_array = malloc(data_count * sizeof(int));
    if (data_array == NULL) {
        printf("Failed to allocate memory for data array\n");
        exit(EXIT_FAILURE);
    }

    // Implement your logic for reading the list of floating-point numbers from standard input and filling the 'data' array here.

    for (int i = 0; i < data_count; ++i) {
        int key_index = binarySearch((*keys), key_size, data[i]);
        if (key_index == -1) {
            printf("Error: Unable to find the corresponding key in the keys array\n");
            exit(EXIT_FAILURE);
        }

        record* rec = (*records) + ((*records)[key_index].offset / sizeof(record));
        if (rec->data_index == i) continue; // this data point already has an assigned index, skip it.

        rec->value = data[i];
        rec->data_index = i;
    }
}

int binarySearch(int* arr, size_t n, double target) {
    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (arr[mid] == target)
            return mid;

        if (arr[mid] < target)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return -1; // key not found
}
```

