    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        assert(false);
    }
    memset(offsets, 0, sizeof(long) * size);
    return offsets;
}

int *init_keys(size_t size) {
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        assert(false);
    }
    memset(keys, 0, sizeof(int) * size);
    return keys;
}

// Allocate and initialize record array with given size and random values within the range [min, max]
Record *init_records(size_t size, int min, int max) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        assert(false);
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = min + rand() % (max - min + 1);
    }
    return records;
}

// Binary search function to find key in the sorted array of records and return the corresponding record if found, else returns NULL
Record* binary_search(const Record *records, size_t size, int key) {
    size_t left = 0;
    size_t right = size - 1;
    size_t mid;

    while (left <= right) {
        mid = (left + right) / 2;

        if (records[mid].value < key)
            left = mid + 1;
        else if (records[mid].value > key)
            right = mid - 1;
        else
            return &records[mid];
    }

    return NULL;
}

// Main function to demonstrate the usage of the implemented functions
