typedef struct {
    int key;
    double value;
} data_record;

void process_csv_file(const char *filename, size_t max_records, size_t *offsets, int *keys, double *values, data_record **data, FILE **file) {
    char line[4096];
    char delimiter[] = ",";
    size_t num_records = 0;
    *file = fopen(filename, "r");

    if (*file == NULL) {
        perror("Error opening file");
        return;
    }

    while (num_records < max_records && fgets(line, sizeof(line), *file)) {
        char *token = strtok(line, delimiter);

        if (!token) continue; // skip empty lines or lines without required fields

        int i = 0;
        data[num_records] = malloc(sizeof(data_record));

        for (; token && i < 3; ++i) {
            if (!strcmp(token, "") || !isdigit(*token)) {
                free(data[num_records]);
                --num_records;
                break;
            }

            switch (i) {
                case 0:
                    sscanf(token, "%ld", &offsets[num_records]);
                    break;
                case 1:
                    sscanf(token, "%d", &keys[num_records]);
                    break;
                case 2:
                    sscanf(token, "%lf", &values[num_records]);
                    break;
            }

            token = strtok(NULL, delimiter);
        }

        if (i == 3) { // if all required fields are present
            data[num_records]->key = keys[num_records];
            data[num_records]->value = values[num_records];
            ++num_records;
        }
    }

    fclose(*file);
}
```

