#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    float x, y;
} Point;

typedef struct {
    Point* points;
    size_t num_points;
} Polygon;

double shoelace(Polygon polygon) {
    double area = 0.0;
    size_t i;
    for (i = 0; i < polygon.num_points - 1; ++i) {
        area += polygon.points[i].x * polygon.points[i+1].y - polygon.points[i+1].x * polygon.points[i].y;
    }
    area += polygon.points[polygon.num_points-1].x * polygon.points[0].y - polygon.points[0].x * polygon.points[polygon.num_points-1].y;
    return fabs(area / 2.0);
}

void init_arrays(size_t double_array_size, size_t point_array_size, size_t polygon_array_size, double* doubles, Point** points, Polygon** polygons) {
    assert(double_array_size > 0 && point_array_size > 0 && polygon_array_size > 0);

    doubles = malloc(double_array_size * sizeof(double));
    if (!doubles) {
        fprintf(stderr, "Error: Could not allocate memory for double array.\n");
        exit(EXIT_FAILURE);
    }

    points = malloc(point_array_size * sizeof(Point*));
    if (!points) {
        fprintf(stderr, "Error: Could not allocate memory for point arrays.\n");
        free(doubles);
        exit(EXIT_FAILURE);
    }

    polygons = malloc(polygon_array_size * sizeof(Polygon*));
    if (!polygons) {
        fprintf(stderr, "Error: Could not allocate memory for polygon arrays.\n");
        free(doubles);
        free(points);
        exit(EXIT_FAILURE);
    }

    size_t i;
    for (i = 0; i < point_array_size; ++i) {
        points[i] = malloc(sizeof(Point));
        if (!points[i]) {
            fprintf(stderr, "Error: Could not allocate memory for a point.\n");
            free(doubles);
            free(points);
            free(polygons);
            exit(EXIT_FAILURE);
        }
    }

    for (i = 0; i < polygon_array_size; ++i) {
        polygons[i] = malloc(sizeof(Polygon));
        if (!polygons[i]) {
            fprintf(stderr, "Error: Could not allocate memory for a polygon.\n");
            free(doubles);
            free(points);
            free(polygons);
            exit(EXIT_FAILURE);
        }
    }
}

void init_rand_coords(size_t point_array_size, Point* points, float min, float max) {
    size_t i;
    for (i = 0; i < point_array_size; ++i) {
        points[i].x = ((float) rand() / RAND_MAX) * (max - min) + min;
        points[i].y = ((float) rand() / RAND_MAX) * (max - min) + min;
    }
}

int main() {
    srand(time(NULL));

    size_t double_array_size = 10;
    size_t point_array_size = 100;
    size_t polygon_array_size = 10;

    double* doubles;
    Point** points;
    Polygon** polygons;

    init_arrays(double_array_size, point_array_size, polygon_array_size, &doubles, &points, &polygons);

    size_t i, j;
    for (i = 0; i < polygon_array_size; ++i) {
        polygons[i]->num_points = point_array_size / polygon_array_size;
        polygons[i]->points = points + i * polygons[i]->num_points;
        init_rand_coords(polygons[i]->num_points, polygons[i]->points, -1.0, 1.0);
    }

    double total_area = 0.0;
    for (i = 0; i < polygon_array_size; ++i) {
        total_area += shoelace(*polygons[i]);
    }

    printf("Total area: %.2f\n", total_area);

    free(doubles);
    for (i = 0; i < point_array_size; ++i) {
        free(points[i]);
    }
    free(points);
    for (i = 0; i < polygon_array_size; ++i) {
        free(polygons[i]);
    }
    free(polygons);

    return EXIT_SUCCESS;
}
