    if (offsetMap == MAP_FAILED) {
        perror("mmap: offsets");
        return 1;
    }

    dataMap = mmap(NULL, recordsCount * sizeof(DataRecord), PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (dataMap == MAP_FAILED) {
        perror("mmap: dataRecords");
        munmap(offsetMap, offsetSize * numSources);
        return 2;
