        while (fread(&offset, sizeof(offset), 1, fp) == 1 && !feof(fp)) {
            fread(&key, sizeof(key), 1, fp);
            fread(&value, sizeof(value), 1, fp);
            valueSizeRead = sizeof(value);

            // Handle out-of-bounds or incorrect data type errors
            if (offset >= offsetSize || key >= keysSize || valueSizeRead != valueSize) {
                fprintf(stderr, "Error: Invalid data format\n");
                goto error_cleanup;
            }

            longOffsets[offset] = key;
            values[offset] = value;
            memcpy(&dataMap[offset], fp, valueSize);
        }
        fclose(fp);
    }

    // Randomly initialize remaining dataRecords if no external data is provided
    for (j = numSources; j < recordsCount; ++j) {
        init_random(&dataMap[j], minValue, maxValue);
    }

    longOffsets = offsetMap;
    dataRecords = dataMap;

    return 0;

error_cleanup:
    if (offsetMap) munmap(offsetMap, offsetSize * numSources);
    if (dataMap) munmap(dataMap, recordsCount * sizeof(DataRecord));
    return 3;
}
