        log_error("Failed to allocate keys memory", logFile);
        free(offsets);
        return -1;
    }

    float* valueTemp = NULL;
    valueArray = (float*)malloc(numRecords * sizeof(float));
    if (!valueArray) {
        log_error("Failed to allocate values memory", logFile);
        free(keysArray);
        free(offsets);
        return -1;
    }

    valueTemp = valueArray;

    // Initialize key and value arrays
    for (size_t i = 0; i < numRecords; ++i) {
        keys[i] = i;
        *valueTemp++ = minVal + rand() / (RAND_MAX / (maxVal - minVal));
    }

    // Allocate memory for data record array and create individual data records
    size_t dataRecordSize = numRecords * sizeof(DataRecord);
