        if (dataRecordArray[i].value < minVal || dataRecordArray[i].value > maxVal) {
            log_error("Invalid float value found: ", logFile);
            log_error(valueTemp - 1 < numRecords ? "Expected range: [%f, %f]", minVal, maxVal), logFile);
            free(keysArray);
            free(valueArray);
            free(offsets);
            free(dataRecordArray);
            return -1;
        }
    }

    // Update offset array
    for (size_t i = 1; i <= numRecords; ++i) {
        offsets[i] = offsets[i - 1] + sizeof(int) + sizeof(float);
