typedef struct HashTable {
    int num_buckets;
    int *bucket_indices;
    struct KVPair **buckets;
} HashTable;

struct KVPair {
    char *key;
    int value;
    struct KVPair *next;
};

int init_hash_table(HashTable **ht, int num_buckets, int initial_pairs) {
    *ht = malloc(sizeof(HashTable));
    if (!*ht) return 1;

    (*ht)->num_buckets = num_buckets;
    (*ht)->bucket_indices = calloc(num_buckets, sizeof(int));
    if (!(*ht)->bucket_indices) {
        free(*ht);
        return 2;
    }

    (*ht)->buckets = calloc(num_buckets, sizeof((*ht)->buckets[0]));
    if (!(*ht)->buckets) {
        free((*ht)->bucket_indices);
        free(*ht);
        return 3;
    }

    for (int i = 0; i < num_buckets && initial_pairs > 0; ++i) {
        (*ht)->buckets[i] = NULL;
        if (random() % i == 0) { // insert initial pairs randomly across buckets
            struct KVPair *kv = malloc(sizeof(struct KVPair));
            kv->key = strdup("key");
            kv->value = random();
            kv->next = (*ht)->buckets[i];
            (*ht)->buckets[i] = kv;
            --initial_pairs;
        }
    }

    return 0; // success
}

void insert(HashTable *ht, const char *key, int value) {
    int hash = hashfunc(key);

    struct KVPair **link = &ht->buckets[hash];
    while (*link != NULL && strcmp((*link)->key, key)) {
        link = &(*link)->next;
    }

    if (!*link) { // create new entry
        struct KVPair *kv = malloc(sizeof(struct KVPair));
        kv->key = strdup(key);
        kv->value = value;
        kv->next = *link;
        *link = kv;
    } else {
        (*link)->value = value; // update existing entry
    }
}

void print_hash_table(const HashTable *ht) {
    for (int i = 0; i < ht->num_buckets; ++i) {
        const struct KVPair *kv = ht->buckets[i];
        while (kv != NULL) {
            printf("Bucket %d: %s -> %d\n", i, kv->key, kv->value);
            kv = kv->next;
        }
    }
}

int hashfunc(const char *key) {
    int hash = 0;
    for (size_t i = 0; key[i]; ++i) hash = (hash << 5) + hash + key[i];
    return hash % ht->num_buckets;
}
```

