#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/*
 * Define the record structure.
 */
typedef struct {
    int value;
} Record;

/*
 * Allocate memory for the arrays with given number of elements.
 * Uses chunked allocation to minimize memory fragmentation.
 */
void* allocate_chunk(size_t size, size_t chunk_size) {
    void* buffer = malloc(size);
    if (!buffer) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    size_t allocated = size;
    size_t chunked = chunk_size > size ? size : chunk_size;
    char* current = buffer;
    while (allocated > 0) {
        current += chunked;
        allocated -= chunked;
        *current = 0;
        if (allocated >= chunked) {
            *(char*)(current + chunked - 1) = '\0';
        }
    }
    return buffer;
}

/*
 * Initialize the large dataset of records.
 * Uses bulk allocation to optimize memory usage and performance.
 */
void initialize_dataset(size_t num_records, size_t* offsets, int* keys, Record** records) {
    /* Allocate memory for arrays using chunked allocation */
    offsets = allocate_chunk(num_records * sizeof(size_t), 1024 * 1024);
    keys = allocate_chunk(num_records * sizeof(int), 1024 * 1024);
    records = allocate_chunk(num_records * sizeof(Record*), 1024 * 1024);

    /* Initialize offsets and keys */
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;
        keys[i] = rand() % 1001;
    }

    /* Set values of records using bulk allocation and parallelization */
    #pragma omp parallel for schedule(static, 128)
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % 1001;
    }
}

/*
 * Free allocated memory for the arrays and records.
 */
void free_dataset(size_t num_records, size_t* offsets, int* keys, Record** records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}
