               free(*offsets);
               return -3;
           }

       qsort(*offsets, offsets_num_max - offsets_num_min + 1, sizeof(long), (void *)comparator);

       *keys = malloc(keys_num * sizeof(int));
       if (*keys == NULL) {
           free(*offsets);
           return -4;
       }

       for (size_t i = 0; i < keys_num; ++i) {
           while (1) {
               (**keys + i) = rand() % keys_num;
               if (i == **keys || bin_search(*keys, *keys + i) >= i) continue;
               break;
           }
