       for (size_t i = 0; i < keys_num; ++i) {
           (**records + i).value = rand() % INT_MAX;
           (**records + i).key = *keys + i;
       }

       return 0;
   }

   int bin_search(long *arr, long *end, long key) {
       long *left = arr;
       long *right = end - 1;
       long mid;
       while (left <= right) {
           mid = (left + right) / 2;
           if (arr[mid] == key) return mid;
           if (arr[mid] < key) left = mid + 1;
           else right = mid - 1;
       }
       return -1;
   }

   int comparator(const void *a, const void *b) {
       return *(long *)a - *(long *)b;
   }

   void print_records(struct record *records, int length) {
       for (size_t i = 0; i < length; ++i) {
           printf("Record %zu: value=%d, key=%d\n", i, records[i].value, *records[i].key);
       }
   }
