    return 0; // Success
}

void sort_records(size_t num, record* records) {
    qsort(records, num, sizeof(record), compare_records);
}

int compare_records(const void* a, const void* b) {
    return ((record*)a)->key - ((record*)b)->key;
}

// Free memory after use.
void clean_up(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].id) free(records[i].id);
    }
    if (records) free(records);
}

// Main function to run the example code.
int main() {
    srand((unsigned int)time(0)); // Seed random number generator
    size_t num_records = 1000;
    long* offsets;
    int* keys;
    record* records;
    int error = initialize_arrays(num_records, &offsets, keys, records);
    if (error) {
        printf("Error: %d\n", error);
        clean_up(offsets, keys, records);
        return 1;
    }

    sort_records(num_records, records);

    // Print sorted records for visualization purposes.
    for (size_t i = 0; i < num_records; ++i) {
        printf("Key: %d\n", records[i].key);
        printf("Value: %.2f\n", records[i].value);
        printf("ID: %s\n", records[i].id);
    }

    clean_up(offsets, keys, records);
    return 0;
}
