#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    const char* key;
    const char* label;
    long offset;
} Record;

int initializeDatabaseRecords(int* input, size_t numInputs, size_t* keysSize, size_t* labelsSize, size_t* recordsSize) {
    if(!input || !keysSize || !labelsSize || !recordsSize) return -1;

    // Allocate memory for key and label arrays
    char* keys = malloc(*keysSize * sizeof(char));
    char* labels = malloc(*labelsSize * sizeof(char));

    if(!keys || !labels) {
        free(keys);
        free(labels);
        return -1;
    }

    // Allocate memory for int array and records array
    int* values = malloc(numInputs * sizeof(int));
    Record* records = malloc(*recordsSize * sizeof(Record));

    if(!values || !records) {
        free(keys);
        free(labels);
        free(values);
        free(records);
        return -1;
    }

    // Copy input values and keys into allocated arrays
    for(size_t i = 0; i < numInputs; ++i) {
        values[i] = input[i];
        keys[i] = (char*)(i + 1); // Using integers as indices for simplicity
    }

    // Initialize records array with proper pointers and offsets
    for(size_t i = 0; i < *recordsSize; ++i) {
        records[i].value = values[i];
        records[i].key = keys + (i % numInputs);
        records[i].label = labels + (i / numInputs % *labelsSize);
        records[i].offset = i;
    }

    // Set new sizes for key and label arrays
    *keysSize += *recordsSize;
    *labelsSize += *recordsSize;

    // Print contents of the records array
    printf("Contents of records array:\n");
    for(size_t i = 0; i < *recordsSize; ++i) {
        printf("Record %zu: value=%d, key=%c, label=%c, offset=%ld\n", i, records[i].value, *(records[i].key), *(records[i].label), records[i].offset);
    }

    // Sort the records array based on their int values
    qsort(records, *recordsSize, sizeof(Record), compareRecords);

    // Search for a specific int value within the records array
    int target = 42;
    size_t index = binarySearch(records, target, *recordsSize);
    if(index != SIZE_MAX) {
        printf("Target value %d found at index %zu\n", target, index);
    } else {
        printf("Target value not found\n");
    }

    // Free allocated memory
    free(keys);
    free(labels);
    free(values);
    free(records);

    return 0;
}

int compareRecords(const void* a, const void* b) {
    // Optimized comparison for good distribution properties without excessive CPU time
    if(((Record*)a)->value < ((Record*)b)->value) return -1;
    if(((Record*)a)->value > ((Record*)b)->value) return 1;
    return 0;
}

size_t binarySearch(Record* arr, int target, size_t n) {
    // Implementation of binary search algorithm
    size_t low = 0;
    size_t high = n - 1;

    while(low <= high) {
        size_t mid = (low + high) / 2;

        if(arr[mid].value == target) return mid;

        if(arr[mid].value < target) low = mid + 1;
        else high = mid - 1;
    }

    return SIZE_MAX;
}
