int read_list(int size, int *numbers) {
    if (size <= 0) return -1;

    for (int i = 0; i < size; ++i)
        scanf("%d", numbers + i);

    return 0;
}

void init_keys(int size, int *numbers, int *keys) {
    for (int i = 0; i < size; ++i)
        keys[numbers[i]] = i;
}

int *malloc_int_array(size_t n) {
    int *arr = malloc(n * sizeof(int));
    if (!arr) return NULL;
    return arr;
}

long *malloc_long_array(size_t n) {
    long *arr = malloc(n * sizeof(long));
    if (!arr) return NULL;
    return arr;
}

struct Record* allocate_records(int size, int *keys) {
    struct Record *arr = malloc(size * sizeof(struct Record));
    if (!arr) return NULL;

    for (int i = 0; i < size; ++i)
        arr[i].key = keys + i;

    return arr;
}

void generate_offsets(struct Record *records, int *keys, int length) {
    srand(time(NULL));
    for (int i = 0; i < length; ++i)
        records[i].offset = rand() % INT_MAX;
}

void print_records(const struct Record *records, int size) {
    printf("Records:\n");
    for (int i = 0; i < size; ++i)
        printf("{%d, %p, %ld}\n", records[i].value, records[i].key, records[i].offset);
}

void sort_records(struct Record *records, int size) {
    qsort(records, size, sizeof(struct Record), (int (*)(const void*, const void*))compare);
}

int search_record(struct Record *records, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (records[i].value == value) return i;
    }

    return -1;
}

void deallocate_records(struct Record *records, int size) {
    free(records);
}

int compare(const void *a, const void *b) {
    const struct Record *ia = a;
    const struct Record *ib = b;
    return ia->value - ib->value;
}

int main(int argc, char **argv) {
    int size = atoi(argv[1]);
    int *numbers = malloc_int_array(size);
    if (!numbers) return EXIT_FAILURE;

    if (read_list(size, numbers)) {
        free(numbers);
        return EXIT_FAILURE;
    }

    int *keys = malloc_int_array(size);
    if (!keys) {
        free(numbers);
        return EXIT_FAILURE;
    }

    init_keys(size, numbers, keys);

    int *records = allocate_records(size, keys);
    if (!records) {
        free(numbers);
        free(keys);
        return EXIT_FAILURE;
    }

    generate_offsets(records, keys, size);

    print_records(records, size);
    sort_records(records, size);
    print_records(records, size);

    int index = search_record(records, size, 10);
    printf("Search result: %d\n", index);

    deallocate_records(records, size);
    free(keys);
    free(numbers);

    return EXIT_SUCCESS;
}
