    set_offsets(records, num_records, offsets);

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100 + 1;
        records[i].key_ptr = keys + i;
    }

    free(keys);
    free(offsets);

    return records;
}

void test_module(char *label, void (*f)()) {
    console.log(`Testing module: ${label}`);
    const blueslip = require('blueslip');
    try {
        f();
        console.log(`Test passed for ${label}`);
    } catch (error) {
        console.error(`Test failed for ${label}: ${error.message}`);
    } finally {
        blueslip.reset();
    }
}
