#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void insert_sorted(Node** head_ref, Node* new_node) {
    if (*head_ref == NULL || (*head_ref)->value > new_node->value) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->next->value <= new_node->value) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void* generate_random(void* arg) {
    int size = *(int*)arg;
    double* numbers = *(double**)arg + 0;
    Node** list = *(Node**)(arg + 1);

    srand((unsigned int)time(NULL));

    for (int i = 0; i < size; ++i) {
        int key = rand() % *((int*)arg - 2) + 2;
        numbers[i] = (double)(rand() % 100);
        insert_sorted(list, create_node(key));
    }

    return NULL;
}

void allocate_and_initialize(int size, int range, double** numbers, int** keys, Node*** list) {
    *numbers = (double*)calloc(size, sizeof(double));
    *keys = (int*)calloc(size, sizeof(int));
    *list = NULL;

    pthread_t threads[range];
    for (int i = 0; i < range; ++i) {
        int* size_arg = &size;
        double** numbers_arg = numbers;
        Node** list_arg = list;
        pthread_create(&threads[i], NULL, generate_random, (void*)(size_arg + 0));
        pthread_create(&threads[i], NULL, generate_random, (void*)((size_arg + 1) + i));
    }

    for (int i = 0; i < range; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

This code defines a `Node` struct and functions to create nodes, insert them into a linked list in sorted order, generate random values within a given range, and dynamically allocate memory for the required arrays. The linked list is managed with thread-safe operations using pthread library functions.']

