sensor_data* read_sensor_data(const char* data_source, size_t* num_samples) {
    FILE *file = fopen(data_source, "r");
    if (!file) {
        perror("Error opening data source");
        *num_samples = 0;
        return NULL;
    }

    // Allocate memory for long timestamps and float sensor readings
    long* timestamps = (long*)malloc(sizeof(long) * *num_samples);
    if (!timestamps) {
        fprintf(stderr, "Error allocating memory for timestamps\n");
        fclose(file);
        *num_samples = 0;
        return NULL;
    }

    float* sensor_readings = (float*)malloc(sizeof(float) * *num_samples);
    if (!sensor_readings) {
        fprintf(stderr, "Error allocating memory for sensor readings\n");
        free(timestamps);
        fclose(file);
        *num_samples = 0;
        return NULL;
    }

    // Allocate memory for sensor_data structures and initialize the quality flags
    sensor_data* sensor_data_array = (sensor_data*)malloc(sizeof(sensor_data) * *num_samples);
    if (!sensor_data_array) {
        fprintf(stderr, "Error allocating memory for sensor_data array\n");
        free(timestamps);
        free(sensor_readings);
        fclose(file);
        *num_samples = 0;
        return NULL;
    }

    for (size_t i = 0; i < *num_samples; ++i) {
        sensor_data_array[i].timestamp = time(NULL);
        if (fscanf(file, "%ld %f", &(timestamps[i]), &(sensor_readings[i])) != 2) {
            fprintf(stderr, "Error reading data from the source\n");
            // Handle this error case by skipping the current record and continuing with the next one
            continue;
        }

        if (isnan(sensor_readings[i])) {
            sensor_data_array[i].sensor_reading = 0.0f;
            sensor_data_array[i].quality_flag = -1; // Use a negative value to indicate corrupted data
        } else {
            sensor_data_array[i].quality_flag = (rand() % 100) < 50 ? 1 : 0; // Set quality flag based on a predefined probability
        }
    }

    fclose(file);

    *num_samples = ftell(stdin); // Rewind the stream to its initial position and return the actual number of read samples
    rewind(stdin);

    return sensor_data_array;
}
