void parse_config(FILE *file, config_pair **keys, record **records) {
    size_t keys_capacity = 0, records_capacity = 0;
    *keys = malloc(keys_capacity * sizeof(config_pair));
    *records = malloc(records_capacity * sizeof(record));

    while (!feof(file)) {
        char line[1024];
        if (fgets(line, sizeof(line), file) == NULL) break;

        // Handle comments and configuration lines
        if (line[0] == '#') continue;

        // Parse keys and offsets
        sscanf(line, "%d %ld", &((*keys)[keys_capacity].key), &((*keys)[keys_capacity].offset));
        keys_capacity++;
        (*keys) = realloc(*keys, (keys_capacity + 1) * sizeof(config_pair));
    }

    // Initialize records with random values and set record capacity based on keys size
    records_capacity = keys_capacity;
    (*records) = malloc(records_capacity * sizeof(record));
    srand(time(NULL));
    for (size_t i = 0; i < records_capacity; ++i) {
        (*records)[i].value = rand() % ((*keys)[keys_capacity - 1].key + 1);
    }
}

