#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>
#include <string.h>
#include <subprocess.h>

typedef struct {
    int key_idx;
    int value;
} record;

int init_arrays(size_t *long_arr_size, size_t *int_arr_size, size_t *record_arr_size, FILE **config_file) {
    long *long_arr = malloc(*long_arr_size * sizeof(long));
    if (!long_arr) {
        perror("Error allocating memory for long array");
        return 1;
    }

    int *int_arr = malloc(*int_arr_size * sizeof(int));
    if (!int_arr) {
        perror("Error allocating memory for int array");
        free(long_arr);
        return 2;
    }

    record *record_arr = malloc(*record_arr_size * sizeof(record));
    if (!record_arr) {
        perror("Error allocating memory for record array");
        free(long_arr);
        free(int_arr);
        return 3;
    }

    srand((unsigned int)time(NULL));

    // Initialize long and int arrays with dummy values
    for (size_t i = 0; i < *long_arr_size; ++i) {
        long_arr[i] = i;
    }
    for (size_t i = 0; i < *int_arr_size; ++i) {
        int_arr[i] = rand() % UINT_MAX;
    }

    // Initialize record array with random values and keys
    for (size_t i = 0; i < *record_arr_size; ++i) {
        record_arr[i].key_idx = rand() % *int_arr_size;
        record_arr[i].value = rand() % UINT_MAX;
    }

    // Print the contents of the record array for verification
    printf("Record array:\n");
    for (size_t i = 0; i < *record_arr_size; ++i) {
        printf("Key: %ld, Value: %d\n", record_arr[i].key_idx, record_arr[i].value);
    }

    // Encrypt passwords and replace placeholders in the configuration file
    PopenCommand(
        "sed -i 's/PLACEHOLDER1/{encrypted_password1}/g' config.txt",
        config_file,
        STDOUT_FILENO,
        STDOUT_FILENO,
        NULL);

    for (size_t i = 0; i < *record_arr_size; ++i) {
        char password[64];
        // Generate a new encrypted password and add it to the configuration file
        snprintf(password, sizeof(password), "ENCryptedPassword%ld", record_arr[i].value);
        PopenCommand(
            "sed -i '$a \"PLACEHOLDER2=%s\"" config.txt",
            password,
            config_file,
            STDOUT_FILENO,
            STDOUT_FILENO,
            NULL);
    }

    // Free allocated memory and return success
    free(long_arr);
    free(int_arr);
    return 0;
}

void PopenCommand(const char *command, FILE **file, int in_fd, int out_fd, ...) {
    va_list args;
    char *args_str;

    va_start(args, command);
    vasprintf(&args_str, command, args);
    va_end(args);

    Pipe pipe;
    if (pipe(pipe.fd) < 0) {
        perror("Error creating pipe");
        free(args_str);
        return;
    }

    pid_t child = fork();
    if (child == -1) {
        perror("Error forking process");
        free(args_str);
        close(pipe.fd[0]);
        close(pipe.fd[1]);
        return;
    }

    if (!child) {
        // Child process
        dup2(pipe.fd[1], STDOUT_FILENO);
        dup2(pipe.fd[1], STERR_FILENO);
        close(pipe.fd[0]);
        close(pipe.fd[1]);

        execl("/usr/bin/python", "/usr/bin/python", args_str, NULL);
        perror("Error executing command");
        free(args_str);
        _exit(1);
    }

    // Parent process
    close(pipe.fd[1]);
    char buf[128];
    ssize_t n;
    while ((n = read(pipe.fd[0], buf, sizeof(buf))) > 0) {
        fwrite(buf, n, 1, *file);
    }
    close(pipe.fd[0]);
}
```

