// Define struct node
typedef struct Node {
    int value;
    struct Node* next;
    char custom_attribute[100]; // Max length of 100 characters for custom attribute
} Node;

void read_csv(char** lines, FILE* file) {
    size_t len = 0;
    ssize_t read;
    char* line = NULL;

    while ((read = getline(&line, &len, file)) != -1) {
        lines = realloc(lines, sizeof(char*) * (len + 1));
        lines[len] = strdup(line);
    }

    if (line) free(line);
}

Node** create_node_array(size_t size) {
    Node **nodes = malloc(sizeof(Node*) * size);
    for (size_t i = 0; i < size; ++i)
        nodes[i] = NULL;

    return nodes;
}

void init_node(Node* node, int value, char* custom_attribute) {
    node->value = value;
    if (custom_attribute == NULL)
        strcpy(node->custom_attribute, "");
    else
        strcpy(node->custom_attribute, custom_attribute);
    node->next = NULL;
}

void randomize(Node* node, int min, int max) {
    node->value = rand() % (max - min + 1) + min;
}

int cmp_nodes(const void *a, const void *b) {
    return (*(const Node **)a)->value - *(const Node **)b)->value;
}

void insert_sorted(Node** list, Node* new_node) {
    if (list == NULL || *list == NULL) {
        *list = new_node;
        return;
    }

    Node* current = *list;
    Node* previous = NULL;

    while (current != NULL && current->value < new_node->value) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL)
        *list = new_node;
    else
        previous->next = new_node;

    new_node->next = current;
}

void free_nodes(Node** list) {
    while (*list != NULL) {
        Node* temp = *list;
        *list = (*list)->next;
        free(temp);
    }
}

int main() {
