        Node* node = malloc(sizeof(Node));
        init_node(node, keys[i], lines[i + 1]); // Custom attribute is the second column in CSV file
        randomize(node, 0, INT_MAX);
        insert_sorted(nodes + keys[i], node);
    }

    free(lines);
    fclose(file);

    // Your application logic here...

    free_nodes(nodes);
    free(values);
    free(keys);
    for (size_t i = 0; i < num_nodes; ++i) free(nodes[i]);
    free(nodes);

    return 0;
}
