void initialize_data(int key_count, const char** keys, int min_val, int max_val) {
    // Allocate memory for offsets, keys, and records arrays with initial capacity equal to key_count
    long* offsets = (long*)malloc((key_count + 1) * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failure: offsets\n");
        return -1;
    }

    int* keys_arr = (int*)calloc(key_count, sizeof(int));
    if (!keys_arr) {
        fprintf(stderr, "Memory allocation failure: keys_arr\n");
        free(offsets);
        return -1;
    }

    record* records = (record*)malloc((key_count + 1) * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failure: records\n");
        free(keys_arr);
        free(offsets);
        return -1;
    }

    metadata* metadatas = (metadata*)malloc((key_count + 1) * sizeof(metadata));
    if (!metadatas) {
        fprintf(stderr, "Memory allocation failure: metadatas\n");
        free(records);
        free(keys_arr);
        free(offsets);
        return -1;
    }

    // Initialize offsets and keys arrays
    *offsets = 0;
    for (int i = 0; i < key_count; ++i) {
        keys_arr[i] = strlen(keys[i]);
        *(offsets + i + 1) = *(offsets + i) + keys_arr[i] + 1; // Additional 1 for the null terminator
    }

    // Set up records and metadatas arrays with dynamic memory allocation for data members
    int cur_offset = 0;
    for (int i = 0; i < key_count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        records[i].data = malloc(keys_arr[i] + 1); // Additional 1 for the null terminator
        if (!records[i].data) {
            fprintf(stderr, "Memory allocation failure: record[%d]->data\n", i);
            free(metadatas);
            free(records);
            free(keys_arr);
            free(offsets);
            return -1;
        }
        memcpy(records[i].data, keys[i], keys_arr[i]); // Copy key string into the record's data

        metadatas[i].rec = &records[i];
        metadatas[i].meta_value = 0;

        cur_offset = *(offsets + i + 1);
    }

    // Set up last offset and add one more offset for the null terminator
    *(offsets + key_count) = cur_offset + keys_arr[key_count - 1] + 1;
}
