```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gsl/ran.h>
#include "csv.h"

typedef struct {
    double value;
    int* key;
    char* label;
    void* offset;
} dataRecord;

int initializeDataRecords(const char* filePath, size_t numRecords, size_t numKeys, size_t numLabels, gsl_rng* r) {
    csv_t* csv = NULL;
    double* values = NULL;
    int* keys = NULL;
    char* labels = NULL;
    dataRecord* dataRecords = NULL;
    void* offset = malloc(numRecords * sizeof(void*));
    int i, j;

    // Open the CSV file and read the values into an array
    csv = csv_read(filePath);
    if (!csv) {
        perror("Error reading the CSV file");
        goto error;
    }

    values = malloc(numRecords * sizeof(double));
    for (i = 0; i < numRecords && !csv_row(csv, i); ++i) {
        values[i] = csv_get_double(csv, i, 0);
    }

    if (!values || i != numRecords) {
        perror("Error reading the values from the CSV file");
        goto error;
    }

    // Allocate and initialize memory for keys, labels, and dataRecord arrays
    keys = malloc(numKeys * sizeof(int));
    labels = calloc(numLabels, sizeof(char));
    dataRecords = calloc(numRecords, sizeof(dataRecord));

    if (!keys || !labels || !dataRecords) {
        perror("Error allocating memory for keys, labels, or dataRecord arrays");
        goto error;
    }

    // Set the values of each record's double field to a random value within a given range
    gsl_ran_mt19937_t mt;
    gsl_ran_seed(&mt, time(NULL));
    gsl_ran_rng_env_setup();
    for (i = 0; i < numRecords; ++i) {
        dataRecords[i].value = gsl_ran_flat(r, 0.0, 1.0);
        dataRecords[i].key = &keys[values[i] * numKeys];
        dataRecords[i].label = labels + (int)(values[i] * numLabels);
        dataRecords[i].offset = offset + i;
    }

    printf("Data Records:\n");
    for (i = 0; i < numRecords; ++i) {
        printf("%f %c%s %p\n", dataRecords[i].value, *dataRecords[i].label, dataRecords[i].key ? *(dataRecords[i].key) : "", dataRecords[i].offset);
    }

    // Sort the data records based on their double values
    qsort(dataRecords, numRecords, sizeof(dataRecord), compareDataRecords);

    // Search for a specific double value within the data records array
    double searchValue = 0.5;
    for (i = 0; i < numRecords; ++i) {
        if (fabs(searchValue - dataRecords[i].value) < 1e-6) {
            printf("Found value %f at index %d\n", searchValue, i);
            break;
        }
    }

    // Clean up and return success
    csv_free(csv);
    free(values);
    free(keys);
    free(labels);
    free(offset);
    return 0;

error:
    if (csv) csv_free(csv);
    if (values) free(values);
    if (keys) free(keys);
    if (labels) free(labels);
    if (dataRecords) free(dataRecords);
    if (offset) free(offset);
    return -1;
}

int compareDataRecords(const void* a, const void* b) {
    dataRecord* recordA = (dataRecord*)a;
    dataRecord* recordB = (dataRecord*)b;
    return (recordA->value > recordB->value) - (recordA->value < recordB->value);
}
