        }

        strcpy(records[i].data, keys[i]); // Copy key to data in record
        records[i].value = generate_random_number(min_val, max_val, even_odd); // Set value in record based on user specified range and parity

        metadata_arr[i].rec = &records[i]; // Assign pointer to the corresponding record in the metadata structure
        metadata_arr[i].meta_value = 0; // Initialize meta_value to 0
    }

