        if (!keys[i] || strchr(keys[i], '\0')) {
            fprintf(stderr, "Error: invalid key found in the keys array\n");
            free_memory(keys_arr);
            free_memory(records);
            free(offsets);
            return;
        }
    }
}

// Helper function to generate random number within a given range and parity
int generate_random_number(int min, int max, int even_odd) {
    srand(time(NULL)); // Seed the random number generator with current time
    int result;
    if (even_odd == 0) {
        result = rand() % (max - min + 1) + min;
    } else {
        result = (rand() % 2 == 0 ? min : min + 1) + rand() % ((max - min + 1) >> 1);
    }
    return result;
}

// Helper function to free allocated memory
void free_memory(void* arr, int size) {
    if (arr && size > 0) {
        free(arr);
    }
}
