        records[i].offset = offsets[i];
        records[i].key = keys[records[i].key];
    }

    // Initialize offset array
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = -1;
    }

    return records;
}

void fill_values(Record* records, int num_records, int min_value, int max_value) {
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

int main(int argc, char** argv) {
    int num_offsets = 0;
    int num_keys = 0;
    int num_records = 0;
    const char* csv_filename = NULL;
    int min_value = 0;
    int max_value = 0;

    static struct option long_options[] = {
        {"offsets", required_argument, NULL, 'o'},
        {"keys", required_argument, NULL, 'k'},
        {"records", required_argument, NULL, 'r'},
        {"csv", required_argument, NULL, 'c'},
        {"min-value", required_argument, NULL, 'm'},
        {"max-value", required_argument, NULL, 'M'},
        {NULL, 0, NULL, 0}
    };

    int option_index = 0;

    while (1) {
        int c = getopt_long(argc, argv, "o:k:r:c:m:M:", long_options, &option_index);

        if (c == -1) break;

        switch (c) {
            case 'o':
                num_offsets = atoi(optarg);
                break;
            case 'k':
                num_keys = atoi(optarg);
                break;
            case 'r':
                num_records = atoi(optarg);
                break;
            case 'c':
                csv_filename = optarg;
                break;
            case 'm':
                min_value = atoi(optarg);
                break;
            case 'M':
                max_value = atoi(optarg);
                break;
        }
    }

    if (!num_offsets || !num_keys || !num_records || !csv_filename || !min_value || !max_value) {
        log_error("Invalid or missing arguments");
        return -1;
    }

    void* data = read_csv(csv_filename);

    if (!data) {
        log_error("Failed to read CSV file");
        return -1;
    }

    void** csv_data = malloc((num_keys + 2) * sizeof(void*)); // Extra space for the first and last row pointers

    if (!csv_data) {
        log_error("Memory allocation for CSV data failed");
        return -1;
    }

    csv_data[0] = data;
    csv_data[num_keys + 1] = NULL;

    int key_index = 0;

    // Iterate through CSV rows and assign keys to their respective offsets
    for (int i = 0; i < num_records; ++i) {
        char** row = (char**) csv_data[key_index++];
        int offset = atoi(row[0]);

        if (offset >= num_offsets || offset < 0) {
            log_error("Invalid offset found in CSV data");
            return -1;
        }

        keys[offset] = row[1];
        offsets[offset] = i;
    }

    Record* records = initialize_records(num_offsets, num_keys + 1, num_records); // Extra space for the first key (CSV header)

    if (!records) {
        log_error("Memory allocation for records failed");
        return -1;
    }

    fill_values(records, num_records, min_value, max_value);

    // Print records
    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: offset=%d, key=%s, value=%d\n", i, records[i].offset, records[i].key, records[i].value);
    }

    free(csv_data);
    free(keys);
    free(offsets);
    return 0;
}

This code takes command-line arguments for the number of offsets, keys, and records, as well as a CSV file and minimum and maximum value ranges. It reads the CSV file into memory, assigns each key to its respective offset in the records array, fills the values for each record with a random number within the specified range, and then prints out the records.']

