typedef struct dataRecord {
    int value;
    const char *key;
    const char *label;
    long offset;
} dataRecord;

int init_dataRecords(size_t numInputs, size_t *inputList, size_t keysSize, size_t labelsSize, dataRecord **records) {
    if (numInputs <= 0 || inputList == NULL || keysSize <= 0 || labelsSize <= 0 || records == NULL) {
        return -1;
    }

    *records = malloc(numInputs * sizeof(dataRecord));
    if (*records == NULL) {
        return -2;
    }

    size_t *keys = malloc(keysSize * sizeof(size_t));
    if (keys == NULL) {
        free(*records);
        return -3;
    }

    size_t *labels = malloc(labelsSize * sizeof(size_t));
    if (labels == NULL) {
        free(*records);
        free(keys);
        return -4;
    }

    if (numInputs > INT32_MAX) {
        free(*records);
        free(keys);
        free(labels);
        return -5;
    }

    for (size_t i = 0; i < numInputs; ++i) {
        (*records + i)->value = inputList[i];
        (*records + i)->key = keys + (*keysSize > i ? i : i % *keysSize);
        (*records + i)->label = labels + (*labelsSize > i ? i : i % *labelsSize);
        if (i > 0) {
            long offset = (*records)[i - 1].offset + 1;
            if (offset > INT32_MAX) {
                free(*records);
                free(keys);
                free(labels);
                return -6;
            }
            (*records + i)->offset = offset;
        } else {
            (*records + i)->offset = 0;
        }
    }

    qsort(*records, numInputs, sizeof(dataRecord), (int (*)(const void *, const void *))compareDataRecords);

    printf("Data records:\n");
    for (size_t i = 0; i < numInputs; ++i) {
        printf("value: %d, key: %s, label: %s, offset: %ld\n", (*records + i)->value, (*records + i)->key, (*records + i)->label, (*records + i)->offset);
    }

    free(keys);
    free(labels);

    return 0;
}

int compareDataRecords(const void *a, const void *b) {
    const dataRecord *aa = (const dataRecord *)a;
    const dataRecord *bb = (const dataRecord *)b;
    if (aa->value < bb->value) {
        return -1;
    } else if (aa->value > bb->value) {
        return 1;
    } else {
        return 0;
    }
}

int searchDataRecords(size_t numInputs, dataRecord *records, int valueToFind) {
    size_t left = 0, right = numInputs - 1;
    while (left <= right) {
        size_t mid = left + (right - left) / 2;
        if (records[mid].value == valueToFind) {
            return (int)(mid);
        } else if (records[mid].value < valueToFind) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}
