    if (!ptr) {
        log("ERROR", "Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_arr(void** arr, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(arr[i]);
    }
    free(arr);
}

long* initialize_offsets(size_t size) {
    return safe_malloc(sizeof(long) * size);
}

int* initialize_keys(size_t size) {
    return safe_malloc(sizeof(int) * size);
}

record* initialize_records(size_t size, int min, int max) {
    record* records = safe_malloc(sizeof(record) * size);
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].key   = rand() % (max - min + 1) + min;
        records[i].offset = i;
    }
    return records;
}

void merge(record* arr, int left, int mid, int right, int(*compare)(const void*, const void*)) {
    int n1 = mid - left;
    int n2 = right - mid;

    record* L = safe_malloc((n1 + 1) * sizeof(record));
    record* R = safe_malloc((n2 + 1) * sizeof(record));

    for (int i = 0; i < n1; ++i) {
        L[i] = arr[left + i];
    }
    L[n1].key   = INT_MAX; // sentinel value
    L[n1].offset = INT_MAX;

    for (int j = 0; j < n2; ++j) {
        R[j] = arr[mid + j];
    }
    R[n2].key   = INT_MAX; // sentinel value
    R[n2].offset = INT_MAX;

    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (compare(&L[i], &R[j]) <= 0) {
            arr[k++] = L[i++];
        } else {
            arr[k++] = R[j++];
        }
    }

    free(L);
    free(R);
}

int compare_records(const void* a, const void* b) {
    record* left = (record*)a;
    record* right = (record*)b;
    return left->key - right->key;
}

void merge_sort(record* arr, int left, int right, int(*compare)(const void*, const void*)) {
    if (right > left) {
        int mid = (left + right) / 2;
        merge_sort(arr, left, mid, compare);
        merge_sort(arr, mid + 1, right, compare);
        merge(arr, left, mid, right, compare);
    }
}

void sort_records(record* records, int size, int min, int max) {
    if (!records || !size) return;

    merge_sort(records, 0, size - 1, compare_records);
}

int main() {
    const size_t offsets_size = 5000000;
    const size_t keys_size = 5000000;
    const size_t records_size = 5000000;
