// Record structure definition
typedef struct {
    int value;
} record;

// Function to generate a random number within the given range
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Quick sort function adapted from GeeksforGeeks
void quicksort(record* arr, int left, int right) {
    if (left < right) {
        int pivot_index = partition(arr, left, right);

        quicksort(arr, left, pivot_index - 1);
        quicksort(arr, pivot_index + 1, right);
    }
}

int partition(record* arr, int left, int right) {
    record pivot = arr[right];
    int i = (left - 1);

    for (int j = left; j <= right - 1; j++) {
        if (arr[j].value < pivot.value) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[right]);
    return (i + 1);
}

