typedef struct {
    double value;
    int *key;
    char *label;
    long int offset;
} dataRecord;

int initializeDataRecords(size_t inputSize, size_t *keysSize, size_t *labelsSize, size_t recordsSize, dataRecord **records) {
    double *input = malloc(inputSize * sizeof(double));
    if (!input) return 1;

    int *keys = malloc(*keysSize * sizeof(int));
    char *labels = malloc(*labelsSize * sizeof(char));
    if (!(keys && labels)) {
        free(input);
        return 1;
    }

    dataRecord *recordsArray = malloc(recordsSize * sizeof(dataRecord));
    if (!recordsArray) {
        free(input);
        free(keys);
        free(labels);
        return 1;
    }

    *records = recordsArray;

    // Read input data and initialize keys/labels arrays
    for (size_t i = 0; i < inputSize; ++i) {
        scanf("%lf", &input[i]);
        keys[i] = -1;
        labels[i] = '\0';
    }

    // Initialize data records
    size_t usedKeys = 0, usedLabels = 0;
    for (size_t i = 0; i < inputSize; ++i) {
        if (input[i] >= 0.0) continue; // Ignore positive numbers as keys

        dataRecord *record = &recordsArray[usedRecords];
        record->value = input[i];
        record->key = &keys[usedKeys++];
        record->label = &labels[usedLabels++];
        record->offset = i;
    }

    // Set keys and labels for the remaining data records
    for (size_t i = 0; i < inputSize; ++i) {
        if (input[i] >= 0.0) continue;

        dataRecord *record = &recordsArray[usedRecords++];
        int keyIndex = usedKeys++;
        char label = labels[usedLabels++];

        record->value = input[i];
        record->key = &keys[keyIndex];
        record->label = &labels[keyIndex];
        record->offset = i;

        // Set key and label for the corresponding position in the original arrays
        if (keys[keyIndex] != -1) {
            fprintf(stderr, "Error: Duplicate key value.\n");
            return 1;
        }
        keys[keyIndex] = i;
        labels[keyIndex] = label;
    }

    *keysSize = usedKeys;
    *labelsSize = usedLabels;

    // Sort data records based on their double values
    qsort(*records, usedRecords, sizeof(dataRecord), compareDataRecords);

    return 0;
}

// Compare function for qsort
int compareDataRecords(const void *a, const void *b) {
    const dataRecord *recordA = a;
    const dataRecord *recordB = b;
    return (recordA->value > recordB->value) - (recordA->value < recordB->value);
}

// Function to search for a specific double value within the dataRecords array
int binarySearch(const dataRecord *records, size_t recordsSize, double targetValue) {
    size_t left = 0;
    size_t right = recordsSize - 1;

    while (left <= right) {
        size_t mid = (left + right) / 2;

        if (records[mid].value == targetValue) return mid;

        if (records[mid].value < targetValue) left = mid + 1;
        else right = mid - 1;
    }

    return -1;
}

// Print the contents of the dataRecords array
void printDataRecords(const dataRecord *records, size_t recordsSize) {
    for (size_t i = 0; i < recordsSize; ++i) {
        printf("Value: %.2f, Key: %ld, Label: %c, Offset: %ld\n", records[i].value, *(records[i].key), *(records[i].label), records[i].offset);
    }
}

