    for (int i = 0; i < concurrencyLevel && numInitialized < recordMaxLimit; ++i) {
        int rc = pthread_create(&threads[i], NULL, initializeRecord, &dataMutex, keys, labels, values, dataRecords, &numInitialized, minVal, maxVal);
        if (rc) return -5;
