}

// Comparator functions for qsort
int intComparator(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int dataRecordComparator(const void *a, const void *b) {
    return ((dataRecord*)a->value - *(dataRecord*)b)->value;
}

// Function for initializing a single record in a separate thread
void* initializeRecord(void *args) {
    pthread_mutex_t *dataMutex = args;
    int *keys, *labels, *values, *numInitialized, minVal, maxVal;
    dataRecord *dataRecords;

    // Lock the mutex to ensure thread-safe access to shared resources
    pthread_mutex_lock(dataMutex);

    // Generate a random value within the specified range using a secure random number generator
    double currentValue = minVal + rand() / (RAND_MAX / (maxVal - minVal));

    // Set the timestamp to the current time when each record is initialized
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    int keyIndex, labelIndex;
    // Find suitable keys and labels for the new record based on availability and offset value constraints
    for (keyIndex = 0; keyIndex < *numInitialized; ++keyIndex) {
        if (abs(dataRecords[keyIndex].offset - rawtime) > INT_MAX) break;
        if (!dataRecords[keyIndex].value || dataRecords[keyIndex].key == keys[*keyIndex]) continue;
        if (keyIndex == 0 || dataRecords[keyIndex].label != dataRecords[keyIndex - 1].label) {
            labelIndex = *labels - labels + *labels++;
            break;
        }
    }
    if (keyIndex == *numInitialized) return NULL; // No suitable key or label found, skip this iteration

    int key = keys[keyIndex];
    char label = labels[labelIndex];

    // Allocate memory for the new record and set its fields
    dataRecord *newDataRecord = realloc(dataRecords, (*numInitialized + 1) * sizeof(dataRecord));
    if (!newDataRecord) return NULL; // Memory allocation failed, skip this iteration

    newDataRecord[*numInitialized].value = currentValue;
    newDataRecord[*numInitialized].key = key;
    newDataRecord[*numInitialized].label = label;
    newDataRecord[*numInitialized].offset = rawtime;

    // Increment the number of initialized records and unlock the mutex
    (*numInitialized)++;
    pthread_mutex_unlock(dataMutex);

    return (void*)newDataRecord;
}']

