};

int init_arrays(int *keys, int key_size, int *offsets, int offset_size) {
    if (key_size <= 0 || offset_size <= 0)
        return -1;

    for (int i = 0; i < key_size; ++i)
        keys[i] = i;

    for (int i = 0; i < offset_size; ++i)
