    int *records = malloc(sizeof(struct Record) * size);
    if (!records)
        return NULL;

    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % INT_MAX;
        records[i].key = NULL;
        records[i].offset = rand();
    }

