int init_array(int inputSize, int *input, int *keySize, int *keys, int *recordSize, Record **records) {
    if(!input || !keys || !recordSize || !records) return -1;

    *recordSize = inputSize;
    *records = (Record *) malloc(*recordSize * sizeof(Record));
    if(!*records) return -2;

    for(int i = 0; i < inputSize; ++i) {
        (*records + i)->value = input[i];
        (*records + i)->key = keys + i;
        (*records + i)->offset = (long) i;
    }

    qsort(*records, inputSize, sizeof(Record), compareRecords);

    return 0;
}

int find_value(int value, Record *records, int recordSize) {
    int left = 0, right = recordSize - 1;

    while(left <= right) {
        int mid = (left + right) / 2;

        if((*records + mid)->value < value) left = mid + 1;
        else if ((*records + mid)->value > value) right = mid - 1;
        else return mid;
    }

    return -1;
}

int compareRecords(const void *a, const void *b) {
    return (*(Record *) a)->value - (*(Record *) b)->value;
}

int main(int argc, char **argv) {
    if(argc < 3) return -1;

    int inputSize = atoi(argv[1]);
    int *input = (int *) malloc(inputSize * sizeof(int));
    for(int i = 0; i < inputSize; ++i) scanf("%d", input + i);

    int keySize = inputSize;
    int *keys = (int *) malloc(keySize * sizeof(int));
    if(!keys) return -2;

    Record *records;
    if(init_array(inputSize, input, &keySize, keys, NULL, &records)) return -3;

    // Print contents of records array
    printf("Contents:\n");
    for(int i = 0; i < inputSize; ++i) {
        printf("Record %d: value=%d key=%d offset=%ld\n", i, (*records + i)->value, *keys + i, (*records + i)->offset);
    }

    // Implement search and sort functions here...

    free(input);
    free(keys);
    free(records);

    return 0;
}
