const int INITIAL_TABLE_SIZE = 1024;
const float LOAD_FACTOR_THRESHOLD = 0.75f;

struct bucket {
    Record* records;
    size_t capacity;
    size_t count;
    struct bucket* next;
};

struct hash_table {
    struct bucket** table;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
};

struct hash_table* create_hash_table() {
    struct hash_table* table = malloc(sizeof(*table));
    if (!table) return NULL;

    table->size = INITIAL_TABLE_SIZE;
    table->count = 0;
    table->table = calloc(table->size, sizeof(*(table->table[0])));
    if (!table->table) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&(table->mutex), NULL);
    return table;
}

int hash(int key, size_t table_size) {
    return key % table_size;
}

void resize_hash_table(struct hash_table* table) {
    struct bucket** new_table = realloc(table->table, (table->size * 2) * sizeof(*(table->table[0])));
    if (!new_table) return;

    table->size *= 2;
    memcpy((void*)new_table + table->size, table->table, table->count * sizeof(*(table->table[0])));

    size_t i;
    for (i = 0; i < table->size; ++i) {
        struct bucket* current = table->table[i];
        if (current) {
            table->table[i] = NULL;
            while (current) {
                struct bucket* next_bucket = current->next;
                size_t j = hash(current->records[0].value, table->size * 2);
                current->next = new_table[j];
                new_table[j] = current;
                current = next_bucket;
            }
        }
    }
}

void destroy_hash_table(struct hash_table* table) {
    size_t i;
    for (i = 0; i < table->size; ++i) {
        struct bucket* current = table->table[i];
        while (current) {
            struct bucket* next_bucket = current->next;
            free(current);
            current = next_bucket;
        }
    }
    free(table->table);
    free(table);
}

Record* create_record() {
    Record* record = malloc(sizeof(*record));
    if (!record) return NULL;

    record->value = rand() % 100 + 1;
    return record;
}

int add_record(struct hash_table* table, int key, Record** records) {
    pthread_mutex_lock(&(table->mutex));

    if (find_record(table, key)) {
        pthread_mutex_unlock(&(table->mutex));
        return -1; // Duplicate key
    }

    size_t index = hash(key, table->size);
    struct bucket* current = table->table[index];
    if (!current) {
        table->table[index] = *records;
        ++(table->count);
        pthread_mutex_unlock(&(table->mutex));
        return 0;
    }

    while (current->next && current->next->value < key) current = current->next;

    if (current->next && current->next->value == key) {
        pthread_mutex_unlock(&(table->mutex));
        return -1; // Duplicate key
    }

    struct bucket* new_bucket = malloc(sizeof(*new_bucket));
    if (!new_bucket) {
        pthread_mutex_unlock(&(table->mutex));
        return -2; // Memory allocation failure
    }

    new_bucket->records = *records;
    new_bucket->capacity = 1;
    new_bucket->count = 1;
    new_bucket->next = current->next;
    current->next = new_bucket;
    ++(table->count);

    if (table->count / (float)table->size > LOAD_FACTOR_THRESHOLD) resize_hash_table(table);

    pthread_mutex_unlock(&(table->mutex));
    return 0;
}

Record* find_record(struct hash_table* table, int key) {
    pthread_mutex_lock(&(table->mutex));

    size_t index = hash(key, table->size);
    struct bucket* current = table->table[index];
    while (current && current->count > 0 && current->records[0].value != key) {
        current = current->next;
    }

    Record* result = NULL;
    if (current && current->count > 0) result = &(current->records[0]);

    pthread_mutex_unlock(&(table->mutex));
    return result;
}
