#define BUFFER_SIZE 4096

typedef struct {
    long timestamp;
    float sensor_reading;
} sensor_data;

sensor_data* read_sensor_data_file(const char *filename, size_t *timestamps_len, size_t *sensor_readings_len) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    struct stat file_stat;
    if (fstat(fd, &file_stat) == -1) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    long *timestamps = malloc(file_stat.st_size / sizeof(long));
    if (!timestamps) {
        perror("malloc");
        close(fd);
        return NULL;
    }

    float *sensor_readings = malloc(file_stat.st_size / sizeof(float));
    if (!sensor_readings) {
        perror("malloc");
        free(timestamps);
        close(fd);
        return NULL;
    }

    size_t timestamps_index = 0, sensor_readings_index = 0;
    ssize_t bytes_read;
    char buffer[BUFFER_SIZE];

    while ((bytes_read = read(fd, buffer, BUFFER_SIZE)) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (i % sizeof(long) == 0 && i + sizeof(long) <= bytes_read) {
                timestamps[timestamps_index++] = *((long*)(buffer + i));
            } else if (i % sizeof(float) == 0 && i + sizeof(float) <= bytes_read) {
                sensor_readings[sensor_readings_index++] = *((float*)(buffer + i));
            }
        }
    }

    if (bytes_read == -1) {
        perror("read");
        close(fd);
        free(timestamps);
        free(sensor_readings);
        return NULL;
    }

    if (close(fd) == -1) {
        perror("close");
    }

    *timestamps_len = timestamps_index;
    *sensor_readings_len = sensor_readings_index;

    sensor_data* data = malloc((*timestamps_len) * sizeof(sensor_data));
    if (!data) {
        perror("malloc");
        free(timestamps);
        free(sensor_readings);
        return NULL;
    }

    for (size_t i = 0; i < *timestamps_len; ++i) {
        data[i].timestamp = timestamps[i];
        data[i].sensor_reading = sensor_readings[i];
    }

    free(timestamps);
    free(sensor_readings);

    return data;
}
```

