};

const int HASH_TABLE_SIZE = 1024;
const float LOAD_FACTOR_THRESHOLD = 0.75;

int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

void* hash_insert(struct hash_table *ht, const char *key) {
    size_t index = hash(key);
    struct hash_node **chain = &ht->table[index];
    struct hash_node *node = malloc(sizeof(struct hash_node));

    if (!node) return -1; // Memory allocation failure

    node->entry.str = strdup(key);
    node->entry.value = (double)rand_range(0, 100);
    node->next = *chain;

    *chain = node;

    ht->size++;
    return 0;
}

data_entry* hash_lookup(struct hash_table *ht, const char *key) {
    size_t index = hash(key);
    struct hash_node *current = ht->table[index];

    while (current != NULL) {
        if (strcmp(current->entry.str, key) == 0) return &current->entry;
        current = current->next;
    }

    return NULL;
}

int hash(const char *key) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = (hash << 5) + hash + c; /* hash * 33 + c */
    }

    return hash % HASH_TABLE_SIZE;
}

void resize_hash(struct hash_table *ht) {
    struct hash_table new_ht;
    new_ht.table = malloc(sizeof(struct hash_node *) * (HASH_TABLE_SIZE * 2));
    new_ht.size = 0;

    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        struct hash_node *current = ht->table[i];

        while (current != NULL) {
            struct hash_node* to_insert = malloc(sizeof(struct hash_node));
            to_insert->entry = current->entry;
            to_insert->next = NULL;

            size_t index = hash(&to_insert->entry.str[0]);
            struct hash_node **chain = &new_ht.table[index];
            *chain = to_insert;

            current = current->next;
        }
    }

    free(ht->table);
    ht->table = new_ht.table;
    HASH_TABLE_SIZE *= 2;
}

