constexpr size_t INITIAL_HASH_TABLE_SIZE = 1024;
constexpr float LOAD_FACTOR_THRESHOLD = 0.7f;

struct Record {
    int value;
};

struct HashTableEntry {
    int key;
    Record* record;
    std::list<HashTableEntry> collisions;
};

class HashTable {
private:
    size_t _size;
    std::vector<HashTableEntry> _table;
    std::mutex _mutex;

public:
    explicit HashTable(size_t initSize = INITIAL_HASH_TABLE_SIZE) : _size(initSize), _table(initSize, {}) {}

    int allocateLongs(size_t n, long*& offsets) {
        offsets = new long[n];
        if (!offsets) return -1;
        std::fill(offsets, offsets + n, 0);
        return 0;
    }

    int allocateInts(size_t n, int*& keys) {
        keys = new int[n];
        if (!keys) return -1;
        std::fill(keys, keys + n, 0);
        return 0;
    }

    int allocateRecords(size_t n, Record**& records) {
        records = new Record[n];
        if (!records) return -1;
        for (Record* record : records) record->value = rand() % 100 + 50; // Random value within [50, 150]
        return 0;
    }

    int initializeHashTable(size_t n, long* offsets, int* keys, Record** records) {
        if (n > _size) resize();

        for (size_t i = 0; i < n; ++i) {
            size_t hashKey = keys[i] % _size;
            auto& entry = _table[hashKey];

            // Check for duplicate keys and handle collisions using separate chaining
            if (!std::binary_search(entry.collisions.begin(), entry.collisions.end(), keys[i])) {
                entry.key = keys[i];
                entry.record = &records[i];
            } else {
                // Handle collisions by appending the new entry to the collision list
                entry.collisions.emplace_back(keys[i], nullptr, std::move(entry.collisions));
            }
        }

        return 0;
    }

    void resize() {
        size_t newSize = _size * 2;
        auto oldTable = _table;
        _table.resize(newSize, {});

        // Transfer entries from the old table to the new one while maintaining hash consistency and handling collisions
        for (auto& entry : oldTable) {
            size_t newHashKey = entry.key % newSize;
            _table[newHashKey] = std::move(entry);
            if (!entry.collisions.empty()) {
                auto& newCollisionList = _table[newHashKey].collisions;
                newCollisionList.splice(newCollisionList.end(), entry.collisions);
            }
        }
        _size = newSize;
    }

    void freeMemory() {
        for (auto& entry : _table) {
            delete entry.record;
            for (auto& collision : entry.collisions) {
                delete collision.record;
            }
        }
        _table.clear();
    }

    int get(int key, Record** record) const {
        std::lock_guard<std::mutex> lock(_mutex);

        size_t hashKey = key % _size;
        for (const auto& entry : _table[hashKey].collisions) {
            if (entry.key == key) {
                *record = entry.record;
                return 0;
            }
        }

        if (_table[hashKey].key == key) {
            *record = &_table[hashKey].record;
            return 0;
        }
        return -1; // Key not found
    }
};
