    pthread_mutex_destroy(&rng_mutex);
    pthread_join(rng_thread, NULL);

    return records;
}

void* random_init(void* arg) {
    pthread_mutex_t* mutex = (pthread_mutex_t*)arg;
    srand((unsigned int)time(NULL)); // Initialize with current time
    pthread_mutex_lock(mutex);
    return NULL;
}
