        munmap(offsets, *offsets_len * sizeof(long));
        return -1;
    }
    total_memory += *keys_len * sizeof(int);

    if (total_memory > memory_usage_limit) {
        log_error("Total memory usage exceeded limit.", log_file);
        munmap(offsets, *offsets_len * sizeof(long));
        munmap(keys, *keys_len * sizeof(int));
        return -1;
    }

    records = malloc(*records_len * sizeof(record));
    if (!records) {
        log_error("Failed to allocate memory for records.", log_file);
        munmap(offsets, *offsets_len * sizeof(long));
        munmap(keys, *keys_len * sizeof(int));
        return -1;
    }
    total_memory += *records_len * sizeof(record);

    if (total_memory > memory_usage_limit) {
        log_error("Total memory usage exceeded limit.", log_file);
        free(records);
        munmap(offsets, *offsets_len * sizeof(long));
        munmap(keys, *keys_len * sizeof(int));
        return -1;
    }

    // Set record values to random integers within a given range.
    for (size_t i = 0; i < *records_len; ++i) {
        pthread_mutex_lock(&random_gen_mutex);
        records[i].value = rand() % MAX_INTEGER; // Change this to your desired random number generation method.
        pthread_mutex_unlock(&random_gen_mutex);
    }

    for (size_t i = 0; i < *records_len; ++i) {
        log_record_init(&records[i], log_file);
    }

    // Validate external data sources (offsets and keys) before processing them.
    if (check_data(offsets, *offsets_len * sizeof(long), "offsets") || check_data(keys, *keys_len * sizeof(int), "keys")) {
        log_error("Invalid or missing data in external sources.", log_file);
        free(records);
        munmap(offsets, *offsets_len * sizeof(long));
        munmap(keys, *keys_len * sizeof(int));
        return -1;
    }

    // Adjust the number of records to process based on validated data.
    if (*records_len > *offsets_len || *records_len > *keys_len) {
        *records_len = *offsets_len < *keys_len ? *offsets_len : *keys_len;
    }

    return 0;
}
