void read_data(FILE **files, long *offsets, int *keys, float *values, char **strings, size_t *num_records, pthread_mutex_t *mutex) {
    for (size_t i = 0; i < *num_records; ++i) {
        if (!(*files)) return; // Check if any file is invalid before reading

        fscanf(*files, "%ld%d%f", offsets + i, keys + i, values + i);
        char str[256];
        fgets(str, sizeof(str), *files);
        strings[i] = (char*)malloc((strlen(str) + 1) * sizeof(char));
        strcpy(strings[i], str);

        if (fgetc(*files) != EOF || i != (*num_records - 1)) { // Check for newline character or end of file
            fprintf(stderr, "Invalid data format\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(mutex);
        if ((*keys)[i] != (*offsets + i - 1) + 1 || !(*values >= 0.0 && *values <= 100.0)) { // Check for data consistency
            fprintf(stderr, "Data inconsistency detected\n");
            exit(EXIT_FAILURE);
        }
        pthread_mutex_unlock(mutex);
    }
}

dataRecord* init_data(size_t num_records, FILE **files, pthread_mutex_t *mutex) {
    dataRecord *data = (dataRecord*)malloc(num_records * sizeof(dataRecord));
    long *offsets = NULL;
    int *keys = NULL;
    float *values = NULL;
    char **strings = NULL;
    size_t current_record = 0;

    // Allocate memory for offsets, keys, values and strings
    offsets = (long*)calloc(num_records, sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    values = (float*)malloc(num_records * sizeof(float));
    strings = (char**)malloc(num_records * sizeof(char*));

    read_data(files, offsets, keys, values, strings, &num_records, mutex);

    for (size_t i = 0; i < num_records; ++i) {
        data[i].key = keys[i];
        data[i].value = values[i];
        data[i].str_ptr = strings[i];

        // Set random int and float field values for each record (optional)
        if (1) {
            data[i].key = rand() % 100 + 1;
            data[i].value = (float)(rand() % 100 + 1) / 100.0;
        }
    }

    // Free allocated memory for offsets, keys, values and strings (optional)
    free(offsets);
    free(keys);
    free(values);
    for (size_t i = 0; i < num_records; ++i) {
        free(strings[i]);
    }
    free(strings);

    return data;
}
```

