#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    const int *key;
    const char *label;
    long offset;
} dataRecord;

int read_and_initialize(const int max_doubles, FILE *input, int *keys, const char **labels, dataRecord **dataRecords, long *offsets) {
    if (!input || !max_doubles || !keys || !labels || !dataRecords || !offsets)
        return -1;

    rewind(input);
    double *numbers = malloc(sizeof(double) * max_doubles);
    if (!numbers) {
        perror("Failed to allocate memory for numbers");
        return -1;
    }

    int count = 0;
    while (fscanf(input, "%lf", numbers + count++) == 1 && count < max_doubles);

    if (count != max_doubles) {
        free(numbers);
        return -2; // Insufficient or too many input values
    }

    *dataRecords = malloc(sizeof(dataRecord) * count);
    if (!*dataRecords) {
        perror("Failed to allocate memory for dataRecords");
        free(numbers);
        return -1;
    }

    *offsets = malloc(sizeof(long) * count);
    if (!*offsets) {
        perror("Failed to allocate memory for offsets");
        free(dataRecords);
        free(numbers);
        return -1;
    }

    *keys = malloc(sizeof(int) * count);
    if (!*keys) {
        perror("Failed to allocate memory for keys");
        free(*dataRecords);
        free(*offsets);
        free(numbers);
        return -1;
    }

    *labels = malloc(sizeof(char *) * count);
    if (!*labels) {
        perror("Failed to allocate memory for labels");
        free(*dataRecords);
        free(*offsets);
        free(*keys);
        free(numbers);
        return -1;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < count; ++i) {
        (*dataRecords + i)->value = numbers[i] + RAND_MAX * rand() / RAND_MAX; // Generate random values within [number, number + RAND_MAX] range
        (*keys + i) = i; // Set key to the index of dataRecord
        (*labels + i) = (const char *)malloc(strlen("Record ") + 10); // Create label for each record with a unique identifier
        sprintf((*labels + i), "Record %ld", i + 1);
        (*offsets + i) = rand() % RAND_MAX; // Set offset to a random value up to RAND_MAX
    }

    qsort(*dataRecords, count, sizeof(dataRecord), (int(*)(const void *, const void *))compareDoubleValues); // Sort the dataRecords array based on double values

    free(numbers);

    return 0;
}

int compareDoubleValues(const void *a, const void *b) {
    return (*(dataRecord *)a)->value - (*(dataRecord *)b)->value;
}

int binary_search(dataRecord array[], int size, double value, int *result_index) {
    int left = 0;
    int right = size - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (array[mid].value < value)
            left = mid + 1;
        else if (array[mid].value > value)
            right = mid - 1;
        else {
            *result_index = mid;
            return 0; // Found the value
        }
    }

    *result_index = -1; // Value not found
    return -1;
}

void print_dataRecords(const dataRecord *data, const int size) {
    for (int i = 0; i < size; ++i) {
        printf("Record %d: key=%ld label=\"%s\" value=%.6f offset=%ld\n", i + 1, *(const long *)data[i].key, data[i].label, data[i].value, data[i].offset);
        data += i + 1; // Advance the pointer to skip printed record and continue printing the next one
    }
}
```

