        return -5;
    }
    memset(*timestamps, 0, inputSize * sizeof(time_t));

    // Allocate memory for databaseRecord array and initialize outputSize
    size_t recordSize = (inputSize + 1) * sizeof(databaseRecord);
    databaseRecord *records = malloc(recordSize);
    if (records == NULL) {
        free(*data);
        free(*keys);
        free(*labels);
        free(*timestamps);
        perror("Failed to allocate memory for records");
        return -6;
    }

    // Initialize databaseRecord array
    for (size_t i = 0; i < inputSize; ++i) {
        records[i].value = *data[i];
        records[i].key = &keys[i];
        records[i].label = &labels[i];
        records[i].timestamp = &timestamps[i];
        records[i].offset = 0;
    }
    records[inputSize].value = -1; // sentinel value to mark end of data
    *outputSize = inputSize + 1;

    qsort(records, *outputSize, sizeof(databaseRecord), (int (*)(const void*, const void*))compareDoubles);

    printf("Database records:\n");
    for (size_t i = 0; i < *outputSize; ++i) {
        if (i != 0) printf("\n");
        printf("%f (%d, %c, %ld)\n", records[i].value, *(records[i].key), *(records[i].label), records[i].offset);
    }

    return 0;
}

int compareDoubles(const void *a, const void *b) {
    return (*(double*)a - *(double*)b);
}
