#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <limits.h>

typedef struct Record {
    int key;
    int value;
} Record;

enum ErrorCodes {
    NO_ERROR = 0,
    MEMORY_ALLOCATION_FAILURE = -1,
    OUT_OF_RANGE_ERROR = -2,
    INSUFFICIENT_MEMORY_ERROR = -3,
    EXTERNAL_DATA_SOURCE_FAILURE = -4
};

void log_error(int error_code) {
    switch (error_code) {
        case MEMORY_ALLOCATION_FAILURE:
            printf("Memory allocation failure\n");
            break;
        case OUT_OF_RANGE_ERROR:
            printf("Value out of range\n");
            break;
        case INSUFFICIENT_MEMORY_ERROR:
            printf("Insufficient memory for required operations\n");
            break;
        case EXTERNAL_DATA_SOURCE_FAILURE:
            printf("Error with external data source\n");
            break;
    }
}

int create_record_system(Record** records, int* offsets, int* keys, int max_records, int min_value, int max_value, int* memory_used) {
    *memory_used = 0;
    if (max_records <= 0 || max_value < min_value) {
        return EXTERNAL_DATA_SOURCE_FAILURE;
    }

    *offsets = calloc(max_records, sizeof(int));
    if (*offsets == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    *keys = calloc(max_records, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return MEMORY_ALLOCATION_FAILURE;
    }

    *records = malloc(sizeof(Record) * max_records);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return MEMORY_ALLOCATION_FAILURE;
    }

    srand(time(NULL));
    int record_index = 0;
    for (int i = 0; i < *memory_used && record_index < max_records; ++i) {
        if (keys[i] != 0) continue; // Skip filled records
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        offsets[record_index] = i;
        (*records + record_index)->key = keys[i];
        (*records + record_index++)->value = rand() % (max_value - min_value + 1) + min_value;
        (*memory_used)++;
    }

    if (record_index >= max_records) { // If there's no room for a new record, resize memory
        Record* temp = realloc(*records, sizeof(Record) * (*memory_used * 2));
        if (temp == NULL) {
            free(*offsets);
            free(*keys);
            free(*records);
            return INSUFFICIENT_MEMORY_ERROR;
        }
        *records = temp;
    }

    return NO_ERROR;
}
