#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int intValue;
    double floatValue;
    char* word;
} data_record;

void initializeData(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t offsetCount = 0;
    long *offsets = NULL;
    size_t keyCount = 0;
    int *keys = NULL;
    size_t floatCount = 0;
    double *floats = NULL;
    size_t recordCount = 0;
    data_record *records = NULL;

    char word[256]; // buffer for reading words from CSV file
    char **words = NULL; // list of predefined words
    size_t wordCount = 0;

    size_t lineNumber = 0;
    int columnCount = 0;

    while ((columnCount < 6) && (fscanf(file, "%[^,],%" columnCount "*s", word, &word[0]) == columnCount + 1)) {
        lineNumber++;

        if (columnCount > 0) { // skip first row which has field names
            if (!strcmp(word, "")) {
                continue; // ignore missing columns
            }

            switch (columnCount) {
                case 1:
                    offsets = realloc(offsets, ++offsetCount * sizeof(long));
                    sscanf(word, "%ld", &offsets[offsetCount - 1]);
                    break;
                case 2:
                    keys = realloc(keys, ++keyCount * sizeof(int));
                    sscanf(word, "%d", &keys[keyCount - 1]);
                    break;
                case 3:
                    floats = realloc(floats, ++floatCount * sizeof(double));
                    sscanf(word, "%lf", &floats[floatCount - 1]);
                    break;
                case 4: // intValue
                    records = realloc(records, ++recordCount * sizeof(data_record));
                    sscanf(word, "%d", &(records[recordCount - 1]).intValue);
                    break;
                case 5: // floatValue
                    records = realloc(records, recordCount * sizeof(data_record));
                    sscanf(word, "%lf", &(records[recordCount - 1]).floatValue);
                    break;
                default: // word
                    words = realloc(words, ++wordCount + 1);
                    strcpy(words[wordCount], word);
            }
        }
    }

    if (columnCount != 6) {
        fprintf(stderr, "Error: Unexpected number of columns in CSV file\n");
    }

    // Ensure enough memory for the last record's string field
    records = realloc(records, ++recordCount * sizeof(data_record));

    if (wordCount > 0) { // select random word for the last record
        size_t randIndex = (size_t)(rand() % wordCount);
        records[recordCount - 1].word = strdup(words[randIndex]);
    } else {
        records[recordCount - 1].word = NULL; // no predefined words, set the last record's string field to NULL
    }

    fclose(file);

    // Free allocated memory and return pointers
    free(words);
}
```

This implementation reads the CSV file line by line, allocating dynamic memory as needed for each column. If a column is missing or extra, it will skip over it gracefully. The function also handles potential errors such as file I/O issues and malformed data. Additionally, it uses an efficient approach to handle large datasets without consuming excessive memory using realloc().']

