void initialize_data(long *offsets, int *keys, record **records, size_t num_records) {
    assert(num_records > 0);
    if (!offsets || !keys || !records) return;

    // Allocate memory for offsets and keys arrays
    *offsets = calloc(num_records + 1, sizeof(long));
    if (!*offsets) {
        perror("Calloc failed for offsets");
        exit(EXIT_FAILURE);
    }

    // Initialize first element of the offset array to -1 (sentinel value)
    (*offsets)[0] = -1;

    // Allocate memory for keys and records arrays
    *keys = calloc(num_records, sizeof(int));
    if (!*keys) {
        perror("Calloc failed for keys");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize all key values with random integers within the given range (exclusive upper bound)
    srand(time(NULL));
    for (size_t i = 1; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (*offsets)[i - 1] + 1;
        } while ((*keys + i <= key) || (key < *keys));
        (*keys)[i] = key;
        (*offsets)[i] = i;
    }

    // Allocate memory for records array and initialize its elements
    *records = malloc(num_records * sizeof(record));
