#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

typedef struct Record {
    int value;
} Record;

int check_input(size_t num_records, size_t max_array_size, size_t min_value, size_t max_value) {
    if (num_records == 0 || max_array_size > 1e6/2 || max_value < min_value || num_records*(sizeof(long) + sizeof(int) + sizeof(Record)) > max_array_size) {
        return -1; // Invalid input
    }
    return 0; // Valid input
}

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void **mem_ptr) {
    if (*mem_ptr) {
        free(*mem_ptr);
        *mem_ptr = NULL;
    }
}

int* create_key_array(size_t size) {
    return (int*)allocate_memory(sizeof(int) * size);
}

long* create_offset_array(size_t size) {
    return (long*)allocate_memory(sizeof(long) * size);
}

Record* create_record_array(size_t size) {
    return (Record*)allocate_memory(sizeof(Record) * size);
}

int main() {
    srand(time(NULL));

    size_t num_records, max_array_size;
    size_t min_value, max_value;

    printf("Enter the number of records: ");
    scanf("%zu", &num_records);

    printf("Enter the maximum array size (in bytes): ");
    scanf("%zu", &max_array_size);

    printf("Enter the minimum value for each record's int field: ");
    scanf("%zu", &min_value);

    printf("Enter the maximum value for each record's int field: ");
    scanf("%zu", &max_value);

    int error = check_input(num_records, max_array_size, min_value, max_value);
    if (error) {
        fprintf(stderr, "Invalid input. Exiting...\n");
        return EXIT_FAILURE;
    }

    int *keys = create_key_array(num_records);
    long *offsets = create_offset_array(num_records + 1);
    Record *records = create_record_array(num_records);

    // Initialize keys and offsets
    for (size_t i = 0; i < num_records + 1; ++i) {
        offsets[i] = i;
        if (i < num_records) {
            keys[i] = rand() % (max_value - min_value + 1) + min_value;
        }
    }

    // Sort offsets to ensure uniqueness and facilitate linear search for record keys
    qsort(offsets, num_records + 1, sizeof(long), (int (*)(const void *, const void *))compare_long);

    // Assign records based on sorted offsets
    for (size_t i = 0; i < num_records; ++i) {
        size_t j = lower_bound(offsets, num_records + 1, keys[i]) - offsets;
        if (j != num_records) {
            records[j].value = rand() % (max_value - min_value + 1) + min_value;
            keys[i] = j;
        }
    }

    // Free allocated memory when not needed
    free_memory((void**)&keys);
    free_memory((void**)&offsets);
    free_memory((void**)&records);

    return EXIT_SUCCESS;
}

int compare_long(const void *a, const void *b) {
    return (*(const long *)a - *(const long *)b);
}

size_t lower_bound(long* arr, size_t n, int x) {
    size_t left = 0;
    size_t right = n;

    while (left < right) {
        size_t mid = (left + right) / 2;
        if (arr[mid] == x) {
            return mid;
        } else if (arr[mid] < x) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    return left;
}
```
