#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <limits.h>

typedef struct Record {
    int value;
} Record;

void init_arrays(long* offsets, int* keys, Record** records, size_t* capacity, size_t* used, FILE* data) {
    if (!data || !capacity || !used) {
        fprintf(stderr, "Invalid parameters\n");
        exit(EXIT_FAILURE);
    }

    *used = 0;
    *capacity = 100000;
    offsets = realloc(offsets, *capacity * sizeof(long));
    keys = realloc(keys, *capacity * sizeof(int));
    records = realloc(records, *capacity * sizeof(Record));

    long current_offset = 0;
    while (!feof(data)) {
        int key, record_value;
        fscanf(data, "%d %d", &key, &record_value);

        if (ferror(data)) {
            fprintf(stderr, "Error reading data\n");
            exit(EXIT_FAILURE);
        }

        // Validate key and record_value within a given range
        if ((key < 1 || key > INT_MAX) || (record_value < -INT_MAX || record_value > INT_MAX)) {
            continue;
        }

        offsets[*used] = current_offset;
        keys[*used] = key;
        records[*used].value = record_value;
        (*used)++;

        if (*used == *capacity) {
            *capacity *= 2;
            offsets = realloc(offsets, *capacity * sizeof(long));
            keys = realloc(keys, *capacity * sizeof(int));
            records = realloc(records, *capacity * sizeof(Record));
        }

        current_offset += sizeof(Record) + (key - 1);
    }
}

void sort(Record* records, int* keys, size_t used) {
    for (size_t i = 0; i < used - 1; ++i) {
        for (size_t j = i + 1; j < used; ++j) {
            if (keys[i] > keys[j]) {
                Record temp = records[i];
                int key_temp = keys[i];
                keys[i] = keys[j];
                records[i] = records[j];
                keys[j] = key_temp;
                records[j] = temp;
            }
        }
    }
}

void set_random(Record* records, size_t used) {
    srand(time(NULL));
    for (size_t i = 0; i < used; ++i) {
        records[i].value = rand() % 100 + 1; // Range: [1, 100]
    }
}

int main(int argc, char* argv[]) {
    FILE* data = fopen("data.txt", "r");
    if (!data) {
        fprintf(stderr, "Error opening data file\n");
        return EXIT_FAILURE;
    }

    long* offsets = NULL;
    int* keys = NULL;
    Record** records = NULL;
    size_t capacity, used;
    init_arrays(offsets, keys, records, &capacity, &used, data);

    sort(records, keys, used);
    set_random(records, used);

    for (size_t i = 0; i < used; ++i) {
        printf("Record %zu: value=%d key=%d offset=%ld\n", i, records[i].value, keys[i], offsets[i]);
    }

    free(offsets);
    free(keys);
    for (size_t i = 0; i < used; ++i) {
        free(records[i]);
    }
    free(records);
    fclose(data);

    return EXIT_SUCCESS;
}
