#include <string.h>
#include <time.h>
#include <sys/mman.h>
#include <limits.h>

typedef struct Record {
    int key;
    char *str;
    union {
        struct Record *next_record;
        int integer;
    } u;
} Record;

typedef struct DataStructure {
    Record *records;
    long *offsets; // 64-byte aligned
    int *keys;
    size_t capacity;
    size_t size;
} DataStructure;

static void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

DataStructure init_data_structure(size_t max_records) {
    DataStructure ds = {NULL, NULL, NULL, 0, 0};

    align_up(max_records, sizeof(long)) // Align to 64-byte boundary
    size_t offsets_capacity = align_up(max_records * sizeof(Record), 64);
    ds.offsets = mmap(NULL, offsets_capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ds.offsets == MAP_FAILED) {
        log_error("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    align_up(max_records * sizeof(int), 4) // Align to 4-byte boundary
    ds.keys = calloc(max_records, sizeof(int));
    if (!ds.keys) {
        log_error("Failed to allocate memory for keys");
        munmap(ds.offsets, offsets_capacity);
        exit(EXIT_FAILURE);
    }

    ds.records = (Record*)((size_t)ds.offsets + offsets_capacity - max_records * sizeof(Record));
    if ((size_t)ds.records % 64 != 0) {
        log_error("Failed to allocate memory for records with correct alignment");
        free(ds.keys);
        munmap(ds.offsets, offsets_capacity);
        exit(EXIT_FAILURE);
    }

    ds.capacity = max_records;
    ds.size = 0;
    return ds;
}

void set_random_record_values(DataStructure *ds, size_t count) {
    srand(time(NULL));

    for (size_t i = 0; i < count && ds->size < ds->capacity; ++i) {
        Record *record = &ds->records[ds->size];
        record->key = rand() % INT_MAX;
        record->str = calloc(32, sizeof(char)); // Assume maximum length of string is 32 characters

        if (rand() % 2 == 0) {
            record->u.integer = rand() % INT_MAX;
        } else {
            size_t next_index = (ds->size + 1) % ds->capacity;
            Record *next_record = &ds->records[next_index];
            record->u.next_record = next_record;
        }

        // Update offset and key values
        long offset = align_up((size_t)&record->key, 64);
        memcpy(ds->offsets + (ds->size - ds->capacity), &offset, sizeof(long));
        ds->keys[ds->size] = record->key;

        // Update data structure size
        ds->size++;
    }
}

// ... Implement resizing and logging functions as needed.
