// Function to generate random numbers without duplicates
int uniqueRandom(int limit) {
    static int *generatedNumbers = NULL;
    static int generatedNumberCount = 0;
    static int numberIndex = 0;

    // Allocate memory for generated numbers if not already done
    if (!generatedNumbers) {
        generatedNumbers = malloc(INT_MAX * sizeof(int));
        if (!generatedNumbers) return -1;
    }

    // Check if the requested number has been generated before
    if (generatedNumberCount < generatedNumbers[numberIndex]) {
        numberIndex = (numberIndex + 1) % INT_MAX;
        generatedNumbers[numberIndex]++;
        generatedNumberCount++;
    }

    // Generate a random number within the specified limit and ensure it has not been previously generated
    int number = (generatedNumberCount < limit) ? generatedNumberCount : rand() % limit;
    while (generatedNumbers[number] >= limit) {
        number = (number + 1) % INT_MAX;
    }

    return number;
}
