            perror("Memory allocation for offsets failed");
            free(records);
            return NULL;
        }

        records[i].values = malloc(value_size * sizeof(double));
        if (!records[i].values) {
            perror("Memory allocation for values failed");
            free(records[i].offsets);
            free(records);
            return NULL;
        }
    }

    return records;
}

void print_record(const Record *record) {
    printf("Key: %d\n", record->key);
    printf("Offsets: [");
    for (size_t i = 0; i < array_size(record->offsets); ++i) {
        if (i != 0) printf(", ");
        printf("%ld", record->offsets[i]);
    }
    printf("]\nValues: [");
    for (size_t i = 0; i < array_size(record->values); ++i) {
        if (i != 0) printf(", ");
        printf("%f", record->values[i]);
    }
    printf("]\n");
}

// Helper function for calculating the size of an array-like object
size_t array_size(const void* arr) {
    return *(size_t*)((char*)arr + sizeof(void*) - sizeof(size_t));
}
