int read_float_list(double **array, int *size) {
    double num;
    if (fscanf(stdin, "%lf", &num) != 1)
        return -1; // invalid input

    *size = 1;
    *array = malloc(*size * sizeof(double));
    if (!*array)
        return -2; // memory allocation failure
    (*array)[0] = num;

    while (fscanf(stdin, " %lf", &num) == 1) {
        *size += 1;
        double *tmp = realloc(*array, *size * sizeof(double));
        if (!tmp) {
            free(*array);
            return -2; // memory allocation failure
        }
        (*array) = tmp;
        (*array)[*size - 1] = num;
    }

    return 0; // success
}

int allocate_arrays(long *offsets, int *keys, dataRecord **records, long num_records) {
    offsets = malloc(num_records * sizeof(long));
    if (!offsets)
        return -2; // memory allocation failure

    keys = malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return -2; // memory allocation failure
    }

    records = malloc(num_records * sizeof(dataRecord));
    if (!records) {
        free(keys);
        free(offsets);
        return -2; // memory allocation failure
    }

    return 0; // success
}

int generate_random_offset(long min, long max) {
    static long seed = time(NULL);
    unsigned long result;

    // Use xorshift128+ for random number generation
    seed = seed * 2654435761 + 12345;
    result = (seed >> 18) ^ (seed << 31) ^ (seed >> 33);
    result *= 0xbfb1066d;
    result = result * (result | 1) + (result >> 11);

    return (result % (max - min + 1)) + min;
}

