            fprintf(stderr, "Memory allocation failure\n");
            exit(1); // exit on failure
        }

        records[i]->value = array[i];
        records[i]->key = &keys[i];
        records[i]->label = labels + strlen(labels) - (strlen(labels) - strlen(labels + i));
        records[i]->offset = generate_random_offset(0, 1000000000L);
    }
}

