#include <unistd.h>

typedef struct File {
    char* path;
    size_t size;
    char* content;
} File;

int read_files(File** files, size_t* files_size, int fd, off_t file_size) {
    if (!files || !files_size) return -1;

    *files = realloc(*files, (*files_size + 1) * sizeof(File));
    if (!*files) return -1;

    File* file = &((*files)[*files_size]);
    file->path = strdup(fd >= 0 ? "/dev/fd" : "");
    file->content = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);

    if (!file->content) {
        free(file->path);
        return -1;
    }

    file->size = file_size;
    ++(*files_size);

    return 0;
}

void print_files(File* files, size_t files_size) {
    for (size_t i = 0; i < files_size; ++i) {
        printf("Path: %s\n", files[i].path);
        printf("Size: %zu bytes\n", files[i].size);
        printf("Content:\n%s\n", files[i].content);
    }
}
