void init_arrays(int* sizes, size_t num_sizes, double** data, int** keys, Node*** nodes, Record** records, const int min, const int max) {
    for (size_t i = 0; i < num_sizes; ++i) {
        sizes[i] = (sizes[i] == 0) ? 1 : sizes[i];
    }

    *data = malloc(sizeof(double) * sizes[0]);
    if (*data == NULL) {
        perror("Memory allocation error for data array.");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 1; i < num_sizes; ++i) {
        *data = realloc(*data, sizeof(double) * sizes[i] + sizeof(double) * (i - 1));
        if (*data == NULL) {
            perror("Memory allocation error for data array.");
            exit(EXIT_FAILURE);
        }
    }

    *keys = malloc(sizeof(int) * sizes[1]);
    if (*keys == NULL) {
        perror("Memory allocation error for keys array.");
        exit(EXIT_FAILURE);
    }

    *nodes = malloc(sizeof(Node*) * sizes[2]);
    if (*nodes == NULL) {
        perror("Memory allocation error for nodes array.");
        exit(EXIT_FAILURE);
    }

    *records = malloc(sizeof(Record) * sizes[3]);
    if (*records == NULL) {
        perror("Memory allocation error for records array.");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < sizes[3]; ++i) {
        (*records + i)->key = keys[(keys > data) ? 1 : 0][i];
        (*records + i)->value = (*data)[(*records + i)->key];
        if (sizes[2] > 1) {
            (*records + i)->node_ptr = (*nodes + (*records + i)->key);
            if ((*records + i)->node_ptr == NULL) {
                (*records + i)->node_ptr = malloc(sizeof(Node));
                if ((*records + i)->node_ptr == NULL) {
                    perror("Memory allocation error for node.");
                    exit(EXIT_FAILURE);
                }
                (*records + i)->node_ptr->value = rand() % (max - min + 1) + min;
                (*records + i)->node_ptr->next = *nodes[(nodes > data) ? 2 : 1];
                if ((*nodes + 2)[i] != NULL) {
                    (*nodes + 2)[i]->next = (*records + i)->node_ptr;
                }
            } else {
                (*records + i)->node_ptr->value = rand() % (max - min + 1) + min;
            }
        }
    }
}
