bool read_data(int *keys, double *numbers, Node **nodes, FILE *file) {
    int i = 0;
    int key;
    double number;
    Node *current_node = NULL;
    Node *new_node = NULL;

    while (!feof(file)) {
        if (fscanf(file, "%d %lf", &key, &number) != 2) {
            fprintf(stderr, "Invalid data format: %s\n", strerror(errno));
            return false;
        }

        // Allocate memory for new node and initialize it
        new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation error");
            return false;
        }
        new_node->value = key;
        new_node->next = NULL;

        // Check if we have reached the array size limit
        if (i >= MAX_ARRAY_SIZE) {
            fprintf(stderr, "Array size limit exceeded\n");
            return false;
        }

        // Update pointers for current and next nodes
        current_node->next = new_node;
        current_node = new_node;

        // Store the data in the arrays
        keys[i] = key;
        numbers[i++] = number;
    }

    // Make sure we are at the end of the file
    if (feof(file)) {
        return true;
    } else {
        fprintf(stderr, "Unexpected end of file\n");
        return false;
    }
}

