        perror("Memory allocation error");
        goto cleanup;
    }
    keys = malloc(keys_size * sizeof(int));
    if (!keys) {
        perror("Memory allocation error");
        goto cleanup;
    }
    records = malloc((keys_size + 1) * sizeof(Record)); // Extra space for sentinel node
    if (!records) {
        perror("Memory allocation error");
        goto cleanup;
    }

    // ... Implement additional functionality such as sorting or filtering here

cleanup:
