        (*data)[*num]->key = (*keys)[*num];
        (*data)[*num]->label = (*labels)[*num];
        (*data)[*num]->integer_field = 0;

        (*num)++;
    }
}

void randomizeData(int num, dataRecord *data, double min, double max) {
    if (num <= 0 || data == NULL) {
        fprintf(stderr, "Invalid arguments.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    for (int i = 0; i < num; ++i) {
        data[i]->value = min + (rand() % static_cast<int>((max - min) * RAND_MAX)) / RAND_MAX * (max - min);
    }
}

void printData(int num, dataRecord *data) {
    if (num <= 0 || data == NULL) {
