    }
}

int compareFunc(const void *a, const void *b) {
    return (*static_cast<const dataRecord*>(a)->value - *static_cast<const dataRecord*>(b)->value);
}

bool searchValue(int num, dataRecord *data, double value, int *resultIndex) {
    if (num <= 0 || data == NULL || resultIndex == NULL) {
        return false;
    }

    int left = 0;
    int right = num - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (*(data[mid]->value) == value) {
            *resultIndex = mid;
            return true;
        } else if (*(data[mid]->value) < value) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    *resultIndex = -1;
    return false;
}

void freeData(int num, dataRecord **data) {
    if (num <= 0 || data == NULL) {
        return;
    }

    for (int i = 0; i < num; ++i) {
        free((*data)[i]->key);
        free((*data)[i]->label);
        free(*data + i);
    }
}
