#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
    int *key;
    int offset;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct HashTable {
    int capacity;
    float load_factor;
    int size;
    Node **nodes;
    pthread_mutex_t lock;
} HashTable;

HashTable create_hash_table(int capacity, float load_factor) {
    HashTable table = {capacity, load_factor, 0, NULL, PTHREAD_MUTEX_INITIALIZER};
    table.nodes = calloc(capacity, sizeof(Node *));
    return table;
}

Record* create_record(int value, int key) {
    Record *record = malloc(sizeof(Record));
    record->value = value;
    record->key = &key;
    return record;
}

int hash_function(HashTable table, int key) {
    return key % table.capacity;
}

void insert_record(HashTable *table, Record *record) {
    pthread_mutex_lock(&table->lock);

    Node **node_ptr = &table->nodes[hash_function(*table, *(record->key))];
    Node *current_node = *node_ptr;

    if (!*node_ptr) {
        *node_ptr = malloc(sizeof(Node));
        *node_ptr)->record = record;
    } else {
        current_node = *node_ptr;

        while (current_node->next) {
            current_node = current_node->next;
        }

        current_node->next = malloc(sizeof(Node));
        current_node = current_node->next;
        current_node->record = record;
    }

    pthread_mutex_unlock(&table->lock);
}

int main() {
    int array_size, capacity, load_factor;
    scanf("%d %d %d", &array_size, &capacity, &load_factor);

    HashTable table = create_hash_table(capacity, load_factor);

    int *input_arr = malloc(array_size * sizeof(int));

