void readCSV(char* filename, int* offsets, int* keys, float* v1, float* v2, dataRecord** records, int* count) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    char line[256];
    int i = 0, j = 0, offsetIndex = 0, recordCount = 0;

    while (fgets(line, sizeof(line), file)) {
        i = 0;
        dataRecord* currentRecord = &records[recordCount];
        if (recordCount == MAX_RECORDS) break; // handle max records here

        while (line[i]) {
            if ((line[i] == '\t') || (line[i] == ',')) {
                line[i] = '\0';
                ++j;

                switch (j) {
                    case offsetIndex:
                        offsets[offsetIndex] = atoi(strtok(line, "\t,\r\n"));
                        break;
                    case 1:
                        keys[recordCount] = atoi(strtok(NULL, "\t,\r\n"));
                        break;
                    case 2:
                        currentRecord->value1 = (float)atof(strtok(NULL, "\t,\r\n"));
                        break;
                    case 3:
                        currentRecord->value2 = (float)atof(strtok(NULL, "\t,\r\n"));
                        break;
                    default: // handle extra columns here
                }
            }
            ++i;
        }
        if (offsetIndex < offsets[offsetIndex]) {
            offsets[offsetIndex] = -1;
        } else {
            ++offsetIndex;
        }
        currentRecord->data = strdup(strtok(NULL, "\t,\r\n"));
        recordCount++;
    }
    fclose(file);

    sort(offsets, offsetIndex + 1);
}

void cleanup(dataRecord* records, int recordCount) {
