    int binarySearch(double targetValue, dataRecord arr[], size_t len) {
        size_t left = 0;
        size_t right = len - 1;
        size_t mid;

        while (left <= right) {
            mid = left + (right - left) / 2;

            if (arr[mid].value < targetValue)
                left = mid + 1;
            else if (arr[mid].value > targetValue)
                right = mid - 1;
            else
                return mid; // Found the target value
