#define HASH_TABLE_INITIAL_CAPACITY 100
#define RECORD_SIZE sizeof(struct Record)

typedef struct {
    int key;
    void *data;
} HashEntry;

typedef struct Record {
    int value;
} Record;

typedef struct HashTable {
    unsigned long offsets[HASH_TABLE_INITIAL_CAPACITY];
    HashEntry entries[HASH_TABLE_INITIAL_CAPACITY];
    size_t capacity;
    size_t num_entries;
} HashTable;

HashTable *create_hash_table() {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    ht->capacity = HASH_TABLE_INITIAL_CAPACITY;
    ht->num_entries = 0;
    return ht;
}

size_t hash(int key, size_t capacity) {
    return (key % capacity);
}

void rehash(HashTable *ht) {
    HashTable *new_ht = create_hash_table();
    new_ht->capacity *= 2;
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->offsets[i] != -1) {
            HashEntry *entry = &ht->entries[ht->offsets[i]];
            size_t index = hash(entry->key, new_ht->capacity);
            new_ht->offsets[index] = ht->num_entries++;
            new_ht->entries[new_ht->offsets[index]] = *entry;
        }
    }
    free(ht);
    ht = new_ht;
}

void allocate_arrays(HashTable *ht, long *offsets, int *keys, Record **records, size_t num_entries) {
    offsets = (long *)calloc(num_entries, sizeof(long));
    keys = (int *)calloc(num_entries, sizeof(int));
    records = (Record *)malloc(num_entries * RECORD_SIZE);
}

void init_records(HashTable *ht, int min_value, int max_value) {
    srand(time(NULL));
    for (size_t i = 0; i < ht->num_entries; ++i) {
        Record *record = &records[ht->offsets[i]];
        record->value = min_value + rand() % (max_value - min_value + 1);
    }
}

void insert(HashTable *ht, int key, void *data) {
    size_t index = hash(key, ht->capacity);
    while (ht->offsets[index] != -1 && ht->entries[ht->offsets[index]].key != key) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->offsets[index] == -1) {
        ht->offsets[index] = ht->num_entries++;
        ht->entries[ht->offsets[index]].key = key;
        ht->entries[ht->offsets[index]].data = data;
    } else {
        HashEntry *entry = &ht->entries[ht->offsets[index]];
        if (entry->key == key) {
            entry->data = data;
        }
    }
}

void *find(HashTable *ht, int key) {
    size_t index = hash(key, ht->capacity);
    while (ht->offsets[index] != -1 && ht->entries[ht->offsets[index]].key != key) {
        index = (index + 1) % ht->capacity;
    }

    if (ht->offsets[index] == -1) {
        return NULL;
    }

    return ht->entries[ht->offsets[index]].data;
}

void free_hash_table(HashTable *ht) {
    free(ht->entries);
    free(ht);
}

int main() {
    HashTable *ht = create_hash_table();
    long offsets[0];
    int keys[0];
    Record records[0];
    size_t num_entries = 1000;
    allocate_arrays(ht, offsets, keys, &records, num_entries);

    // Load data from external sources...

    insert(ht, 1, &records[0]);
    insert(ht, 2, &records[1]);
    // ... and insert more key-value pairs as needed.

    init_records(ht, 1, 100);

    // Access records using the find function...
    void *record = find(ht, 1);
    printf("The record for key 1 has value: %d\n", ((Record *)record)->value);

    free_hash_table(ht);

    return 0;
}
