int* create_offset_array(size_t size) {
    int *offsets = memalign(sizeof(int), size * sizeof(int));
    if (!offsets) {
        log_allocation_failure("Failed to allocate offset array.");
        return NULL;
    }
    return offsets;
}

int find_next_offset(int *offsets, size_t current_offset) {
    size_t i;
    for (i = current_offset + 1; i < sizeof(offsets) / sizeof(int); ++i) {
        if (offsets[i] == 0) {
            return i;
        }
    }
