    int *new_offsets = realloc(offsets, new_size * sizeof(int));
    if (!new_offsets) {
        log_allocation_failure("Failed to resize offset array.");
        return -1;
    }
    for (i = sizeof(offsets) / sizeof(int); i < new_size / sizeof(int); ++i) {
        new_offsets[i] = 0;
    }
    offsets = new_offsets;
    return current_offset + 1;
}

