// Hash table structure for separate chaining
typedef struct hash_node {
    record data;
    struct hash_node* next;
} hash_node;

int hash(int key) {
    return key % 100;
}

void insert(hash_table* ht, int key, long offset, int value) {
    // Create a new record and node
    record* rec = (record*)malloc(sizeof(record));
    rec->key = key;
    rec->offset = offset;
    rec->value = value;

    hash_node* node = (hash_node*)malloc(sizeof(hash_node));
    node->data = *rec;
    node->next = NULL;

    // Insert into the appropriate bucket
    int index = hash(key);
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = node;
    } else {
        hash_node* current = ht->buckets[index];
        while (current != NULL) {
            // Check for key collisions and handle them by appending the new node to the end of the chain.
            if (current->data.key == key) break;
            current = current->next;
        }
        if (current == NULL) { // Key not found, append the new node at the end of the chain.
            current = ht->buckets[index];
            while (current->next != NULL) current = current->next;
            current->next = node;
        }
    }
}

record* lookup(hash_table* ht, int key) {
    // Search for the key in each bucket of the hash table.
    for (int i = 0; i < 100; ++i) {
        hash_node* current = ht->buckets[i];
        if (current != NULL) {
            while (current != NULL) {
                if (current->data.key == key) return &current->data;
                current = current->next;
            }
        }
    }
    return NULL;
}

void free_hash_table(hash_table* ht) {
    for (int i = 0; i < 100; ++i) {
        hash_node* current = ht->buckets[i];
        while (current != NULL) {
            hash_node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->buckets);
}

void* create_hash_table() {
    // Allocate memory for the hash table and its buckets.
    void* ht = malloc(sizeof(hash_table));
    if (ht == NULL) return NULL;

    ((hash_table*)ht)->buckets = malloc(100 * sizeof(hash_node*));
    if (((hash_table*)ht)->buckets == NULL) {
        free(ht);
        return NULL;
    }

    return ht;
}

// Function to dynamically initialize the arrays for long offsets, int keys and records.
