    long* offsets = (long*)malloc(n_offsets * sizeof(long));
    int* keys = (int*)malloc(n_keys * sizeof(int));

    if (!offsets || !keys) {
        free(ht->buckets);
        free(ht);
        return;
    }

    // Allocate memory for records array
    record* records = (record*)calloc(n_records, sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        free(ht->buckets);
        free(ht);
        return;
    }

    // Fill the records array with random values and map them to their corresponding keys using the hash table.
    for (size_t i = 0; i < n_records; ++i) {
        records[i].value = rand() % 1000;
