#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    float value;
    char *identifier;
} record;

int read_integers(int *input, int *size) {
    fscanf(stdin, "%d", size);
    if (*size <= 0) return -1; // Invalid input

    for (int i = 0; i < *size; ++i) {
        fscanf(stdin, "%d", &input[i]);
        if (feof(stdin)) return -1; // Reached end of file unexpectedly
    }

    return 0;
}

void generate_offsets(int *offsets, int size) {
    for (int i = 0; i < size; ++i) offsets[i] = i;
}

int* malloc2d(size_t rows, size_t cols) {
    int *matrix = malloc(rows * cols * sizeof(int));
    if (!matrix) return NULL; // Out of memory

    for (int i = 0; i < rows * cols; ++i) matrix[i] = 0;
    return matrix;
}

record* malloc_records(size_t size) {
    record *records = malloc(sizeof(record) * size);
    if (!records) return NULL; // Out of memory

    for (int i = 0; i < size; ++i) memset(&records[i], 0, sizeof(record));
    return records;
}

char* generate_identifier(size_t index) {
    static char id[16];
    snprintf(id, sizeof(id), "rec_%zu", index);
    return strdup(id); // May fail if out of memory
}

void initialize_records(record *records, int size, int *keys, float min, float max) {
    for (int i = 0; i < size; ++i) {
        records[i].key = keys[i];
        records[i].value = rand() * (1.0 / RAND_MAX) * (max - min) + min;
        records[i].identifier = generate_identifier(i);
    }
}

void sort_records(record *records, int size) {
    qsort(records, size, sizeof(record), compare_int_keys);
}

int compare_int_keys(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

int find_key(record *records, int size, int key) {
    for (int i = 0; i < size; ++i) {
        if (records[i].key == key) return i;
    }

    return -1; // Not found
}

void print_records(record *records, int size) {
    printf("Records:\n");
    for (int i = 0; i < size; ++i) {
        printf("[%d, %.2f, %s]\n", records[i].key, records[i].value, records[i].identifier);
    }
}

void free_records(record *records, int size) {
    for (int i = 0; i < size; ++i) free(records[i].identifier);
    free(records);
}

int main(int argc, char **argv) {
    srand(time(NULL)); // Seed random number generator

    int input_size = 0;
    if (read_integers(&input_size, &argc, argv) < 0) return -1; // Error handling

    int *input = malloc(input_size * sizeof(int));
    if (!input) return -2; // Out of memory

    if (read_integers(input, &input_size) < 0) return -3; // Error handling

    int *offsets = malloc2d(1, input_size);
    if (!offsets) return -4; // Out of memory

    int *keys = malloc2d(1, input_size);
    if (!keys) return -5; // Out of memory

    record *records = malloc_records(input_size);
    if (!records) return -6; // Out of memory

    generate_offsets(offsets[0], input_size);

    initialize_records(records, input_size, keys[0], 1.0, 10.0);
    sort_records(records, input_size);

    int key = find_key(records, input_size, 5);
    if (key >= 0) printf("Key 5 found at index: %d\n", key);
    else printf("Key 5 not found.\n");

    print_records(records, input_size);

    free(input);
    free(offsets[0]);
    free(keys[0]);
    free_records(records, input_size);

    return 0;
}
