    *records = (dataRecord*) malloc(size * sizeof(dataRecord));
    if (!*records) return 1;

    for (i = 0; i < size; ++i) {
        (*records)[i].value = numbers[i];
        (*records)[i].key = keys ? &keys[i] : NULL;
        (*records)[i].label = labels ? &labels[i] : '\0';
        (*records)[i].offset = i;
