    for (size_t i = 0; i < size; ++i) {
        printf("Index: %zu, Value: %.2f, Key: %zu, Label: %c, Offset: %ld\n", i, records[i].value, *records[i].key, records[i].label, records[i].offset);
    }
}

int searchDataRecords(size_t size, dataRecord *records, double target) {
    int start = 0;
    int end = size - 1;
    int mid;

    while (start <= end) {
        mid = (start + end) / 2;
        if (records[mid].value == target) return mid;
        if (records[mid].value < target) start = mid + 1;
        else end = mid - 1;
    }

    return -1;
}

