typedef struct {
    int value;
    int* key;
    long offset;
} record;

int initialize_records(int *input_values, int input_count, long *offsets, int *keys) {
    if (!input_values || !input_count || !offsets || !keys) return -1;

    // Allocate memory for record array and pointers
    record* records = (record*) malloc(input_count * sizeof(record));
    if (!records) return -2;

    int* keys_array = (int*) malloc((input_count + 1) * sizeof(int)); // Extra space for NULL terminator
    if (!keys_array) {
        free(records);
        return -3;
    }

    long* offsets_array = (long*) calloc(input_count, sizeof(long));
    if (!offsets_array) {
        free(records);
        free(keys_array);
        return -4;
    }

    int i;
    for (i = 0; i < input_count; ++i) {
        keys_array[i] = -1; // Initialize keys to unassigned values
    }
    keys_array[input_count] = -2; // Set sentinel value for end of key array

    srand(time(NULL)); // Seed random number generator

    // Initialize records and keys
    for (i = 0; i < input_count; ++i) {
        int j;
        int random_index = rand() % i;

        record* current = &records[random_index];
        current->value = input_values[random_index];
        current->key = &keys_array[random_index];
        current->offset = offsets_array[random_index];

        // Assign keys and calculate offsets recursively for remaining elements
        for (j = random_index + 1; j < i + 1; ++j) {
            record* next = &records[j];

            if (*next->key == -1) { // Unassigned key
                *next->key = current->key;
                next->offset = current->offset + current->value;
            } else { // Assigned key, calculate offset
                next->offset = *((int*)next->key) + next->value;
            }
        }
    }

    free(keys_array);
    free(offsets_array);

    printf("Records initialized:\n");
    for (i = 0; i < input_count; ++i) {
        printf("Record %d: value=%d, key=%p, offset=%ld\n", i, &records[i].value, records[i].key, records[i].offset);
    }

