['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <math.h>
#include <time.h>

#define MEMORY_POOL_INITIAL_SIZE 1000000
#define MAX_MEMORY_USAGE 75
#define RESIZE_THRESHOLD 60
#define LOG_FILE "error_log.txt"

typedef struct MemoryBlock {
    void* data;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

typedef struct {
    MemoryBlock* head;
    MemoryBlock* tail;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, NULL, 0, MEMORY_POOL_INITIAL_SIZE, PTHREAD_MUTEX_INITIALIZER};

void* mem_alloc(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.current_size + size > memory_pool.max_size * MAX_MEMORY_USAGE) {
        resize_memory_pool();
    }
    MemoryBlock* block = memory_pool.head;
    if (!block || block->size < size) {
        block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
        if (!block) {
            fprintf(stderr, "Error: Out of memory\n");
            return NULL;
        }
        block->data = malloc(size);
        if (!block->data) {
            fprintf(stderr, "Error: Out of memory\n");
            free(block);
            return NULL;
        }
        block->size = size;
        block->next = memory_pool.head;
        memory_pool.head = block;
    }
    void* result = block->data;
    block->data += size;
    block->size -= size;
    if (block->size == 0) {
        if (block == memory_pool.tail) {
            memory_pool.tail = block->next;
        }
        free(block);
    }
    memory_pool.current_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return result;
}

void resize_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    MemoryBlock* current = memory_pool.head;
    size_t new_size = memory_pool.max_size * (1 + RESIZE_THRESHOLD / 100.0);
    while (current != NULL) {
        void* data = current->data;
        size_t size = current->size;
        current->data = mem_alloc(size);
        if (!current->data) {
            fprintf(stderr, "Error: Out of memory\n");
            free_memory_pool();
            return;
        }
        memcpy(current->data, data, size);
        free(data);
        current->size = size;
        current = current->next;
    }
    memory_pool.max_size = new_size;
    pthread_mutex_unlock(&memory_pool.lock);
}

void free_memory_pool() {
    pthread_mutex_lock(&memory_pool.lock);
    MemoryBlock* current = memory_pool.head;
    MemoryBlock* next;
    while (current != NULL) {
        next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    memory_pool.head = memory_pool.tail = NULL;
    memory_pool.current_size = 0;
    memory_pool.max_size = MEMORY_POOL_INITIAL_SIZE;
    pthread_mutex_unlock(&memory_pool.lock);
}

void log_error(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    } else {
        fprintf(stderr, "Error: Unable to open log file for writing.\n");
    }
}

void initialize_records(long *offsets, int *keys, record** records, size_t offset_size, size_t key_size, size_t record_count, int lower_bound, int upper_bound, unsigned int seed, bool use_normal_distribution, bool initialize_with_random_values) {
    if (offset_size == 0 || key_size == 0 || record_count == 0 || upper_bound < lower_bound) {
        log_error("Error: Invalid input parameters\n");
        return;
    }
    srand(seed);

    MemoryBlock* offsets_block = mem_alloc(offset_size * sizeof(long));
    if (!offsets_block) {
        log_error("Error: Out of memory\n");
        return;
    }
    memcpy(offsets_block->data, offsets, offset_size * sizeof(long));

    MemoryBlock* keys_block = mem_alloc((key_size + sizeof(int)) * record_count);
    if (!keys_block) {
        log_error("Error: Out of memory\n");
        free(offsets_block->data);
        return;
    }
    int* keys_array = (int*)keys_block->data;
    for (size_t i = 0; i < record_count; ++i) {
        keys_array[i] = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    pthread_t threads[record_count];
    record** thread_records = calloc(record_count, sizeof(record*));
    for (size_t i = 0; i < record_count; ++i) {
        thread_records[i] = mem_alloc(sizeof(record));
        if (!thread_records[i]) {
            log_error("Error: Out of memory\n");
            free(keys_block->data);
            free_memory_pool();
            return;
        }
    }

    for (size_t i = 0; i < record_count; ++i) {
        pthread_create(&threads[i], NULL, initialize_record, &keys_block->data[i * (key_size + sizeof(int))], offsets_block->data + i * offset_size, key_size, thread_records[i]);
    }

    for (size_t i = 0; i < record_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(offsets_block->data);
    free(keys_block->data);
    free_memory_pool();

    if (initialize_with_random_values) {
        for (size_t i = 0; i < record_count; ++i) {
            records[i]->x = use_normal_distribution ? (rand() % 100 + 50) / 100.0 : rand() / (double)RAND_MAX;
            records[i]->y = use_normal_distribution ? (rand() % 100 + 50) / 100.0 : rand() / (double)RAND_MAX;
        }
    }
}

void* initialize_record(void* arg) {
    record* record = (record*)arg;
