int initializeRecords(size_t num, size_t keyNum, int minValue, int maxValue) {
    if (num == 0 || keyNum == 0) return -1;

    record *records = malloc(num * sizeof(record));
    uint32_t *keys = malloc(keyNum * sizeof(uint32_t));
    if (!records || !keys) {
        perror("Memory allocation failed");
        return -1;
    }

    int *values = calloc(num, sizeof(int));
    if (!values) {
        perror("Memory allocation failed");
        free(records);
        free(keys);
        return -1;
    }

    size_t offsetSize = (size_t)((maxValue - minValue + 1) * num);
    long *offsets = malloc(offsetSize * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed");
        free(records);
        free(keys);
        free(values);
        return -1;
    }

    for (size_t i = 0; i < num; ++i) {
        values[i] = minValue + rand() % (maxValue - minValue + 1);
        records[i].value = values[i];
        records[i].key = &keys[generateKey() % keyNum];
    }

    long offset = 0;
    for (size_t i = 0; i < num; ++i) {
        offsets[values[i] - minValue] += 1;
    }

    for (size_t i = 1; i < offsetSize; ++i) {
        offsets[i] += offsets[i-1];
    }

    size_t j = 0;
    for (size_t i = 0; i < num; ++i) {
        records[j++].key = &keys[offsets[values[i] - minValue]--];
    }

    free(values);
    free(offsets);

