#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define KEY_SIZE 5
#define LABEL_SIZE 20

typedef struct {
    double value;
    const int *key;
    const char *label;
    long offset;
} dataRecord;

int readData(double *input, int size) {
    if (!input || size <= 0) return -1;

    for (int i = 0; i < size; ++i) {
        scanf("%lf", input + i);
    }

    return 0;
}

void initArrays(dataRecord *records, int *keys, char *labels, size_t *capacity) {
    records->value = NULL;
    keys->size = 0;
    labels->size = 0;
    *capacity = MAX_RECORDS;
}

void allocateArrays(dataRecord *records, int *keys, char *labels, size_t capacity) {
    records->value = malloc(capacity * sizeof(double));
    if (!records->value) return;

    keys->size = 0;
    labels->size = 0;
    keys->data = malloc(capacity * KEY_SIZE * sizeof(int));
    if (!keys->data) {
        free(records->value);
        records->value = NULL;
        return;
    }

    labels->data = malloc(capacity * LABEL_SIZE * sizeof(char));
    if (!labels->data) {
        free(keys->data);
        keys->data = NULL;
        free(records->value);
        records->value = NULL;
        return;
    }
}

int initDataRecords(dataRecord *records, int size) {
    allocateArrays(records, &records->key, &records->label, size);
    if (!records->value || !records->key || !records->label) return -1;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = 0.0;
        records[i].key = records->key + i * KEY_SIZE;
        records[i].label = records->label + i * LABEL_SIZE;
    }

    return 0;
}

int generateData(dataRecord *records, int size) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = ((double)(rand() % RAND_MAX)) / RAND_MAX;
        records[i].offset = rand() % 100 + 1;
    }
    return 0;
}

void printDataRecords(dataRecord *records, int size) {
    for (size_t i = 0; i < size; ++i) {
        printf("Record %ld: value=%.4lf key=%d label=%s offset=%ld\n",
            i + 1, records[i].value, *records[i].key, records[i].label, records[i].offset);
    }
}

void sortDataRecords(dataRecord *records, int size) {
    qsort(records, size, sizeof(dataRecord), (int (*)(const void *, const void *))compareRecords);
}

int compareRecords(const void *a, const void *b) {
    return (*(const dataRecord *)a).value - (*(const dataRecord *)b).value;
}

int searchDataRecord(dataRecord *records, int size, double value) {
    for (size_t i = 0; i < size; ++i) {
        if (fabs((*(dataRecord *)records + i).value - value) < 1e-6) return i;
    }
    return -1;
}

void freeDataRecords(dataRecord *records) {
    if (records->value) free(records->value);
    if (records->key->data) free(records->key->data);
    if (records->label->data) free(records->label->data);
}

int main(int argc, char **argv) {
    double input[MAX_RECORDS];
    dataRecord records;

    if (argc < 2) return -1;

    int size = atoi(argv[1]);
    if (size > MAX_RECORDS || size <= 0) return -1;

    if (readData(input, size)) return -1;

    initArrays(&records, &records.key, &records.label, NULL);
    if (initDataRecords(&records, size)) return -1;

    allocateArrays(&records, &records.key, &records.label, size);

    generateData(&records, size);
    printDataRecords(&records, size);
    sortDataRecords(&records, size);
    printDataRecords(&records, size);

    freeDataRecords(&records);
    return 0;
}
