}

// Print the contents of the dataRecords array after initialization.
void printData(dataRecord *records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Index: %2d, Value: %.4f, Key: %p, Label: %p, Offset: %ld\n", i, records[i].value, records[i].key, records[i].label, records[i].offset);
    }
}

// Free memory allocated for dataRecords and related arrays.
void freeData(dataRecord *records, int size, int *keys, char **labels) {
    if (!records || !size) return; // Error: Invalid arguments.

    free(records);
    for (int i = 0; i < size; ++i) {
        free(*(labels + i));
        free(keys + i);
    }
    free(labels);
    free(keys);
}

// Random number generation function.
long randWithSeed(unsigned long *seed) {
    (*seed) = ((*seed) << 13) ^ (*seed) >> 17;
    return (*seed ^ (*seed << 5)) + (*seed >> 6);
}
