int init_arrays(int numKeys, int *keys, int size, int *numVals, Record **records) {
    keys = (int*)realloc(keys, numKeys * sizeof(int));
    if (!keys) return 1;
    if (*numVals > INT_MAX - numKeys) return 1;

    long *offsets = malloc((*numVals + 1) * sizeof(long));
    if (!offsets) return 1;

    Record *records_arr = malloc(*numVals * sizeof(Record));
    if (!records_arr) {
        free(offsets);
        return 1;
