    int i, j, keyIndex, valIndex = -1;
    for (i = 0; i < numKeys; ++i) keys[i] = -1;

    srand(time(NULL));

    for (i = 0; i < *numVals; ++i) {
        int key = rand() % numKeys;
        while (keys[key] >= 0) key = rand() % numKeys;
        keys[key] = valIndex++;

        Record *record = &records_arr[i];
        record->val = i;
        record->key = &keys[key];
        record->offset = offsets[i] = (long)i + 1;
    }

    qsort(records_arr, *numVals, sizeof(Record), (int (*)(const void *, const void *))compare);

    *records = records_arr;
    return 0;
