    for (i = 0; i < size; ++i) {
        printf("Data point %d: value=%f, key=%f, offset=%f\n", i, (*data)[i].value, (*keys)[i], (*offsets)[i]);
    }

    qsort(*data, size, sizeof(data_point), (int(*)(const void*, const void*))compare);

    return 0;
}

int compare(const void *a, const void *b) {
    return (*(data_point *)a).value - (*(data_point *)b).value;
}

int find(float key, data_point* data, int size) {
    int i;
    for (i = 0; i < size; ++i) {
        if (fabsf(key - data[i].value) <= FLT_EPSILON) return i;
    }
    return -1;
}

