#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char *file_path;
    int exists;
    off_t size;
} File;

int read_files(int argc, char **argv, File **files) {
    if (argc <= 1) return -1; // No file paths provided

    *files = malloc(argc - 1);
    if (!*files) return -2; // Memory allocation error

    for (int i = 1; i < argc; ++i) {
        (*files)[i - 1] = malloc(sizeof(File));
        if (!(*files)[i - 1]) return -3; // Memory allocation error

        int status;
        off_t size;
        char file_path[256];
        strcpy(file_path, argv[i]);
        (*files)[i - 1]->file_path = strdup(file_path);
        if (!(*files)[i - 1]->file_path) return -3; // Memory allocation error

        (*files)[i - 1]->exists = lstat(file_path, &size) == 0 && S_ISREG(size.st_mode);
        (*files)[i - 1]->size = (*files)[i - 1]->exists ? size.st_size : -1;

        if (status < 0) {
            free((*files)->file_path); // Free memory if there was an error reading the file
            free(*files);             // Free the entire File structure
            *files = NULL;
            return status;           // Return the error code
        }
    }

    qsort(*files, argc - 1, sizeof(File), (int (*)(const void *, const void *))strcmp);
    return 0;
}
