int initializeDataRecords(int numDoubles, int *numKeys, char **labels, dataRecord **records, FILE *input) {
    double *doubles = malloc(numDoubles * sizeof(double));
    if (!doubles) return 1;

    *records = malloc(numDoubles * sizeof(dataRecord));
    if (!*records) {
        free(doubles);
        return 2;
    }

    for (int i = 0; i < numDoubles; ++i) {
        if (fscanf(input, "%lf", doubles + i) != 1) {
            free(doubles);
            free(*records);
            return 3;
        }
    }

