        scanf("%s", (*labels + i));
    }

    srand(time(NULL));
    for (int i = 0; i < numDoubles; ++i) {
        (*records + i)->key = (*numKeys > i ? *numKeys - i : 0) + *numKeys++;
        (*records + i)->label = (*labels + (*records + i)->value % strlen(*labels));
        (*records + i)->offset = rand();
    }

