void read_config(const char *filename, long *offsets, int *keys, size_t *records_count, size_t *records_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[256];
    bool in_offset = false, in_key = false;
    long current_offset = 0;
    int current_key = 0;
    size_t records_count_tmp = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%ld", &current_offset) == 1 && !in_offset) {
            current_offset++; // Skip the newline character
            in_offset = true;
        } else if (sscanf(line, "%d", &current_key) == 1 && !in_key) {
            records_count_tmp++;
            in_key = true;
        }
    }

    rewind(file);

    if (!in_offset || !in_key) {
        fprintf(stderr, "Invalid configuration file format\n");
        fclose(file);
        return;
    }

    if (current_offset <= 0 || current_key <= 0) {
        fprintf(stderr, "Invalid offset or key values\n");
        fclose(file);
        return;
    }

    *offsets = malloc(current_offset * sizeof(long));
    *keys = malloc(current_key * sizeof(int));
    *records_count = records_count_tmp;
    *records_size = 10; // Initial size for records array

    size_t records_used = 0;
    void *records = calloc(*records_count, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        free(*offsets);
        free(*keys);
        return;
    }

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " \t\n");
        long offset = atol(token);

        if (offset > current_offset) break;

        if (records_used >= *records_size) {
            *records_size *= 2; // Double the size of records array when needed
            records = realloc(records, *records_count * sizeof(Record) * (*records_size));
            if (!records) {
                fprintf(stderr, "Memory allocation failed\n");
                fclose(file);
                free(*offsets);
                free(*keys);
                free(records);
                return;
            }
        }

        int key = current_key++;
        *((long *)(&offsets[offset - 1])) = offset;
        *((int *)(&keys[key - 1])) = key;

        records[records_used].value = rand() % 100 + 1;
        size_t str_len = rand() % 25 + 5;
        records[records_used].str = malloc(str_len + 1);
        memset(records[records_used].str, '\0', str_len + 1);
        snprintf(records[records_used].str, str_len, "%.*s", str_len, generate_random_string(str_len));

        records_used++;
    }

    fclose(file);
}

char *generate_random_string(size_t length) {
    char alphabet[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char random_string[length];
    for (size_t i = 0; i < length; ++i) {
        random_string[i] = alphabet[rand() % strlen(alphabet)];
    }
    return random_string;
}

