['1. C Function `initializeDataRecords`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct DataRecord {
    double value;
    int *key;
    char *label;
    size_t offset;
} DataRecord;

void initializeDataRecords(size_t count, size_t keyCount, size_t labelSize) {
    double *values = malloc(count * sizeof(double));
    int *keys = malloc(keyCount * sizeof(int));
    char *labels = malloc(labelCount * labelSize);
    DataRecord *dataRecords = malloc(count * sizeof(DataRecord));

    if (!values || !keys || !labels || !dataRecords) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        values[i] = 0.0;
        dataRecords[i].value = 0.0;
        dataRecords[i].key = NULL;
        dataRecords[i].label = NULL;
        dataRecords[i].offset = i;
    }

    int index = 0;
    for (size_t i = 0; i < count; ) {
        double input;
        if (scanf("%lf", &input) != 1) break; // Check scanf return value to handle input errors

        DataRecord *record = &dataRecords[index++];
        record->value = input;
        record->key = keys + ((long)record->value % keyCount);
        snprintf(labels + (index - 1) * labelSize, labelSize, "record%zu", index - 1);
        record->label = malloc((strlen(labels) + 1) * sizeof(char));
        strcpy(record->label, labels + (index - 1) * labelSize);

        // Sort based on double values
        for (size_t j = i; j < index; ++j) {
            if (dataRecords[i].value > dataRecords[j].value) {
                DataRecord temp = dataRecords[i];
                dataRecords[i] = dataRecords[j];
                dataRecords[j] = temp;
            }
        }
    }

    free(labels);
}
```

