           if (!metadata[i]->filename) {
               *error = -3;
               free_and_null(metadata, i);
               return;
           }

           // Optimized random number generation with XorShift128+
           uint64_t xorshift128plus(uint64_t *state) {
               uint64_t z = *state;
               uint64_t t;

               t = (z >> 12) ^ (z << 25) ^ (z << 39);
               uint64_t r = t ^ (t << 8) ^ (t << 27) ^ (t << 61);
               *state = *(uint64_t*)&r;
               return r;
           }

           metadata[i]->filesize = xorshift128plus(&seed) % MAX_FILESIZE;
           metadata[i]->lastModTime = time(NULL);

           // Initialize filename with a random string
           char *rand_str = malloc(FILENAME_MAX * sizeof(char));
           for (int j = 0; j < FILENAME_MAX && rand_str[j] != '\0'; ++j) {
               rand_str[j] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"[xorshift128plus(&seed) % 62];
           }
           rand_str[FILENAME_MAX] = '\0';
           strcpy(metadata[i]->filename, rand_str);
       }
   }

   void free_and_null(struct FileMetadata **metadata, int index) {
       for (int i = 0; i < index; ++i)
           free(metadata[i]->filename);
       free(metadata);
       metadata = NULL;
   }

   void print_metadata(int size, struct FileMetadata *metadata) {
       for (int i = 0; i < size; ++i) {
           printf("File %d: Name=%s Size=%lld Bytes Last Modified Time=%s\n", i, metadata[i]->filename, metadata[i]->filesize, ctime(&metadata[i]->lastModTime));
       }
   }

   int main(int argc, char *argv[]) {
       unsigned int size;
       if (argc != 2) {
           fprintf(stderr, "Usage: %s <number_of_files>\n", argv[0]);
           return 1;
       }
       sscanf(argv[1], "%u", &size);

       int error = 0;
       init_metadata(size, &error);
       if (error) {
           fprintf(stderr, "Error: Failed to allocate memory\n");
           return error;
       }

       print_metadata(size, metadata);
       free_and_null(metadata, size);

