int initializeSensorData(int sensorCount, int readingMaxLimit, int maxTimestamp, double minVal, double maxVal, char* sensorIDPrefix) {
    // Validate input parameters
    if (sensorCount <= 0 || readingMaxLimit < 1 || maxTimestamp <= 0 || maxTimestamp < minVal || maxVal < minVal) return -1;

    // Allocate memory for arrays and structures
    int **timestamps = malloc(sensorCount * sizeof(int*));
    double **readings = malloc(sensorCount * readingMaxLimit * sizeof(double));
    char **sensorIDs = calloc(sensorCount, sizeof(char*) * strlen(sensorIDPrefix) + 1);
    sensorReading **sensorReadings = malloc(sensorCount * readingMaxLimit * sizeof(sensorReading*));

    if (!timestamps || !readings || !sensorIDs || !sensorReadings) {
        // Handle memory allocation errors
        free(timestamps);
        free(readings);
        free(sensorIDs);
        free(sensorReadings);
        return -1;
    }

    for (int i = 0; i < sensorCount; ++i) {
        // Initialize timestamps, readings, and sensorIDs arrays
        timestamps[i] = calloc(readingMaxLimit, sizeof(int));
        readings[i] = calloc(readingMaxLimit, sizeof(double));
        sensorIDs[i] = (char*)malloc((strlen(sensorIDPrefix) + 1) * sizeof(char));
