            sensorReadings[i*readingMaxLimit + j] = malloc(sizeof(sensorReading));

            if (!sensorReadings[i*readingMaxLimit + j]) {
                // Handle memory allocation errors
                for (int k = i; k >= 0; --k) {
                    free(timestamps[k]);
                    free(readings[k]);
                    free(sensorIDs[k]);
                    free(sensorReadings[k]);
                }
                free(timestamps);
                free(readings);
                free(sensorIDs);
                free(sensorReadings);
                return -1;
            }

            sensorReadings[i*readingMaxLimit + j]->reading = (double)(rand() * (maxVal - minVal) / RAND_MAX + minVal);
            sensorReadings[i*readingMaxLimit + j]->timestamp = &timestamps[i][j];
            sensorReadings[i*readingMaxLimit + j]->sensorID = sensorIDs[i];
            sensorReadings[i*readingMaxLimit + j]->offset = rand() % maxTimestamp;
        }
    }

    // Implement additional functionalities such as sorting, searching, etc. (not shown here)

    return 0;
}
