#include <time.h>
#include <errno.h>

enum RecordStatus { ACTIVE, INACTIVE };
struct Record { int value; enum RecordStatus status; };
struct Transaction { struct Record* records; size_t numRecords; };

// Validate input parameters
bool validateInput(size_t* offsets, size_t numOffsets, size_t* keys, size_t numKeys, size_t* records, size_t numRecords, int minValue, int maxValue, const char* logFilePath) {
    if (offsets == NULL || keys == NULL || records == NULL) return false;
    for (size_t i = 0; i < numOffsets; ++i) {
        if (offsets[i] <= 0) return false;
    }
    for (size_t i = 0; i < numKeys; ++i) {
        if (keys[i] <= 0) return false;
    }
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i] <= 0) return false;
    }
    if (minValue > maxValue) return false;
    if (logFilePath == NULL || strlen(logFilePath) == 0) return false;
    return true;
}

// Allocate and initialize arrays
void* allocArray(size_t size, const char* errorMsg) {
    void* ptr = calloc(size, sizeof(int));
    if (!ptr) {
        fprintf(stderr, "%s: out of memory\n", errorMsg);
        exit(1);
    }
    return ptr;
}

void allocateAndInitialize(size_t* offsets, size_t numOffsets, size_t* keys, size_t numKeys, size_t* records, size_t numRecords, int minValue, int maxValue, const char* logFilePath, bool active) {
    if (!validateInput(offsets, numOffsets, keys, numKeys, records, numRecords, minValue, maxValue, logFilePath)) return;

    long* offsetValues = allocArray(numOffsets, "offset values");
    int* keysArray = allocArray(numKeys, "key array");
    struct Record* recordsArray = allocArray(numRecords * sizeof(struct Record), "record array");
    struct Transaction* transactionsArray = allocArray(1, "transaction array");

    for (size_t i = 0; i < numOffsets; ++i) offsetValues[i] = offsets[i];
    for (size_t i = 0; i < numKeys; ++i) keysArray[i] = keys[i];

    // Initialize transaction array
    transactionsArray->records = recordsArray;
    transactionsArray->numRecords = 0;

    FILE* logFile = fopen(logFilePath, "w");
    if (!logFile) {
        perror("Failed to open log file");
        exit(1);
    }

    // Set up random number generator
    srand(time(NULL));

    for (size_t i = 0; i < numKeys; ++i) {
        int key = keysArray[i];
        if (key >= offsetValues[i] && key < offsetValues[i + 1]) {
            struct Record* record = &recordsArray[transactionsArray->numRecords];
            record->value = (rand() % (maxValue - minValue + 1)) + minValue;
            record->status = active ? ACTIVE : INACTIVE;
            fprintf(logFile, "Record %zu: status=%d value=%d\n", transactionsArray->numRecords, record->status, record->value);
            ++transactionsArray->numRecords;
        }
    }

    fclose(logFile);
}

int main() {
    size_t offsets[] = { 10, 20, 30 };
    size_t keys[] = { 5, 7, 9 };
    size_t records[] = { 2, 4, 6 };
    int minValue = -10;
    int maxValue = 10;
    const char* logFilePath = "/path/to/log.txt";
    bool activeStatus = true;

    allocateAndInitialize(offsets, sizeof(offsets)/sizeof(size_t), keys, sizeof(keys)/sizeof(size_t), records, sizeof(records)/sizeof(size_t), minValue, maxValue, logFilePath, activeStatus);

    printf("Successfully allocated and initialized arrays\n");

    return 0;
}
