    srand((unsigned int)time(NULL));

    size_t i, j;
    for (i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].key = &keys[(i + offsets[i]) % num_keys];
        records[i].additional_field = i; // Example: additional field could be a unique identifier for each record
    }

    // Sort the records by their values
    qsort(records, num_records, sizeof(Record), compare_functions);

    // Function to compare Record structures based on value field
    int compare_functions(const void *a, const void *b) {
        return (*(Record *)a).value - (*(Record *)b).value;
    }

    // Function to search for a specific integer value within the records array
    int find_value(int value, Record *records, size_t num_records) {
        int low = 0;
        int high = num_records - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (records[mid].value < value)
                low = mid + 1;
            else if (records[mid].value > value)
                high = mid - 1;
            else
