} record;

int init_records(size_t size, size_t keysize, size_t records_per_key, size_t maxOffset, size_t minValue, size_t maxValue) {
    if (keysize < 1 || records_per_key < 1 || maxOffset <= 0 || minValue >= maxValue)
        return -1; // Invalid input parameters

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    offsets = malloc(maxOffset * sizeof(long));
    if (!offsets) {
        free(keys);
        return -2; // Allocation for offset array failed
    }

    keys = malloc(keysize * records_per_key * sizeof(int));
    if (!keys) {
        free(offsets);
        return -3; // Allocation for key array failed
    }

    records = malloc(keysize * records_per_key * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -4; // Allocation for record array failed
    }

    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < keysize * records_per_key; ++i) {
        int keyIndex = rand() % keysize;
        if (!keys[keyIndex]) { // Avoid duplicates in the keys array
            keys[keyIndex] = i / records_per_key + 1;
            offsets[(long)keys[keyIndex] - 1] = (long)i;
        }
