    for (size_t i = 0; i < keysize * records_per_key; ++i) {
        size_t randValue = (rand() % (maxValue - minValue + 1)) + minValue;
        records[i].value = randValue;
        records[i].key = &keys[(size_t)(offsets[(long)records[i].key-1] / records_per_key)];
        records[i].offset = (long)i;
    }

    return 0; // Success
}

