#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    int *key;
    long offset;
};

int read_input(int *nums, int size) {
    if (scanf("%d%*c", nums) != size) {
        return -1;
    }
    return 0;
}

void init_offsets_keys(int keys[], long offsets[], int size) {
    for (int i = 0; i < size; ++i) {
        offsets[i] = (long)i;
        keys[i] = -1;
    }
}

Record *init_records(int values[], int keys[], long offsets[], int size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        records[i].value = values[i];
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
    }
    return records;
}

void print_records(Record *records, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Record %d: value=%d key=%p offset=%ld\n", i, records[i].value, records[i].key, records[i].offset);
    }
}

void sort_records(Record *records, int size) {
    qsort(records, size, sizeof(Record), compare_records);
}

int search_record(Record *records, int value, int size) {
    int left = 0;
    int right = size - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (records[mid].value == value) {
            return mid;
        }
        if (records[mid].value < value) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

void *my_realloc(void *ptr, size_t old_size, size_t new_size) {
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr) {
        fprintf(stderr, "Memory allocation error!\n");
        exit(-1);
    }
    return new_ptr;
}

void my_free(void *ptr) {
    free(ptr);
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s input_size keys_size records_size\n", argv[0]);
        return -1;
    }

    int inputSize = atoi(argv[1]);
    int keysSize = atoi(argv[2]);
    int recordsSize = atoi(argv[3]);

    if (inputSize <= 0 || keysSize <= 0 || recordsSize <= 0) {
        fprintf(stderr, "Invalid argument values. All sizes must be positive.\n");
        return -1;
    }

    int *nums = malloc(sizeof(int) * inputSize);
    if (!nums) {
        fprintf(stderr, "Memory allocation error!\n");
        return -1;
    }

    int keys[keysSize];
    long offsets[recordsSize];
