    if (read_input(nums, inputSize)) {
        my_free(nums);
        return -1;
    }

    init_offsets_keys(keys, offsets, recordsSize);

    records = init_records(nums, keys, offsets, recordsSize);
    if (!records) {
        my_free(nums);
        return -1;
    }

    print_records(records, recordsSize);

    sort_records(records, recordsSize);

    printf("Sorted Records:\n");
    print_records(records, recordsSize);

    int value = 5;
    int index = search_record(records, value, recordsSize);
    if (index == -1) {
