int init_records(int n, ...) {
    int i, k, *keys, *values, size, offset = 0;
    record *records;

    va_list argp;
    va_start(argp, n);
    size = va_arg(argp, int);
    va_end(argp);

    keys = (int *)malloc((size + n) * sizeof(int));
    if (!keys) return 1;

    for (i = 0; i < size; ++i) {
        if (scanf("%d", &keys[i]) != 1) goto err;
    }

    values = (int *)malloc(size * sizeof(int));
    if (!values) goto err;

    for (i = 0; i < size; ++i) {
        if (scanf("%d", &values[i]) != 1) goto err;
    }

    records = malloc(size * sizeof(record));
    if (!records) goto err;

    for (i = 0; i < size; ++i) {
        for (k = 0; k < size; ++k) {
            if (values[k] == keys[i]) break;
        }
        if (k == size) {
            fprintf(stderr, "Error: Duplicate key detected\n");
            goto err;
        }

        records[i].value = values[k];
        records[i].key = &keys[i];
        records[i].offset = offset++;
    }

    qsort(records, size, sizeof(record), (int (*)(const void *, const void *))cmp);
    printf("Contents of the records array:\n");
    for (i = 0; i < size; ++i) {
        printf("%d %ld\n", records[i].value, *(records[i].key));
    }

    return 0;
err:
    free(keys);
    free(values);
    free(records);
    return 1;
}

int cmp(const void *a, const void *b) {
    record *x = (record *)a;
    record *y = (record *)b;
    if (x->value > y->value) return 1;
    if (x->value < y->value) return -1;
