#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct ConfigRecord {
    char** keys;
    int* values;
    size_t key_count;
    size_t value_count;
    pthread_mutex_t lock;
} ConfigRecord;

ConfigRecord* create_config_record(size_t key_count, size_t value_count) {
    ConfigRecord* config = (ConfigRecord*)malloc(sizeof(ConfigRecord));
    if (!config) {
        fprintf(stderr, "Failed to allocate memory for ConfigRecord\n");
        return NULL;
    }

    config->keys = (char**)(malloc((key_count + 1) * sizeof(char*)));
    if (!config->keys) {
        fprintf(stderr, "Failed to allocate memory for keys array in ConfigRecord\n");
        free(config);
        return NULL;
    }

    config->values = (int*)malloc((value_count + 1) * sizeof(int));
    if (!config->values) {
        fprintf(stderr, "Failed to allocate memory for values array in ConfigRecord\n");
        free(config->keys);
        free(config);
        return NULL;
    }

    config->key_count = key_count;
    config->value_count = value_count;

    pthread_mutex_init(&config->lock, NULL);

    for (size_t i = 0; i < key_count + 1; ++i) {
        config->keys[i] = NULL;
    }

    return config;
}

void set_config(ConfigRecord* config, const char* key, int value) {
    size_t key_index = 0;
    for (size_t i = 0; i < config->key_count + 1 && config->keys[i]; ++i) {
        if (!strcmp(config->keys[i], key)) {
            key_index = i;
            break;
        }
    }

    if (key_index == config->key_count) {
        // Key not found, add a new one
        char** temp_keys = realloc(config->keys, ((config->key_count + 2) * sizeof(char*)));
        if (!temp_keys) {
            fprintf(stderr, "Failed to allocate memory for keys array in ConfigRecord\n");
            return;
        }
        config->keys = temp_keys;

        int* temp_values = realloc(config->values, ((config->value_count + 2) * sizeof(int)));
        if (!temp_values) {
            fprintf(stderr, "Failed to allocate memory for values array in ConfigRecord\n");
            free(config->keys);
            return;
        }
        config->values = temp_values;

        config->keys[config->key_count + 1] = NULL;
        config->value_count++;
    }

    pthread_mutex_lock(&config->lock);
    config->keys[key_index] = strdup(key);
    if (!config->keys[key_index]) {
        fprintf(stderr, "Failed to allocate memory for key in ConfigRecord\n");
        pthread_mutex_unlock(&config->lock);
        return;
    }

    config->values[key_index] = value;
    pthread_mutex_unlock(&config->lock);
}

int get_config(ConfigRecord* config, const char* key) {
    size_t key_index = 0;
    for (size_t i = 0; i < config->key_count + 1 && config->keys[i]; ++i) {
        if (!strcmp(config->keys[i], key)) {
            key_index = i;
            break;
        }
    }

    if (key_index == config->key_count) {
        return 0;
    }

    pthread_mutex_lock(&config->lock);
    int value = config->values[key_index];
    pthread_mutex_unlock(&config->lock);

    return value;
}

void randomize_config(ConfigRecord* config, size_t min, size_t max) {
    for (size_t i = 0; i < config->value_count; ++i) {
        if (config->values[i]) {
            config->values[i] = rand() % (max - min + 1) + min;
        }
    }
}
```

