typedef struct {
    double value;
    int key;
    char *str;
} data_entry;

void read_csv(const char *filename, size_t *doubles, size_t *ints, size_t *chars, data_entry **entries, size_t *entries_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char delimiter[] = ",";
    char line[4096], *token;
    size_t doubles_cap = 10, ints_cap = 10, chars_cap = 10, entries_cap = 10;
    size_t doubles_len = 0, ints_len = 0, chars_len = 0, entries_len = 0;

    *doubles = malloc(doubles_cap * sizeof(double));
    *ints = malloc(ints_cap * sizeof(int));
    *chars = malloc((chars_cap + 1) * sizeof(char));
    *entries = malloc(entries_cap * sizeof(data_entry));

    while (fgets(line, sizeof(line), file)) {
        token = strtok(line, delimiter);

        if (!token) continue; // Ignore empty lines or malformed entries

        doubles[doubles_len] = atof(token);
        ints[ints_len] = atoi(strtok(NULL, delimiter));
        chars[chars_len++] = strdup(strtok(NULL, delimiter));

        if (entries_len == entries_cap) {
            entries_cap *= 2;
            entries = realloc(entries, entries_cap * sizeof(data_entry));
        }

        data_entry *entry = &entries[entries_len];
        entry->value = doubles[doubles_len];
        entry->key = ints[ints_len];
        entry->str = chars[chars_len - 1];
        entries_len++;
    }

    fclose(file);

    *doubles = realloc(*doubles, doubles_len * sizeof(double));
    *ints = realloc(*ints, ints_len * sizeof(int));
    *chars = realloc(*chars, (chars_len + 1) * sizeof(char));

    *entries_count = entries_len;
}
