```cpp
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>
#include <mutex>
#include <functional>

struct ConfigurationRecord {
    std::vector<std::string> keys;
    std::vector<int> values;
};

class ConfigManager {
private:
    std::vector<ConfigurationRecord> records_;
    mutable std::mutex records_lock_;

    void set_values(size_t idx, size_t key_count, int min_value, int max_value) {
        for (size_t i = 0; i < key_count; ++i) {
            ConfigurationRecord& record = records_[idx];
            record.keys.push_back("key" + std::to_string(i));
            record.values.push_back(rand() % (max_value - min_value + 1) + min_value);
        }
    }

public:
    ConfigManager(size_t record_count, size_t key_count_per_record, int min_value, int max_value) {
        records_.resize(record_count);
        std::for_each(std::begin(records_), std::end(records_), [this, key_count_per_record, min_value, max_value](ConfigurationRecord& record) { set_values(std::distance(std::begin(records_), &record), key_count_per_record, min_value, max_value); });
    }

    ConfigurationRecord* get_record(size_t idx) {
        std::unique_lock<std::mutex> lock(records_lock_);
        return &records_[idx];
    }

    void update_config(size_t idx, size_t key_count, const std::vector<std::string>& keys, const std::vector<int>& values) {
        std::unique_lock<std::mutex> lock(records_lock_);
        ConfigurationRecord& record = records_[idx];
        if (record.keys.size() < key_count) {
            for (size_t i = record.keys.size(); i < key_count; ++i) {
                record.keys.push_back(keys[i]);
                record.values.push_back(0);
            }
        }
        for (size_t i = 0; i < std::min(record.keys.size(), key_count); ++i) {
            size_t found = std::distance(std::begin(record.keys), std::find(std::begin(record.keys), std::end(record.keys), keys[i]));
            if (found == record.keys.size()) {
                record.keys.push_back(keys[i]);
                record.values.push_back(0);
            }
            record.values[found] = values[i];
        }
    }
};
```

