void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

int *readIntArray(int *size, int minSize, int maxSize) {
    if (*size < minSize || *size > maxSize)
        error_exit("Invalid array size");

    int *array = malloc(*size * sizeof(int));
    if (!array)
        error_exit("Memory allocation failed");

    for (int i = 0; i < *size; ++i)
        scanf("%d", &array[i]);

    return array;
}

char *readCharArray(int size, int minSize, int maxSize) {
    char *array = malloc(size * sizeof(char));
    if (!array)
        error_exit("Memory allocation failed");

    for (int i = 0; i < size; ++i) {
        scanf("%c", &array[i]);
        if (getchar() != '\n')
            ungetc('\n', stdin);
    }

    return array;
}

long *readLongArray(int *size, int minSize, int maxSize) {
    if (*size < minSize || *size > maxSize)
        error_exit("Invalid array size");

    long *array = malloc(*size * sizeof(long));
    if (!array)
        error_exit("Memory allocation failed");

    for (int i = 0; i < *size; ++i)
        scanf("%ld", &array[i]);

    return array;
}

DataRecord* readDataRecords(int *keysSize, int *labelsSize, long *offsetsSize, int dataSize, double minValue, double maxValue) {
    DataRecord *records = malloc(dataSize * sizeof(DataRecord));
    if (!records)
        error_exit("Memory allocation failed");

    long *offsets = readLongArray(offsetsSize, 1, INT_MAX);
    int *keys = readIntArray(keysSize, 1, INT_MAX);
    char *labels = readCharArray(*labelsSize, 1, INT_MAX);

    for (int i = 0; i < dataSize; ++i) {
        double value;
        scanf("%lf", &value);

        records[i].value = (rand() % (maxValue - minValue + 1)) + minValue;
        records[i].key = &keys[offsets[i]];
        records[i].label = labels + offsets[i];
        records[i].offset = offsets[i];
    }

    free(offsets);
    free(keys);
    free(labels);

    return records;
}

void printDataRecord(const DataRecord *record) {
    printf("(%ld, %d, %c, %.2lf)\n", record->offset, *record->key, *record->label, record->value);
}

void threadFunction(int start, int end, const DataRecord *records, int dataSize) {
    for (int i = start; i < end; ++i)
        printDataRecord(&records[i]);
}

int main(int argc, char **argv) {
    if (argc != 7)
        error_exit("Invalid number of arguments");

    int keysSize = atoi(argv[1]), labelsSize = atoi(argv[2]), dataSize = atoi(argv[3]);
    long offsetsSize = atoi(argv[4]);
    double minValue = atof(argv[5]), maxValue = atof(argv[6]);

    int ascendingOrder = atoi(argv[argc - 1]) == 1;
    srand(time(NULL));

    DataRecord *records = readDataRecords(&keysSize, &labelsSize, &offsetsSize, dataSize, minValue, maxValue);

    // Implement thread-safe access to the records array using pthreads.
    pthread_t threads[dataSize];
    int segmentSize = dataSize / (ascendingOrder ? 1 : dataSize);
    for (int i = 0; i < dataSize; ++i) {
        int start = ascendingOrder ? i * segmentSize : i + (segmentSize - 1);
        int end = ascendingOrder ? start + segmentSize : i + 1;
        pthread_create(&threads[i], NULL, threadFunction, start, end, records, dataSize);
    }

    // Wait for all threads to finish execution.
    for (int i = 0; i < dataSize; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);

    return EXIT_SUCCESS;
}
