#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct dataRecord {
    double value;
    int *key;
    char *label;
    long int offset;
} dataRecord;

int initializeDataRecords(size_t numDoubles, size_t *numKeys, size_t *numLabels, dataRecord **dataRecords) {
    size_t i;

    // Allocate memory for double array
    *dataRecords = malloc(numDoubles * sizeof(dataRecord));
    if (!*dataRecords) return 1;

    // Allocate memory for key and label arrays
    (*numKeys) *= numDoubles;
    (*numLabels) *= numDoubles;
    int *keys = malloc((*numKeys) * sizeof(int));
    char *labels = malloc((*numLabels) * sizeof(char));
    if (!keys || !labels) {
        free(*dataRecords);
        return 2;
    }

    // Initialize key and label arrays with random values
    for (i = 0; i < (*numKeys + *numLabels); ++i) {
        keys[i] = rand();
        labels[i] = rand() % 26 + 'a';
    }

    // Initialize dataRecords array
    for (i = 0; i < numDoubles; ++i) {
        (*dataRecords)[i].value = rand();
        (*dataRecords)[i].key = &keys[i];
        (*dataRecords)[i].label = &labels[i];
        (*dataRecords)[i].offset = i + 1;
    }

    // Sort dataRecords array
    qsort(*dataRecords, numDoubles, sizeof(dataRecord), compareDoubles);

    // Print contents of dataRecords array
    for (i = 0; i < numDoubles; ++i) {
        printf("Data Record %ld: value=%.2f key=%d label='%c'\n", (*dataRecords)[i].offset, (*dataRecords)[i].value, **((int *const*)(*dataRecords)[i].key), **((char *)const*((*dataRecords)[i].label)));
    }

    // Search for a specific double value within the dataRecords array
    double searchValue = 123456.789;
    int foundIndex = binarySearch(*dataRecords, numDoubles, searchValue);
    if (foundIndex != -1) {
        printf("Found data record with value %.2f at index %ld\n", (*dataRecords)[foundIndex].value, foundIndex + 1);
    } else {
        printf("Did not find data record with value %.2f\n", searchValue);
    }

    free(keys);
    free(labels);

    return 0;
}

int binarySearch(dataRecord *arr, size_t length, double value) {
    size_t left = 0;
    size_t right = length - 1;
    while (left <= right) {
        size_t mid = (left + right) / 2;
        if (arr[mid].value == value) return mid;
        if (arr[mid].value < value) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int compareDoubles(const void *a, const void *b) {
    return (*(double *)a - *(double *)b);
}
