        int random = input[rand() % num_integers];
        if (keys[random] == -1) {
            keys[random] = j++;
            offsets[i++] = rand(); // Use random offset for each integer initially
        }
    }
    return 0;
}

record* init_records(int num_integers, int *keys, long *offsets) {
    record *records = malloc(num_integers * sizeof(record));
    if (!records)
        return NULL;

    for (int i = 0; i < num_integers; ++i) {
        records[i].value = *(keys[i] >= 0 ? &input[keys[i]] : NULL);
        records[i].key = keys + (keys[i] >= 0 ? keys[i] : -1);
        records[i].offset = offsets[i];
    }
    return records;
}

void print_records(int num_integers, record *records) {
    if (!num_integers || !records)
        return;

    printf("Records:\n");
    for (int i = 0; i < num_integers; ++i)
        printf("(%d, %p, %ld)\n", records[i].value, records[i].key, records[i].offset);
}

void sort_records(int num_integers, record *records) {
    if (!num_integers || !records)
        return;

    qsort(records, num_integers, sizeof(record), compare_records);
}

int search_value(int num_integers, record *records, int value) {
    if (!num_integers || !records)
        return -1;

    int left = 0, right = num_integers - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (records[mid].value == value)
            return mid;
        else if (records[mid].value < value)
            left = mid + 1;
        else
            right = mid - 1;
    }
    return -1;
}

int compare_records(const void *a, const void *b) {
    return (*(record *)a).value - *(record *)b;
}

int main(int argc, char **argv) {
    srand(time(NULL));
    int num_integers = argc > 1 ? atoi(argv[1]) : 10;
    int *input = malloc(num_integers * sizeof(int));

    for (int i = 0; i < num_integers; ++i)
        input[i] = i + 1;

    if (!init_arrays(num_integers, input, NULL, NULL)) {
        int *offsets = malloc(num_integers * sizeof(long));
        if (!offsets) {
            free(input);
            return -1;
        }

        if (init_arrays(num_integers, input, offsets, NULL)) {
            free(input);
            free(offsets);
            return -1;
        }

        int *keys = malloc((num_integers + 1) * sizeof(int));
        if (!keys) {
            free(offsets);
            return -1;
        }

        record *records = init_records(num_integers, keys, offsets);
        if (!records) {
            free(keys);
            free(offsets);
            return -1;
        }

        print_records(num_integers, records);
        sort_records(num_integers, records);
        print_records(num_integers, records);

        int search_result = search_value(num_integers, records, 5);
        printf("Search result: %d\n", search_result);

        free(keys);
        free(offsets);
        free(records);
    }

    free(input);
    return 0;
}
