```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define dataRecord structure
typedef struct {
    double value;
    int *key;
    char *label;
    long offset;
} dataRecord;

int initializeDataRecords(size_t inputSize, size_t keysCount, size_t labelsCount, size_t recordsCount, dataRecord **records) {
    size_t i, j;
    double *input = calloc(inputSize, sizeof(double));
    if (!input) return 1; // Allocation failure

    int *keys = calloc(keysCount, sizeof(int));
    if (!keys) { free(input); return 2; }

    char *labels = calloc(labelsCount, sizeof(char));
    if (!labels) { free(input); free(keys); return 3; }

    dataRecord *recordsArray = calloc(recordsCount, sizeof(dataRecord));
    if (!recordsArray) { free(input); free(keys); free(labels); return 4; }

    *records = recordsArray; // Assign pointer to the returned array

    for (i = 0; i < inputSize; ++i) {
        scanf("%lf", &input[i]);
    }

    // Optimized random number generation using Xorshift128+
    unsigned long x = 362436069, y = 521288629, z = 753422189, w = 1368589893;
    for (i = 0; i < recordsCount; ++i) {
        x += y << 23 ^ y >> 17 ^ x << 5 ^ x >> 3 ^ w;
        y += x << 11 ^ x >> 21 ^ w ^ w >> 29;
        z += x << 7 ^ x >> 45 ^ y;
        w += y << 13 ^ y >> 18 ^ z ^ z >> 25;
        recordsArray[i].value = input[(int)(x * (double)inputSize / INT_MAX)];
        recordsArray[i].key = &keys[(int)(y * keysCount / INT_MAX)];
        recordsArray[i].label = &labels[(int)(z * labelsCount / INT_MAX)];
        recordsArray[i].offset = (long)((double)w * ((double)recordsCount - 1) / UINT64_MAX);
    }

    // Print the contents of the dataRecords array after initialization
    for (i = 0; i < recordsCount; ++i) {
        printf("dataRecord %d: value=%.2f, key=%d, label=%c, offset=%ld\n", i, recordsArray[i].value, *recordsArray[i].key, *recordsArray[i].label, recordsArray[i].offset);
    }

    // Sort the dataRecords array based on their double values
    qsort(*records, recordsCount, sizeof(dataRecord), (int (*)(const void *, const void *))compareDoubleValues);

    // Search for a specific double value within the dataRecords array
    if (binarySearch(0, recordsCount - 1, 3.14, *records) != -1) {
        printf("3.14 found in the dataRecords array\n");
    } else {
        printf("3.14 not found in the dataRecords array\n");
    }

    free(input);
    free(keys);
    free(labels);

    return 0; // Successful execution
}

// Comparison function for qsort()
int compareDoubleValues(const void *a, const void *b) {
    const dataRecord *pA = (const dataRecord *)a;
    const dataRecord *pB = (const dataRecord *)b;

    if (*(pA->value) > *(pB->value)) return 1;
    else if (*(pA->value) < *(pB->value)) return -1;
    return 0;
}

// Binary search function for finding a specific value within the dataRecords array
int binarySearch(size_t left, size_t right, double value, const dataRecord *dataRecords) {
    if (left <= right) {
        size_t mid = left + (right - left) / 2;
        if (*(dataRecords[mid].value) == value) return mid;
        if (*(dataRecords[mid].value) < value) return binarySearch(mid + 1, right, value, dataRecords);
        return binarySearch(left, mid - 1, value, dataRecords);
    }
    return -1; // Value not found in the array
}
