#include <time.h>

typedef struct {
    int value;
    int *key;
    long *offset;
} record;

int init_records(int size, int *input, int min, int max) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    long *temp_offsets = NULL;
    int *temp_keys = NULL;
    record *temp_records = NULL;
    size_t i, j;
    int error_code = 0;

    // Allocate memory for offsets and keys arrays
    if (!(offsets = malloc(size * sizeof(long)))) {
        perror("Error allocating memory for offsets array");
        error_code = 1;
        goto cleanup;
    }

    if (!(keys = malloc(size * sizeof(int)))) {
        perror("Error allocating memory for keys array");
        error_code = 2;
        goto cleanup;
    }

    // Initialize offsets and keys arrays with zeros
    for (i = 0; i < size; ++i) {
        offsets[i] = 0;
        keys[i] = -1;
    }

    // Sort the input integers and store their indices in temp_keys array
    for (i = 0; i < size; ++i) {
        for (j = i + 1; j < size; ++j) {
            if (input[i] > input[j]) {
                int temp = input[i];
                input[i] = input[j];
                input[j] = temp;
                int tmp = keys[i];
                keys[i] = keys[j];
                keys[j] = tmp;
            }
        }
    }

    // Allocate memory for temporary records array and fill it with placeholders
    if (!(temp_records = malloc(size * sizeof(record)))) {
        perror("Error allocating memory for temp_records array");
        error_code = 3;
        goto cleanup;
    }

    // Assign keys and offsets to the temporary records array
    for (i = 0; i < size; ++i) {
        temp_records[i].key = &keys[i];
        temp_records[i].offset = &temp_offsets[offsets[i]];
        temp_offsets[input[i]] = offsets[i];
    }

    // Allocate memory for records array and fill it with placeholders
    if (!(records = malloc(size * sizeof(record)))) {
        perror("Error allocating memory for records array");
        error_code = 4;
        goto cleanup;
    }

    // Assign keys and offsets to the final records array
    for (i = 0; i < size; ++i) {
        records[i] = temp_records[keys[i]];
    }

    // Set random values within the given range and print the contents of the records array
    srand(time(NULL));
    for (i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
        printf("Record[%ld]: key=%d, offset=%ld, value=%d\n", i, *records[i].key, *records[i].offset, records[i].value);
    }

cleanup:
    // Free temporary memory allocations
    free(temp_offsets);
    free(temp_keys);
    free(temp_records);

    return error_code;
}
