#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int id;
    struct Node* next;
} Node;

Node* read_node(FILE* fp) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    if (fscanf(fp, "%d%*c %c%*c", &node->id) != 2 || getc(fp) != '\n') {
        free(node);
        perror("Invalid data in configuration file");
        exit(EXIT_FAILURE);
    }

    node->next = NULL;
    return node;
}

double* read_doubles(FILE* fp, int* count) {
    double* doubles = malloc(*count * sizeof(double));
    if (!doubles) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < *count; ++i) {
        if (fscanf(fp, "%lf%*c\n", doubles + i) != 1) {
            free(doubles);
            perror("Invalid data in configuration file");
            exit(EXIT_FAILURE);
        }
    }

    return doubles;
}

char* read_chars(FILE* fp, int* count) {
    char* chars = malloc(*count * sizeof(char));
    if (!chars) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < *count; ++i) {
        if (fscanf(fp, "%c%*c", chars + i) != 1 || getc(fp) != '\n') {
            free(chars);
            perror("Invalid data in configuration file");
            exit(EXIT_FAILURE);
        }
    }

    return chars;
}

void read_config(const char* filename, int max_lines, double** doubles, char** chars, Node*** nodes) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    int lines = 0;
    while (lines < max_lines && fgetc(fp) != EOF) ++lines;
    rewind(fp);

    if (lines > max_lines) {
        perror("Too many lines in configuration file");
        exit(EXIT_FAILURE);
    }

    *doubles = read_doubles(fp, &lines);
    *chars = read_chars(fp, &lines);
    *nodes = malloc(lines * sizeof(Node*));
    if (!*nodes) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < lines; ++i) {
        (*nodes + i) = read_node(fp);
        if (!(*nodes + i)) break;
    }
}
