typedef struct Record {
    int value;
    int *key;
    long offset;
} Record;

void read_integers(int *input, int size) {
    int i = 0;
    for (i = 0; i < size; ++i) {
        scanf("%d", &input[i]);
    }
}

int *read_file(const char *filename, int *size) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;
    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(int);
    rewind(file);
    int *input = malloc(*size * sizeof(int));
    if (!input) {
        fclose(file);
        return NULL;
    }
    read_integers(input, *size);
    fclose(file);
    return input;
}

void initialize_arrays(int n, int *keys, long *offsets, Record **records) {
    keys = realloc(keys, n * sizeof(int));
    offsets = realloc(offsets, n * sizeof(long));
    records = malloc(n * sizeof(Record));
    int i;
    for (i = 0; i < n; ++i) {
        keys[i] = -1;
        offsets[i] = 0;
        records[i].value = 0;
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
    }
}

void set_random_values(int n, Record *records) {
    srand(time(NULL));
    int i;
    for (i = 0; i < n; ++i) {
        records[i].value = rand() % RAND_MAX;
    }
}

void print_records(int n, Record *records) {
    int i;
    for (i = 0; i < n; ++i) {
        printf("Record %d: value=%d, key=%d, offset=%ld\n", i, records[i].value, *(records[i].key), records[i].offset);
    }
}

void sort_records(int n, Record *records) {
    qsort(records, n, sizeof(Record), compare_records);
}

int find_value(int n, Record *records, int value) {
    int left = 0;
    int right = n - 1;
    int mid;
    while (left <= right) {
        mid = (left + right) / 2;
        if (records[mid].value == value) return mid;
        if (records[mid].value < value) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int compare_records(const void *a, const void *b) {
    return ((Record *) a)->value - ((Record *) b)->value;
}

int main() {
    int n_input, n_records;
    scanf("%d", &n_input);
    int *input = read_file("data.txt", &n_records);
    if (!input) return 1;

    int *keys, *offsets;
    Record *records;
    initialize_arrays(n_records, keys, offsets, &records);

    set_random_values(n_records, records);

    for (int i = 0; i < n_input; ++i) {
        int key = input[i];
        if (key >= 0 && key < n_records) {
            records[key].offset += 1;
            keys[key] = i;
        } else {
            printf("Invalid index: %d\n", key);
        }
    }

    print_records(n_records, records);
    sort_records(n_records, records);
    print_records(n_records, records);

    int search_value;
    scanf("%d", &search_value);
    if (find_value(n_records, records, search_value) != -1) {
        printf("Value found!\n");
    } else {
        printf("Value not found.\n");
    }

    free(input);
    free(keys);
    free(offsets);
    free(records);
    return 0;
}
