void parse_line(char** fields, size_t* num_fields, FILE* file) {
    char c;
    *num_fields = 0;
    while ((c = fgetc(file)) != EOF && isspace(c)) {} // Skip leading whitespace
    if (c == EOF) return;
    fields[(*num_fields)] = malloc(strlen(&c) + 1);
    strcpy(fields[*num_fields++], &c);
    while ((c = fgetc(file)) != EOF && !isspace(c)) {} // Consume rest of field
    if (c == EOF || c == '\n') return;
    while (c == ' ') {
        if (c == EOF) return;
        c = fgetc(file);
        fields[*num_fields] = realloc(fields[*num_fields], strlen(&c) + 1 + (*num_fields * sizeof(char)));
        strcat(fields[*num_fields++], &c);
        while (c != EOF && c != '\n' && !isspace(c)) c = fgetc(file);
    }
}

int read_csv(void** int_arr, void** double_arr, void** char_arr, void** node_arr, FILE* file) {
    size_t num_fields;
    char* int_field = NULL, *double_field = NULL, *char_field = NULL, *id_field = NULL;
    Node* current_node = NULL, **next_node = &current_node;

    while ((parse_line(&int_field, &num_fields, file), num_fields == 4) || feof(file)) {
        if (num_fields != 4) continue;

        *int_arr = realloc(*int_arr, sizeof(int) * (*((int*)*int_arr + 1));
        *(int*)(*int_arr + (*((int*)*int_arr + 1))++) = atoi(int_field);

        *double_arr = realloc(*double_arr, sizeof(double) * (*((double*)*double_arr + 1));
        *(double*)(*double_arr + (*((double*)*double_arr + 1))++) = atof(double_field);

        *char_arr = realloc(*char_arr, sizeof(char) * (*((char*)*char_arr + 1));
        (*char_arr)[(*((char*)*char_arr + 1))++] = *char_field;

        *next_node = malloc(sizeof(Node));
        (*next_node)->id = atoi(id_field);
        (*next_node)->next = current_node;
        current_node = *next_node;

        free(int_field);
        free(double_field);
        free(char_field);
        free(id_field);

        next_node = &((*next_node)->next);
    }

    if (feof(file)) return 0;
    return -1;
}
