#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

int is_in_range(int n) {
    return (n >= 100 && n <= 10000);
}

void generate_unique_values(int *arr, int size, int min, int max) {
    for (int i = 0; i < size; ++i) {
        arr[i] = min + rand() % ((max - min) + 1);
        for (int j = 0; j < i; ++j) {
            if (arr[i] == arr[j]) {
                --i;
                break;
            }
        }
    }
}

Record* init_records(int num_records, int *seed) {
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(*seed);
    generate_unique_values((int*)records, num_records, 1, INT_MAX);
    return records;
}

long* init_offsets(int num_records) {
    if (!is_in_range(num_records)) {
        fprintf(stderr, "Invalid number of records. Must be between 100 and 10000.\n");
        return NULL;
    }

    long *offsets = malloc((num_records + 1) * sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed");
        return NULL;
    }

    offsets[0] = 0;
    for (int i = 1; i <= num_records; ++i) {
        offsets[i] = offsets[i - 1] + 1;
    }
    return offsets;
}

int* init_keys(int num_records) {
    if (!is_in_range(num_records)) {
        fprintf(stderr, "Invalid number of records. Must be between 100 and 10000.\n");
        return NULL;
    }

    int *keys = malloc(num_records * sizeof(int));
    if (!keys) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % num_records;
    }
    return keys;
}

