    if (!records) die("Failed to allocate memory for records.");

    int *keys = malloc(sizeof(int) * arrSize);
    if (!keys) die("Failed to allocate memory for keys.");

    int *offsets = malloc((arrSize + 1) * sizeof(int));
    if (!offsets) die("Failed to allocate memory for offsets.");

    initialize_arrays(keys, arrSize, minKey, maxKey);

    for (size_t i = 0; i < recordsSize; ++i) {
        records[i].val = rand() % (maxOffset - minOffset + 1) + minOffset;
        records[i].key = keys + arr[i];
        records[i].offset = offsets + i;
    }

    // Initialize the first element of the offset array to -1, as it does not correspond to any record.
    offsets[0] = -1;

    return records;
}

