[' ```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

enum { MIN_RECORDS = 100, MAX_RECORDS = 10000 };

void initialize_data(long *offsets, int *keys, record **records, long *lengths, size_t num_records) {
    if (num_records < MIN_RECORDS || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records specified. Should be between %zu and %zu.\n", MIN_RECORDS, MAX_RECORDS);
        return;
    }

    offsets = calloc((num_records + 1), sizeof(long));
    if (!offsets) {
        perror("Memory allocation failed");
        return;
    }

    keys = malloc(num_records * sizeof(int));
    if (!keys) {
        perror("Memory allocation failed");
        free(offsets);
        return;
    }

    records = calloc(num_records, sizeof(record*));
    if (!records) {
        perror("Memory allocation failed");
        free(keys);
        free(offsets);
        return;
    }

    lengths = malloc(num_records * sizeof(long));
    if (!lengths) {
        perror("Memory allocation failed");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    srand((unsigned int)time(NULL)); // Set seed for random number generator

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand();
        } while (find_duplicate_value(keys, i, value));

        keys[i] = value;
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            perror("Memory allocation failed");
            free(lengths);
            free(records);
            free(keys);
            free(offsets);
            return;
        }

        records[i]->value = value;
        lengths[i] = 1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i + 1] = offsets[i] + lengths[i];
    }
}

bool find_duplicate_value(int *arr, size_t idx, int value) {
    for (size_t i = 0; i < idx; ++i) {
        if (arr[i] == value) {
            return true;
        }
    }
    return false;
}
```
