#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} record;

void populate_records(record *records, size_t num_records, size_t min_value, size_t max_value) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = (long)i * sizeof(record); // for simplicity, assuming each record is of the same size
    }
}

void save_data(const char *filename, const record *records, size_t num_records, const long *keys, size_t num_keys, const long *offsets) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    fwrite(num_records, sizeof(size_t), 1, file); // save the number of records
    fwrite(num_keys, sizeof(size_t), 1, file); // save the number of keys and offsets
    fwrite(offsets, sizeof(long), num_keys, file); // save offsets
    fwrite(keys, sizeof(int), num_keys, file); // save keys
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i], sizeof(record), 1, file); // save records
    }
    fclose(file);
}

void load_data(const char *filename, record **records, size_t *num_records, int *num_keys, long **offsets) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t num_read_records = 0;
    fread(num_records, sizeof(size_t), 1, file); // read the number of records
    if (*num_records == 0) {
        printf("No data found.\n");
        fclose(file);
        return;
    }

    size_t num_read_keys = 0;
    fread(num_keys, sizeof(size_t), 1, file); // read the number of keys and offsets
    if (num_keys != 2) {
        printf("Invalid format. Keys and Offsets should be two values.\n");
        fclose(file);
        return;
    }

    *offsets = malloc(*num_keys * sizeof(long));
    num_read_keys += fread(*offsets, sizeof(long), *num_keys, file); // read offsets
    if (num_read_keys != *num_keys) {
        printf("Error reading offsets.\n");
        free(*offsets);
        fclose(file);
        return;
    }

    *num_keys = num_read_keys;
    int read_keys = 0;
    *num_keys += fread(num_keys + *num_keys, sizeof(int), *num_keys, file); // read keys
    if (*num_keys - read_keys != *num_keys) {
        printf("Error reading keys.\n");
        free(*offsets);
        fclose(file);
        return;
    }

    *records = malloc(*num_records * sizeof(record));
    num_read_records += fread(*records, sizeof(record), *num_records, file); // read records
    if (num_read_records != *num_records) {
        printf("Error reading records.\n");
        free(*offsets);
        free(*records);
        fclose(file);
        return;
    }

    if (*num_keys != num_read_keys || *num_records != num_read_records) {
        printf("Inconsistent number of read elements.\n");
        free(*offsets);
        free(*records);
        fclose(file);
        return;
    }

    fclose(file);
}

int main(int argc, char **argv) {
    // Handle command-line arguments and environment variables for configuring initial data size
    // ...

    size_t num_records = ...;
    size_t num_keys = 2; // assuming two keys: keys and offsets

