    int i, j, keyIndex = 0;
    if (!num || !data) return -1;

    *data = (DataRecord*)malloc(num * sizeof(DataRecord));
    if (*data == NULL) return -2;

    double *numbers = malloc(num * sizeof(double));
    char **labels = calloc(num, sizeof(char*));
    int *keys = malloc(num * sizeof(int));

    if (!numbers || !labels || !keys) {
        free(*data);
        return -3;
    }

    // Generate data and initialize arrays
