            freeNumbers(numbers);
            freeLabels(labels);
            free(keys);
            return -4;
        }

        (*data)[i].value = numbers[i];
        (*data)[i].key = &keys[keyIndex++];
        (*data)[i].label = labels[i];
        (*data)[i].offset = i;
    }

    qsort((*data), num, sizeof(DataRecord), (int(*)(const void*, const void*))compare);

    // Print data records
    printf("\nInitialized data:\n");
    for (i = 0; i < num; i++) {
        printf("Value: %f, Key: %d, Label: %s, Offset: %ld\n", (*data)[i].value, **((*data)[i].key), (*data)[i].label, (*data)[i].offset);
    }

    free(numbers);
    return 0;
}

int compare(const void *a, const void *b) {
    if (((DataRecord*)a)->value > ((DataRecord*)b)->value)
        return 1;
    else if (((DataRecord*)a)->value < ((DataRecord*)b)->value)
        return -1;
    return 0;
}

// Helper functions to free memory
void freeNumbers(double *numbers) {
    if (numbers) free(numbers);
}

void freeLabels(char **labels) {
    int i;
    for (i = 0; i < numElements(labels); i++)
        free(labels[i]);
    free(labels);
}

int numElements(const void *arr) {
    int size, i;
    if (arr == NULL) return 0;
    if (sizeof(arr) <= sizeof(int)) // For arrays of type int
        return *(int*)arr;

    char *ptr = (char*)arr;
    for (i = 0; ptr[i] != '\0'; i++);
    size = i / sizeof(void*);
    return size;
}

