        printf("Record %d: Value=%d Key=%d Offset=%ld\n", i, records[i].value, *records[i].key, *records[i].offset);
    }
}

void cleanup(long *offsets, int *keys, record *records) {
    if(offsets) free(offsets);
    if(keys) free(keys);
    if(records) free(records);
}

