void read_data(const char* filename, double* data, size_t* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    *data = malloc((size_t)file_size);
    if (!*data) {
        perror("Error allocating memory for data");
        fclose(file);
        return;
    }

    size_t bytes_read = fread(*data, sizeof(double), (size_t)file_size, file);
    if (bytes_read != (size_t)file_size) {
        perror("Error reading data from file");
        free(*data);
        *data = NULL;
        fclose(file);
        return;
