        return LIMIT_EXCEEDED;
    }

    offsets = realloc(offsets, offsetCount * sizeof(long));
    if (!offsets) {
        return MEMORY_ERROR;
    }

    keys = realloc(keys, keyCount * sizeof(int));
    if (!keys) {
        free(offsets);
        return MEMORY_ERROR;
    }

    records = malloc(limit * recordSize);
    if (!records) {
        free(offsets);
        free(keys);
        return MEMORY_ERROR;
    }

    *numRecords = 0;

    srand(time(NULL));
    for (size_t i = 0; i < limit; ++i) {
        records[(*numRecords)] = (Record){ .value = rand() % range };
        (*numRecords)++;
        if ((*numRecords) >= offsetCount || (*numRecords) >= keyCount) {
            break;
        }
    }

    qsort(offsets, offsetCount, sizeof(long), (int (*)(const void *, const void *))compareLongs);
    qsort(keys, keyCount, sizeof(int), (int (*)(const void *, const void *))compareInts);

    return NO_ERROR;
}

int compareInts(const void* a, const void* b) {
    return *(const int*)a - *(const int*)b;
}

int compareLongs(const void* a, const void* b) {
    return *(const long*)a - *(const long*)b;
}
```

