#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h> // for alignment

struct Record {
    int key;
    long* offsets_aligned; // properly aligned pointer to the offset array
    size_t offsets_size;
    pthread_mutex_t lock;
    bool is_cached;
};

#pragma pack(push, 16)
struct AlignedRecord {
    struct Record record;
    char padding[16 - sizeof(struct Record)]; // ensure alignment
};
#pragma pack(pop)

void initialize_records(long *offsets, int *keys, struct AlignedRecord** records, int num_records, int key_range_min, int key_range_max, size_t max_memory_usage, enum InitializationMode mode) {
    if (num_records * sizeof(struct Record) + max_memory_usage > max_memory_usage) {
        fprintf(stderr, "Error: Total memory usage exceeds the specified limit\n");
        return;
    }

    pthread_mutex_t shared_lock = PTHREAD_MUTEX_INITIALIZER;
    struct AlignedRecord* cached_records = NULL;
    size_t allocated_size = 0;

    for (int i = 0; i < num_records; ++i) {
        if (i < num_records - 1 && mode == SEQUENTIAL) {
            offsets[i] = i + 1;
        } else if (mode == RANDOM) {
            offsets[i] = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        }
    }

    pthread_mutex_lock(&shared_lock);

    if (cached_records && num_records <= cached_records[num_records - 1].offsets_size / sizeof(struct Record)) {
        struct AlignedRecord* current_record = &cached_records[num_records - 1];
        for (int i = current_record->record.offsets_size / sizeof(struct Record); i < num_records; ++i) {
            current_record->record.offsets_aligned = realloc(current_record->record.offsets_aligned, (i + 1) * sizeof(long));
            if (!current_record->record.offsets_aligned) {
                fprintf(stderr, "Error: Failed to allocate memory for offsets array\n");
                pthread_mutex_unlock(&shared_lock);
                return;
            }
            current_record->record.is_cached = false;
        }
    } else {
        struct AlignedRecord* new_records = malloc(num_records * sizeof(struct AlignedRecord));
        if (!new_records) {
            fprintf(stderr, "Error: Failed to allocate memory for records\n");
            pthread_mutex_unlock(&shared_lock);
            return;
        }
        allocated_size += num_records * sizeof(struct AlignedRecord);

        for (int i = 0; i < num_records; ++i) {
            new_records[i].record.offsets_aligned = malloc(sizeof(long));
            if (!new_records[i].record.offsets_aligned) {
                fprintf(stderr, "Error: Failed to allocate memory for offset array\n");
                pthread_mutex_unlock(&shared_lock);
                free(new_records);
                return;
            }

            new_records[i].record.is_cached = false;
        }
        cached_records = new_records;
    }

    for (int i = 0; i < num_records; ++i) {
        new ((&(cached_records[i].record))) struct Record(); // initialize the records with default values
        if (mode == SEQUENTIAL)
            cached_records[i].record.offsets_aligned[0] = i + 1;
        else if (mode == RANDOM)
            *(cached_records[i].record.offsets_aligned) = offsets[i];
    }

    for (int i = 0; i < num_records; ++i) {
        keys[i] = cached_records[i].record.key;
        records[i] = &(cached_records[i].record);
    }

    pthread_mutex_unlock(&shared_lock);
}
