typedef struct {
    time_t timestamp;
    int eventType;
    float sensorReading;
} sensorData;

int initializeDataStructures(size_t *timestamps, size_t *eventTypes, size_t *sensorReadings, sensorData **data, size_t *dataSize, size_t *maxDataSize, int *errorFlag) {
    size_t dataLength = MAX_ELEMENTS;
    *data = (sensorData*) malloc(dataLength * ELEMENT_SIZE);
    if (!*data) {
        fprintf(stderr, "Memory allocation failed.\n");
        *errorFlag = 1;
        return -1;
    }

    *maxDataSize = dataLength;
    *dataSize = 0;

    *timestamps = (size_t*) malloc(dataLength * sizeof(size_t));
    if (!*timestamps) {
        fprintf(stderr, "Memory allocation for timestamps failed.\n");
        free(*data);
        *errorFlag = 1;
        return -1;
    }

    *eventTypes = (size_t*) malloc(dataLength * sizeof(size_t));
    if (!*eventTypes) {
        fprintf(stderr, "Memory allocation for eventTypes failed.\n");
        free(*timestamps);
        free(*data);
        *errorFlag = 1;
        return -1;
    }

    *sensorReadings = (size_t*) malloc(dataLength * sizeof(float));
    if (!*sensorReadings) {
        fprintf(stderr, "Memory allocation for sensorReadings failed.\n");
        free(*timestamps);
        free(*eventTypes);
        free(*data);
        *errorFlag = 1;
        return -1;
    }

    // Initialize arrays with random values or initial data if available
    for (size_t i = 0; i < dataLength; ++i) {
        (*timestamps)[i] = rand() % TIMESTAMP_RANGE;
        (*eventTypes)[i] = rand() % EVENT_TYPE_RANGE;
        (*sensorReadings)[i] = (rand() % SENSOR_READING_RANGE) * 0.01f;
    }

    // Log initial data statistics for debugging and auditing purposes
    printf("Initializing data structures with %zu elements.\n", dataLength);
    logDataStatistics(data, dataSize, maxDataSize);

    return 0;
}

void resizeDataStructures(size_t *timestamps, size_t *eventTypes, size_t *sensorReadings, sensorData **data, size_t *maxDataSize, size_t newSize) {
    if (newSize <= *maxDataSize) return; // No resizing needed if the new size is less than or equal to the maximum size.

    sensorData* tempData = (sensorData*) realloc(*data, newSize * ELEMENT_SIZE);
    if (!tempData) {
        fprintf(stderr, "Memory allocation for resized data failed.\n");
        return;
    }
    *data = tempData;

    size_t* newTimestamps = (size_t*) realloc(*timestamps, newSize * sizeof(size_t));
    if (!newTimestamps) {
        fprintf(stderr, "Memory allocation for resized timestamps failed.\n");
        free(*data);
        return;
    }
    *timestamps = newTimestamps;

    size_t* newEventTypes = (size_t*) realloc(*eventTypes, newSize * sizeof(size_t));
    if (!newEventTypes) {
        fprintf(stderr, "Memory allocation for resized eventTypes failed.\n");
        free(*timestamps);
        free(*data);
        return;
    }
    *eventTypes = newEventTypes;

    size_t* newSensorReadings = (size_t*) realloc(*sensorReadings, newSize * sizeof(float));
    if (!newSensorReadings) {
        fprintf(stderr, "Memory allocation for resized sensorReadings failed.\n");
        free(*timestamps);
        free(*eventTypes);
        free(*data);
        return;
    }
    *sensorReadings = newSensorReadings;

    *maxDataSize = newSize;
}

void logDataStatistics(const sensorData* data, size_t dataSize, size_t maxDataSize) {
    // Log the number of elements used and maximum number of elements allocated.
    printf("Used %zu out of a possible %zu elements.\n", dataSize, maxDataSize);
}
