int init_records(size_t size, int min_value, int max_value, size_t *keys_out, size_t *offsets_out, int sort) {
    if (size == 0) {
        return -1;
    }

    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return -2;
    }

    long *offsets = malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(records);
        return -2;
    }

    int *keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(records);
        free(offsets);
        return -2;
    }

    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    if (sort) {
        qsort(records, size, sizeof(Record), compare);
    }

    *keys_out = keys;
    *offsets_out = offsets;
    return 0;

    int compare(const void *a, const void *b) {
        const Record *r_a = a;
        const Record *r_b = b;

        return r_a->value - r_b->value;
    }
}

void print_records(size_t size, const int *keys, const long *offsets, const Record *records) {
    for (size_t i = 0; i < size; ++i) {
        printf("Record %zu:\n", i);
        printf("\tValue: %d\n", records[i].value);
        printf("\tKey: %d\n", keys[*records[i].key]);
        printf("\tOffset: %ld\n\n", offsets[*records[i].offset]);
    }
}

void free_records(Record *records, int *keys, long *offsets) {
    free(records);
    free(keys);
    free(offsets);
}
