    struct_data* data;
} struct_meta;

struct list_node {
    struct_meta* node;
    struct list_node* next;
};

void initialize_data_arrays(double* values, char* keys, struct_data** data_array, struct_meta** meta_array, size_t array_size) {
    json_object *root = json_tokener_parse(/* Your JSON file path here */);
    if (!root) {
        fprintf(stderr, "Error: Failed to parse JSON data\n");
        exit(1);
    }

    struct list_node* meta_list = NULL;
    size_t index = 0;

    json_object_object_foreach(root, key, value) {
        if (index >= array_size) break;

        // Allocate memory for data and meta structures
        struct_data* current_data = malloc(sizeof(struct_data));
        struct_meta* current_meta = malloc(sizeof(struct_meta));
        if (!current_data || !current_meta) {
            fprintf(stderr, "Error: Memory allocation failure\n");
            exit(1);
        }

        current_data->value = json_object_get_int(json_object_dotget(value, "value"));
        if (current_data->value == 0) {
            fprintf(stderr, "Error: Invalid data value: %d\n", current_data->value);
            exit(1);
        }

        // Set next pointers for data structures
        struct_data* temp = data_array[index];
        current_data->next = temp;
        data_array[index] = current_data;

        current_meta->data = current_data;

        if (meta_list) {
            meta_list->next = malloc(sizeof(struct list_node));
            if (!meta_list->next) {
                fprintf(stderr, "Error: Memory allocation failure\n");
                exit(1);
            }
            meta_list = meta_list->next;
        } else {
            meta_list = malloc(sizeof(struct list_node));
            if (!meta_list) {
                fprintf(stderr, "Error: Memory allocation failure\n");
                exit(1);
            }
            meta_list->next = NULL;
        }

        meta_list->node = current_meta;
        index++;
    }

    // Set remaining elements in data array to NULL
    for (size_t i = index; i < array_size; i++) {
        data_array[i] = NULL;
    }

    *meta_array = meta_list->node;
}
