int search_record(struct Record *records, int size, int value) {
    int low = 0;
    int high = size - 1;
    int mid;

    while (low <= high) {
        mid = (low + high) / 2;

        if (records[mid].value < value)
            low = mid + 1;
        else if (records[mid].value > value)
            high = mid - 1;
        else
            return mid;
    }
    return -1;
}

int main(int argc, char *argv[]) {
    int keys = argc > 1 ? atoi(argv[1]) : 5;
    int values = argc > 2 ? atoi(argv[2]) : 10;
    int error_code = init_and_assign(keys, values, NULL, NULL, &records);
    if (error_code) return error_code;

    print_records(records, keys + 1);
    sort_records(records, keys + 1);
    print_records(records, keys + 1);

    int search_value = 25;
    printf("Searching for value=%d\n", search_value);
    int index = search_record(records, keys + 1, search_value);
    if (index == -1) {
        puts("Value not found");
    } else {
        printf("Value found at index %d\n", index);
    }

    free_memory(NULL, NULL, records);
    return 0;
}
