#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int *key;
    long offset;
} Record;

int initialize_arrays(int *input, int inputSize, int *keys, int *offsets, size_t recordsSize) {
    if (!input || !keys || !offsets) return -1;

    for (size_t i = 0; i < recordsSize; ++i) {
        offsets[i] = rand() % inputSize;
        keys[i] = input[offsets[i]];
    }
    return 0;
}

Record* initialize_records(size_t recordsSize, int *keys, long *offsets) {
    Record *records = malloc(recordsSize * sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < recordsSize; ++i) {
        records[i].value = keys[i];
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
    }
    return records;
}

void print_records(Record *records, size_t recordsSize) {
    for (size_t i = 0; i < recordsSize; ++i) {
        printf("{ value: %d, key: %p, offset: %ld }\n", records[i].value, records[i].key, records[i].offset);
    }
}

