        if (records[i].value == value) return i;
    }
    return -1;
}

int main(int argc, char **argv) {
    int *input, *keys, *offsets;
    size_t inputSize = atoi(argv[1]), recordsSize = atoi(argv[2]);

    input = malloc(inputSize * sizeof(int));
    keys = malloc(recordsSize * sizeof(int));
    offsets = malloc((recordsSize + inputSize) * sizeof(long));

    if (!input || !keys || !offsets) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }

    for (size_t i = 0; i < inputSize; ++i) {
        scanf("%d", &input[i]);
    }

